    local d = (level or 1) - (_G.__units.player.level or 1)
    if d >= 5 then return { r = 1.00, g = 0.24, b = 0.24 } end
    if d >= 3 then return { r = 1.00, g = 0.60, b = 0.30 } end
    if d >= -2 then return { r = 1.00, g = 0.94, b = 0.45 } end
    if d >= -8 then return { r = 0.51, g = 0.86, b = 0.51 } end
    return { r = 0.62, g = 0.62, b = 0.62 }
end
function GetQuestGreenRange() return 8 end
function wipe(t) for k in pairs(t) do t[k] = nil end return t end
function CreateColor(r, g, b, a) return { r = r, g = g, b = b, a = a, GetRGBA = function(s) return s.r, s.g, s.b, s.a end } end
function SetPortraitTexture() end

SlashCmdList = {}

-- action bar / binding / secure mocks ---------------------------------------

local actions = {}          -- slot -> {texture, count, cd={start,duration}, ...}
for i = 1, 12 do
	actions[i] = { texture = 130000 + i, count = (i == 8) and 20 or 0 }
end
actions[3].cd = { start = 990, duration = 30 }     -- a real cooldown
actions[5].cd = { start = 999, duration = 1.5 }    -- a global; must NOT get text
actions[2].usable, actions[2].noMana = false, true
actions[9].usable = false                           -- unusable, but affordable
actions[4].inRange = false
actions[6].current = true
actions[7].equipped = true
actions[11] = nil                                   -- an empty slot
-- A couple of slots on page 2 (13-24), so "is this page empty" is a question
-- with two different answers to test against.
actions[13] = { texture = "Icons\\Page2A", count = 0, usable = true, inRange = true }
actions[14] = { texture = "Icons\\Page2B", count = 0, usable = true, inRange = true }
_G.__actions = actions

function HasAction(s) return actions[s] ~= nil end
function GetActionTexture(s) return actions[s] and actions[s].texture end

-- The game answers GetActionCount for a slot that no longer holds anything with
-- whatever the departed stack last counted. Slot 11 is empty and models exactly
-- that, which is the whole reason the button reads HasAction first.
_G.__staleCounts = { [11] = 20 }
function GetActionCount(s)
	if actions[s] then return actions[s].count or 0 end
	return _G.__staleCounts[s] or 0
end
function GetActionCooldown(s)
	local a = actions[s]
	if a and a.cd then return a.cd[1], a.cd[2], 1 end
	return 0, 0, 0
end
function IsUsableAction(s)
	local a = actions[s]
	if not a then return false, false end
	if a.usable == false then return false, a.noMana and true or false end
	return true, false
end
function IsActionInRange(s)
	local a = actions[s]
	if a and a.inRange == false then return false end
	return true
end
function IsCurrentAction(s) return actions[s] and actions[s].current or false end
function IsAutoRepeatAction(s) return false end
function IsEquippedAction(s) return actions[s] and actions[s].equipped or false end
function PickupAction(s) _G.__picked = s end
function PlaceAction(s) _G.__placed = s end
function GetActionBarPage() return _G.__actionPage or 1 end

-- stance and pet -------------------------------------------------------------
-- Two forms and a three-slot pet, so the bars that size themselves have
-- something to size themselves to.
_G.__forms = {
	{ texture = "Icons\\Bear",   active = false, castable = true },
	{ texture = "Icons\\Cat",    active = true,  castable = true },
}
function GetNumShapeshiftForms() return #_G.__forms end
function GetShapeshiftFormInfo(i)
	local f = _G.__forms[i]
	if not f then return nil end
	return f.texture, f.active, f.castable
end
function GetShapeshiftFormCooldown() return 0, 0, 0 end

_G.__petActions = {
	{ name = "Attack",  texture = "Icons\\PetAttack", token = false, active = true },
	{ name = "Follow",  texture = "Icons\\PetFollow", token = false, active = false },
	-- A TOKEN ACTION REPORTS THE NAME OF A GLOBAL for its name as well as for its
	-- texture, which is the trap in this API: read the name straight through and
	-- the tooltip on a hunter's Growl says "PET_TOKEN_GROWL_NAME".
	{ name = "PET_TOKEN_GROWL_NAME", texture = "PET_TOKEN_GROWL", token = true,
	  active = false, autoAllowed = true, autoEnabled = true, spellID = 2649 },
}
_G.PET_TOKEN_GROWL      = "Icons\\PetGrowl"
_G.PET_TOKEN_GROWL_NAME = "Growl"

-- SEVEN RETURNS, not six. The seventh is the spellID, and it is what the
-- tooltip's second line is looked up from - a mock one short made that path
-- unreachable, so a console that never asked for it could not be caught.
function GetPetActionInfo(i)
	local a = _G.__petActions[i]
	if not a then return nil end
	return a.name, a.texture, a.token, a.active, a.autoAllowed, a.autoEnabled,
		a.spellID
end
function GetPetActionsUsable() return true end
function GetPetActionCooldown() return 0, 0, 0 end
_G.__pageHooks = {}
function ChangeActionBarPage(page)
    _G.__actionPage = page
    for _, fn in ipairs(_G.__pageHooks) do fn(page) end
end
-- Both shapes. The object form - hooksecurefunc(obj, "Method", fn) - is what
-- takes ownership of a widget method away from whatever else is setting it, and
-- the chat tabs depend on it: Blizzard fades docked tabs out and the only way to
-- keep them on screen is to be called after every SetAlpha.
function hooksecurefunc(a, b, c)
    if type(a) == "table" then
        local obj, name, fn = a, b, c
        local orig = obj[name]
        if type(orig) ~= "function" then return end
        obj[name] = function(self, ...)
            local r = { orig(self, ...) }
            fn(self, ...)
            return unpack(r)
        end
        return
    end
    local name, fn = a, b
    if name == "ChangeActionBarPage" then
        _G.__pageHooks[#_G.__pageHooks + 1] = fn
        return
    end
    -- Genuinely wrap the global. Swallowing these made the harness agree with any
    -- amount of "we hooked the function that puts Blizzard's look back", which is
    -- exactly the claim that most needs testing.
    local orig = _G[name]
    if type(orig) ~= "function" then return end
    _G[name] = function(...)
        local r = { orig(...) }
        fn(...)
        return unpack(r)
    end
end
function debugstack() return "Blizzard_ActionBar/ActionBar.lua:412\nFrameXML/MainMenuBar.lua:88" end
-- Steerable: the reward cards branch on CHATLINK versus DRESSUP, and a mock that
-- answers true to both makes those two branches indistinguishable.
-- NOTE the name: `__modifiedClick` is already taken further down by the
-- GetModifiedClick table, and clobbering it silently broke action-bar dragging.
_G.__clickAnswer = nil
function IsModifiedClick(what)
	if _G.__clickAnswer == nil then return true end
	return _G.__clickAnswer == what
end
-- Reads the SAME table SetCVar writes. It used to answer a constant false,
-- which made every CVar-driven branch in the addon untestable: a feature gated
-- on one could never be seen to turn on, and a test that flipped the CVar was
-- testing nothing at all.
function GetCVarBool(name)
	local v = _G.__cvars[name]
	return v == "1" or v == 1 or v == true
end

-- ---------------------------------------------------------------------------
-- CVars
--
-- A real store rather than a stub, because zen now BORROWS several of these and
-- the interesting question is whether it gives them back. The client keeps them
-- as strings and normalises numbers on the way in, which is modelled here on
-- purpose: an addon that compares GetCVar's answer to the number it wrote is a
-- restore that silently never fires, and a mock returning the number back would
-- hide exactly that.
--
-- An unknown name throws, as it does in the client. That is what makes probing
-- with GetCVar the only safe way to write one.
-- ---------------------------------------------------------------------------

_G.__cvars = {
	-- The client reads this itself every time it opens a quest page: "1"
	-- shows the text at once, "0" types it out. Present here because a
	-- SetCVar to a name the client does not have is an error, which is how
	-- this mock catches an addon writing a setting that does not exist.
	instantQuestText = "0",
	Sound_EnableAllSound  = "1",
	Sound_MasterVolume    = "1",
	Sound_MusicVolume     = "0.2",
	Sound_SFXVolume       = "0.8",
	Sound_AmbienceVolume  = "0.6",
	Sound_DialogVolume    = "0.7",
	Sound_EnableMusic     = "1",
	Sound_EnableSFX       = "1",
	Sound_EnableAmbience  = "1",
	Sound_EnableDialog    = "1",
	-- Off, because that is the interesting case: with this off the client kills
	-- every sounding handle when the window loses focus and starts none of them
	-- again, which is a programme that goes quiet on an alt-tab and never comes
	-- back. Checked against Blizzard's own Audio.lua for the spelling - the
	-- unknown-name error above is what makes getting it wrong a failed test
	-- rather than a setting nobody ever wrote.
	Sound_EnableSoundWhenGameIsInBG = "0",

	-- How fast MoveViewUpStart/MoveViewDownStart actually turn the camera, in
	-- degrees a second. NOT a constant on a real client: Blizzard's own Mouse
	-- Look Speed slider writes cameraYawMoveSpeed and then this at half of it,
	-- over a 90-to-270 range - so it is 45 to 135 depending on a setting in the
	-- player's own options, and a zen tilt expressed as a DURATION was a
	-- different angle for every player. 90 is the client's own default.
	cameraPitchMoveSpeed               = "90",
	cameraYawMoveSpeed                 = "180",

	colorblindMode                     = "0",
	nameplateMaxDistance               = "20",
	nameplateShowAll                   = "0",
	nameplateShowEnemies               = "1",
	nameplateShowEnemyMinions          = "1",
	nameplateShowEnemyMinus            = "1",
	nameplateShowFriendlyPlayers       = "1",
	nameplateShowFriendlyPlayerMinions = "1",
	nameplateShowFriendlyNpcs          = "1",

	-- The floating text, which is a SEPARATE system from the bars above and has
	-- to be modelled separately or the test cannot tell them apart. Note
	-- UnitNameHostleNPC: that is Blizzard's spelling, in their own source, and
	-- has been for twenty years.
	UnitNameOwn                    = "1",
	UnitNameNPC                    = "1",
	UnitNameFriendlySpecialNPCName = "1",
	UnitNameHostleNPC              = "1",
	UnitNameInteractiveNPC         = "1",
	UnitNameNonCombatCreatureName  = "1",
	UnitNameFriendlyPlayerName     = "1",
	UnitNameFriendlyMinionName     = "1",
	UnitNameEnemyPlayerName        = "1",
	UnitNameEnemyMinionName        = "1",

	-- The over-the-shoulder offset. Present here, but the module must not
	-- REQUIRE it: it appears nowhere in the Classic Era interface source and may
	-- genuinely not exist on a live 1.15 client.
	test_cameraOverShoulder = "0",

	-- Socials and Guild are mutually exclusive on this one.
	useClassicGuildUI              = "1",

	-- The two that decide whether the shoulder offset does anything. Writing the
	-- offset without these is what shipped, and the camera did not move - so the
	-- mock carries them purely so a test can assert they were written.
	CameraKeepCharacterCentered    = "1",
	CameraReduceUnexpectedMovement = "1",

	-- Deliberately ABSENT: nameplateShowFriends, and the four pet/guardian name
	-- CVars the module lists from DialogueUI. Between them they cover both
	-- halves of the probe: a name that is gone from this flavour, and names that
	-- may only exist on another one. It is the name older clients
	-- use and the module lists it, so its absence here is the test that the
	-- module probes before it writes rather than assuming.
}

function GetCVar(name)
	if type(name) ~= "string" then fail("GetCVar got " .. tostring(name)) end
	return _G.__cvars[name]
end

-- Counted, not just thrown. An addon that wraps every SetCVar in a pcall looks
-- identical from the outside whether it probes first or fires blind, and the
-- client logs the blind one. This is what makes "it probed" testable.
_G.__badCVarWrites = 0

-- Every write, not just the bad ones. An idempotent writer and a spendthrift
-- one are indistinguishable through __badCVarWrites, which only counts writes
-- to names the client does not have.
_G.__cvarWrites = 0

function SetCVar(name, value)
	_G.__cvarWrites = _G.__cvarWrites + 1
	if _G.__cvars[name] == nil then
		_G.__badCVarWrites = _G.__badCVarWrites + 1
		error("SetCVar: unknown console variable '" .. tostring(name) .. "'", 2)
	end
	-- Six decimal places for a FLOAT, the way the client writes one back - but
	-- an integer comes back as an integer. Formatting everything to 6dp meant
	-- SetCVar("Sound_EnableMusic", 0) read back as "0.000000", which is not
	-- what the client stores and not what anything comparing it expects.
	if type(value) == "number" then
		_G.__cvars[name] = (value % 1 == 0)
			and string.format("%d", value)
			or string.format("%.6f", value)
	else
		_G.__cvars[name] = tostring(value)
	end

	-- SWITCHING A CHANNEL OFF STOPS WHAT IS ON IT. That is what the sound
	-- options do and it is the only lever an addon has over a sound whose handle
	-- it has lost - a reload throws the handle away and leaves the audio
	-- running. Modelled here because a mock that only consulted the CVar when a
	-- sound STARTED made "switch it off and on to clear the ghost" a line that
	-- could not be tested and could not fail.
	local channel = name:match("^Sound_Enable(%a+)$")
	if channel and _G.__cvars[name] == "0" then
		for handle, ch in pairs(_G.__channel) do
			if ch == channel then
				_G.__playing[handle] = nil
				_G.__channel[handle] = nil
			end
		end
	end
	return true
end

_G.__music = nil
function PlayMusic(file)
	if type(file) ~= "string" then fail("PlayMusic got " .. tostring(file)) end
	_G.__music = file
end
function StopMusic() _G.__music = nil end

-- PlaySoundFile, which is what a PROGRAMME uses. PlayMusic loops, which is
-- right for zen and wrong for an episode.
--
-- IT ANSWERS nil WHEN THE CHANNEL IS MUTED, and that is the whole reason this
-- is modelled rather than stubbed to true: the brief calls the muted case out
-- specifically, and a mock that always plays would let a console that shows
-- silence and looks broken pass every check.
_G.__musicMuted = false
_G.__sounds     = {}          -- handle -> file, everything ever started
_G.__playing    = {}          -- handle -> file, still going
_G.__channel    = {}          -- handle -> which channel it went out on
local nextHandle = 0

function PlaySoundFile(file, channel)
	if type(file) ~= "string" then fail("PlaySoundFile got " .. tostring(file)) end
	-- The console plays on Ambience, not Music: it silences the game's own
	-- music for the flight, and sharing that channel would silence itself too.
	-- "the music is off" therefore means whichever channel it is using.
	if _G.__musicMuted and (channel == "Music" or channel == "Ambience") then
		return nil
	end
	if channel and _G.__cvars["Sound_Enable" .. channel] == "0" then return nil end

	nextHandle = nextHandle + 1
	_G.__sounds[nextHandle]  = file
	_G.__playing[nextHandle] = file
	_G.__channel[nextHandle] = channel
	_G.__lastSound = file
	return true, nextHandle
end

function StopSound(handle)
	if handle == nil then return end
	_G.__playing[handle] = nil
	_G.__channel[handle] = nil
end

--- How many are still going. More than one means a segment was started over
--  the top of another, which on a real client is two tracks at once.
function _G.__soundsPlaying()
	local n = 0
	for _ in pairs(_G.__playing) do n = n + 1 end
	return n
end

-- ---------------------------------------------------------------------------
-- the body and the camera
--
-- The camera mock keeps a real zoom NUMBER, because the interesting property is
-- that the player's own distance comes back exactly - a mock that only recorded
-- "zoom was called" could not tell an exact restore from an approximate one.
--
-- Pitch is modelled as what it really is: a movement with a start and a stop,
-- and a running total of how long it has been moving. That is the only way to
-- catch the failure that actually matters here, which is a nudge that gets
-- started and never stopped.
-- ---------------------------------------------------------------------------

_G.__camera = { zoom = 12, pitchMoving = nil, pitchUp = 0, pitchDown = 0 }
_G.__mounted = false
_G.__emotes = {}

function IsMounted() return _G.__mounted end

function GetCameraZoom() return _G.__camera.zoom end

function CameraZoomIn(d)
	if type(d) ~= "number" then fail("CameraZoomIn got " .. tostring(d)) end
	_G.__camera.zoom = math.max(0, _G.__camera.zoom - d)
end

function CameraZoomOut(d)
	if type(d) ~= "number" then fail("CameraZoomOut got " .. tostring(d)) end
	_G.__camera.zoom = _G.__camera.zoom + d
end

local function bankPitch()
	local c = _G.__camera
	if not c.pitchMoving then return end
	c["pitch" .. c.pitchMoving] = c["pitch" .. c.pitchMoving]
		+ (time - (c.startedAt or time))
	c.pitchMoving = nil
end

--- Starting a movement while another is running is NOT an error.
--
--  It was, in the first version of this mock, and the rule was invented: the
--  client simply changes direction, and asserting otherwise produced twenty
--  failures describing a bug that did not exist. Worse, it cascaded - the failed
--  start left the mock's idea of the current direction wrong, so the stop that
--  arrived later matched nothing and every subsequent start failed too.
--
--  The property that actually matters is not "one at a time". It is "nothing is
--  left moving when zen is over", and that is `pitchMoving == nil`, asserted
--  where the test controls the timers rather than globally. A pitch movement
--  left running rotates the camera through the floor until the player reloads.
local function moveStart(dir)
	return function()
		local c = _G.__camera
		if c.pitchMoving then
			c.restarts = (c.restarts or 0) + 1
			bankPitch()
		end
		c.pitchMoving = dir
		c.startedAt = time
		-- The reversal is a movement followed immediately by a C_Timer stop.
		-- Flagging it here lets that stop's delay be captured as THIS movement's
		-- duration rather than as whatever timer happened to be scheduled last.
		--
		-- "Up" because the shot drops the camera DOWN and the reversal is
		-- therefore the upward one. It was "Down" while the shot tilted up, and
		-- flipping the module without flipping this measures the wrong movement.
		if dir == "Up" then c.awaitingDelay = true end
	end
end

local function moveStop(dir)
	return function()
		if _G.__camera.pitchMoving ~= dir then return end
		bankPitch()
	end
end

MoveViewUpStart, MoveViewUpStop     = moveStart("Up"), moveStop("Up")
MoveViewDownStart, MoveViewDownStop = moveStart("Down"), moveStop("Down")

C_ChatInfo = C_ChatInfo or {}
function C_ChatInfo.PerformEmote(token)
	_G.__emotes[#_G.__emotes + 1] = token
	_G.__emote = token
	return true
end

local bindings = { ACTIONBUTTON1 = "1", ACTIONBUTTON2 = "SHIFT-BUTTON4", ACTIONBUTTON3 = "NUMPAD7" }
_G.__bindingSet = bindings
function GetBindingKey(name) return bindings[name] end
function GetBindingText(k) return k end

-- SetBinding writes into the *account* binding set, which is why keys assigned
-- in our bind mode survive the addon being turned off. A key can only mean one
-- thing, so assigning it moves it off whatever had it before - the same
-- behaviour Blizzard's own keybinding panel has.
_G.__savedBindingSet = nil
function SetBinding(key, action)
	for name, k in pairs(bindings) do
		if k == key then bindings[name] = nil end
	end
	if action then bindings[action] = key end
	return true
end
function GetCurrentBindingSet() return 1 end
function SaveBindings(which) _G.__savedBindingSet = which end

_G.__modifiedClick = { PICKUPACTION = "SHIFT", SELFCAST = "ALT" }
function GetModifiedClick(name) return _G.__modifiedClick[name] end
function IsAltKeyDown() return _G.__alt or false end
function IsControlKeyDown() return _G.__ctrl or false end

-- Override bindings belong to an *owner*; ClearOverrideBindings(owner) drops
-- only that owner's. Modelling that matters here, because the fix for the dock
-- firing the wrong page is precisely "clear Blizzard's, then set ours".
_G.__overrides = {}
_G.__overrideOwner = {}
_G.__clearedOverrides = {}

function SetOverrideBindingClick(owner, priority, key, button, mouse)
    _G.__overrides[key] = button
    _G.__overrideOwner[key] = owner
end

function ClearOverrideBindings(owner)
    if owner and owner.GetName and owner:GetName() then
        _G.__clearedOverrides[owner:GetName()] = true
    end
    for key, o in pairs(_G.__overrideOwner) do
        if o == owner then
            _G.__overrides[key] = nil
            _G.__overrideOwner[key] = nil
        end
    end
end

function GetBindingAction(key, checkOverride)
    if checkOverride and _G.__overrides[key] then
        return "CLICK " .. _G.__overrides[key] .. ":LeftButton"
    end
    return _G.__bindings and _G.__bindings[key] or ""
end
_G.__stateDrivers = {}
function RegisterStateDriver(frame, state, values) _G.__stateDrivers[state] = values end
function UnregisterStateDriver(frame, state) _G.__stateDrivers[state] = nil end

-- THE CLIENT'S OWN PARTY FRAMES, in the shape this client actually has.
--
-- There are NO PartyMemberFrame1..4 globals. PartyFrame.lua builds the member
-- buttons from a frame pool - CreateFramePool("BUTTON", self,
-- "PartyMemberFrameTemplate", ...) - and a pooled frame gets no name. The
-- container is the only thing with one.
--
-- The first version of this mock invented the four globals, so the suite was
-- green about hiding frames that do not exist while the real ones sat on
-- screen next to ours. A mock must never be kinder than the client, and
-- inventing a global it does not have is the kindest thing a mock can do.
PartyFrame = CreateFrame("Frame", "PartyFrame", UIParent)
PartyFrame.__protected = true
for i = 1, 4 do
	-- Nameless, and children of the container, which is why banishing the
	-- container is enough.
	local b = CreateFrame("Button", nil, PartyFrame)
	b.__protected = true
end

-- The raid-style version of the same four people, drawn instead when the
-- player has that setting on.
CompactPartyFrame = CreateFrame("Frame", "CompactPartyFrame", UIParent)
CompactPartyFrame.__protected = true

-- The tab down the left-hand side and the Party Members flyout behind it -
-- the marker grid, Ready Check, Countdown, Convert to Raid. Our controls
-- panel is what replaces it.
CompactRaidFrameManager = CreateFrame("Frame", "CompactRaidFrameManager", UIParent)
CompactRaidFrameManager.__protected = true

_G.__unitWatched = {}
function RegisterUnitWatch(f)
	_G.__unitWatched[f] = true
	f.__unitWatch = true
	f.__protected = true          -- the state driver owns its visibility now
end
function UnregisterUnitWatch(f) _G.__unitWatched[f] = nil; f.__unitWatch = nil end

-- The tooltip, modelled far enough to catch the class of bug where something
-- SHOWS a tooltip correctly and something else empties it a moment later.
--
-- Two behaviours matter and both are the client's, not ours:
--
--   * SetOwner CLEARS the tooltip. Blizzard's own handlers open with it, so a
--     refresh that then fails to fill the tooltip leaves it empty.
--   * an EMPTY tooltip does not draw. Show() on one is a hide.
--
-- and the driver: GameTooltip's OnUpdate re-runs `owner:UpdateTooltip()` every
-- TOOLTIP_UPDATE_TIME (Blizzard_GameTooltip/Classic/GameTooltip.lua:461). That
-- is modelled as __tooltipTick() rather than a real timer.
GameTooltip = CreateFrame("Frame", "GameTooltip")
GameTooltip:Hide()

--- The ANCHOR KIND is recorded, not dropped.
--
--  It was thrown away here while the addon-made tooltip mock beside this one
--  kept it - so "where does this tooltip go" was a question the harness could
--  ask of a scanning tooltip and not of the one every button in the game uses.
--  A bar whose tooltips went to the wrong side of the screen was invisible.
function GameTooltip:SetOwner(o, anchor)
	self.__owner, self.__anchor = o, anchor
	self.__shows = nil          -- SetOwner clears. This is the whole point.
end
function GameTooltip:GetOwner() return self.__owner end
function GameTooltip:IsOwned(f) return self.__owner == f end

function GameTooltip:SetQuestLogItem(kind, i)
	self.__shows = { "item", kind, i, _G.__questSelected }
end
function GameTooltip:SetSpellByID(id) self.__shows = { "spell", id } end

--- The container path. Correct for a real bag and for a bank BAG; it answers
--  nothing for the generic bank container, which is why Blizzard's own bank
--  frame uses SetInventoryItem instead and never calls this for bag -1.
function GameTooltip:SetBagItem(bag, slot)
	if bag == BANK_CONTAINER then
		self.__shows = nil
		return nil
	end
	local info = C_Container.GetContainerItemInfo(bag, slot)
	self.__shows = info and { "bagitem", bag, slot } or nil
	return info and true or nil
end

function GameTooltip:SetInventoryItem(unit, slot)
	self.__shows = slot and { "invitem", unit, slot } or nil
	return slot and true or nil
end
function GameTooltip:SetHyperlink(link) self.__shows = link and { "link", link } or nil end

function GameTooltip:SetAction() end

local rawTooltipShow, rawTooltipHide = GameTooltip.Show, GameTooltip.Hide
function GameTooltip:Show()
	-- An empty tooltip is a hidden tooltip.
	if self.__shows or (self.__lines and #self.__lines > 0) then
		rawTooltipShow(self)
	else
		rawTooltipHide(self)
	end
end

-- ---------------------------------------------------------------------------
-- the tooltip's LINES
--
-- Everything above models the tooltip as an opaque box that is either full or
-- empty, which was enough while the only question was "did something empty it".
-- Modules/Tooltips.lua asks a different question - what does line 2 SAY, and is
-- it still saying it after another addon has been at it - so the lines have to
-- be real FontStrings under their real global names.
--
-- Faithful in the details that decide the module's correctness:
--
--   * both GameTooltipTextLeft1 (global) and GameTooltip.TextLeft1 (parentKey)
--     resolve, because both are declared in GameTooltipTemplate.xml:25
--   * SetUnit CLEARS first, fires OnTooltipCleared, then fills, then fires
--     OnTooltipSetUnit - which is the cycle Tooltips.lua's ResetCard and OnUnit
--     are two halves of
--   * the level line is written in the client's own shape, "Level 18 Humanoid"
--     for a plain mob and "Level 20 Elite Humanoid" for an elite, so the strip
--     is tested against the string it will actually meet
--   * NineSlice exists and is a child FRAME, not a backdrop
-- ---------------------------------------------------------------------------

local function tooltipLines(tip)
	tip.__lines = {}
	tip.__hasScript = {
		OnTooltipSetUnit = true, OnTooltipSetItem = true,
		OnTooltipSetSpell = true, OnTooltipCleared = true,
		OnShow = true, OnHide = true, OnSizeChanged = true, OnUpdate = true,
	}

	-- The NineSlice border. A child frame with a Center texture, exactly as
	-- TooltipBackdropTemplate builds it - NOT a backdrop, which GameTooltip has
	-- never had on this branch.
	local ns = CreateFrame("Frame", nil, tip)
	ns.Center = ns:CreateTexture(nil, "BACKGROUND")
	tip.NineSlice = ns
	tip.layoutType = "TooltipDefaultLayout"

	function tip:SetBackdropColor(r, g, b, a) self.__bdColor = { r, g, b, a } end
	function tip:SetBackdropBorderColor(r, g, b, a) self.__bdBorder = { r, g, b, a } end

	local function lineFor(self, i, side)
		local name = self:GetName()
		local key = (side or "Left") .. i
		self.__strings = self.__strings or {}
		if not self.__strings[key] then
			local fs = self:CreateFontString(name and (name .. "Text" .. key) or nil, "ARTWORK")
			self.__strings[key] = fs
			self["Text" .. key] = fs
		end
		return self.__strings[key]
	end
	tip.__lineFor = lineFor

	function tip:ClearLines()
		self.__lines = {}
		self.__shows = nil
		self.__unit = nil
		self.__item = nil
		for _, fs in pairs(self.__strings or {}) do fs:SetText(nil) end
		local h = self.__scripts and self.__scripts.OnTooltipCleared
		if h then h(self) end
	end

	function tip:AddLine(text, r, g, b)
		self.__lines[#self.__lines + 1] = text
		local fs = lineFor(self, #self.__lines, "Left")
		fs:SetText(text)
		fs:SetTextColor(r or 1, g or 1, b or 1, 1)
		self.__shows = self.__shows or { "text" }
		-- Adding a line resizes the tooltip. Firing OnSizeChanged here is what
		-- makes the Pawn case - lines appended after the tooltip is already up -
		-- reachable from a test at all.
		local h = self.__scripts and self.__scripts.OnSizeChanged
		if h then h(self) end
	end

	function tip:AddDoubleLine(l, r)
		self:AddLine(l)
		lineFor(self, #self.__lines, "Right"):SetText(r)
	end

	function tip:SetText(text, r, g, b)
		self:ClearLines()
		self:AddLine(text, r, g, b)
	end

	function tip:NumLines()
		if self.__lines and #self.__lines > 0 then return #self.__lines end
		return self.__shows and 1 or 0
	end
	--- The first line, which is what a real tooltip's GetText answers. A real
	--  method the mock did not have, so a caller asking what a tooltip says got
	--  a nil-index rather than an answer.
	function tip:GetText()
		local first = self.__lines and self.__lines[1]
		return first and lineFor(self, 1, "Left"):GetText() or nil
	end
	function tip:GetLeftLine(i) return lineFor(self, i, "Left") end

	function tip:SetPadding(w, h) self.__padding = { w, h } end
	function tip:GetPadding() return (self.__padding or { 0, 0 })[1] end
	function tip:SetMinimumWidth(w) self.__minWidth = w end
	function tip:GetMinimumWidth() return self.__minWidth or 0 end

	function tip:GetUnit() return self.__unit and UnitName(self.__unit), self.__unit end
	function tip:IsUnit(token) return self.__unit == token end
	function tip:GetItem() return self.__itemName, self.__item end
	function tip:GetSpell() return self.__spellName, self.__spellID end

	--- Driven by GUID rather than by token. This is how a SCANNING tooltip is
	--  filled - SetUnit on one that is not the cursor's does not reliably lay
	--  its lines out, which is why every addon that reads a title uses this.
		function tip:SetHyperlink(link)
		local guid = type(link) == "string" and link:match("^unit:(.+)$")
		if not guid then return end
		-- COUNTED. The title cache exists so that every Beverage Merchant
		-- in the world is scanned once rather than once per plate, and a
		-- cache that never hits looks identical on screen to one that
		-- does. This is the only way to tell them apart.
		_G.__titleScans = (_G.__titleScans or 0) + 1
		local d = _G.__unitForGUID(guid)
		if not d then return end
		-- The route that actually fills a scanner, so it goes round the guard.
		local was = self.__addonMade
		self.__addonMade = nil
		for token, other in pairs(_G.__units) do
			if other == d then self:SetUnit(token) break end
		end
		self.__addonMade = was
	end

	--- The client's own SetUnit, in the order the client does it.
	--
	--  On a tooltip an ADDON made, this fills nothing. That is not a guess: the
	--  first nameplate title reader used SetUnit, passed every check here, and
	--  returned an empty line for every NPC in the game - and Plater, which has
	--  read titles on this flavour for years, drives its scanner with
	--  SetHyperlink("unit:"..guid) instead. A mock that filled the lines anyway
	--  is what let that ship.
	function tip:SetUnit(unit)
		self:ClearLines()
		if self.__addonMade then return end
		self.__unit = unit
		local d = _G.__units[unit]
		if not d then return end

		self:AddLine(d.name or "Unknown")
		-- Line two is a player's guild or an NPC's title, in angle brackets
		-- either way. It is the only place the client writes "<Innkeeper>" -
		-- nothing on a nameplate carries it - which is why reading it needs a
		-- tooltip at all.
		-- A player's guild is bracketed; an NPC's title is NOT. Plater puts its
		-- own angle brackets on a title before drawing it, which is how we know
		-- - and this mock used to bracket both, so a parser that only accepted
		-- bracketed lines passed here and read nothing whatever in game.
		--
		-- Colourblind mode inserts a line before it, so the title is not always
		-- on line two.
		if d.guild then self:AddLine("<" .. d.guild .. ">") end
		if (_G.__cvars.colorblindMode or "0") ~= "0" then
			self:AddLine(d.isPlayer and (d.class or "Warrior") or "Humanoid")
		end
		if d.title then self:AddLine(d.title) end

		local lvl = (d.level == -1) and "??" or tostring(d.level or 1)
		local words = {}
		local cls = d.classification
		if cls == "elite" then words[#words + 1] = ELITE
		elseif cls == "rareelite" then
			-- TWO words, spaced, as the client writes them. Jammed together as
			-- "RareElite" this quietly stopped exercising the case it exists for:
			-- a strip that only removes one classification word.
			words[#words + 1] = RARE
			words[#words + 1] = ELITE
		elseif cls == "rare" then words[#words + 1] = RARE end
		words[#words + 1] = d.isPlayer and (d.class or "Warrior") or (d.creature or "Humanoid")
		-- string.format, not the `format` alias: that is assigned further down the
		-- file than this, and while it happens to be in place by the time a test
		-- runs, depending on it is depending on an ordering nobody wrote down.
		self:AddLine(string.format(UNIT_LEVEL_TEMPLATE, lvl) .. " " .. table.concat(words, " "))

		local sb = _G[(self:GetName() or "") .. "StatusBar"]
		if sb then
			sb:SetMinMaxValues(0, d.hpMax or 100)
			sb:SetValue(d.hp or d.hpMax or 100)
			sb:Show()
		end

		local h = self.__scripts and self.__scripts.OnTooltipSetUnit
		if h then h(self) end
	end

	function tip:SetItemByID(id, name, quality)
		self:ClearLines()
		self.__item = "|Hitem:" .. tostring(id) .. "|h"
		self.__itemName = name or "Test Item"
		self.__itemQuality = quality or 3
		local qc = ITEM_QUALITY_COLORS[self.__itemQuality] or { r = 1, g = 1, b = 1 }
		self:AddLine(self.__itemName, qc.r, qc.g, qc.b)
		local h = self.__scripts and self.__scripts.OnTooltipSetItem
		if h then h(self) end
	end

	function tip:SetSpell(id, name, body)
		self:ClearLines()
		self.__spellID, self.__spellName = id, name or "Conjure Water"
		self:AddLine(self.__spellName)
		self:AddLine(body or "Conjures 14 bottles of fresh water.")
		local h = self.__scripts and self.__scripts.OnTooltipSetSpell
		if h then h(self) end
	end

	return tip
end

tooltipLines(GameTooltip)

--- The tooltip's own status bar. Note the NAME: the XML declares
--  $parentStatusBar with NO parentKey, so GameTooltip.StatusBar is nil on this
--  branch and only the global exists. A mock that offered the parentKey would
--  hide a real nil-index.
do
	local sb = CreateFrame("StatusBar", "GameTooltipStatusBar", GameTooltip)
	sb:SetHeight(8)
	sb:Hide()
end

--- The other tooltips a skin has to cover.
--
--  Exposed as a global as well, so the suite can stand up a tooltip that another
--  addon hooked BEFORE we did. Both hook orders are reachable in the game and
--  the module has to be right under either.
function _G.__makeTooltip(name)
	return tooltipLines(CreateFrame("Frame", name, UIParent))
end

-- An addon that needs to READ a tooltip makes its own rather than borrowing
-- GameTooltip, which belongs to whatever the cursor is over. CreateFrame with
-- the GameTooltip type (or template) has to hand back something that behaves
-- like one, or a scanning tooltip is untestable and every test of it is really
-- a test of a bare frame.
do
	local plain = CreateFrame
	function CreateFrame(kind, name, parent, template)
		local f = plain(kind, name, parent, template)
		if kind == "GameTooltip"
			or (type(template) == "string" and template:find("GameTooltip")) then
			tooltipLines(f)
			-- Made by an ADDON, and that matters: see SetUnit below.
			f.__addonMade = true
			-- SetOwner CLEARS, exactly as it does on GameTooltip. A scanner that
			-- forgets to call it reads the LAST unit it looked at, which is a
			-- bug that only shows up on the second thing you point at.
			function f:SetOwner(owner, anchor)
				self.__owner, self.__anchor = owner, anchor
				self:ClearLines()
			end
		end
		return f
	end
end

for _, n in ipairs({ "ItemRefTooltip", "ShoppingTooltip1", "ShoppingTooltip2",
	"EmbeddedItemTooltip", "WorldMapTooltip" }) do
	_G.__makeTooltip(n)
end

--- The font OBJECTS. Not FontStrings - a font object has SetFont and nothing
--  else we use, and Tooltips.lua restyling these is what silently carries the
--  typeface into every line another addon adds.
for _, n in ipairs({ "GameTooltipHeaderText", "GameTooltipText", "GameTooltipTextSmall" }) do
	_G[n] = {
		-- Starts with the client's real face, at the sizes FontStyles.xml gives
		-- these three. A mock that started blank would let a module capture nil as
		-- "the original" and call putting nothing back a successful restore.
		__font = { [[Fonts\FRIZQT__.TTF]], n:find("Small") and 10 or 12, "" },
		-- RETURNS NOTHING, because the client's does not. A FontString answers
		-- isValid; a font object answers nothing at all, and a mock that is
		-- kinder than the client hides exactly the bug that made every tooltip
		-- in the game come out in Friz Quadrata - the fallback in
		-- Media:SetFont read this return and fell through on every call.
		SetFont = function(self, path, size, flags)
			if type(path) ~= "string" then fail(n .. ":SetFont path " .. tostring(path)) return end
			-- Refusing a face leaves the object on the one it already had -
			-- the client's own - which is why a font OBJECT needs no fallback:
			-- what it keeps is what the fallback would have set.
			if _G.__badFonts and _G.__badFonts[path] then return end
			self.__font = { path, size, flags }
		end,
		GetFont = function(self)
			local c = self.__font
			if not c then return nil end
			return c[1], c[2], c[3]
		end,
	}
end

--- The globals Tooltips.lua hooksecurefuncs. Each one has to EXIST, and each
--  one has to do the thing the hook is compensating for - in particular
--  SharedTooltip_SetBackdropStyle really does put the border back, which is the
--  whole reason StripArt is called from four places.
--- The inbox, which the client will ONLY answer at a mailbox.
--
--  GetLatestThreeSenders knows about mail that arrived while you were logged
--  in and nothing else, so mail waiting from before login has no names on it
--  at all. This is where the names and the true unread count live, and it is
--  behind a mailbox - which is why the Toolbox reads it when it can and
--  remembers what it said.
_G.__inbox = nil            -- nil models "not at a mailbox / nothing loaded"
function GetInboxNumItems()
	return _G.__inbox and #_G.__inbox or 0
end

--- packageIcon, stationeryIcon, sender, subject, money, COD, daysLeft,
--  itemCount, wasRead, ... - wasRead is the NINTH, and it is the one that
--  matters: an inbox is a list of mail, not a list of unread mail.
function GetInboxHeaderInfo(i)
	local m = _G.__inbox and _G.__inbox[i]
	if not m then return nil end
	return nil, nil, m.sender, m.subject or "", 0, 0, 30, 0, m.read or false
end

--- Blizzard's FCF dock keeps its OWN record of where a chat frame goes, per
--  character, and re-applies it on events an addon does not all hear. Moving
--  the frame without telling it leaves two records disagreeing.
_G.__fcfSaved = {}
function FCF_SavePositionAndDimensions(f)
	if not f or not f.GetID then error("FCF_SavePositionAndDimensions: not a chat frame") end
	local point, _, _, x, y = f:GetPoint(1)
	_G.__fcfSaved[f:GetID()] = { point = point, x = x, y = y }
end

--- ...and what it does with that record later. This is the "few seconds later"
--  in the report: an event fires, Blizzard restores ITS answer, and a position
--  we saved correctly is undone by one we never updated.
function FCF_RestorePositionAndDimensions(f)
	local rec = f and f.GetID and _G.__fcfSaved[f:GetID()]
	if not rec or not rec.point then
		-- A NEW CHARACTER has no record, which is the case that made this
		-- visible: Blizzard falls back to its default corner.
		f:ClearAllPoints()
		f:SetPoint("BOTTOMLEFT", UIParent, "BOTTOMLEFT", 32, 32)
		return
	end
	f:ClearAllPoints()
	f:SetPoint(rec.point, UIParent, rec.point, rec.x, rec.y)
end

function SharedTooltip_SetBackdropStyle(tip)
	if not tip or not tip.NineSlice then return end
	tip.NineSlice:Show()
	tip.NineSlice:SetAlpha(1)
end

function GameTooltip_SetDefaultAnchor(tip, parent)
	tip:SetOwner(parent, "ANCHOR_NONE")
	tip:ClearAllPoints()
	tip:SetPoint("BOTTOMRIGHT", UIParent, "BOTTOMRIGHT", -13, 70)
	tip.default = 1
end

function GameTooltip_ShowStatusBar() end
function GameTooltip_ClearStatusBars() end

-- %s rather than the client's %d, so a "??" level can go through the same
-- format call. Anything matching ON this template has to cope with both, which
-- is a real divergence and is called out where it matters.
UNIT_LEVEL_TEMPLATE = "Level %s"
LEVEL = "Level"
ELITE = "Elite"
RARE = "Rare"
BOSS = "Boss"
HEALTH = "Health"
FACTION_STANDING_LABEL2 = "Hostile"
FACTION_STANDING_LABEL4 = "Neutral"
FACTION_STANDING_LABEL5 = "Friendly"

function UnitClassification(u)
	local d = _G.__units and _G.__units[u]
	return d and d.classification or "normal"
end

function BreakUpLargeNumbers(n)
	local s = tostring(math.floor(tonumber(n) or 0))
	local out = (s:reverse():gsub("(%d%d%d)", "%1,"):reverse())
	return (out:gsub("^,", ""))
end

function GameTooltip_Hide() GameTooltip.__shows = nil GameTooltip:Hide() end
function ResetCursor() end
function CursorUpdate() end
function ShowInspectCursor() end
TOOLTIP_UPDATE_TIME = 0.2

--- One turn of GameTooltip's OnUpdate.
function _G.__tooltipTick()
	local owner = GameTooltip:GetOwner()
	if owner and owner.UpdateTooltip then owner:UpdateTooltip(owner) end
end

--- Blizzard's own container tooltip handler, which our buttons inherit unless
--  we replace it. Faithful in the one respect that matters: it re-owns the
--  tooltip (clearing it) and then fills it with SetBagItem.
function ContainerFrameItemButton_OnEnter(self)
	GameTooltip:SetOwner(self, "ANCHOR_NONE")
	GameTooltip:SetBagItem(self:GetParent():GetID(), self:GetID())
	GameTooltip:Show()
end
function ContainerFrameItemButton_OnLeave() GameTooltip_Hide() ResetCursor() end

-- THE UNIT MENUS, AS 1.15.9 ACTUALLY HAS THEM.
--
-- This mock used to define PlayerFrameDropDown and TargetFrameDropDown, which
-- do not exist on this client and have not for years. It invented them because
-- our code went looking for them - so the suite proved that code found what it
-- was after, and right-clicking a unit frame did nothing in the game. That is
-- the seventh shipped bug traceable to the mock being kinder than the client.
--
-- What the client really has: two secure actions. "menu" calls the button's own
-- menu-function attribute, which is how Blizzard's frames do it; "togglemenu"
-- works the unit out itself, which is how every addon does it. Both end at
-- UnitPopup_OpenMenu.
_G.__unitMenu = nil
function UnitPopup_OpenMenu(which, contextData)
	_G.__unitMenu = { which = which, unit = contextData and contextData.unit }
end

--- The two secure actions, transcribed from SecureTemplates.lua rather than
--  remembered. A mock that answers a right-click more readily than the client
--  is how the bug above survived the suite.
local SECURE_ACTIONS = {}

SECURE_ACTIONS.menu = function(self, unit)
	local fn = self:GetAttribute("menu-function")
	if type(fn) == "function" then fn(self, unit, "RightButton", false) end
end

SECURE_ACTIONS.togglemenu = function(self, unit)
	if not unit then return end
	local which
	if UnitIsUnit(unit, "player") then which = "SELF"
	elseif UnitIsUnit(unit, "pet") then which = "PET"
	elseif UnitIsPlayer(unit) then
		if UnitInRaid(unit) then which = "RAID_PLAYER"
		elseif UnitInParty(unit) then which = "PARTY"
		else which = "PLAYER" end
	elseif UnitIsUnit(unit, "target") then which = "TARGET" end
	if which then UnitPopup_OpenMenu(which, { unit = unit }) end
end

--- Right-click, the way the secure handler does it: through the attributes,
--  never through a reference the caller happened to keep. A reference is
--  exactly what the broken version also had.
function _G.__rightClick(button)
	local action = SECURE_ACTIONS[button:GetAttribute("*type2") or ""]
	if not action then return false end
	action(button, button:GetAttribute("unit"))
	return true
end

