print("== bags: sorting compacts stacks and never reorders ==")
do
	_G.__pickups = {}
	_G.__pending = {}
	Bg:Show()
	local f = Bg.frames.bags

	-- Wool is split 8 + 3 across bag 1 slots 1 and 2; linen is 12 + 5 across
	-- bag 0 slots 2 and 6. Both stack to 20, so both should end up as one.
	local freeBefore = select(1, C_Container.GetContainerNumFreeSlots(0))
		+ select(1, C_Container.GetContainerNumFreeSlots(1))

	Bg:StartSort(f)
	_G.__drainTimers(20)

	check(Bg.sorting == nil,
		"it stops on its own once a pass moves nothing - a routine that moves"
		.. " the player's items in a loop until they log out is much worse than"
		.. " one that gives up")

	local wool, linen = {}, {}
	for slot = 1, _G.__bags[1].size do
		local e = _G.__bags[1].slots[slot]
		if e and e[1] == 2592 then wool[#wool + 1] = e[2] end
	end
	for slot = 1, _G.__bags[0].size do
		local e = _G.__bags[0].slots[slot]
		if e and e[1] == 2589 then linen[#linen + 1] = e[2] end
	end

	check(#wool == 1 and wool[1] == 11,
		"two partial wool stacks became one of 11 (" .. #wool .. " stack(s))")
	check(#linen == 1 and linen[1] == 17,
		"and two partial linen stacks became one of 17 (" .. #linen .. " stack(s))")

	local freeAfter = select(1, C_Container.GetContainerNumFreeSlots(0))
		+ select(1, C_Container.GetContainerNumFreeSlots(1))
	check(freeAfter == freeBefore + 2,
		"which is two slots given back (" .. freeBefore .. " -> " .. freeAfter
		.. ") - that is the entire point of the button; the grid is already"
		.. " sorted by us, so reordering the physical bags buys nothing")

	check(_G.__cursor == nil,
		"and the cursor is empty at the end - an item left on it is an item the"
		.. " next click drops somewhere nobody asked for")

	-- Unstackables must be left where they are.
	check(_G.__bags[0].slots[1] and _G.__bags[0].slots[1][1] == 6948,
		"the Hearthstone never moved - it does not stack, so there is nothing"
		.. " to compact and no reason to touch it")
	check(_G.__bags[1].slots[5] and _G.__bags[1].slots[5][1] == 19019,
		"and neither did Thunderfury")

	-- Put the fixture back for the tests below.
	_G.__bags[1].slots[1] = { 2592, 8 }
	_G.__bags[1].slots[2] = { 2592, 3 }
	_G.__bags[0].slots[2] = { 2589, 12 }
	_G.__bags[0].slots[6] = { 2589, 5 }
	Bg:Rebuild(f)
end

print("== bags: sorting refuses to run in combat ==")
do
	_G.__pickups = {}
	_G.__pending = {}
	_G.__inCombat = true
	Bg.sorting = nil
	Bg:StartSort(Bg.frames.bags)
	check(#_G.__pickups == 0, "no items are moved while a fight is on")
	check(Bg.sorting == nil, "and it does not leave itself half-started")
	_G.__inCombat = false

	-- The harder case: a fight starting DURING a run.
	--
	-- Refusing to begin is easy. A routine already walking the bags has to
	-- notice too, and the only place it can notice is inside the pass -- so the
	-- fixture is arranged to need MORE THAN ONE pass. Three wool stacks of 15,
	-- 12 and 10 cannot fit in one: the first merge fills a stack to its cap of
	-- 20 and pushes 7 back, and the leftovers need a second pass. That is what
	-- makes "it stopped" distinguishable from "it had already finished".
	_G.__bags[1].slots[1] = { 2592, 15 }
	_G.__bags[1].slots[2] = { 2592, 12 }
	_G.__bags[3].size = 4
	_G.__bags[3].slots = { [1] = { 2592, 10 } }
	_G.__pickups, _G.__pending = {}, {}
	Bg.sorting = nil
	Bg:StartSort(Bg.frames.bags)
	local afterFirst = #_G.__pickups
	check(afterFirst > 0, "a sort out of combat does start (" .. afterFirst .. ")")
	check(#_G.__pending > 0, "and has more passes queued (" .. #_G.__pending .. ")")

	_G.__inCombat = true
	_G.__drainTimers(10)
	check(#_G.__pickups == afterFirst,
		"and a fight starting mid-run stops it where it stands (" .. #_G.__pickups
		.. " vs " .. afterFirst .. ")")
	check(Bg.sorting == nil, "and it lets go rather than waiting to resume")
	_G.__inCombat = false

	-- And the ceiling.
	--
	-- A pass that keeps finding work forever means an assumption here is wrong
	-- -- most plausibly that the server confirms a move -- and an addon that
	-- shuffles somebody's bags in a loop until they log out is far worse than
	-- one that gives up. The fixture cannot produce that state (its pickups
	-- really do merge, and the module binds C_Container at load, so it cannot
	-- be stubbed out from here) so the counter is driven directly.
	_G.__pickups, _G.__pending = {}, {}
	_G.__bags[3].size = 4
	_G.__bags[3].slots = { [1] = { 2592, 4 }, [2] = { 2592, 5 } }
	Bg.sorting = { kind = "bags", passes = 40 }
	Bg:SortPass()
	check(Bg.sorting == nil,
		"the pass ceiling stops a run that would otherwise never end")
	check(#_G.__pickups == 0,
		"and it stops before moving anything else (" .. #_G.__pickups .. ")")

	-- One under the ceiling still works, so the guard is a ceiling and not an
	-- off-by-one that quietly halves how much a sort is allowed to do.
	_G.__pickups, _G.__pending = {}, {}
	Bg.sorting = { kind = "bags", passes = 38 }
	Bg:SortPass()
	check(#_G.__pickups > 0, "while a pass under it runs normally ("
		.. #_G.__pickups .. " pickups)")
	Bg.sorting = nil

	-- A timer from a stopped run must not drive the next one.
	--
	-- C_Timer.After cannot be cancelled, so stopping and restarting inside the
	-- 50ms step leaves an orphan in flight. Left unguarded it runs a pass
	-- against the new run's state, and from then on two chains drive one sort
	-- at double the rate the server will accept moves.
	_G.__pickups, _G.__pending = {}, {}
	_G.__bags[3].size = 4
	_G.__bags[3].slots = { [1] = { 2592, 10 } }
	_G.__bags[1].slots[1] = { 2592, 15 }
	_G.__bags[1].slots[2] = { 2592, 12 }
	Bg.sorting = nil
	Bg:StartSort(Bg.frames.bags)
	local orphan = _G.__pending[1]
	check(orphan ~= nil, "a run queues its next pass")
	Bg:StopSort()

	_G.__pending = {}
	Bg.sorting = nil
	Bg:StartSort(Bg.frames.bags)

	-- Work is put back so that a pass firing now WOULD move something. Without
	-- that, "the orphan did nothing" is indistinguishable from "there was
	-- nothing left to do", which is how this test passes against no guard at
	-- all.
	_G.__bags[3].slots = { [1] = { 2592, 4 }, [2] = { 2592, 5 } }
	local settled = #_G.__pickups
	_G.__pending = {}
	orphan()
	check(#_G.__pickups == settled,
		"and an orphan from the run before it does nothing at all, even with"
		.. " work sitting there for it (" .. #_G.__pickups .. " vs " .. settled
		.. ")")
	Bg.sorting = nil

	-- A dirty cursor at the start. Anything can be on it -- a half-finished
	-- drag, a spell -- and picking up onto a full cursor DROPS what was there.
	_G.__pickups, _G.__pending = {}, {}
	_G.__bags[0].slots = { [1] = { 6948, 1 }, [2] = { 2589, 12 }, [3] = { 159, 20 },
		[4] = { 3300, 1 }, [6] = { 2589, 5 }, [7] = { 10250, 1 } }
	_G.__bags[1].slots = { [1] = { 2592, 8 }, [2] = { 2592, 3 }, [3] = { 117, 20 },
		[4] = { 1183, 1 }, [5] = { 19019, 1 } }
	_G.__bags[3].size = 4
	_G.__bags[3].slots = { [1] = { 2592, 4 } }
	_G.__cursor = { bag = 3, slot = 2, id = 2251, count = 2 }
	Bg.sorting = nil
	Bg:StartSort(Bg.frames.bags)
	_G.__drainTimers(20)
	check(_G.__cursor == nil, "a sort empties the cursor before it touches anything")
	local back = _G.__bags[3].slots[2]
	check(back and back[1] == 2251 and back[2] == 2,
		"and what was on it goes back where it came from rather than being"
		.. " dropped into whatever slot the sort happened to be looking at")

	_G.__inCombat = false
	_G.__cursor = nil
	_G.__bags[3].size = 0
	_G.__bags[3].slots = {}
	_G.__bags[1].slots[1] = { 2592, 8 }
	_G.__bags[1].slots[2] = { 2592, 3 }
	_G.__bags[0].slots[2] = { 2589, 12 }
	_G.__bags[0].slots[6] = { 2589, 5 }
	Bg.sorting = nil
end

print("== bags: junk auto-sell is off, and guarded when on ==")
do
	local cfg = A.Config:Module("bags")
	check(cfg.junkAutoSell == false,
		"auto-sell ships OFF - it is the only thing here that spends the"
		.. " player's items, and the dimmed JUNK section is honest about what it"
		.. " would take without anybody having to switch it on to find out")

	local list, value = Bg:JunkList()
	check(#list == 2,
		"the junk list is poor-quality items that HAVE a value (" .. #list .. ")")
	local hasWorthless = false
	for _, e in ipairs(list) do
		local info = C_Container.GetContainerItemInfo(e.bag, e.slot)
		if info.itemID == 5758 then hasWorthless = true end
	end
	check(not hasWorthless,
		"and the Worthless Rock is not among them - hasNoValue is the"
		.. " authoritative 'cannot be sold' flag, and is not the same question"
		.. " as 'sellPrice is zero'")
	check(value == 42, "with the total the vendor would pay (" .. value .. ")")

	local hasQuest = false
	for _, e in ipairs(list) do
		local info = C_Container.GetContainerItemInfo(e.bag, e.slot)
		if info.itemID == 9901 then hasQuest = true end
	end
	check(not hasQuest,
		"and the grey QUEST item is not among them either - quality wins over"
		.. " class when deciding where to show something, and must not win when"
		.. " deciding what to spend; a quest starter sold by an automatic sweep"
		.. " is a quest you have to earn again")

	-- Identity, not properties. Over a run of several seconds the player can
	-- loot into a slot the sweep has already listed but not yet reached.
	_G.__used, _G.__pending = {}, {}
	_G.MerchantFrame:Show()
	Bg.selling = nil
	local listed = select(1, Bg:JunkList())
	Bg.selling = { list = listed, index = 1, worth = 0, earned = 0, sold = 0 }
	local victim = listed[1]
	local was = _G.__bags[victim.bag].slots[victim.slot]
	_G.__bags[victim.bag].slots[victim.slot] = { 1183, 1 }   -- a DIFFERENT grey
	Bg:SellStep()
	_G.__bags[victim.bag].slots[victim.slot] = was
	check(#_G.__used == 0,
		"a slot whose contents changed since it was listed is skipped, even"
		.. " though what is in it now is also grey and also sellable - the"
		.. " question is 'is this still the item I listed', not 'is this junk'")
	Bg.selling = nil
	_G.MerchantFrame:Hide()

	_G.__used, _G.__pending = {}, {}
	cfg.junkAutoSell = true
	_G.MerchantFrame:Hide()
	Bg.selling = nil
	Bg:SellJunk()
	check(#_G.__used == 0,
		"and nothing is sold with no merchant open - UseContainerItem with no"
		.. " merchant window USES the item instead of selling it")

	_G.MerchantFrame:Show()
	Bg.selling = nil
	Bg:SellJunk()
	check(#_G.__used == 1,
		"one item goes per step, not the whole list in a loop - the server drops"
		.. " calls that arrive too fast (" .. #_G.__used .. ")")

	-- The merchant closing mid-run is the dangerous case, because the same call
	-- that sells with a merchant open USES the item without one.
	_G.MerchantFrame:Hide()
	_G.__drainTimers(5)
	check(#_G.__used == 1,
		"and the merchant closing mid-run stops it dead rather than using the"
		.. " rest of the items where they stand (" .. #_G.__used .. ")")
	check(Bg.selling == nil, "and it does not leave a run half-open")
	check(Bg.lastSale and Bg.lastSale.sold == 1 and Bg.lastSale.earned == 30,
		"and an interrupted run reports one item and its price, not the whole"
		.. " list's - reporting money that never arrived is a lie about money ("
		.. tostring(Bg.lastSale and Bg.lastSale.earned) .. ")")

	-- All the way through, with the merchant staying open. The fixture is put
	-- back first, because the interrupted run above really did sell one.
	_G.__bags[0].slots[4] = { 3300, 1 }
	_G.__bags[1].slots[4] = { 1183, 1 }
	_G.__used, _G.__pending = {}, {}
	_G.MerchantFrame:Show()
	Bg.selling = nil
	Bg:SellJunk()
	_G.__drainTimers(10)
	check(#_G.__used == 2, "with it open the whole list goes (" .. #_G.__used .. ")")
	check(Bg.lastSale and Bg.lastSale.earned == 42,
		"and it reports what it actually EARNED, not what the list was worth"
		.. " when it started (" .. tostring(Bg.lastSale and Bg.lastSale.earned) .. ")")
	check(#(select(1, Bg:JunkList())) == 0, "and there is no junk left")
	check(_G.__bags[2].slots[2] and _G.__bags[2].slots[2][1] == 5758,
		"except the Worthless Rock, which is still there - it has no value, so"
		.. " it was never on the list")

	_G.MerchantFrame:Hide()
	Bg.selling = nil
	cfg.junkAutoSell = false
end

print("== bags: turning it off gives Blizzard's back ==")
do
	local toggleBefore = _G.ToggleAllBags
	A:SetModuleEnabled("bags", false)

	check(_G.ToggleAllBags ~= toggleBefore, "the global toggle is handed back")
	local before = _G.__bagToggled
	_G.ToggleAllBags()
	check(_G.__bagToggled == before + 1, "and it is Blizzard's again, not ours")

	check(_G.ContainerFrame1.__aetherSuppress == nil,
		"the OnShow suppressor is disarmed - the hook itself can never be"
		.. " removed, so it is gated on this flag or the player has no bags at"
		.. " all until /reload")
	_G.ContainerFrame1:Show()
	check(_G.ContainerFrame1:IsShown(), "and a container frame really does show again")
	_G.ContainerFrame1:Hide()

	check(_G.BankFrame:GetScript("OnHide") ~= nil, "BankFrame gets its OnHide back")
	check(_G.BankFrame:GetParent() == UIParent, "and is reparented to UIParent")
	check(_G.UIPanelWindows["BankFrame"] ~= nil, "and returns to the panel manager")

	local found = false
	for _, n in ipairs(_G.UISpecialFrames) do if n == "AetherUIBags" then found = true end end
	check(not found, "and it leaves UISpecialFrames")

	A:SetModuleEnabled("bags", true)
	check(Bg.enabled, "and it comes back on")
	check(_G.ContainerFrame1.__aetherSuppress == true, "re-arming the suppressor")
end

print("== bags: the purse and the stack plate read from the palette ==")
do
	Bg:Show()
	local f = Bg.frames.bags
	local c = A.Palette.c

	-- Gold, and gold in every skin. A purse that went rose on Dawn would be
	-- reading as a warning about something.
	local r, g, b = f.foot.coin:GetVertexColor()
	check(math.abs(r - c.money[1]) < 0.001 and math.abs(g - c.money[2]) < 0.001
		and math.abs(b - c.money[3]) < 0.001,
		"the coin is the money gold (" ..
		string.format("%.2f %.2f %.2f", r, g, b) .. ")")
	local drift = {}
	for _, name in ipairs(SKINS) do
		if A.Palette.skins[name].money ~= A.Palette.skins.midnight.money then
			drift[#drift + 1] = name
		end
	end
	check(#drift == 0, "and the same gold on every skin (" ..
		table.concat(drift, ", ") .. ")")

	-- The plate under a stack count is CHROME - a near-black in the skin's own
	-- hue - and it was the literal 0.04, 0.03, 0.08 until the family existed.
	local pill
	for _, row in pairs(f.buttons or {}) do
		if type(row) == "table" then
			for _, btn in pairs(row) do
				if type(btn) == "table" and btn.countPill then
					pill = pill or btn.countPill
				end
			end
		end
	end
	check(pill ~= nil, "a slot has a count plate at all")
	if pill then
		local pr, pg, pb, pa = pill:GetVertexColor()
		local want = c.countPill
		check(math.abs(pr - want[1]) < 0.001 and math.abs(pg - want[2]) < 0.001
			and math.abs(pb - want[3]) < 0.001 and math.abs(pa - want[4]) < 0.001,
			"and it is the skin's near-black at the plate alpha (" ..
			string.format("%.2f %.2f %.2f %.2f", pr, pg, pb, pa) .. ")")
		check(0.299 * pr + 0.587 * pg + 0.114 * pb < 0.2,
			"dark enough for light digits to sit on, which is the whole job")
	end

	-- The wash behind a bar is the skin's track white, not the literal one, and
	-- the caller still chooses its weight.
	local P = A.Palette
	local track = P:Track(0.14)
	check(math.abs(track[4] - 0.14) < 0.001,
		"Track honours the alpha it is handed")
	check(math.abs((P:Track()[4] or 1) - 0.14) < 0.001,
		"and handed none, falls back to the token's own 0.14 - WRITTEN OUT,"
		.. " because a wash compared against the token it came from cannot see"
		.. " that weight change (" .. string.format("%.2f", P:Track()[4] or 1)
		.. ")")
	local xp = A:GetModule("xpbar")
	if xp and xp.frame and xp.frame.bg then
		local _, _, _, xa = xp.frame.bg:GetVertexColor()
		check(math.abs(xa - 0.10) < 0.001,
			"and the XP bar asks for a quieter 0.10 than the default, which is"
			.. " the only thing proving the override is read at all (" ..
			string.format("%.2f", xa) .. ")")
	end
	check(track[1] == P.c.barTrack[1] and track[2] == P.c.barTrack[2],
		"with the SKIN's white rather than 1, 1, 1 - which is the same thing on"
		.. " Midnight and is not on the other three")
	local same = 0
	for _, name in ipairs(SKINS) do
		if A.Palette.skins[name].barTrack[1] == P.c.barTrack[1]
			and A.Palette.skins[name].barTrack[2] == P.c.barTrack[2]
			and A.Palette.skins[name].barTrack[3] == P.c.barTrack[3] then
			same = same + 1
		end
	end
	check(same < #SKINS,
		"and it really does differ between skins - four identical washes would"
		.. " pass the line above without the token doing anything")

	Bg:Hide()
end

print("== bags: restyle ==")
do
	Bg:Show()
	local f = Bg.frames.bags
	A.Palette:Apply(OTHER)
	Bg:OnSkinChanged()
	check(math.abs((f._fillColor[4] or 1) - A.Palette:ReadingFill()[4]) < 0.001,
		"the window takes the READING fill on " .. OTHER .. " too - it carries"
		.. " stack counts and a money string over moving scenery")
	A.Palette:Apply("midnight")
	Bg:OnSkinChanged()
	check(math.abs((f._fillColor[4] or 1) - A.Palette:ReadingFill()[4]) < 0.001,
		"and again on Midnight, from the one shared helper")

	local c = A.Palette.c
	check(c.itemQuality and c.itemQuality[4] and c.itemQuality[4].glow,
		"epic carries a glow as well as a rim - that is what makes a purple"
		.. " findable at a glance in a grid of eighty")
	check(c.itemQuality[1].glow == nil,
		"and common does not, which is not the same as a transparent one")
	Bg:Hide()
end

print("== bags: every quality band exists in both skins ==")
do
	-- The vocabulary check below only compares TOP-LEVEL keys, so a nested band
	-- missing from one skin is a nil index in the middle of a redraw and would
	-- sail straight past it.
	local missing = {}
	for _, name in ipairs(SKINS) do
		local q6 = A.Palette.skins[name].itemQuality
		for q = 0, 5 do
			if not q6[q] then missing[#missing + 1] = name .. " " .. q
			elseif not q6[q].edge then missing[#missing + 1] = name .. " " .. q .. ".edge" end
		end
	end
	check(#missing == 0, "all six bands, all four skins, each with a rim ("
		.. table.concat(missing, ", ") .. ")")
end

-- ---------------------------------------------------------------------------
-- skins
--
-- Daylight became a genuinely LIGHT skin on 2026-08-11 - white panels, dark ink
-- - which inverts the assumption every other module was written under. These
-- checks exist because the failure mode is not an error: it is a colour that is
-- technically applied and visually absent.
-- ---------------------------------------------------------------------------

print("== nameplates: the mock is as unkind as the client ==")
do
	-- The module out of the way: this block is about what the CLIENT does, and
	-- the module's whole job is to countermand some of it.
	A:SetModuleEnabled("nameplates", false)

	local seen = { created = 0, added = 0, removed = 0 }
	local spy = {}
	A:RegisterEvent(spy, "NAME_PLATE_CREATED", function() seen.created = seen.created + 1 end)
	A:RegisterEvent(spy, "NAME_PLATE_UNIT_ADDED", function() seen.added = seen.added + 1 end)
	A:RegisterEvent(spy, "NAME_PLATE_UNIT_REMOVED", function() seen.removed = seen.removed + 1 end)

	local base = __spawnPlate("nameplate1", {
		exists = true, name = "Kolkar Marauder", level = 18, reaction = 2,
		hp = 900, hpMax = 1000,
	})
	check(C_NamePlate.GetNamePlateForUnit("nameplate1") == base,
		"a plate that is up is findable by its token")
	check(seen.created == 1 and seen.added == 1, "created once, added once")

	base.__leftBehind = "kodo"
	__despawnPlate("nameplate1")
	check(seen.removed == 1 and C_NamePlate.GetNamePlateForUnit("nameplate1") == nil,
		"and unfindable once it is taken away")
	check(UnitExists("nameplate1") == false,
		"with the token no longer a unit at all - a module still holding it gets"
		.. " nothing back, which is exactly what the client says")

	local again = __spawnPlate("nameplate1", {
		exists = true, name = "Wandering Kodo", level = 15, reaction = 4,
	})
	check(again == base,
		"the next mob is handed the SAME frame - plates are recycled, not minted,"
		.. " so anything left on one turns up on somebody else")
	check(again.__leftBehind == "kodo", "with the last tenant's things still on it")
	check(seen.created == 1, "and no second CREATED for a frame that already exists")

	again.UnitFrame:Hide()
	__despawnPlate("nameplate1")
	local third = __spawnPlate("nameplate1", {
		exists = true, name = "Gazrog", level = 20, reaction = 2,
	})
	check(third.UnitFrame:IsShown(),
		"Blizzard's own plate is pooled separately and comes back SHOWN on the"
		.. " next unit - hiding it once when the plate is created is not enough,"
		.. " and is why skinned nameplates ship with theirs flickering underneath")

	__spawnForbiddenPlate("nameplate99")
	check(C_NamePlate.GetNamePlateForUnit("nameplate99") == nil,
		"a forbidden plate is invisible to the getters, the way it is to any"
		.. " insecure caller - handling that event pair earns you a nil and a taint")

	__despawnPlate("nameplate1")
	A:UnregisterAllEvents(spy)
	check(__plateCount() == 0, "and nothing is left standing behind us")

	A:SetModuleEnabled("nameplates", true)
end

local NPm = A:GetModule("nameplates")

print("== nameplates: one capsule, and Blizzard's put away ==")
do
	local base = __spawnPlate("nameplate1", {
		exists = true, name = "Kolkar Marauder", level = 18, reaction = 2,
		hp = 700, hpMax = 1000, classification = "normal",
	})
	local f = NPm.plateFor(base)
	check(f ~= nil and f:IsShown(), "a hostile gets a plate")
	check(f:GetParent() == base,
		"parented to the client's base rather than replacing it - the base is the"
		.. " click target and it is protected, so it is left entirely alone")
	check(not base.UnitFrame:IsShown(), "and Blizzard's own is put away")

	check(f.name:GetText() == "Kolkar Marauder", "the name is on it")
	check(f.badge.label:GetText() == "18", "with the level in the badge")
	local fill = select(1, A.Palette:DifficultyColors(18))
	check(f.badge.disc.__color and f.badge.disc.__color[1] == fill[1],
		"tinted by difficulty, off the same band the quest log uses")
	check(f.bar:IsShown() and f.bar:GetValue() == 700, "and the health bar reads")

	-- The recycling trap, end to end.
	__despawnPlate("nameplate1")
	check(f.name:GetText() == "", "a plate that goes away is CLEARED, not just hidden")

	local again = __spawnPlate("nameplate1", {
		exists = true, name = "Wandering Kodo", level = 15, reaction = 4,
		hp = 500, hpMax = 500,
	})
	check(again == base and NPm.plateFor(again) == f,
		"the recycled base keeps the same plate rather than growing a second one")
	check(f.name:GetText() == "Wandering Kodo", "rebound to whoever turned up on it")
	check(not base.UnitFrame:IsShown(),
		"and Blizzard's plate is hidden AGAIN - it is pooled per unit and arrives"
		.. " shown, so hiding it once when the base was created would have left it"
		.. " flickering under every mob after the first")

	check(not f.bar:IsShown(),
		"a neutral out of combat carries a name and nothing else - a yellow plate"
		.. " is 'not my problem yet' and a health bar on one says nothing")
	check(select(1, f.name:GetPoint()) == "LEFT",
		"and with nothing under it the name CENTRES rather than staying anchored"
		.. " for a bar that is not there, hanging high over a band of empty glass")

	_G.__units.nameplate1.inCombat = true
	fire("UNIT_FLAGS", "nameplate1")
	check(f.bar:IsShown(), "until it is in a fight, and then it does")
	check(select(1, f.name:GetPoint()) == "BOTTOMLEFT",
		"and the name moves up to make room for it")

	-- Drawn at profile.scale like every other module. Left at 1 the capsule is
	-- enormous against a HUD at 0.71, which is what the first pass shipped as.
	--
	-- On a plate BUILT after the change, not one that has since been through
	-- OnConfigChanged: those are two different code paths and only one of them
	-- runs when a mob walks up.
	A.db.profile.scale = 0.9
	local other = __spawnPlate("nameplate2", {
		exists = true, name = "Gazrog", level = 20, reaction = 2, hp = 10, hpMax = 10,
	})
	local of = NPm.plateFor(other)
	local mult = A.Config:Module("nameplates").scale
	check(math.abs(of:GetScale() - 0.9 * mult * 0.8) < 0.001,
		"a plate is BUILT at profile.scale, times the module's own multiplier,"
		.. " times the .8 an off-target plate wears")

	A.db.profile.scale = 0.71
	NPm:OnConfigChanged()
	check(math.abs(of:GetScale() - 0.71 * mult * 0.8) < 0.001,
		"and follows profile.scale when it moves, without losing the .8")
	__despawnPlate("nameplate2")

	-- A token with nothing behind it. The client does this when a unit arrives
	-- and is gone inside the same frame, and it is what a forbidden plate would
	-- look like if one ever reached this handler. It has to be a no-op, not a
	-- capsule hung on a frame we invented to have something to hang it on.
	local function built()
		local n = 0
		for _ in pairs(NPm.plates) do n = n + 1 end
		return n
	end
	local before = built()
	fire("NAME_PLATE_UNIT_ADDED", "nameplate77")
	check(built() == before,
		"a token with no plate behind it builds nothing and raises nothing")

	__despawnPlate("nameplate1")
end

print("== nameplates: the target is the one you can read ==")
do
	local mob = { exists = true, name = "Kolkar Marauder", level = 18, reaction = 2,
		hp = 900, hpMax = 1000 }
	local other = { exists = true, name = "Kolkar Wrangler", level = 17, reaction = 2,
		hp = 400, hpMax = 1000 }

	local baseA = __spawnPlate("nameplate1", mob)
	local baseB = __spawnPlate("nameplate2", other)
	local a, b = NPm.plateFor(baseA), NPm.plateFor(baseB)
	local full = A.db.profile.scale * A.Config:Module("nameplates").scale

	check(math.abs(a:GetScale() - full * 0.8) < 0.001
		and math.abs(a:GetAlpha() - 0.62) < 0.001,
		"with nothing targeted every plate is off-target: .8 and .62")

	-- UnitIsUnit answers on identity, so this is the same mob, not a copy.
	_G.__units.target = mob
	fire("PLAYER_TARGET_CHANGED")

	check(NPm.step(nil, 1) == false, "the fade finishes")
	check(math.abs(a:GetScale() - full) < 0.001 and math.abs(a:GetAlpha() - 1) < 0.001,
		"the target comes up to full size and full strength")
	check(a._rimColor ~= nil, "and takes a rim glow in its reaction")
	check(math.abs(a._rimColor[4] - 0.28) < 0.001, "at the deck's .28")
	check(a._edgeColor[4] > b._edgeColor[4],
		"with a stronger rim than the plates around it")

	check(math.abs(b:GetScale() - full * 0.8) < 0.001 and b._rimColor == nil,
		"while everything else stays small and unglowed")

	-- The transition, rather than a snap.
	_G.__units.target = other
	fire("PLAYER_TARGET_CHANGED")
	NPm.step(nil, 0.05)
	local mid = a:GetScale()
	check(mid < full and mid > full * 0.8,
		"a target change is a 150ms move, not a jump - part way through, the plate"
		.. " losing focus is between the two sizes")
	check(NPm.step(nil, 1) == false and math.abs(a:GetScale() - full * 0.8) < 0.001,
		"and it arrives")
	check(b._rimColor ~= nil and a._rimColor == nil,
		"with the glow having moved across, not been left on both")

	-- Losing the target entirely.
	_G.__units.target = nil
	fire("PLAYER_TARGET_CHANGED")
	NPm.step(nil, 1)
	check(b._rimColor == nil, "dropping the target takes the glow with it")

	-- A plate that arrives already targeted does not swell into place.
	_G.__units.target = mob
	__despawnPlate("nameplate1")
	local again = __spawnPlate("nameplate1", mob)
	local a2 = NPm.plateFor(again)
	check(math.abs(a2:GetScale() - full) < 0.001,
		"and a plate that walks up ALREADY targeted arrives at full size rather"
		.. " than growing into it - it was correct before you could see it")

	-- The client will not always answer UnitIsUnit about a plate the instant it
	-- arrives, and a whole batch of them comes back at once when zen gives the
	-- nameplate CVars back. Answer "not the target" then and nothing asks again
	-- until the player clicks something.
	do
		local late = { exists = true, name = "Late Kodo", level = 15, reaction = 2,
			hp = 5, hpMax = 5 }
		_G.__units.target = late
		local baseL = __spawnPlate("nameplate3", late)
		local lf = NPm.plateFor(baseL)

		-- ...as if the token had not resolved yet when the plate came up.
		lf._want, lf._at = 0, 0
		NPm.applyEmphasis(lf)
		check(math.abs(lf:GetScale() - full * 0.8) < 0.001, "dim to begin with")

		tick(0)
		check(math.abs(lf:GetScale() - full) < 0.001,
			"asked again on the next frame, so your own target does not sit at"
			.. " off-target dim until you click something")

		_G.__units.target = nil
		__despawnPlate("nameplate3")
	end

	-- Released part way through a fade, which is the ordinary case: you switch
	-- target and the mob you left dies before the transition finishes.
	_G.__units.target = nil
	fire("PLAYER_TARGET_CHANGED")
	NPm.step(nil, 0.05)
	__despawnPlate("nameplate1")
	__despawnPlate("nameplate2")
	check(next(NPm.moving) == nil,
		"a plate released mid-fade is taken out of the moving set, not left"
		.. " animating a frame nobody can see")
	check(a._rimColor == nil and b._rimColor == nil,
		"and keeps no glow for whoever gets it next")
end

print("== nameplates: your debuffs, under your target, and nobody else's ==")
do
	-- Four debuffs, one of them cast by somebody else. Hung on `target` and the
	-- nameplate token pointed at the same unit, because that is the shape in
	-- game: the plate and the target frame are two tokens for one mob and both
	-- have to read the same list.
	local savedAuras = _G.__auras.target
	_G.__auras.target = { HARMFUL = {
		{ "Chilled",   135834, 0, "Magic", 8,  nil, "player", true },
		{ "Bleeding",  132090, 2, nil,     12, nil, "boss1",  false },
		{ "Frostbite", 135842, 0, "Magic", 5,  nil, "player", true },
		{ "Rend",      132155, 0, nil,     10, nil, "player", true },
	} }

	local mob = { exists = true, name = "Kolkar Marauder", level = 18,
		reaction = 2, hp = 900, hpMax = 1000 }
	_G.__units.target = mob

	local baseA = __spawnPlate("nameplate1", mob)
	-- B carries debuffs of mine TOO. Without that, "off-target shows none" is
	-- true whether the module checks focus or simply has nothing to draw.
	local savedFocus = _G.__auras.focus
	_G.__auras.focus = { HARMFUL = {
		{ "Serpent Sting", 132204, 0, nil, 15, nil, "player", true },
	} }
	local mate = { exists = true, name = "Kolkar Wrangler", level = 17,
		reaction = 2, hp = 400, hpMax = 1000 }
	_G.__units.focus = mate
	local baseB = __spawnPlate("nameplate2", mate)
	local a, b = NPm.plateFor(baseA), NPm.plateFor(baseB)

	fire("PLAYER_TARGET_CHANGED")
	NPm.step(nil, 1)

	check(a._chipCount == 3,
		"the target shows the three debuffs that are MINE - the fourth on it was"
		.. " cast by somebody else and is not my business")
	check((b._chipCount or 0) == 0,
		"and an off-target plate carries none at all even though I have a debuff"
		.. " on that one too - which is most of what makes the target's readable")

	local first = a.chips[1].text:GetText()
	check(first:find("Chilled") ~= nil and first:find("s") ~= nil,
		"a chip is the name and what is left of it (" .. tostring(first) .. ")")
	check(a.chips[1].icon:IsShown(), "with its icon")

	-- Overflow.
	local saved = _G.__auras.target.HARMFUL
	local many = {}
	for i = 1, 7 do
		many[i] = { "Debuff " .. i, 135834, 0, "Magic", 10, nil, "player", true }
	end
	_G.__auras.target.HARMFUL = many
	fire("UNIT_AURA", "nameplate1")
	check(a._chipCount == 5,
		"seven of mine is four chips and a fifth carrying the remainder")
	check(a.chips[5].text:GetText() == "+3", "which says how many are not shown")
	check(not a.chips[5].icon:IsShown(), "and has no icon of its own")

	_G.__auras.target.HARMFUL = saved
	fire("UNIT_AURA", "nameplate1")
	check(a._chipCount == 3, "and it comes back down again")
	check(not a.chips[4]:IsShown() and not a.chips[5]:IsShown(),
		"with the chips it no longer needs HIDDEN rather than left on screen"
		.. " showing a debuff that has expired")

	-- Focus moving takes them with it.
	_G.__units.target = nil
	fire("PLAYER_TARGET_CHANGED")
	check((a._chipCount or 0) == 0, "dropping the target takes its chips away")

	_G.__auras.target = savedAuras
	_G.__auras.focus = savedFocus
	_G.__units.focus = nil
	__despawnPlate("nameplate1")
	__despawnPlate("nameplate2")
end

print("== nameplates: the cast capsule ==")
do
	local mob = { exists = true, name = "Kolkar Wrangler", level = 17, reaction = 2,
		hp = 900, hpMax = 1000 }
	local base = __spawnPlate("nameplate1", mob)
	local f = NPm.plateFor(base)

	check(f.cast == nil or not f.cast:IsShown(), "nothing casting, no capsule")

	-- Through the LIBRARY's registry, which is the only route that exists for a
	-- nameplate unit: the native UNIT_SPELLCAST_* events fire for the player
	-- alone on this client.
	_G.__ccCasts.nameplate1 = { name = "Lightning Bolt", icon = 136048,
		channel = false, start = time * 1000, finish = (time + 3) * 1000 }
	_G.__ccFire("UNIT_SPELLCAST_START", "nameplate1")

	check(f.cast and f.cast:IsShown(), "the library's callback opens the capsule")
	check(f.cast.text:GetText() == "Lightning Bolt", "with the spell named")
	check(f.cast.bar:GetValue() < 0.1, "and the bar at the start of it")

	time = time + 1.5
	f.cast:GetScript("OnUpdate")(f.cast, 1.5)
	check(f.cast.bar:GetValue() > 0.4 and f.cast.bar:GetValue() < 0.6,
		"half way through a three second cast, the bar is half way along")

	-- Chips share the space under the plate, so they move down out of its way.
	local savedAuras = _G.__auras.target
	_G.__auras.target = { HARMFUL = {
		{ "Chilled", 135834, 0, "Magic", 8, nil, "player", true },
	} }
	_G.__units.target = mob
	fire("PLAYER_TARGET_CHANGED")
	NPm.step(nil, 1)
	check(f._chipCount == 1, "the target has a chip")
	check(select(2, f.chips[1]:GetPoint()) == f.cast,
		"and it hangs off the CAST capsule while one is open, rather than being"
		.. " drawn through the middle of it")

	_G.__ccCasts.nameplate1 = nil
	_G.__ccFire("UNIT_SPELLCAST_STOP", "nameplate1")
	check(not f.cast:IsShown(), "the capsule closes when the cast stops")
	check(select(2, f.chips[1]:GetPoint()) == f,
		"and the chips move back up under the plate")

	-- A channel runs the other way.
	_G.__ccCasts.nameplate1 = { name = "Drain Life", icon = 136163, channel = true,
		start = time * 1000, finish = (time + 4) * 1000 }
	_G.__ccFire("UNIT_SPELLCAST_CHANNEL_START", "nameplate1")
	local atStart = f.cast.bar:GetValue()
	time = time + 2
	f.cast:GetScript("OnUpdate")(f.cast, 2)
	check(atStart > f.cast.bar:GetValue(),
		"a channel EMPTIES rather than fills - it is time you have left, not time"
		.. " you have spent")

	-- And a plate handed on mid-cast does not carry it to the next mob.
	__despawnPlate("nameplate1")
	check(not f.cast:IsShown() and f.cast.state == nil,
		"a plate released mid-cast stops casting, rather than showing the last"
		.. " tenant's spell over whoever gets it next")

	_G.__ccCasts.nameplate1 = nil
	_G.__auras.target = savedAuras
	_G.__units.target = nil
end

print("== nameplates: a friendly is a name, not a plate ==")
do
	local mate = { exists = true, name = "Kindarhazan", level = 19, reaction = 5,
		isPlayer = true, class = "Shaman", classToken = "SHAMAN",
		guild = "Samophlange", hp = 800, hpMax = 800 }
	local base = __spawnPlate("nameplate1", mate)
	local f = NPm.plateFor(base)

	check(f._nameForm == true, "a friendly player is drawn as a name")
	check(f.name._aetherStyle == "npFriendly",
		"in its own type role, a point up on the capsule's - a friendly name is"
		.. " shadowed type straight onto the world with no glass under it, and"
		.. " the same size there is a size smaller")
	A:Restyle()
	check(f.name._aetherStyle == "npFriendly",
		"and it SURVIVES a skin change - W.Restyle used to apply a named role"
		.. " without recording it, so the next skin pass put the original back"
		.. " and the name shrank with nothing on screen to explain why")
	check(f._fillColor[4] == 0,
		"with the glass gone entirely rather than dimmed - a faint capsule behind"
		.. " a friendly name is the thing the deck is most explicit about not wanting")
	check(f.name:GetText() == "Kindarhazan", "the name is there")
	check(f.guild:IsShown() and f.guild:GetText() == "<Samophlange>",
		"and the guild under it, in angle brackets")

	check(f.badge:IsShown() and f.badge.label:GetText() == "19",
		"a player gets a level pip")
	local cc = A.Palette:OrbBaseColor("nameplate1")
	check(cc ~= nil and math.abs(f.badge.disc.__color[1] - cc[1]) < 0.001,
		"tinted by CLASS, from the orb palette the HUD's own level disc uses -"
		.. " two sizes of one disc should not be two different colours")
	check(not f.bar:IsShown(),
		"and no health bar at all while they are unhurt - a street of full green"
		.. " bars is noise with nothing in it")

	_G.__units.nameplate1.hp = 300
	fire("UNIT_HEALTH", "nameplate1")
	check(f.bar:IsShown(), "a bar appears when they are hurt, and only then")

	-- The skull rule. Joe, in game at 0.3.19: a friendly player showed one.
	_G.__units.nameplate1.level = -1
	NPm.UpdateAll(f)
	check(not f.badge:IsShown(),
		"a friendly whose level the client will not report has NO pip - never a"
		.. " skull, which says 'too far above you to judge as a threat' and is"
		.. " meaningless about somebody who is not one")

	-- A friendly NPC is a name and nothing else.
	__despawnPlate("nameplate1")
	local npc = { exists = true, name = "Innkeeper Boorand Plainswind", level = 30,
		reaction = 5, isPlayer = false, hp = 500, hpMax = 500 }
	__spawnPlate("nameplate1", npc)
	check(not f.badge:IsShown() and not f.guild:IsShown(),
		"a friendly NPC carries a name alone - no pip, no guild")
	check(f.name:GetText() == "Innkeeper Boorand Plainswind", "just the name")

	-- Party class colours are an opt-in.
	__despawnPlate("nameplate1")
	__spawnPlate("nameplate1", mate)
	check(f.name.__color[1] == A.Palette.c.ttFriendly[1],
		"a friendly player's name is blue by default, whoever they are")
	A.Config:Module("nameplates").partyClassColors = true
	_G.__units.nameplate1.inParty = true
	NPm.UpdateAll(f)
	check(math.abs(f.name.__color[1] - cc[1]) < 0.001,
		"class-coloured once you ask for it, from the same palette as the pip")
	_G.__units.nameplate1.inParty = false
	NPm.UpdateAll(f)
	check(f.name.__color[1] == A.Palette.c.ttFriendly[1],
		"and only for your PARTY, not for everybody in the city")
	A.Config:Module("nameplates").partyClassColors = false

	-- And the form has to be able to change back, because the frame is recycled.
	__despawnPlate("nameplate1")
	local mob = { exists = true, name = "Kolkar Marauder", level = 18, reaction = 2,
		hp = 900, hpMax = 1000 }
	__spawnPlate("nameplate1", mob)
	check(f._nameForm == false and f._fillColor[4] > 0,
		"the same frame becomes a capsule again for the next mob that walks up")
	check(f.name._aetherStyle == "npName",
		"with the capsule's own type role back, rather than the friendly one it"
		.. " was wearing a moment ago")
	check(f.badge:IsShown() and f.badge.label:GetText() == "18"
		and not f.guild:IsShown(),
		"with the badge back at plate size and the guild line gone")
	check(select(2, f.bar:GetPoint()) == f.name,
		"and the bar re-anchored inside the capsule rather than left under a"
		.. " guild line belonging to somebody who has walked off")

	__despawnPlate("nameplate1")
end

print("== nameplates: asking the client for friendly plates ==")
do
	local cv = _G.__cvars
	cv.nameplateShowFriendlyPlayers = "0"
	cv.nameplateShowFriendlyNpcs    = "0"
	_G.__badCVarWrites = 0

	NPm.applyCVars()
	cv.nameplateShowFriendlyPlayerMinions = "0"
	cv.nameplateShowEnemyMinions = "0"
	check(cv.nameplateShowFriendlyPlayerMinions == "0", "(minions start off)")

	NPm.applyCVars()
	check(cv.nameplateShowFriendlyPlayerMinions == "1"
		and cv.nameplateShowEnemyMinions == "1",
		"pets, imps and everything else somebody summoned are asked for too -"
		.. " without them a hunter's pet keeps the client's own floating name"
		.. " while the hunter standing next to it wears ours")

	check(cv.nameplateShowAll == "1",
		"the client is asked to draw plates for EVERYTHING, not only for your"
		.. " target and whatever is hitting you - without it a vendor at her"
		.. " counter never gets a plate at all, so nothing of ours runs on her"
		.. " and she keeps the engine's own floating name")

	-- ...but only when we are setting up. V toggles this one, and putting it
	-- back every time it moved would mean pressing V did nothing.
	cv.nameplateShowAll = "0"
	fire("CVAR_UPDATE", "nameplateShowAll", "0")
	check(cv.nameplateShowAll == "0",
		"and NOT forced back when the player turns it off themselves - it is on"
		.. " a keybind, and an addon that fights V is an addon that broke V")
	NPm.applyCVars(true)
	check(cv.nameplateShowAll == "1", "though changing a setting re-applies it")

	check(cv.nameplateMaxDistance == "41",
		"and the client is asked to make plates as far out as it will - past that"
		.. " there is no plate and the engine draws its own floating name, which"
		.. " is why the lettering changed at a fixed distance")

	A.Config:Module("nameplates").maxDistance = 900
	NPm.applyCVars()
	check(cv.nameplateMaxDistance == "41",
		"clamped to what the client's own slider offers rather than written raw")
	A.Config:Module("nameplates").maxDistance = 41

	check(cv.nameplateShowFriendlyPlayers == "1" and cv.nameplateShowFriendlyNpcs == "1",
		"friendly players AND friendly NPCs are asked for - without this the"
		.. " engine draws them as floating name text and never makes a plate, so"
		.. " the friendly form has nothing at all to draw on")
	check(_G.__badCVarWrites == 0,
		"and nameplateShowFriends, which this flavour does not have, is probed"
		.. " rather than fired blind - the client logs the blind one")

	-- Refused in combat, so queued rather than dropped.
	cv.nameplateShowFriendlyNpcs = "0"
	_G.__inCombat = true
	NPm.applyCVars()
	check(cv.nameplateShowFriendlyNpcs == "0" and NPm._cvarsPending == true,
		"a fight starting mid-load defers the write rather than losing it")
	_G.__inCombat = false
	fire("PLAYER_REGEN_ENABLED")
	check(cv.nameplateShowFriendlyNpcs == "1" and NPm._cvarsPending == nil,
		"and it lands when the fight ends")

	-- Zen borrows these. Two modules writing the same console variable is how
	-- one of them silently undoes the other.
	local Zn = A:GetModule("zen")
	-- On before zen, because that is what we asked the client for.
	cv.nameplateShowFriendlyNpcs = "1"
	Zn:SetWorldText(1)
	NPm.applyCVars()
	check(cv.nameplateShowFriendlyNpcs == "0" and NPm._cvarsPending == true,
		"a nameplate setting changed DURING a zen does not put every friendly"
		.. " plate back on screen in the middle of it")
	Zn:RestoreWorldText()
	check(cv.nameplateShowFriendlyNpcs == "1",
		"and zen gives back the value it borrowed, which was ours - so there is"
		.. " nothing left to redo when it ends")

	-- Somebody else moving them puts ours back. A console variable has no owner,
	-- and an addon that backs these up before we set them restores the old
	-- values over the top when its cutscene ends.
	cv.nameplateShowFriendlyNpcs = "0"
	cv.nameplateMaxDistance = "20"
	fire("CVAR_UPDATE", "nameplateShowFriendlyNpcs", "0")
	check(cv.nameplateShowFriendlyNpcs == "1" and cv.nameplateMaxDistance == "41",
		"a console variable moved out from under us is put back, whoever moved it")

	_G.__cvarWrites = 0
	fire("CVAR_UPDATE", "nameplateShowFriendlyNpcs", "1")
	check(_G.__cvarWrites == 0,
		"and re-running it when nothing is wrong writes nothing at all - which is"
		.. " what stops us and the next addon setting each other off forever")

	-- Never turned off: that state is the player's own console setting.
	A.Config:Module("nameplates").friendlyNames = false
	cv.nameplateShowFriendlyNpcs = "0"
	NPm.applyCVars()
	check(cv.nameplateShowFriendlyNpcs == "0",
		"switching friendly names off makes friendlies wear the capsule - it does"
		.. " not go and clear their console variables")
	A.Config:Module("nameplates").friendlyNames = true
end

print("== options: every control is wired to something that exists ==")
do
	-- A control bound to a key that is not in the defaults does NOTHING, and
	-- says nothing about it: the slider moves, the value is written into a
	-- table nobody reads, and the setting silently has no effect. The panel is
	-- the only way most of this is reachable, so a typo here is a feature that
	-- quietly is not there.
	local missing, count = {}, 0

	local function walk(node, where)
		for key, opt in pairs(node.args or {}) do
			local at = (where or "") .. "/" .. tostring(key)
			if opt.type == "group" then
				walk(opt, at)
			elseif opt.arg and opt.arg.path then
				count = count + 1
				-- Against the DEFAULTS, not the live profile. The profile is
				-- whatever this suite has written into it by now, and Set writes
				-- a key whether or not it was ever declared - so resolving there
				-- means a control with a typo in its path CREATES the key it was
				-- looking for and then reports itself as fine.
				-- `defaultTrue` toggles are absent from the defaults ON PURPOSE:
				-- Get reads nil as true for them, so declaring one would say the
				-- same thing twice and the two could disagree.
				local t = (not opt.arg.defaultTrue) and A.Config.defaults.profile or nil
				local path = opt.arg.path
				if t == nil then path = nil end
				if path then
					for i = 1, #path - 1 do
						t = type(t) == "table" and t[path[i]] or nil
					end
					if type(t) ~= "table" or t[path[#path]] == nil then
						missing[#missing + 1] = at .. " -> "
							.. table.concat(path, ".")
					end
				end
			end
		end
	end
	walk(A.Options:Build())

	check(count > 40, "the panel binds a fair number of controls (" .. count .. ")")

	-- And nothing bound to a key no code reads. That is not statically knowable
	-- in general, so this is the two that were: the minimap drawer's switches
	-- outlived the drawer itself, wrote modules.minimap.drawer and .skinButtons,
	-- and nothing had consulted either since the buttons moved to the rail.
	local tree = A.Options:Build()
	check(tree.args.minimap and tree.args.minimap.args.drawer == nil
		and tree.args.minimap.args.skinButtons == nil
		and tree.args.minimap.args.buttonSpacing == nil,
		"and the minimap's dead drawer controls are gone with the drawer")
	check(#missing == 0,
		"and every one resolves to a key that exists in the defaults ("
		.. table.concat(missing, ", ") .. ")")

	-- And the nameplate page in particular, since it is the newest.
	local np = A.Options:Build().args.nameplates
	check(np ~= nil and np.type == "group", "nameplates has a page of its own")
	check(np and np.args.enabled and np.args.friendlyNames and np.args.scale,
		"carrying the switches that were only reachable by editing a table")
end

print("== nameplates: an NPC is not a mob ==")
do
	-- Joe: "Kodo is a mob. Flight Master Devrak is an NPC." Reaction cannot tell
	-- them apart - a wandering kodo is neutral and so is an NPC of a faction you
	-- have not earned yet. What separates them is whether you can hit it.
	local kodo = { exists = true, name = "Wandering Kodo", level = 15,
		reaction = 4, hp = 500, hpMax = 500 }
	local devrak = { exists = true, name = "Devrak", level = 30,
		reaction = 4, hp = 900, hpMax = 900, canAttack = false,
		title = "Flight Master" }

	local baseK = __spawnPlate("nameplate1", kodo)
	local baseD = __spawnPlate("nameplate2", devrak)
	local k, d = NPm.plateFor(baseK), NPm.plateFor(baseD)

	check(k._nameForm == false and k._fillColor[4] > 0,
		"a neutral MOB keeps the capsule - it is a thing you might have to"
		.. " fight, and the level and the health are what you want off it")
	check(d._nameForm == true and d._fillColor[4] == 0,
		"while an NPC at the same reaction is a name - not enough reputation is"
		.. " a fact about your standing, not about whether he is a mob")
	check(d.name:GetText() == "Devrak" and not d.badge:IsShown(),
		"the name, with no capsule and no level on it")
	check(not d.bar:IsShown(), "and no health bar while he is unhurt")

	check(d.guild:IsShown() and d.guild:GetText() == "<Flight Master>",
		"and his TITLE under it - which is what tells you he is the one to talk"
		.. " to. A nameplate carries no title, so it is read off the second line"
		.. " of his tooltip, where the client keeps it")
	check(GameTooltip.__unit ~= "nameplate2",
		"through a tooltip of our own, never GameTooltip - that one belongs to"
		.. " whatever the cursor is over, and driving it here would flicker"
		.. " somebody else's tooltip every time a vendor walked past")

	_G.__units.nameplate2.hp = 100
	fire("UNIT_HEALTH", "nameplate2")
	check(d.bar:IsShown(), "which appears if somebody is beating on him")

	-- And a hostile one is a capsule whatever else is true of it.
	__despawnPlate("nameplate2")
	__spawnPlate("nameplate2", { exists = true, name = "Kolkar Marauder",
		level = 18, reaction = 2, hp = 900, hpMax = 1000 })
	check(d._nameForm == false, "anything you can attack is a capsule")

	-- Joe: vendors and flight masters are names whatever their reaction. Kaja
	-- the ammo merchant is NEUTRAL, and therefore attackable, and therefore
	-- indistinguishable from the kodo by reaction or by attackability. The
	-- client gives her a title and gives the kodo none.
	__despawnPlate("nameplate2")
	__spawnPlate("nameplate2", { exists = true, name = "Kaja", level = 30,
		reaction = 4, hp = 1003, hpMax = 1003, title = "Guns and Ammo Merchant" })
	check(d._nameForm == true,
		"a NEUTRAL vendor is a name - she has a job, and the title is the only"
		.. " thing in Lua that says so")
	check(d.guild:GetText() == "<Guns and Ammo Merchant>", "with her trade under it")
	check(k._nameForm == false,
		"while the kodo standing beside her, equally neutral and equally"
		.. " attackable, is still a capsule")

	-- A mob's second line is its LEVEL, and taking that for a title puts
	-- "Level 15 Beast" under a kodo's name - which is worse than no title.
	check(k.guild:IsShown() == false, "a mob's level line is not read as a title")

	-- COLOURBLIND MODE INSERTS A LINE. With it on the title is on line three,
	-- and reading line two regardless gets you the wrong string for every NPC
	-- in the game - for the players who need that setting, and nobody else.
	_G.__cvars.colorblindMode = "1"
	__despawnPlate("nameplate2")
	__spawnPlate("nameplate2", { exists = true, name = "Zargh", level = 30,
		reaction = 4, hp = 900, hpMax = 900, title = "Butcher" })
	check(d._nameForm == true and d.guild:GetText() == "<Butcher>",
		"the title line moves with colourblind mode, which adds one above it")
	_G.__cvars.colorblindMode = "0"

	-- ...but a named hostile carries a title too, and that one you want to see
	-- the health of.
	__despawnPlate("nameplate2")
	__spawnPlate("nameplate2", { exists = true, name = "Edwin VanCleef", level = 22,
		reaction = 2, hp = 4000, hpMax = 4000, title = "Defias Kingpin" })
	check(d._nameForm == false,
		"a hostile with a title is still a capsule - a named boss has one, and"
		.. " its name without its health is the worst of both")

	-- A creature with no title is remembered as having none, or every plain mob
	-- is re-scanned on every plate it ever appears on.
	local vendor = { exists = true, name = "Larhka", level = 30, reaction = 5,
		hp = 500, hpMax = 500, canAttack = false, title = "Beverage Merchant" }
	__despawnPlate("nameplate1")
	__spawnPlate("nameplate1", vendor)
	check(k.guild:GetText() == "<Beverage Merchant>", "a vendor keeps her trade")

	__despawnPlate("nameplate1")
	__despawnPlate("nameplate2")
end

print("== palette: the orb's class colours are the CLIENT's ==")
do
	-- The orb names its nine colours rather than reading RAID_CLASS_COLORS, so a
	-- colour-blind addon can recolour every name in the game without the level
	-- disc moving under it. That is worth keeping and it is also how a copy goes
	-- stale, so the copy is checked.
	--
	-- Shaman is the one that matters: PINK on Vanilla, blue from TBC on. The two
	-- files sit side by side in Blizzard_SharedXML and this client loads the
	-- Vanilla one, so pink is not a preference here, it is the version.
	local wrong = {}
	for class, cc in pairs(RAID_CLASS_COLORS) do
		local units = _G.__units
		units.__cc = { exists = true, isPlayer = true, class = class,
			classToken = class, reaction = 5 }
		local ours = A.Palette:OrbBaseColor("__cc")
		if math.abs(ours[1] - cc.r) > 0.004 or math.abs(ours[2] - cc.g) > 0.004
			or math.abs(ours[3] - cc.b) > 0.004 then
			wrong[#wrong + 1] = class
		end
		units.__cc = nil
	end
	check(#wrong == 0,
		"every class the client names, the orb names the same (" ..
		table.concat(wrong, ", ") .. ")")

	-- And the shipped default is a default, not somebody's setting.
	-- Reachable, or A:Debug is a diagnostic nobody can read.
	A.db.profile.debug = false
	SlashCmdList["AETHERUI"]("debug on")
	check(A.db.profile.debug == true, "debug can be switched on from a slash command")
	SlashCmdList["AETHERUI"]("debug off")
	check(A.db.profile.debug == false, "and off again")

	check(A.Config.defaults.profile.scale == 1.0,
		"the default scale is 1, which is what a 1920x1080 screen wants. It was"
		.. " 0.71 under a comment deriving it from the DECK's proportions, which"
		.. " is sound arithmetic about the deck and was never a claim about what"
		.. " a player should get")

	check(math.abs(RAID_CLASS_COLORS.SHAMAN.r - 0.96) < 0.004
		and math.abs(RAID_CLASS_COLORS.SHAMAN.b - 0.73) < 0.004,
		"and a Shaman is pink, because this is Vanilla - blue is TBC's answer")
end

print("== popups: the client's dialogs in our glass ==")
do
	local PPm = A:GetModule("popups")

	-- SCALE. A dialog left at the client's size is enormous beside the
	-- interface that raised it, and it is the one window that turns up without
	-- being asked for.
	local popScale = A.db.profile.scale
	A.db.profile.scale = 0.8
	PPm:Skin()
	check(_G.StaticPopup1:GetScale() == 0.8,
		"a dialog is drawn at the profile's scale like everything else of ours")
	A.db.profile.scale = popScale
	PPm:Skin()

	-- BOTH conventions. Half the mock's dialogs carry their parts as fields and
	-- half name them globally, because both are live on this client - and a
	-- module that knows one convention skins half the dialogs in the game while
	-- looking perfectly correct on whichever half it was written against.
	for i = 1, 4 do
		local p = _G["StaticPopup" .. i]
		check(p.__aetherPanel ~= nil,
			"dialog " .. i .. " has a glass panel behind it")
		check(p.__border:IsShown() == false and p.__bg:IsShown() == false,
			"and the stone frame it came with is hidden, not covered over")
		check(p.__nine.__fill:GetTexture() == 0,
			"including the background hanging off it in a CHILD FRAME - that is"
			.. " not one of the dialog's own regions, so a strip that only walks"
			.. " GetRegions leaves the thing you actually see through")

		local alert = PPm.Element(p, "AlertIcon")
		check(alert and not alert:IsShown(),
			"the warning triangle goes with the stone it was drawn for - what the"
			.. " dialog asks is in the words")

		local text = PPm.Element(p, "Text")
		check(text and text._aetherStyle == "qlObjName",
			"the question is re-roled into our type")

		local b1 = PPm.Element(p, "Button1")
		check(b1 and b1.__aetherSkin ~= nil, "and each button gets a pill behind it")
				check(b1:GetFontString()._aetherStyle == "tbCardTitle", "with our lettering on it")

		-- THE ONE THAT SHIPPED WRONG. A button's pushed art is hidden until you
		-- press it, so hiding "everything currently shown" left it in place and
		-- Blizzard's button flashed back the instant you clicked.
		local pushed = b1:GetPushedTexture()
		check(pushed and pushed:GetTexture() == 0,
			"the PUSHED art is cleared through the setter, not merely hidden -"
			.. " the client shows it on mousedown and there is no moment of ours"
			.. " in between")
		local normal = b1:GetNormalTexture()
		check(normal and normal:GetTexture() == 0, "and so is the normal art")
		local hi = b1:GetHighlightTexture()
		check(hi and hi:GetTexture() == 0, "and the highlight")
	end

	-- The client can put art BACK. A button's pushed texture is hidden until it
	-- is pressed, and once shown it stayed shown for every dialog after.
	do
		local p2 = _G.StaticPopup2
		p2.__later:Show()
		p2:GetScript("OnShow")(p2)
		check(not p2.__later:IsShown(),
			"art the client reveals later is taken down on the next show, rather"
			.. " than being left because it was not up when we first looked -"
			.. " which is how a texture appears once and then stays for good")
	end

	-- The buttons are DRESSED, not rebuilt: what you click is still the
	-- client's, because several of these dialogs run protected actions.
	local p1 = _G.StaticPopup1
	local b1 = PPm.Element(p1, "Button1")
	check(b1:GetParent() == p1 and b1.__aetherSkin:GetParent() == b1,
		"the button is still the client's own, in the client's own place - the"
		.. " pill hangs off it rather than the other way round")

	-- Off gives Blizzard's back, whole. Every module here is a reskin.
	A:SetModuleEnabled("popups", false)
	check(p1.__aetherPanel == nil and p1.__border:IsShown()
		and b1.__aetherSkin == nil,
		"switching it off returns the dialog the client drew, art and all")
	A:SetModuleEnabled("popups", true)
	check(_G.StaticPopup1.__aetherPanel ~= nil, "and on again re-dresses it")

	-- ...and off puts the button's own art back, not just our pill.
	A:SetModuleEnabled("popups", false)
	local restored = PPm.Element(_G.StaticPopup1, "Button1"):GetNormalTexture()
	check(restored and restored:GetTexture() == "dialog-button-up",
		"switching off gives the button its own art back, by name - clearing a"
		.. " texture is not undone by hiding a region")
	check(_G.StaticPopup1.__nine.__fill:GetTexture() == "dialog-background",
		"and the dialog's own background comes back with it, out of the child"
		.. " frame it lives in")
	A:SetModuleEnabled("popups", true)
end

print("== reskin: taking a client frame apart, reversibly ==")
do
	local R = A.Reskin

	-- Element, under both conventions. The reworked frames are MIXIN objects
	-- and resolve their parts through __index, so rawget finds a frame and none
	-- of its pieces - which shipped once as a dialog with untouched buttons.
	local mixin = CreateFrame("Frame", "AetherTestMixinFrame", UIParent)
	local part = CreateFrame("Button", nil, mixin)
	setmetatable(mixin, { __index = function(_, k) return k == "Button1" and part or nil end })
	check(R.Element(mixin, "Button1") == part,
		"a part reached through __index is found - rawget would answer nil for"
		.. " every one of them")

	local named = CreateFrame("Frame", "AetherTestNamedFrame", UIParent)
	local far = CreateFrame("Button", "AetherTestNamedFrameButton1", named)
	check(R.Element(named, "Button1") == far,
		"and a part that only exists as a global name is found too")
	check(R.Element(named, "Nothing") == nil, "with nothing invented for a part that is absent")

	-- Strip: regions, and the art hiding in child frames.
	local host = CreateFrame("Frame", nil, UIParent)
	local own = host:CreateTexture(nil, "BACKGROUND")
	own:SetTexture("stone")
	local hiddenArt = host:CreateTexture(nil, "OVERLAY")
	hiddenArt:SetTexture("glow")
	hiddenArt:Hide()

	host.NineSlice = CreateFrame("Frame", nil, host)
	local backdrop = host.NineSlice:CreateTexture(nil, "BACKGROUND")
	backdrop:SetTexture("dialog-background")

	local store = {}
	R.Strip(host, store)
	check(own:GetTexture() == 0 and not own:IsShown(),
		"a texture is CLEARED, not merely hidden - a hidden one is one the"
		.. " client can show again, and does")
	check(backdrop:GetTexture() == 0,
		"and the backdrop in a child frame goes with it, which GetRegions never"
		.. " returns and is the whole reason a stripped dialog stayed opaque")

	hiddenArt:Show()
	R.Strip(host, store)
	check(not hiddenArt:IsShown(),
		"art revealed later is taken down on the next pass, rather than being"
		.. " left because it was down when we first looked")

	R.Restore(store)
	check(own:GetTexture() == "stone" and own:IsShown(), "and it all goes back")
	check(backdrop:GetTexture() == "dialog-background", "including the child frame's")
	check(not hiddenArt:IsShown(),
		"except what the client had hidden itself, which stays hidden - putting"
		.. " everything back means as it WAS, not as much of it as possible")

	-- Buttons: the four state textures, through the setters.
	local btn = CreateFrame("Button", nil, UIParent)
	btn:SetNormalTexture("up")
	btn:SetPushedTexture("down")
	R.ClearButton(btn)
	check(btn:GetNormalTexture():GetTexture() == 0
		and btn:GetPushedTexture():GetTexture() == 0,
		"cleared through the setters - the client shows the pushed one on"
		.. " mousedown and there is no moment of ours in between")
	R.RestoreButton(btn)
	check(btn:GetNormalTexture():GetTexture() == "up"
		and btn:GetPushedTexture():GetTexture() == "down",
		"and restored by name, because clearing is not undone by showing")

	-- ORDER-INDEPENDENT. A caller may strip a button's regions before clearing
	-- its state textures - both orders are reasonable and each has been written
	-- once already. Clearing second must not record the emptied value as though
	-- it were the client's, or the restore puts "cleared" back.
	local either = CreateFrame("Button", nil, UIParent)
	either:SetNormalTexture("up")
	local st = {}
	R.Strip(either, st)
	R.ClearButton(either)
	R.Restore(st)
	R.RestoreButton(either)
	check(either:GetNormalTexture():GetTexture() == "up",
		"whichever order the caller strips and clears in, the button gets its"
		.. " own art back")

	-- DRESSED, HANDED BACK, DRESSED AGAIN. Switching a module off restores every
	-- state texture it took, and switching it on runs the dressing a second time
	-- over a widget that still carries our marker - so a dresser that tests the
	-- marker before it clears returns before it has taken back what it gave up,
	-- and the client's border is on our cell until the next reload.
	local twice = CreateFrame("Button", nil, UIParent)
	twice:SetNormalTexture("slot-border")
	twice.IconTexture = twice:CreateTexture(nil, "BACKGROUND")
	twice.IconTexture:SetTexture("an-item")
	R.Slot(twice)
	R.RestoreButton(twice)
	R.Slot(twice)
	check(twice:GetNormalTexture():GetTexture() == 0,
		"and a slot dressed, handed back and dressed again is bare the second"
		.. " time too")
	check(twice.IconTexture:GetTexture() == "an-item",
		"with the item still in it")
end

print("== panels: the client's windows in our glass ==")
do
	local PNm = A:GetModule("panels")

	local cf = _G.CharacterFrame
	check(cf.__aetherPanel ~= nil, "the character sheet has a glass panel behind it")
	check(cf.__stone:GetTexture() == 0, "and its stone frame is cleared")
	check(cf.Bg.__fill:GetTexture() == 0,
		"including the background in its child frame, which is where these keep"
		.. " the thing you can actually see")
	check(cf.TitleContainer.__bar:GetTexture() == 0,
		"and the stone band behind the title, which hangs off a TitleContainer -"
		.. " the game menu's Header under a second name. On the help window that"
		.. " band was the last thing left drawing on the whole frame")
	check(_G.CharacterFrameTitleText._aetherStyle == "pnTitle",
		"the title is re-roled into our type")

	-- OUTLINED, unlike our own panels' type. These labels sit over whatever the
	-- window is showing - a paper doll, a talent tree's artwork, a map - rather
	-- than over an even fill of ours, and an unoutlined word on that reads as
	-- smudged.
	-- NOT OUTLINED, and it used to be. The argument was that these labels sit
	-- over the window's own contents rather than over a fill of ours - true of
	-- the stone windows, and untrue the moment the art came off. What they sit
	-- over now is our glass, like every other string in this interface, and
	-- nothing else here is outlined.
	local _, _, titleFlags = _G.CharacterFrameTitleText:GetFont()
	check(titleFlags == "",
		"and NOT outlined - it sits on our own glass now, and a stroke round it"
		.. " is a thing this interface does nowhere else ("
		.. tostring(titleFlags) .. ")")

	local close = _G.CharacterFrameCloseButton
	check(close.__aetherX and (close.__aetherX:GetText() or "") ~= "",
		"and the way out is our own mark - with the stone X cleared there would"
		.. " otherwise be nothing left to click")
	check(close:GetNormalTexture():GetTexture() == 0, "its art gone with the rest")
	check(close:GetParent() == cf,
		"on the client's own button, which is still the thing that closes the"
		.. " window - nothing here is rebuilt or reparented")

	-- THE INSIDES. A window is mostly not a window: the character sheet is item
	-- slots, tabs, bars, lists and check boxes, and a shell in our glass with
	-- Blizzard's stone furniture inside it is the worse of the two looks.
	local head, neck = _G.CharacterHeadSlot, _G.CharacterNeckSlot

	check(head.__aetherSlot == true, "an equipment slot wears our cell")
	check(head:GetNormalTexture():GetTexture() == 0, "its stone border cleared")
	check(_G.CharacterHeadSlotIconTexture:GetTexture() == "item-icon-CharacterHeadSlot",
		"and THE ITEM IS STILL IN IT - the icon is a region of the button, so"
		.. " stripping the slot would blank the item and leave the border"
		.. " correctly gone, which is why Reskin.Slot must not strip")

	local hr, hg, hb = head.edge:GetVertexColor()
	local q = _G.ITEM_QUALITY_COLORS[4]
	check(hr == q.r and hg == q.g and hb == q.b,
		"an epic sits in a rim of its own quality")
	local nr, ng, nb = neck.edge:GetVertexColor()
	local e = A.Palette.c.glassEdge
	check(nr == e[1] and ng == e[2] and nb == e[3],
		"and an empty slot keeps the ordinary rim - colouring every slot would"
		.. " make the colour mean nothing")

	-- The rim has to answer the client, not just the dressing. Unequip it.
	_G.__setSlotQuality(1, nil)
	_G.PaperDollItemSlotButton_Update(head)
	hr, hg, hb = head.edge:GetVertexColor()
	check(hr == e[1] and hg == e[2] and hb == e[3],
		"take the item off and the rim follows, because the client repaints a"
		.. " slot whenever its item changes and a rim set once at dress time"
		.. " would keep an epic border around an empty slot")
	_G.__setSlotQuality(1, 4)

	check(_G.CharacterFrameTab1.__aetherTab ~= nil, "a tab gets our pill")
	check(_G.CharacterFrameTab1:GetNormalTexture():GetTexture() == 0
		and _G.CharacterFrameTab1:GetDisabledTexture():GetTexture() == 0,
		"with BOTH its art sets cleared - Blizzard draws a tab in three pieces"
		.. " and keeps a whole second set for the disabled state")
	check(_G.CharacterFrameTab1Text._aetherStyle ~= nil, "and its label in our type")

	check(_G.PaperDollFrame:GetRegions():GetTexture() == 0,
		"the panes inside lose their stone as well")

	check(_G.ReputationBar1.__aetherFill ~= nil, "a reputation bar takes our fill")
	check(_G.ReputationBar1:GetStatusBarTexture():GetTexture() == A.Media.texture.bar,
		"set AFTER the strip, which empties the fill along with everything else")

	local thumb = _G.ReputationListScrollFrameScrollBar:GetThumbTexture()
	check(thumb:GetTexture() == A.Media.texture.flat,
		"a scroll bar's thumb is ours - the one part of a scroll bar anybody"
		.. " actually looks at")

	check(_G.ReputationDetailAtWarCheckbox.__aetherCheck ~= nil,
		"and a check box gets a pill")

	-- MORE ROWS, NOT JUST MORE ROOM. Blizzard builds twelve and reuses them as
	-- you scroll, so a taller window buys nothing: the list still ends twelve
	-- rows down with empty glass under it. The rows come from the client's own
	-- templates and its own update function fills them - we only add to the
	-- pool and say how many there are.
	check(_G.SKILLS_TO_DISPLAY > 12,
		"the skill list grows to fit the window (" .. _G.SKILLS_TO_DISPLAY
		.. " rows, from the client's twelve)")
	check(_G.SkillRankFrame13 ~= nil and _G.SkillTypeLabel13 ~= nil,
		"with real rows behind the number - a count raised over rows that do not"
		.. " exist is an error in the client's own update loop, not a longer list")

	local newPt, newRel, newRelPt, _, newY = _G.SkillRankFrame13:GetPoint(1)
	check(newPt == "TOPLEFT" and newRel == _G.SkillRankFrame12
		and newRelPt == "BOTTOMLEFT",
		"each new row hangs off the one above it, as the client's own do")
	check(_G.SkillRankFrame13.__aetherFill ~= nil,
		"and the rows we added are skinned like the rest")

	-- And it stops at the window. A count larger than the space is the same
	-- bug in the other direction.
	local tallEnough = _G.SKILLS_TO_DISPLAY * 18 + 79 + 78
	check(tallEnough <= cf:GetHeight() + 18,
		"and no more of them than the window can hold ("
		.. _G.SKILLS_TO_DISPLAY .. " x 18 inside " .. cf:GetHeight() .. ")")

	-- THE DISCLOSURE MARKS. Blizzard's stone plus and minus are the last thing
	-- in either tree still drawn by the other interface.
	local header = _G.SkillTypeLabel1
	check(header:GetNormalTexture():GetTexture() == 0,
		"a group header's stone mark is cleared")
	check(header.__aetherGlyph ~= nil, "and ours is drawn instead")
	check(header.__aetherGlyph:GetText() == "\226\136\146",
		"an expanded group shows a minus - the real one, U+2212, because a"
		.. " hyphen beside a full-height plus reads as a dash that lost something")
	check(_G.SkillTypeLabel2.__aetherGlyph:GetText() == "+",
		"and a collapsed one shows a plus")

	-- Where the client's own mark was, not in the middle of the row.
	local gp, grel = header.__aetherGlyph:GetPoint(1)
	check(gp == "CENTER" and grel == header:GetNormalTexture(),
		"drawn on the texture we emptied, which still holds the client's own"
		.. " anchors - a header button is the whole 285px row, so a glyph"
		.. " centred on it lands in the middle of the group's name")

	-- And it survives the client repainting them, which it does on every
	-- expand, every collapse and every scroll.
	_G.SkillFrame_UpdateSkills()
	check(header:GetNormalTexture():GetTexture() == 0
		and header.__aetherGlyph:GetText() == "\226\136\146",
		"and the mark stays ours after the client repaints the list")

	check(_G.ReputationHeader1.__aetherGlyph ~= nil,
		"the reputation tree's headers get the same treatment")

	-- A SCROLL BAR HAS TO SAY IT SCROLLS. A list you can scroll with no visible
	-- sign of it reads as a list that ends where its rows stop.
	local sb = _G.SkillListScrollFrameScrollBar
	check(sb.__aetherTrack ~= nil,
		"a scroll bar keeps a visible rail, not just a thumb")
	local _, _, _, thumbAlpha = sb:GetThumbTexture():GetVertexColor()
	check(thumbAlpha and thumbAlpha > 0.3,
		"with a thumb you can actually see against the glass (" .. tostring(thumbAlpha) .. ")")

	-- "ALL" governs every group in the tree, so it belongs at the head of them,
	-- on the left. The client hangs it off a stone tab out to the right, which
	-- reads as a sibling of the groups rather than their parent.
	local allBtn = _G.SkillFrameCollapseAllButton
	local allPt, allRel, allRelPt, _, allY = allBtn:GetPoint(1)
	check(allPt == "BOTTOMLEFT" and allRel == _G.SkillTypeLabel1 and allRelPt == "TOPLEFT",
		"the All control sits above the first group and shares its left edge,"
		.. " which is what makes it read as their parent")
	check(_G.SkillFrameExpandTabLeft:GetTexture() == 0,
		"and the stone tab it used to hang off is cleared")
	check(_G.CharacterNameText._aetherStyle == "pnTitle",
		"the character's name is re-roled")

	-- THE INSIDE LETTERING. A window in our glass with the client's own font in
	-- every row of it is half a skin.
	local statLabel = _G.CharacterStatFrame1Label
	local labelFont, labelSize, labelFlags = statLabel:GetFont()
	check(labelFont and labelFont:find("Outfit", 1, true) ~= nil,
		"a stat row is in our lettering (" .. tostring(labelFont) .. ")")
	check(labelSize == 10,
		"AT THE CLIENT'S OWN SIZE (" .. tostring(labelSize) .. ") - these sit in"
		.. " rows it measured, so a size of ours reflows somebody else's window")
	check(labelFlags == "", "and unoutlined like the rest of the window")

	-- Nested one deeper, because the client nests these.
	local nestedFont, nestedSize = _G.CharacterStatFrame1StatText:GetFont()
	check(nestedFont and nestedFont:find("Outfit", 1, true) and nestedSize == 12,
		"including the ones a level down inside it (" .. tostring(nestedSize) .. ")")

	-- THE MAIN MENU. Its shell was in glass while every button inside it stayed
	-- a red Blizzard plate, which is the worst of both.
	local opt = _G.GameMenuButtonOptions
	check(opt.__aetherSkin ~= nil, "the main menu's buttons are ours as well")
	check(opt:GetNormalTexture():GetTexture() == 0, "with their own plate cleared")
	check(opt:GetFontString()._aetherStyle ~= nil, "and their lettering re-roled")

	-- Named nowhere: the client's set of these changes between builds, so the
	-- frame is asked what it has.
	check(_G.GameMenuButtonQuit.__aetherSkin ~= nil,
		"every one of them, however many the build happens to have")

	-- ITS TITLE IS SOMEWHERE ELSE. Anything on the shared dialog template keeps
	-- the title inside a Header child, with the ornate stone plate as that
	-- header's BG - not in a global $parentTitleText like the older frames.
	local gmHeader = _G.GameMenuFrame.Header
	check(gmHeader.BG:GetTexture() == 0,
		"the menu's stone title bar is cleared - it hangs off a Header child, so"
		.. " a strip that only knows Border and Bg leaves it standing")
	check(gmHeader.Text._aetherStyle == "pnTitle",
		"and its title is found there and re-roled, rather than missed for want"
		.. " of a $parentTitleText")

	-- That header straddles the frame's top edge ON PURPOSE, so the stone plate
	-- can overhang it. Take the plate away and the words hang over the rim.
	local htPt, htRel, htRelPt, _, htY = gmHeader.Text:GetPoint(1)
	check(htPt == "TOP" and htRel == _G.GameMenuFrame and htRelPt == "TOP" and htY < 0,
		"and it is brought inside the window (y=" .. tostring(htY) .. ") rather"
		.. " than left hanging over the top edge where the plate used to be")

	check(_G.SkillTypeLabel1:GetFontString()._aetherStyle ~= nil,
		"a skill tree's collapse header is re-roled THROUGH the button - it is a"
		.. " Button carrying a string, answers SetText like a FontString, and"
		.. " has no SetFont, so handing it straight to the font setter took the"
		.. " whole module down with a nil call")

	check(not _G.SkillFrameCancelButton:IsShown(),
		"the spare Close in the middle of the skills list is gone - the corner"
		.. " already has one and two of them is one too many")

	-- INSETS. A client frame is bigger than the window you can see: its art
	-- carries wide transparent margins and it reserves room below for the tabs.
	local px, _, _, ox, oy = cf.__aetherPanel:GetPoint(1)
	check(px == "TOPLEFT" and ox ~= 0 and oy ~= 0,
		"the glass is inset to the visible window rather than the frame's full"
		.. " extent, which is what left a slab of padding down the right")

	-- TABS. Blizzard's overlap on purpose and the art hides the join; with the
	-- art gone the overlap is the only thing you can see.
	local function ShownTabs()
		local out, k = {}, 1
		while _G["CharacterFrameTab" .. k] do
			local tb = _G["CharacterFrameTab" .. k]
			if tb:IsShown() then out[#out + 1] = tb end
			k = k + 1
		end
		return out
	end

	local function RowSpill(tabs)
		for _, tb in ipairs(tabs) do
			local lb = tb:GetFontString()
			if lb and lb:GetStringWidth() > tb:GetWidth() - 6 then
				return lb:GetText() .. " (" .. string.format("%.1f", lb:GetStringWidth())
					.. " in " .. string.format("%.1f", tb:GetWidth()) .. ")"
			end
		end
	end

	-- ONLY THE ONES YOU CAN SEE. The pet tab sits SECOND, between Character and
	-- Reputation, and is hidden on a character without a pet. Laying out every
	-- tab the client defined gave it a slot of its own, and the row had a hole
	-- in it exactly one tab wide with nothing in it.
	local shown = ShownTabs()
	check(#shown == 4 and not _G.CharacterFrameTab2:IsShown(),
		"the hidden pet tab is left out of the row (" .. #shown .. " of 5 placed)")

	local t1, t2 = shown[1], shown[2]
	local tp, trel, _, chosenGap = t2:GetPoint(1)
	check(tp == "LEFT" and trel == t1,
		"and each tab chains off the one before it IN THE ROW rather than in the"
		.. " client's numbering, which is where that hole came from")

	-- ONE WIDTH FOR ALL OF THEM. Sizing each to its own word leaves the strip
	-- sprung: "Character" is half again the width of "Skills", so the space
	-- between the pills lands differently at every join.
	local w1, uneven = t1:GetWidth(), nil
	for i, tb in ipairs(shown) do
		if math.abs(tb:GetWidth() - w1) > 0.01 then
			uneven = "#" .. i .. " " .. string.format("%.1f", tb:GetWidth())
		end
	end
	check(uneven == nil,
		"every tab is the same width (" .. string.format("%.1f", w1) .. ")"
		.. (uneven and (" - " .. uneven) or ""))

	local _, tabSize, tabFlags = t1:GetFontString():GetFont()
	check(tabFlags == "",
		"a tab's label is our own type and unoutlined (" .. tostring(tabFlags)
		.. " at " .. tostring(tabSize) .. ") - on a FILLED tab a black stroke"
		.. " around dark type on a light fill reads as a sticker")

	local spilled = RowSpill(shown)
	check(spilled == nil,
		"no label is wider than the tab it sits in" .. (spilled and (": " .. spilled) or ""))

	-- LEFT-ALIGNED, and it used to be centred.
	--
	-- A row of tabs is a list of places you can go, and a list starts at the
	-- left edge of the thing it belongs to - the same edge everything else in
	-- the window starts at. Centred, the row moved every time a tab appeared or
	-- went away: a hunter's pet tab arriving slid Character, Skills and
	-- Reputation sideways under the cursor.
	local total = w1 * #shown + chosenGap * (#shown - 1)
	local insL, insR = 10, -30
	local visible = cf:GetWidth() + insR - insL
	local _, _, _, startX = t1:GetPoint(1)
	local leftAir = startX - insL
	check(math.abs(leftAir - 16) < 0.5,
		"and the row starts at the left edge rather than floating in the middle"
		.. " (" .. string.format("%.1f", leftAir) .. " in)")
	check(total <= visible + 0.5,
		"inside it (" .. string.format("%.1f", total) .. " of "
		.. string.format("%.1f", visible) .. ")")

	-- AND WITH A PET, WHICH IS FIVE. Every check above this ran on the four a
	-- character without one has, so the row that actually overhung in game -
	-- Character, Pet, Reputation, Skills, Honor - was the one arrangement
	-- nothing here had ever laid out.
	do
		_G.CharacterFrameTab2:Show()
		fire("PLAYER_ENTERING_WORLD")

		local five = ShownTabs()
		check(#five == 5, "a hunter's sheet has five tabs (" .. #five .. ")")

		local _, _, _, gap5 = five[2]:GetPoint(1)
		local total5 = five[1]:GetWidth() * #five + gap5 * (#five - 1)
		local _, _, _, start5 = five[1]:GetPoint(1)

		-- HOW FAR OVER, against how far the window may give. That is the whole
		-- decision: the layout spends padding, then the gap, then a point or two
		-- of lettering, and whatever is still over is taken out of the glass -
		-- up to a cap, past which the row overhangs and that is the honest
		-- answer. Five tabs went past that cap, which is what was on screen.
		--
		-- The cap is named here rather than read, deliberately: a test that asks
		-- the module what its own limit is cannot notice the limit being wrong.
		local TAB_GROW_MAX, TAB_EDGE = 48, 16
		local visible5 = cf:GetWidth() + insR - insL
		local over = total5 + TAB_EDGE * 2 - visible5

		check(RowSpill(five) == nil,
			"no label is wider than its tab with five of them"
			.. (RowSpill(five) and (": " .. RowSpill(five)) or ""))
		check(over <= TAB_GROW_MAX + 0.5,
			"and the row of five is within what the window may give up ("
			.. string.format("%.1f", over) .. " over, cap " .. TAB_GROW_MAX .. ")")

		_G.CharacterFrameTab2:Hide()
		fire("PLAYER_ENTERING_WORLD")
	end

	-- A window too narrow for the words at any padding we can give up. The row
	-- has to stay inside it and the labels inside their pills, which is the
	-- path the clamp exists for - at full width the padding alone absorbs it
	-- and the clamp never runs.
	--
	-- The number is chosen to force the LAST rung of the gap, and it had to come
	-- down when the tab font did: a smaller word needs a narrower window before
	-- the gap is what is left to give, and 350 was no longer tight enough to
	-- prove anything.
	local fullWidth = cf:GetWidth()
	cf:SetWidth(320)                                -- a few pixels short, as it goes
	fire("PLAYER_ENTERING_WORLD")

	local tightTabs = ShownTabs()
	local tightSpill = RowSpill(tightTabs)
	local _, _, _, tightGap = tightTabs[2]:GetPoint(1)

	local tight = 0
	for _, tb in ipairs(tightTabs) do tight = tight + tb:GetWidth() end
	tight = tight + tightGap * (#tightTabs - 1)

	check(tightGap == 2,
		"squeezed into a narrow window the gap gives way first (" .. tightGap .. ")")

	-- And when there is nothing of ours left to give, the WINDOW gives: a few
	-- pixels of glass either side costs nothing and beats a row hanging over
	-- the edge of it.
	local grownRight
	for pi = 1, 4 do
		local pt, _, _, px = cf.__aetherPanel:GetPoint(pi)
		if pt == "BOTTOMRIGHT" then grownRight = px end
	end
	check(grownRight and grownRight > -30,
		"and after that the window widens to hold the row (right edge "
		.. string.format("%.1f", grownRight or -30) .. " from -30)")
	check(tight + 32 <= 350 + (grownRight or -30) - 10 + 0.5,
		"which is then wide enough for it (" .. string.format("%.1f", tight) .. ")")

	-- Then, and only then, a point or two of the lettering.
	local baseSize = (A.Media.style["tbCardTitle"] or {})[2]
	local lettering = _G.CharacterFrameTab1Text._aetherSize
	check(lettering ~= nil and baseSize and lettering < baseSize,
		"and after that the lettering gives a point (" .. tostring(lettering)
		.. " from " .. tostring(baseSize) .. ") - a shade smaller reads fine,"
		.. " three dots in place of three letters does not")

	-- The words survive. Shortening "Character" to "Charac..." trades three
	-- letters for three dots and tells the player less than the word did.
	local shortened
	for _, tb in ipairs(tightTabs) do
		local lb = tb:GetFontString()
		if lb and lb.GetWidth and (lb:GetWidth() or 0) > 0 then
			shortened = lb:GetText()
		end
	end
	check(shortened == nil,
		"and no word is truncated to make it fit" ..
		(shortened and (": " .. shortened) or "") .. " - the padding gives way,"
		.. " then the gap, and after that the row is simply wider than the"
		.. " window and says so")
	check(tightSpill == nil, "with every label still inside its own pill")

	cf:SetWidth(fullWidth)
	fire("PLAYER_ENTERING_WORLD")

	-- AND IT HAS TO STAY FITTED. The client re-sizes its own tabs on show and
	-- on every click, straight over anything we set. A row that is only correct
	-- until the player touches it is not correct.
	local fitted = t2:GetWidth()
	_G.PanelTemplates_TabResize(t2, 24)
	check(t2:GetWidth() == fitted,
		"the client re-sizing a tab does not undo the fit (" .. t2:GetWidth()
		.. ") - it does this on show and on every tab click, so a width set"
		.. " once at dress time lasts until the player touches the window")

	local tpt1, trel1, trelP1, tx1 = t1:GetPoint(1)
	check(tpt1 == "BOTTOMLEFT" and trelP1 == "BOTTOMLEFT" and trel1 == cf,
		"the row is anchored by its own bottom-left corner to the frame's ("
		.. tostring(tpt1) .. " -> " .. tostring(trelP1) .. " x=" .. tostring(tx1)
		.. ") - the client anchors this tab by its CENTRE, so keeping its point"
		.. " and overwriting only the x reads 18 as 'put the middle here' and"
		.. " hangs half the tab off the side of the screen")

	-- The client's own placement is still remembered, because off has to put
	-- the tab back where it found it.
	check(t1.__aetherAnchor and t1.__aetherAnchor[1] == "CENTER",
		"while the client's own anchor is still recorded for the way back")

	-- The client marks the OPEN tab by disabling it, which reads backwards
	-- until you know it.
	-- Selecting through the CLIENT'S OWN function, which moves the label up
	-- into the raised part of its stone art on the way.
	_G.PanelTemplates_SelectTab(t1)
	_G.PanelTemplates_UpdateTabs(cf)

	local lp, lrel, lrelP, lx, ly = t1:GetFontString():GetPoint(1)
	check(lp == "CENTER" and lrelP == "CENTER" and lx == 0 and ly == 0,
		"the selected tab's label stays in the middle of its pill (y="
		.. tostring(ly) .. ") - the client nudges it up on every selection,"
		.. " which is right for raised stone and wrong for a flat pill")

	fire("PLAYER_ENTERING_WORLD")
	-- FILLED, the way the chat's selected tab is: dark type on the accent,
	-- inverted from everything else on screen. A tab that was merely brighter
	-- than its neighbours read as hovered rather than as the one you are on.
	check(t1.__aetherTab._fillColor == A.Palette.c.accent
		and t2.__aetherTab._fillColor ~= A.Palette.c.accent,
		"the open tab is FILLED and the rest are not - brighter alone reads as"
		.. " hovered, and the inversion is the whole signal")
	t1:Enable()

	-- SCALE. Every other frame of ours is drawn at profile.scale.
	local wasScale = A.db.profile.scale
	A.db.profile.scale = 1.2
	fire("PLAYER_ENTERING_WORLD")
	check(cf:GetScale() == 1.2,
		"the window honours profile.scale, rather than being the one thing on"
		.. " screen still at the client's size")

	-- But not below a floor. Everything inside these windows is the client's
	-- own art at a fixed pixel size - the paper doll, the item icons, its stat
	-- rows - and below about this it stops being readable rather than merely
	-- small. A profile scale that suits our HUD is not automatically one that
	-- suits a Blizzard window.
	A.db.profile.scale = 0.5
	fire("PLAYER_ENTERING_WORLD")
	check(cf:GetScale() == 0.85,
		"and never shrinks past the floor (" .. cf:GetScale() .. " at a profile"
		.. " scale of 0.5)")

	A.db.profile.scale = wasScale
	fire("PLAYER_ENTERING_WORLD")

	-- NOT A WINDOW. The old FriendsFrame XML still defines a GuildFrame pane -
	-- setAllPoints, inside the social window - and the panel list named it as a
	-- window of its own, so it got glass behind a pane that already had some and
	-- a scale of its own inside a frame already scaled. The guild button on this
	-- client opens Communities; nothing opens that pane at all.
	do
		local pane = CreateFrame("Frame", "GuildFrame", _G.FriendsFrame)
		pane:SetAllPoints(_G.FriendsFrame)
		fire("PLAYER_ENTERING_WORLD")
		check(pane.__aetherPanel == nil,
			"a pane that happens to carry a window's name is not dressed as one")
	end

	-- LOAD ON DEMAND. Half of these do not exist at login; they arrive with
	-- their own addon the first time you open them, and a list walked once at
	-- startup would never see them.
	check(_G.WorldMapFrame == nil, "the map is not loaded yet")
	_G.__loadPanelAddon("WorldMapFrame")
	fire("ADDON_LOADED", "Blizzard_WorldMap")
	check(_G.WorldMapFrame.__aetherPanel ~= nil,
		"and is skinned when its addon turns up, rather than only at login")

	-- Off hands the client its windows back.
	A:SetModuleEnabled("panels", false)
	check(cf.__aetherPanel == nil and cf.__stone:GetTexture() == "stone-border"
		and cf.Bg.__fill:GetTexture() == "panel-background",
		"switching it off returns the window the client drew, background and all")
	check(close:GetNormalTexture():GetTexture() == "close-up"
		and close.__aetherX == nil,
		"and its own close button with it")
	A:SetModuleEnabled("panels", true)
	check(cf.__aetherPanel ~= nil, "and on again re-dresses it")
end

print("== panels: the spellbook, which spells nothing the way the others do ==")
do
	local sb = _G.SpellBookFrame
	fire("PLAYER_ENTERING_WORLD")

	-- ITS TITLE IS NOT $parentTitleText. Nothing errors when a skin looks for
	-- one and does not find it; the window simply keeps the client's lettering
	-- and the skin reports success.
	check(_G.SpellBookTitleText._aetherStyle == "pnTitle",
		"the title is found under the client's own name for it and re-roled")

	local tPt, tRel, tRelPt, _, tY = _G.SpellBookTitleText:GetPoint(1)
	check(tPt == "TOP" and tRel == sb and tRelPt == "TOP" and tY < 0,
		"and brought to the top of the glass (y=" .. tostring(tY) .. ") - the"
		.. " client put it six pixels right of centre because the page it was"
		.. " printed on is not centred in the frame either")

	local close = _G.SpellBookCloseButton
	check(close.__aetherX and close:GetNormalTexture():GetTexture() == 0,
		"its close button is found under ITS own name and gets our mark, rather"
		.. " than being missed for want of a $parentCloseButton")
	local cPt, cRel, cRelPt = close:GetPoint(1)
	check(cPt == "TOPRIGHT" and cRel == sb and cRelPt == "TOPRIGHT",
		"and moves to the corner (" .. tostring(cPt) .. ") - the client sat it 44"
		.. " in and 25 down, in the middle of a stone rim that is now gone")

	-- THE SPELLS. Icon in a region, ring as the normal texture, parchment disc
	-- behind both: one sweep would blank the icon and the other would leave the
	-- disc, and only knowing which is which gets it right.
	local b1 = _G.SpellButton1
	check(b1.__aetherSlot == true, "a spell sits in one of our cells")
	check(_G.SpellButton1IconTexture:GetTexture() == "spell-icon-1",
		"AND THE SPELL IS STILL IN IT - the icon is a region of the button, so a"
		.. " strip takes the picture and leaves the cell correctly empty")
	check(b1.EmptySlot:GetTexture() == 0,
		"with the parchment disc behind it cleared - that one is not a state"
		.. " texture, so clearing the button's four would leave it drawing")
	check(b1:GetNormalTexture():GetTexture() == 0, "and the ring around it gone")
	check(b1.SpellName._aetherStyle ~= nil and b1.SpellSubName._aetherStyle ~= nil,
		"the spell's name and rank are in our lettering")

	-- The client repaints these on every refresh - on open, on a tab click, on
	-- learning a spell - and puts its own white highlight square back with them.
	b1:UpdateButton()
	check(b1:GetHighlightTexture():GetTexture() == 0,
		"and the client's own highlight square does not come back on the next"
		.. " refresh, which is every time the book is opened or turned")
	local nr, ng, nb = b1.SpellName:GetTextColor()
	local ink = A.Palette.c.text
	check(nr == ink[1] and ng == ink[2] and nb == ink[3],
		"nor its own gold on the name (" .. string.format("%.2f", nr) .. ")")

	-- THE SCHOOL TABS. Here the icon IS the normal texture: the client calls
	-- SetNormalTexture with the school's image every time it refreshes them.
	local st1, st2 = _G.SpellBookSkillLineTab1, _G.SpellBookSkillLineTab2
	check(st1.__aetherSlot == true, "a school tab wears the same cell")
	check(st1.__plate:GetTexture() == 0,
		"with the 64px stone plate behind a 32px button cleared")

	sb:UpdateSkillLineTabs()
	check(st1:GetNormalTexture():GetTexture() == "Interface\\Icons\\Spell_Frost_FrostBolt02",
		"AND THE SCHOOL'S ICON SURVIVES - it is the normal texture, so the sweep"
		.. " that clears a button's art blanks the picture the player is looking"
		.. " for and leaves a column of empty cells")
	check(st1:GetCheckedTexture():GetTexture() == "Interface\\Buttons\\CheckButtonHilight",
		"and so does the mark saying which school you are on")

	local sPt, sRel, sRelPt = st1:GetPoint(1)
	check(sPt == "TOPRIGHT" and sRel == sb and sRelPt == "TOPRIGHT",
		"the column hangs off the glass's own right edge (" .. tostring(sPt) .. ")")
	local s2Rel, s2Y = select(2, st2:GetPoint(1)), select(5, st2:GetPoint(1))
	check(s2Rel == st1 and s2Y == -6,
		"and closes up under it (" .. tostring(s2Y) .. ") - Blizzard's 17 is the"
		.. " clearance its stone needed, and without the stone it reads as a"
		.. " column of unrelated icons")

	-- THE PAGE TURNER. Both arrows are engraved in the art; take the art off
	-- without putting something there and it is two invisible squares.
	local prev = _G.SpellBookPrevPageButton
	check(prev:GetNormalTexture():GetTexture() == 0 and prev.__aetherMark
		and (prev.__aetherMark:GetText() or "") ~= "",
		"the page turner keeps a mark of ours where its engraved arrow was")

	local pr, pg, pb = _G.SpellBookPageText:GetTextColor()
	check(_G.SpellBookPageText._aetherStyle ~= nil and (pr + pg + pb) > 1,
		"and the page number is readable (" .. string.format("%.2f", pr) .. ","
		.. string.format("%.2f", pg) .. ") - the client prints it in near-black"
		.. " because it is printing it on parchment")

	local ranks = _G.ShowAllSpellRanksCheckbox
	check(ranks.__aetherCheck ~= nil, "the spell-ranks box is ours")

	-- A BADGE, NOT A PILL. A pill whose width equals its height is a circle made
	-- of two cap slices meeting in the middle with nothing between them - the
	-- seam Glass's own header warns about - and it came back on screen as a
	-- jagged ring. The tooltip's level chip and Zen's corner glyph both learned
	-- this before it; the shape has art authored at 64 for exactly this size.
	local chip = ranks.__aetherCheck
	check(chip.disc and chip.disc:GetTexture() == A.Media.texture.chipDisc
		and chip.ring and chip.ring:GetTexture() == A.Media.texture.chipRim,
		"and drawn as a badge - the 64px chip disc and rim - rather than a pill"
		.. " squeezed square, whose two caps meet in the middle with a"
		.. " zero-width centre between them")

	local lPt, lRel, lRelPt, lx = _G.ShowAllSpellRanksCheckboxText:GetPoint(1)
	check(lPt == "LEFT" and lRel == ranks and lRelPt == "RIGHT" and lx >= 4,
		"with its label off the edge of it (x=" .. tostring(lx) .. ") - the"
		.. " client anchors that flush, which clears its own small square inside"
		.. " a larger transparent button but touches a box of ours that fills it")

	check(ranks:GetCheckedTexture():GetTexture() == "checkbox-tick",
		"AND ITS TICK SURVIVES - the tick is a region of the button like the box"
		.. " around it, so a plain strip takes both and leaves a check box that"
		.. " never looks checked whatever the client thinks its state is")

	-- THE BOOK'S OWN TABS. All three start hidden and the client shows the ones
	-- that apply from its own update, so the first dress sees an empty row. A
	-- layout that gives up on an empty row without asking to be told when a tab
	-- appears never runs at all.
	local bt1, bt2 = _G.SpellBookFrameTabButton1, _G.SpellBookFrameTabButton2
	check(bt1.__aetherTab == nil, "the book's tabs start hidden, so none is placed")

	sb:Update()
	check(bt1.__aetherTab ~= nil and bt2.__aetherTab ~= nil,
		"and are laid out when the client shows them - from the client's own"
		.. " update, not from a re-dress nobody would have run")
	check(math.abs(bt1:GetWidth() - bt2:GetWidth()) < 0.01,
		"in one even row (" .. string.format("%.1f", bt1:GetWidth()) .. ")")

	local hl, hr, ht, hb = bt1:GetHitRectInsets()
	check(hl == 0 and hr == 0 and ht == 0 and hb == 0,
		"AND STILL CLICKABLE. The client keeps the clicks 13 in from the top of"
		.. " a 64px tab and 15 up from the bottom; re-size that tab to 26 and the"
		.. " two insets meet, so it draws, highlights, reads correctly and does"
		.. " nothing at all when you click it")

	check(bt1.__aetherTab._fillColor == A.Palette.c.accent
		and bt2.__aetherTab._fillColor ~= A.Palette.c.accent,
		"and the book you are in is the filled one")

	local bPt, bRel, bRelPt = bt1:GetPoint(1)
	check(bPt == "BOTTOMLEFT" and bRel == sb and bRelPt == "BOTTOMLEFT",
		"anchored by its own corner (" .. tostring(bPt) .. ")")

	-- AND WITH NO CLICK INVOLVED. Enabling a tab moves its label up into the
	-- raised part of art that is no longer there, and the client enables and
	-- disables these from its own update - which runs when a spell is learned
	-- while the book is open, with nothing of ours prompted to answer it.
	sb:Update()
	local lPt, _, lRelPt, lx, ly = bt1:GetFontString():GetPoint(1)
	check(lPt == "CENTER" and lRelPt == "CENTER" and lx == 0 and ly == 0,
		"the selected tab's label is put back in the middle of its pill (y="
		.. tostring(ly) .. ") after the client's own rebuild")

	-- OFF AND ON AGAIN. Switching the module off hands the client every texture
	-- back, which is the point of it - and switching it on runs the dressing a
	-- second time over a frame that already carries our markers. Every one of
	-- these returned early on its own marker, so the second pass stopped before
	-- it had taken back the art the first pass had just given up.
	A:SetModuleEnabled("panels", false)
	check(b1.EmptySlot:GetTexture() ~= 0 and st1.__plate:GetTexture() ~= 0,
		"off gives the spellbook its parchment and its stone back")

	A:SetModuleEnabled("panels", true)
	fire("PLAYER_ENTERING_WORLD")
	check(b1.EmptySlot:GetTexture() == 0 and st1.__plate:GetTexture() == 0
		and b1:GetNormalTexture():GetTexture() == 0,
		"and on again takes all of it off a second time, rather than stopping at"
		.. " a marker left over from the first")
	check(_G.SpellButton1IconTexture:GetTexture() == "spell-icon-1"
		and _G.ShowAllSpellRanksCheckbox:GetCheckedTexture():GetTexture() == "checkbox-tick",
		"with the spell and the tick still where they were")
end

print("== panels: the windows an NPC opens ==")
do
	fire("PLAYER_ENTERING_WORLD")

	-- THE VENDOR. A row's own regions are the empty-slot disc and the stone
	-- label plate; the item's picture is on a BUTTON INSIDE IT. Get that
	-- backwards and you blank the shop and keep the furniture.
	local row = _G.MerchantItem1
	check(_G.MerchantFrame.__aetherPanel ~= nil, "the vendor window is in glass")
	check(row.__slot:GetTexture() == 0 and row.__plate:GetTexture() == 0,
		"a row's empty-slot disc and label plate come off")
	check(row.ItemButton.__aetherSlot == true,
		"the item sits in one of our cells")
	check(_G.MerchantItem1ItemButtonIconTexture:GetTexture() == "merchant-icon-1",
		"WITH THE GOODS STILL IN IT - the picture is on the button inside the"
		.. " row, not on the row, which is what makes stripping the row safe")
	check(row.Name._aetherStyle ~= nil, "the item's name is in our lettering")

	-- The anvil IS the normal texture on these, so they go the way a school tab
	-- does rather than the way a button does.
	-- REPAIR KEEPS EVERY REGION IT HAS. Its anvil is a BORDER-layer region, not
	-- the normal texture, it is named after the button's stem rather than the
	-- button, and it is cropped out of a shared sheet by texcoords. Dressing
	-- these as icon buttons cleared the anvils and left two empty squares.
	check(_G.MerchantRepairAllButton.__aetherSkin ~= nil,
		"repair gets our surface behind it")
	check(_G.MerchantRepairAllIcon:GetTexture()
			== "Interface\\MerchantFrame\\UI-Merchant-RepairIcons",
		"and keeps its anvil, which is a region of its own and not this"
		.. " button's normal texture")

	check(_G.MerchantPrevPageButtonText._aetherStyle ~= nil,
		"the page turner keeps its own words, re-roled - it already says Prev"
		.. " and Next, and a chevron of ours beside them said it twice")
	check(_G.MerchantFrameTab1.__aetherTab ~= nil,
		"and its two tabs are laid out like every other window's")

	-- THE QUEST GIVER: four panels of one window, one shown at a time.
	local detail = _G.QuestFrameDetailPanel
	check(_G.QuestFrame.__aetherPanel ~= nil, "the quest window is in glass")
	check(select(1, detail:GetRegions()):GetTexture() == 0,
		"and every one of its four panels loses its parchment")
	check(_G.QuestNpcNameFrameText._aetherStyle == "pnTitle",
		"who you are talking to is in our lettering")
	check(_G.QuestFrameAcceptButton.__aetherSkin ~= nil, "its buttons are ours")

	-- ONE BUTTON SHAPE, AND IT IS A ROUNDED RECTANGLE.
	--
	-- There were three versions of this: a pill behind a client button, a pill
	-- behind a client tab, and a pill built as a button in the quest log. All
	-- three drew a CAPSULE, because CreatePill was the nearest thing to hand -
	-- and a capsule's two caps come out of a 256-texel texture, so at button
	-- height they are minified more than ten times and the client does not
	-- mipmap. Same crunch as the tooltip badge and the check box.
	check(_G.QuestFrameAcceptButton.__aetherSkin._kind == "panel",
		"and drawn as a rounded rectangle at the deck's own radius rather than"
		.. " a capsule (" .. tostring(_G.QuestFrameAcceptButton.__aetherSkin._kind)
		.. ")")
	check(_G.MerchantFrameTab1.__aetherTab._kind == "panel",
		"a tab is the same surface in a different state, not a second kind")

	-- LEFT-ALIGNED, and this is the window that can tell. The character sheet's
	-- four tabs happen to total exactly the width that centring would give
	-- them, so it agreed with both rules; two tabs in a 336-wide window do not.
	local _, _, _, mtx = _G.MerchantFrameTab1:GetPoint(1)
	check(mtx and math.abs(mtx - 16) < 0.5,
		"the vendor's tab row starts at the left edge (" .. tostring(mtx)
		.. ") - centred, a row slides sideways every time a tab comes or goes")
	-- NOT A CELL. These are wide rows - an icon at one end, the item's name
	-- beside it - and a cell sizes its picture to the whole button, so the icon
	-- came out stretched the width of the row.
	check(_G.QuestProgressItem1.__aetherSlot == nil,
		"what the quest wants from you is NOT dressed as a cell - the row is"
		.. " wide and a cell would stretch the icon across all of it")
	check(_G.QuestProgressItem1IconTexture:GetTexture() == "quest-item-1"
		and _G.QuestProgressItem1:GetNormalTexture():GetTexture() == 0,
		"its border comes off and the icon is left where the client drew it")

	-- GOSSIP, on the modern template - so the shell is the shared one and what
	-- is left is the parchment behind the words.
	local panel = _G.GossipFrame.GreetingPanel
	check(select(1, panel:GetRegions()):GetTexture() == 0,
		"the gossip window's parchment comes off")
	check(panel.GoodbyeButton.__aetherSkin ~= nil, "its goodbye is one of ours")
	check(select(1, panel.ScrollBar.Track:GetRegions()):GetTexture() == 0
		and panel.ScrollBar.Back:GetNormalTexture():GetTexture() == 0,
		"and its scroll bar is taken apart, being a frame of frames like the"
		.. " community list's rather than a slider with regions on it")

	-- INK CHOSEN FOR PARCHMENT. A quest's text and a gossip option are near
	-- black because that is what reads on paper; on glass they are a smudge.
	-- The rule everywhere else - the client's colours are meant, leave them -
	-- is right for a window whose background we did not change and wrong here.
	local ink = A.Palette.c.text
	local qr, qg, qb = _G.QuestFrameDetailPanelInk:GetTextColor()
	check(qr == ink[1] and qg == ink[2] and qb == ink[3],
		"the quest's text is lifted off the paper it was printed for ("
		.. string.format("%.2f", qr) .. ")")

	-- AND ONLY THE DARK. The test is the colour rather than the window, so a
	-- heading that was gold because gold means something stays gold.
	local gr, gg = _G.QuestFrameDetailPanelGold:GetTextColor()
	check(gr == 1 and gg == 0.82,
		"while a gold heading is left exactly as the client set it ("
		.. string.format("%.2f,%.2f", gr, gg) .. ")")

	-- THE GOSSIP ROWS ARE POOLED, and re-acquired every time the list is
	-- rebuilt - which is on open and on every option you pick. Dressed once,
	-- they are right until you click something.
	local row = panel.ScrollBox:GetFrames()[1]
	local rr = row:GetFontString():GetTextColor()
	check(rr == ink[1], "a gossip option is lifted too")

	_G.GossipFrame:Update()
	rr = row:GetFontString():GetTextColor()
	check(rr == ink[1],
		"and stays lifted after the list is rebuilt, which is what picking an"
		.. " option does (" .. string.format("%.2f", rr) .. ")")
	check(row.Icon:GetTexture() == "Interface\\QuestFrame\\UI-Quest-BulletPoint",
		"with its bullet still on it")

	-- AND SO IS A QUEST TITLE, which keeps its string in a region of its own
	-- rather than answering GetFontString. Naming the string per shape found
	-- nothing on this row, so it kept our lettering from the first pass and got
	-- the client's ink back on every rebuild.
	local quest = panel.ScrollBox.__quest
	check(quest.__fs._aetherStyle ~= nil, "a quest title is in our lettering")

	-- AND ITS INK IS INSIDE THE STRING. The title comes through
	-- NORMAL_QUEST_DISPLAY as |cff000000<name>|r, so the font string reports
	-- white while drawing black. Lifting the font string's colour changed
	-- nothing you could see.
	local qtext = quest.__fs:GetText()
	check(not qtext:find("|cff000000", 1, true),
		"with the black baked into it rewritten (" .. tostring(qtext) .. ")")
	check(qtext:find("Verog the Dervish", 1, true) ~= nil,
		"and the title itself still in there")
	check(quest.Icon:GetTexture() == "Interface\\GossipFrame\\AvailableQuestIcon",
		"with the quest mark still on it")

	-- A TITLE IN A BAND KEEPS THE CLIENT'S SIZE. The modern template gives it a
	-- TitleContainer twenty pixels tall, and our own title role at nineteen
	-- fills it corner to corner and overhangs the ends.
	local _, gossipSize = _G.GossipFrameTitleText:GetFont()
	local _, charSize = _G.CharacterFrameTitleText:GetFont()
	check(gossipSize < charSize,
		"the gossip window's title keeps the size the client measured its band"
		.. " for (" .. tostring(gossipSize) .. " vs the old windows' "
		.. tostring(charSize) .. ")")
end

print("== panels: the trainer, whose rows are two things at once ==")
do
	_G.__loadPanelAddon("ClassTrainerFrame")
	fire("ADDON_LOADED", "Blizzard_TrainerUI")

	local tf = _G.ClassTrainerFrame
	check(tf.__aetherPanel ~= nil, "the trainer is in glass")

	-- THE SAME ELEVEN BUTTONS ARE BOTH KINDS. The client fills them from one
	-- list: a heading gets a plus or a minus as its normal texture, a spell
	-- gets ClearNormalTexture. So which a row is has to be read on every
	-- refresh, from the mark itself, BEFORE ours replaces it.
	local head, spell = _G.ClassTrainerSkill1, _G.ClassTrainerSkill2
	check(head.__aetherGlyph ~= nil and head.__aetherGlyph:IsShown(),
		"a heading gets our own disclosure mark")
	check(head:GetNormalTexture():GetTexture() == 0,
		"with the client's stone plus or minus cleared")
	check(spell.__aetherGlyph == nil or not spell.__aetherGlyph:IsShown(),
		"and a SPELL gets none - it is the same button, and a mark on it would"
		.. " say the row folds when it does not")

	check(head:GetFontString()._aetherStyle ~= nil, "the row is in our lettering")
	local hr = head:GetFontString():GetTextColor()
	check(hr == A.Palette.c.text[1],
		"lifted off the parchment it was printed for")

	check(_G.ClassTrainerSkillIcon.__aetherSlot == true,
		"the spell you are being sold sits in a cell - this one IS square,"
		.. " unlike the quest giver's wide rows")
	check(_G.ClassTrainerTrainButton.__aetherSkin ~= nil, "and Train is ours")

	-- TRAIN ALL IS ANONYMOUS. It carries no name at all - only its label is
	-- named, as ClassTrainerFrameText - so the three push buttons are found by
	-- their three-slice shape rather than by a list of names that cannot
	-- include this one.
	check(tf.__trainAll.__aetherSkin ~= nil,
		"and so is Train All, which has no name to be listed under")
	check(tf.__trainAll.Left:GetTexture() == 0,
		"with its three slices of client stone taken off")
	check(tf.__trainAll.__fs._aetherStyle ~= nil, "and its label in our lettering")

	-- THE FILTER. Its holder comes off, its arrow stays because nothing of ours
	-- says "this opens" better at 24 pixels - but tinted, since the client's is
	-- gold stone and gold on our glass reads as a colour that means something.
	local filter = tf.FilterDropdown
	check(filter.__aetherSkin ~= nil, "the filter is in one of our pills")
	check(filter.Background:GetTexture() == 0, "with its stone holder taken off")
	local ar = filter.Arrow:GetVertexColor()
	check(ar == A.Palette.c.textDim[1],
		"and its arrow inked like the rest of our marks ("
		.. string.format("%.2f", ar) .. ")")

	-- AND PULLED INSIDE THE GLASS. 44 in from the frame's right edge sat inside
	-- the parchment's margin and outside ours, which stops 28 short.
	local point, _, _, x = filter:GetPoint()
	check(point == "TOPRIGHT" and x > -44,
		"and moved in off the frame's edge, where the glass stops (" .. tostring(x) .. ")")

	-- THE ARROW IS REPLACED, NOT TINTED. The client's is a blue-grey stone
	-- BUTTON, and a vertex colour multiplies that rather than replacing it - so
	-- tinting it left a blue stone button sitting in one of our pills.
	check(filter.Arrow:GetTexture() == A.Media.texture.chevron,
		"its arrow is our own chevron, which points down unrotated")
	check(filter.Arrow:GetWidth() == 10,
		"at a mark's size rather than the client's 24px control")

	-- AND THE LIST IT OPENS IS A WINDOW OF ITS OWN. Not a child of the dropdown
	-- and not built until the first click, so nothing on the trainer's pass can
	-- reach it - which is why it stayed black stone inside a skinned window.
	filter:OpenMenu()
	local menu = filter.menu
	check(menu ~= nil and menu.__aetherPanel ~= nil, "the menu it opens is in glass")
	check(menu.__bg:GetTexture() == 0 and menu.__fill:GetTexture() == 0,
		"with the ornate plate and the black fill under it both taken off")
	-- THROUGH A FONT OBJECT, because the menu forbids SetFont on its own
	-- strings - the mock raises if it is called, so reaching this at all means
	-- the locked path was taken.
	check(menu.__firstRow.__fontObject ~= nil,
		"and its rows re-roled through a font object, which the menu does allow")
	check(menu.__firstRow._aetherStyle ~= nil, "so they are in our lettering")

	-- AND THE ARROW SURVIVES BEING CLICKED. The client re-atlases it and
	-- re-colours the text on every state change.
	filter:OnButtonStateChanged()
	check(filter.Arrow:GetTexture() == A.Media.texture.chevron
		and filter.Arrow:GetWidth() == 10,
		"the chevron goes back after the client redraws the control")
	check(filter.Text:GetTextColor() == A.Palette.c.text[1],
		"and so does our ink on its label")
	check(_G.ClassTrainerExpandTabLeft:GetTexture() == 0,
		"the little stone tab the All control hangs off is cleared")

	-- AND THE ROWS SWAP KINDS. Expand a heading and the client refills all
	-- eleven from a longer list, so row one may be a spell next time and row
	-- two a heading. A mark decided once is a mark on the wrong row.
	_G.ClassTrainerFrame_Update()
	check(head.__aetherGlyph:IsShown() and head.__aetherGlyph:GetText() == "+",
		"a heading that collapsed shows a plus rather than the minus it had")
	check(spell.__aetherGlyph == nil or not spell.__aetherGlyph:IsShown(),
		"and the spell row still carries no mark after the refresh")

	-- EVERY ROW, NOT THE FIRST ELEVEN. CLASS_TRAINER_SKILLS_DISPLAYED is 11 in
	-- Blizzard's source and this client draws more, so a loop bounded by the
	-- number in the source left the rest of a mage's spell list in Friz.
	local last = _G["ClassTrainerSkill26"]
	check(last ~= nil and last:GetFontString()._aetherStyle ~= nil,
		"a row past the eleventh is in our lettering too")
	check(last:GetFontString():GetTextColor() == A.Palette.c.text[1],
		"and lifted off the parchment with the rest")

	-- The mark is read from the client's own service data. Its texture answers
	-- with a file ID here, as the client's does, so anything reading the path
	-- gets a number and decides every row is a spell.
	check(_G.ClassTrainerSkill25.__aetherGlyph ~= nil
		and _G.ClassTrainerSkill25.__aetherGlyph:IsShown(),
		"a heading below the eleventh gets its mark from the service, not the art")

	-- "All" carries a flag rather than a service index, and reading its texture
	-- instead left a plus on it with the whole tree expanded.
	local all = _G.ClassTrainerCollapseAllButton
	all.collapsed = nil
	A:GetModule("panels").Dress(tf)
	check(all.__aetherGlyph:GetText() == "\226\136\146",
		"All shows a minus while the tree is expanded ("
		.. tostring(all.__aetherGlyph:GetText()) .. ")")
	all.collapsed = 1
	A:GetModule("panels").Dress(tf)
	check(all.__aetherGlyph:GetText() == "+", "and a plus once it is collapsed")
end

print("== panels: the flight master, whose map is a region of the frame ==")
do
	local tx = _G.TaxiFrame
	tx:Show()

	check(tx.__aetherPanel ~= nil, "the flight map is in glass")

	-- THE MAP IS THE WINDOW. It is a texture region of the frame, exactly like
	-- the parchment around it, so the sweep that took the art took the map and
	-- left the flight points floating in the dark.
	check(_G.TaxiMap:GetTexture() ~= 0 and _G.TaxiMap:IsShown(),
		"the map itself survives the strip ("
		.. tostring(_G.TaxiMap:GetTexture()) .. ")")
	check(tx.__stone:GetTexture() == 0, "while the frame's own art still comes off")
	check(_G.TaxiPortrait:GetTexture() == 0,
		"and the portrait goes, having lost the ring it sat in")

	-- Named TaxiCloseButton, not TaxiFrameCloseButton, which is why this one
	-- window kept the client's red X.
	check(_G.TaxiCloseButton.__aetherX ~= nil, "its close button is ours")

	local who = _G.TaxiMerchant
	check(who._aetherStyle ~= nil and who:GetTextColor() == A.Palette.c.text[1],
		"and the flight master's name is lifted into our lettering")
end

print("== timers: breath, fatigue, and the colour that says which ==")
do
	local TMm = A:GetModule("timers")
	check(TMm ~= nil and TMm.enabled, "the timers module is on")

	local f = _G.MirrorTimer1
	check(f.__border:GetTexture() == 0 and f.__plate:GetTexture() == 0,
		"a timer's stone border and its black plate come off")
	check(f.__aetherPill ~= nil, "and glass goes behind it")

	-- THE CAPSULE IS THE FRAME. Behind the bar alone it is a sliver two pixels
	-- taller than the fill, which is a rim rather than a capsule.
	local bar = _G.MirrorTimer1StatusBar
	check(f.__aetherPill:GetParent() == f
		and f.__aetherPill:GetWidth() == f:GetWidth(),
		"the capsule covers the frame, the way the cast bar's does ("
		.. tostring(f.__aetherPill:GetWidth()) .. " of " .. tostring(f:GetWidth())
		.. ") - behind the fill alone it is a rim two pixels taller than the bar")

	-- ABOVE THE GLASS. The template lowers this bar's frame level in its own
	-- OnLoad, so a capsule put behind the frame draws over the fill - which is
	-- the bar coming back as a pale block with no capsule anywhere.
	check(bar:GetFrameLevel() > f.__aetherPill:GetFrameLevel(),
		"and the fill sits above it (" .. bar:GetFrameLevel() .. " vs "
		.. f.__aetherPill:GetFrameLevel() .. ") - the template LOWERS this bar,"
		.. " so left alone the glass is drawn over the top of it")

	-- The cast bar's layout: the word on the left, the fill beside it.
	local tPt, tRel, tRelPt = _G.MirrorTimer1Text:GetPoint(1)
	check(tPt == "LEFT" and tRel == f and tRelPt == "LEFT",
		"the word sits at the left of the capsule (" .. tostring(tPt) .. ")")
	check(_G.MirrorTimer1Text._aetherStyle == "castName",
		"in the cast bar's own lettering, because this is the same object")

	local bPt, bRel = bar:GetPoint(1)
	check(bPt == "LEFT" and bRel == _G.MirrorTimer1Text,
		"and the fill starts where the word ends rather than at a fixed offset -"
		.. " 'Feign Death' is half again the width of 'Breath', so the bar gives"
		.. " way rather than the word being clipped")
	check(bar:GetHeight() == 7,
		"at the cast bar's own height (" .. bar:GetHeight() .. ")")

	-- WHICH TIMER IT IS, IN THE COLOUR - and re-applied, because the client
	-- sets its own from MirrorTimerColors every time a timer starts. A colour
	-- set once at login is a colour you see until the first time you dive.
	MirrorTimer_Show("BREATH", 30000, 60000, 1, 0, "Breath")
	local br, bg, bb = bar:GetStatusBarTexture():GetVertexColor()
	-- POWER rather than CAST. Both are blue and the cast blue is the paler, so
	-- over bright water it came back reading as a white bar with a grey end.
	local breath = A.Palette.c.power[1]
	check(br == breath[1] and bg == breath[2] and bb == breath[3],
		"breath is our blue rather than Blizzard's (" ..
		string.format("%.2f,%.2f,%.2f", br, bg, bb) .. ")")

	-- A DIFFERENT TIMER TAKES A DIFFERENT FRAME. The client picks whichever of
	-- the three is free, so all three have to have been dressed - and the
	-- colour has to follow the KIND, not the frame.
	MirrorTimer_Show("EXHAUSTION", 30000, 60000, 1, 0, "Fatigue")
	local bar2 = _G.MirrorTimer2StatusBar
	local er, eg = bar2:GetStatusBarTexture():GetVertexColor()
	local tired = A.Palette.c.energy[1]
	check(er == tired[1] and eg == tired[2],
		"and fatigue is our yellow, on whichever of the three frames was free")

	-- Off hands the client its own back.
	A:SetModuleEnabled("timers", false)
	check(f.__border:GetTexture() == "Interface\\CastingBar\\UI-CastingBar-Border"
		and f.__aetherPill == nil,
		"switching it off returns the border the client drew")
	A:SetModuleEnabled("timers", true)
	check(_G.MirrorTimer1.__aetherPill ~= nil, "and on again re-dresses it")

	for i = 1, 3 do _G["MirrorTimer" .. i]:Hide() end
end

print("== panels: guild and communities, read off the live client ==")
do
	_G.__loadPanelAddon("CommunitiesFrame")
	fire("ADDON_LOADED", "Blizzard_Communities")

	local cf = _G.CommunitiesFrame
	check(cf.__aetherPanel ~= nil, "the guild window is in glass")

	-- THE SIDE TABS keep their picture in an Icon REGION rather than as the
	-- normal texture the spellbook's school tabs use. Assuming the spellbook's
	-- shape here would dress four empty cells and throw the icons away, and it
	-- is the kind of wrong that looks deliberate.
	local roster = cf.RosterTab
	check(roster.__aetherSlot == true, "a side tab wears one of our cells")
	check(roster.Icon:GetTexture() == "communities-icon-RosterTab",
		"WITH ITS PICTURE STILL IN IT - the icon is a region called Icon, not"
		.. " this button's normal texture, so the shape that works on the"
		.. " spellbook would blank it here")
	check(roster.__ring:GetTexture() == 0, "and the stone ring behind it gone")

	-- THREE-SLICE BUTTONS. Left, Right and Middle rather than a normal texture,
	-- so ClearButton finds nothing to clear and the plate outlives it.
	local invite = cf.InviteButton
	check(invite.__aetherSkin ~= nil, "a push button is in one of our pills")
	check(invite.Left:GetTexture() == 0 and invite.Middle:GetTexture() == 0,
		"with all three of its slices cleared, which a normal texture is not")

	-- A DROPDOWN'S ARROW IS REPLACED. It was kept once, on the grounds that it
	-- says "this opens" better than anything of ours would at that size. It
	-- does not: the atlas is a blue-grey stone BUTTON, a picture of a control
	-- rather than a mark on one, and a tint multiplies it rather than
	-- replacing it. Every dropdown gets our chevron now, this one included.
	local dd = cf.StreamDropdown
	check(dd.__aetherSkin ~= nil and dd.Background:GetTexture() == 0,
		"a dropdown's stone holder comes off")
	check(dd.Arrow:GetTexture() == A.Media.texture.chevron,
		"and its arrow is our chevron")
	check(dd.Text._aetherStyle ~= nil, "with its text re-roled")

	check(cf.CommunitiesList.FilligreeOverlay ~= nil
		and select(1, cf.CommunitiesList.FilligreeOverlay:GetRegions()):GetTexture() == 0,
		"the ornate frame around the community list is cleared - it hangs off a"
		.. " child of its own, so a strip of the list alone leaves it drawing")

	check(cf.MemberList.ShowOfflineButton.__aetherCheck ~= nil,
		"and the roster's own check box is ours")

	-- THE SCROLL BAR IS A FRAME OF FRAMES on this window - a track, a thumb and
	-- two arrows, each a child - so a strip of the bar itself finds no regions,
	-- clears nothing, and leaves the stone down the side of the list.
	local bar = cf.CommunitiesList.ScrollBar
	check(select(1, bar.Track:GetRegions()):GetTexture() == 0
		and bar.Back:GetNormalTexture():GetTexture() == 0,
		"a scroll bar is taken apart rather than swept, because nothing in one"
		.. " is a picture and every part of it is a child")

	-- THE CREST comes inside. The portrait template hangs it off the corner to
	-- overlap a stone ring that framed it - the main menu's title plate again -
	-- so with the ring gone it floats outside the window.
	local crest = cf.PortraitOverlay.Portrait
	local cPt, cRel, cRelPt, cx, cy = crest:GetPoint(1)
	check(cPt == "TOPLEFT" and cRel == cf and cx > 0 and cy < 0,
		"the guild crest is brought inside the glass (" .. tostring(cx) .. ","
		.. tostring(cy) .. ") rather than hung off the corner")
	check(crest:GetWidth() < 61,
		"and drawn smaller than the template's own size ("
		.. tostring(crest:GetWidth()) .. " from 61)")
	check(cf.PortraitOverlay.CircleMask:GetWidth() == crest:GetWidth(),
		"with its mask following it - one left where the portrait used to be"
		.. " crops a circle out of empty air")

	-- The big pane you get when you are in no guild: the client's own dark
	-- plate, and two paragraphs in the client's own lettering.
	local finder = _G.ClubFinderGuildFinderFrame
	check(select(1, finder:GetRegions()):GetTexture() == 0
		and select(1, finder.DisabledFrame:GetRegions()):GetTexture() == 0,
		"the pane on the right loses its plate")
	check(finder.DisabledFrame.Title._aetherStyle ~= nil
		and finder.DisabledFrame.Description._aetherStyle ~= nil,
		"and its heading and its paragraph are in our lettering")

	-- A PANE ARRIVES WHEN ITS TAB IS PICKED. Everything but the one you are
	-- looking at is hidden, and a window dressed once at open leaves the other
	-- three in Blizzard's stone the moment you click.
	local benefits = cf.GuildBenefitsFrame
	local art = select(1, benefits:GetRegions())
	art:SetTexture("communities-pane-art")           -- as the client repaints it

	local click = roster:GetScript("OnClick")
	check(click ~= nil,
		"a side tab is hooked - there is no update function on this window to"
		.. " wrap, and none we could name without its source, so the click is"
		.. " the only thing that says which pane is showing now")
	if click then click(roster) end

	check(art:GetTexture() == 0,
		"and a pane that comes back is taken back off, because a window dressed"
		.. " once at open leaves the other three in stone the moment you click")
end

print("== panels: the talent tree, without cutting its branches ==")
do
	_G.__loadPanelAddon("PlayerTalentFrame")
	fire("ADDON_LOADED", "Blizzard_TalentUI")

	local tf = _G.PlayerTalentFrame
	check(tf.__aetherPanel ~= nil,
		"the talent frame is in glass when its addon turns up")
	check(_G.PlayerTalentFrameBackgroundTopLeft:GetTexture() == 0,
		"and the tree's parchment comes off it")

	-- THE BRANCHES AND ARROWS STAY. They are regions of the scroll child and of
	-- the arrow frame, and they are the only thing on screen saying which talent
	-- depends on which. Strip either frame and the tree becomes forty
	-- unconnected icons - which looks tidy enough to pass a screenshot.
	check(_G.PlayerTalentFrameBranch1:GetTexture() == "Interface\\TalentFrame\\UI-TalentBranches"
		and _G.PlayerTalentFrameArrow1:GetTexture() == "Interface\\TalentFrame\\UI-TalentArrows",
		"but the branches and arrows are left alone - they ARE the tree, and a"
		.. " sweep of the frame they hang off takes them with the parchment")

	local t1, t2, t3 = _G.PlayerTalentFrameTalent1, _G.PlayerTalentFrameTalent2,
		_G.PlayerTalentFrameTalent3
	check(t1.__aetherSlot == true, "a talent wears the same cell as a spell")
	check(_G.PlayerTalentFrameTalent1IconTexture:GetTexture() == "talent-icon-1",
		"with the talent still in it")
	check(_G.PlayerTalentFrameTalent1Slot:GetTexture() == 0
		and t1:GetNormalTexture():GetTexture() == 0,
		"and both the stone ring and the empty slot behind it cleared")

	-- THE STATE, IN THE RIM. The client weighs the rank against the maximum,
	-- the tier against the points spent, the prerequisites and whether there is
	-- a point spare - and then says the answer in the Slot's vertex colour.
	-- Reading that is one source of truth; working it out again from
	-- GetTalentInfo would be a second set of rules to keep in step.
	local function rim(b)
		local r, g = b.edge:GetVertexColor()
		return r, g
	end
	local open, full, plain =
		A.Palette.c.talentOpen, A.Palette.c.talentFull, A.Palette.c.glassEdge

	local r1, g1 = rim(t1)
	check(r1 == open[1] and g1 == open[2],
		"one you can put a point in takes the open rim")
	local r2, g2 = rim(t2)
	check(r2 == full[1] and g2 == full[2],
		"a finished one takes the full rim")
	local r3, g3 = rim(t3)
	check(r3 == plain[1] and g3 == plain[2],
		"and one you cannot reach yet keeps the ordinary one - three states, so"
		.. " a rim set for one of them cannot pass by looking right once")

	check(t1.__aetherRank and t1.__aetherRank.disc:GetTexture() == A.Media.texture.chipDisc,
		"the rank sits on a chip of ours rather than Blizzard's stone plate")
	check(_G.PlayerTalentFrameTalent1Rank._aetherStyle ~= nil,
		"with the client's own count on top of it, re-roled - it is what does"
		.. " the counting, and ours would be a second number to keep in step")
	check(not t3.__aetherRank:IsShown(),
		"and no chip at all where the client shows no rank")

	-- THE REPAINT. TalentFrame_Update runs on open, on every tab click and on
	-- every point spent, and it re-sets all four background pieces from the
	-- spec's own art. Art taken off once at dress time is art you see again on
	-- the first click.
	_G.TalentFrame_Update()
	check(_G.PlayerTalentFrameBackgroundTopLeft:GetTexture() == 0
		and t1:GetNormalTexture():GetTexture() == 0,
		"the parchment and the rings stay off after the client repaints the tree")
	local r1b = rim(t1)
	check(r1b == open[1], "and the rims still say what state each talent is in")

	local tb1, tb2 = _G.PlayerTalentFrameTab1, _G.PlayerTalentFrameTab2
	check(tb1.__aetherTab ~= nil and math.abs(tb1:GetWidth() - tb2:GetWidth()) < 0.01,
		"its tabs are one even row (" .. string.format("%.1f", tb1:GetWidth()) .. ")")
	check(_G.PlayerTalentFrameTab4.__aetherTab == nil,
		"and the glyph tab, which this flavour never shows, is left out of it")

	check(not _G.PlayerTalentFrameCancelButton:IsShown(),
		"the spare Close in the corner of the tree is gone, like the skills"
		.. " list's - the window already has one")

	local cPt, cRel, cRelPt = _G.PlayerTalentFrameCloseButton:GetPoint(1)
	check(cPt == "TOPRIGHT" and cRel == tf and cRelPt == "TOPRIGHT",
		"and the real one is in the corner rather than 44 in and 25 down, where"
		.. " the stone rim used to be")

	check(_G.PlayerTalentFrameLearnButton.__aetherSkin ~= nil
		and _G.PlayerTalentFrameLearnButton:GetNormalTexture():GetTexture() == 0,
		"its buttons are ours")
	check(_G.PlayerTalentFrameTalentPointsText._aetherStyle ~= nil
		and _G.PlayerTalentFrameSpentPointsText._aetherStyle ~= nil,
		"and both point readings are in our lettering")

	-- THE OTHER SKIN. A window's shell is a surface and answers ApplySkin; a
	-- talent's rim is a colour read out of the palette once, at dress time, and
	-- nothing re-reads it. So the tree kept the skin it was dressed under until
	-- the next time the frame happened to be redrawn.
	--
	-- Which rim to watch matters. The learned/available greens are SEMANTIC and
	-- deliberately identical in every skin, so a tree that never re-read them at
	-- all would still look right - they cannot prove anything. The unreachable
	-- talent wears glassEdge, which is chrome and moves, and it is the only one
	-- of the three that can tell a re-read from a stale colour.
	do
		local was = A.db.profile.skin
		local midEdge = A.Palette.skins.midnight.glassEdge
		local otherEdge = A.Palette.skins[OTHER].glassEdge
		check(midEdge[1] ~= otherEdge[1] or midEdge[2] ~= otherEdge[2],
			"the ordinary rim is chrome, and really is a different colour on "
			.. OTHER .. " - the greens are semantic and would prove nothing")

		A.db.profile.skin = OTHER
		A:Restyle()
		local dr, dg = rim(t3)
		check(math.abs(dr - otherEdge[1]) < 0.001 and math.abs(dg - otherEdge[2]) < 0.001,
			"switching skin takes the talent rims with it (" ..
			string.format("%.2f", dr) .. " vs " .. string.format("%.2f", otherEdge[1]) .. ")")

		-- And the semantic half of the same tree did NOT move, which is the rule
		-- the family is built on rather than an accident of this module.
		check(rim(t1) == open[1],
			"while the learned green is exactly what it was - a skin remaps"
			.. " chrome, never what a colour MEANS")

		A.db.profile.skin = was
		A:Restyle()
	end
end

print("== palette: difficulty has one owner ==")
do
	local P = A.Palette
	local QLm = A:GetModule("questlog")

	_G.__units.player.level = 16
	check(P:DifficultyBand(21) == "impossible" and P:DifficultyBand(19) == "verydifficult"
		and P:DifficultyBand(16) == "difficult" and P:DifficultyBand(10) == "standard"
		and P:DifficultyBand(1) == "trivial",
		"all five bands answer off the player's level")
	check(QLm.DifficultyBand(21) == P:DifficultyBand(21),
		"and the quest log still answers under its own name - the tracker resolves"
		.. " QL.DifficultyBand per call and would have dropped silently to its"
		.. " neutral fallback if the move had taken that away")

	check(P:SkullLevel(26) == true, "ten levels up is a skull")
	check(P:SkullLevel(25) == false, "nine is still a number")
	check(P:SkullLevel(-1) == true,
		"and so is a unit the client will not name a level for - it hands back -1"
		.. " there, which as a number is far BELOW you, not above")

	local fill, edge, ink = P:DifficultyColors(21)
	local band = P.c.questDiff.impossible.text
	check(ink == band, "the badge's number is the quest log's own band colour")
	check(fill[1] == band[1] and fill[4] == 0.15 and edge[4] == 0.40,
		"with the disc at .15 of it and the rim at .40 - the tooltip badge's recipe")
	local triv = P:DifficultyColors(1)
	check(triv[1] ~= fill[1] or triv[2] ~= fill[2],
		"and a trivial level is not tinted like a deadly one")
end

print("== palette: a name tells friendly PLAYER from friendly NPC ==")
do
	local P, units = A.Palette, _G.__units
	units.__np = { exists = true, name = "Kolkar Marauder", level = 18, reaction = 2 }

	check(P:NameReaction("__np") == P.c.ttHostile, "a hostile mob takes the red")
	units.__np.reaction = 4
	check(P:NameReaction("__np") == P.c.ttNeutral, "neutral takes the gold")
	units.__np.reaction = 5
	check(P:NameReaction("__np") == P.c.ttFriendlyNPC, "a friendly NPC is green")
	units.__np.isPlayer = true
	check(P:NameReaction("__np") == P.c.ttFriendly, "and a friendly PLAYER is blue")

	-- Why the name does not simply go through ReactionEdge.
	local playerEdge = P:ReactionEdge("__np")
	units.__np.isPlayer = false
	local npcEdge = P:ReactionEdge("__np")
	check(npcEdge[1] == playerEdge[1] and npcEdge[2] == playerEdge[2],
		"ReactionEdge collapses both friendlies into one green - correct for a rim,"
		.. " useless for the one line of text on a friendly nameplate")

