print("== skins: all four define the same vocabulary ==")
do
	-- Composed from one function now, so this ought to be unfalsifiable - and it
	-- is kept precisely because it USED to fail. Two hand-written tables drifted
	-- to 81 differences in 86 tokens. The day somebody adds a per-skin special
	-- case to Compose, this is what notices.
	local mid = A.Palette.skins.midnight
	local missing = {}
	for _, name in ipairs(SKINS) do
		local skin = A.Palette.skins[name]
		check(skin ~= nil, name .. " exists at all")
		for token in pairs(mid) do
			if skin[token] == nil then missing[#missing + 1] = name .. " lacks " .. token end
		end
		for token in pairs(skin) do
			if mid[token] == nil then missing[#missing + 1] = name .. " only: " .. token end
		end
	end
	check(#missing == 0,
		"every token exists in every skin - a token added to one only is a nil"
		.. " index in the middle of a redraw (missing: "
		.. table.concat(missing, ", ") .. ")")
end

print("== palette: the colours that are written out, so drift fails ==")
do
	-- WRITTEN OUT, deliberately. Everywhere else in this file a colour is
	-- compared against the palette, which proves the lookup works and says
	-- nothing about the value - move the token and the check moves with it.
	--
	-- These are the client's own numbers and the whole point of them is that
	-- they MATCH THE GAME: a curse that is one purple on an aura ring and
	-- another on Blizzard's own frames is worse than no colour at all. So the
	-- expected values live here, spelled out, and drift fails.
	local WANT = {
		{ "debuffSchool", "Magic",     0.55, 0.78, 1.00 },
		{ "debuffSchool", "Curse",     0.70, 0.50, 1.00 },
		{ "debuffSchool", "Disease",   0.70, 0.60, 0.35 },
		{ "debuffSchool", "Poison",    0.55, 0.85, 0.45 },
		{ "zonePvP",      "sanctuary", 0.41, 0.80, 0.94 },
		{ "zonePvP",      "arena",     1.00, 0.10, 0.10 },
		{ "zonePvP",      "friendly",  0.10, 1.00, 0.10 },
		{ "zonePvP",      "hostile",   1.00, 0.10, 0.10 },
		{ "zonePvP",      "contested", 1.00, 0.70, 0.00 },
		{ "zonePvP",      "combat",    1.00, 0.10, 0.10 },
	}
	-- Flat colours rather than tables, so they are listed apart. The gold is
	-- ours rather than the client's, but it is here for the same reason: a
	-- colour compared only against its own token can move without a check
	-- noticing, and the coin moving is a thing somebody would see.
	local FLAT = {
		{ "iconNoMana",   0.45, 0.55, 1.00 },
		{ "iconUnusable", 0.40, 0.40, 0.40 },
		{ "money",        0.90, 0.76, 0.42 },
	}
	local moved = {}
	for _, w in ipairs(WANT) do
		local group, key = w[1], w[2]
		local c = (A.Palette.c[group] or {})[key]
		if type(c) ~= "table" then
			moved[#moved + 1] = group .. "." .. key .. " missing"
		else
			for i = 1, 3 do
				if math.abs(c[i] - w[i + 2]) > 0.0001 then
					moved[#moved + 1] = string.format("%s.%s[%d] %.3f want %.3f",
						group, key, i, c[i], w[i + 2])
				end
			end
		end
	end
	for _, w in ipairs(FLAT) do
		local c = A.Palette.c[w[1]]
		for i = 1, 3 do
			if type(c) ~= "table" or math.abs(c[i] - w[i + 1]) > 0.0001 then
				moved[#moved + 1] = w[1] .. "[" .. i .. "]"
			end
		end
	end
	check(#moved == 0,
		"the schools, the zone types, the button states and the money gold are"
		.. " exactly the values they shipped as ("
		.. table.concat(moved, ", ") .. ")")

	-- And they are the same on every skin, because they are not ours to remap.
	local drifted = {}
	for _, group in ipairs({ "debuffSchool", "zonePvP" }) do
		for _, name in ipairs(SKINS) do
			if A.Palette.skins[name][group] ~= A.Palette.skins.midnight[group] then
				drifted[#drifted + 1] = name .. "." .. group
			end
		end
	end
	check(#drifted == 0,
		"and one table shared by all four skins, not four copies to keep in"
		.. " step (" .. table.concat(drifted, ", ") .. ")")
end

section("skins: a live switch, with no reload", function()
	local P, W2 = A.Palette, A.Widgets

	-- THE POINT OF THE WHOLE FAMILY. The brief asks for a live switch and a
	-- character keeping its choice; a skin you have to /reload into is a skin
	-- nobody tries on.
	--
	-- Before the two registries below, a switch left around five hundred
	-- surfaces wearing the skin they were BUILT under - every module walked its
	-- own widgets on OnSkinChanged and most of them missed some. A surface knows
	-- which tokens it was dressed from; its owner should not have to remember on
	-- its behalf.
	local function key(c)
		return string.format("%.4f/%.4f/%.4f/%.4f", c[1], c[2], c[3], c[4] or 1)
	end

	A.db.profile.skin = "midnight" A:Restyle()
	local wasGlass = P.c.glass
	A.db.profile.skin = OTHER A:Restyle()
	check(P.current == OTHER, "the switch lands on " .. OTHER)
	check(key(P.c.glass) ~= key(wasGlass),
		"and the glass really is a different colour, or nothing below means"
		.. " anything")

	-- Every registered surface, every registered string, every registered
	-- texture. Swept as a set rather than named one at a time: a check that
	-- lists frames only covers the frames somebody thought to list.
	local stale = {}
	for _, sf in ipairs(A.Glass.surfaces) do
		if sf._fillToken and sf._fillColor
			and key(sf._fillColor) ~= key(P.c[sf._fillToken]) then
			stale[#stale + 1] = "fill:" .. sf._fillToken
		end
		if sf._edgeToken and sf._edgeColor
			and key(sf._edgeColor) ~= key(P.c[sf._edgeToken]) then
			stale[#stale + 1] = "edge:" .. sf._edgeToken
		end
	end
	check(#stale == 0,
		#A.Glass.surfaces .. " glass surfaces, and not one still wearing the old"
		.. " skin (" .. table.concat(stale, ", ", 1, math.min(#stale, 6)) .. ")")

	local inkStale = 0
	for _, fs in ipairs(W2.inked) do
		local want = fs._aetherInk and P.c[fs._aetherInk]
		if want and fs.GetTextColor and key({ fs:GetTextColor() }) ~= key(want) then
			inkStale = inkStale + 1
		end
	end
	check(inkStale == 0,
		#W2.inked .. " strings, likewise (" .. inkStale .. " stale)")

	local tintStale = 0
	for _, tex in ipairs(W2.tinted) do
		local want = tex._aetherTint and P.c[tex._aetherTint]
		if want then
			local a = tex._aetherTintAlpha or want[4] or 1
			local r, g, b, ta = tex:GetVertexColor()
			if math.abs(r - want[1]) > 0.001 or math.abs(g - want[2]) > 0.001
				or math.abs(b - want[3]) > 0.001 or math.abs((ta or 1) - a) > 0.001 then
				tintStale = tintStale + 1
			end
		end
	end
	check(tintStale == 0,
		#W2.tinted .. " textures, likewise, AT THE WEIGHT THE CALLER ASKED FOR -"
		.. " the XP wash is quieter than a status bar and has to stay that way"
		.. " across a restyle (" .. tintStale .. " stale)")

	-- And the sweeps are not no-ops. Zero surfaces swept passes every line
	-- above, and is exactly what a registry that never registers looks like.
	check(#A.Glass.surfaces > 100 and #W2.inked > 100,
		"with real numbers in both registries, not an empty sweep (" ..
		#A.Glass.surfaces .. " surfaces, " .. #W2.inked .. " strings, " ..
		#W2.tinted .. " textures)")

	A.db.profile.skin = "midnight" A:Restyle()
end)

section("profiles: nothing keeps a reference to a config table", function()
	local AB2 = A:GetModule("actionbars")
	local was = A.db:GetCurrentProfile()

	-- WHAT ACEDB DOES ON THE WAY OUT, and it is not a bug: switching away from
	-- a profile strips every value equal to a default OUT OF THAT PROFILE'S
	-- TABLES, in place, so only the differences are saved. Anything holding one
	-- of those tables is left with an EMPTY one - not stale, empty.
	--
	-- Proved here directly rather than inferred, because every file involved
	-- reads perfectly correctly and only a real SetProfile shows it.
	local held = A.db.profile.modules.actionbars.bars[2]
	check(held.point ~= nil, "a config entry has a point in it to begin with")
	A.db:SetProfile("__profiletest")
	check(held.point == nil,
		"and the table we held is emptied by the switch - THIS is the hazard, and"
		.. " a module that cached one has been reading nothing ever since")

	-- So every bar must be pointing at the LIVE entry, not the one it was built
	-- with. Checked by identity: equal contents would also pass if the module
	-- had copied the values across, and a copy goes stale on the next write.
	local live = A.db.profile.modules.actionbars.bars
	local byId = {}
	for _, c in ipairs(live) do byId[tostring(c.id)] = c end
	local wrong, hollow = {}, {}
	for _, bar in ipairs(AB2.bars) do
		if byId[tostring(bar.id)] and bar.cfg ~= byId[tostring(bar.id)] then
			wrong[#wrong + 1] = bar.id
		end
		if bar.kind == "action" and bar.cfg.point == nil then
			hollow[#hollow + 1] = bar.id
		end
	end
	check(#wrong == 0,
		"every bar reads the new profile's own table (" ..
		table.concat(wrong, ", ") .. ")")
	check(#hollow == 0,
		"and every one of them has an anchor point - a bar with none is anchored"
		.. " to nothing, which is the top-left corner and no way to drag it back ("
		.. table.concat(hollow, ", ") .. ")")

	-- AND IT HAPPENS BEFORE ANYTHING READS IT. The restyle reads bar.cfg for the
	-- dock skin and the per-bar scale, and it runs first - so re-binding inside
	-- OnConfigChanged alone was already too late, and the bug survived a fix
	-- that looked complete.
	check(A.lastFailure == nil,
		"and the whole switch raised nothing (" .. tostring(A.lastFailure) .. ")")

	-- A DISABLED bar too. Every bar that was wrong was a disabled one: the
	-- re-bind lived in the branch that runs for enabled bars only, so the check
	-- has to name a bar that is off.
	local off
	for _, bar in ipairs(AB2.bars) do
		if bar.cfg.enabled == false then off = off or bar end
	end
	check(off ~= nil, "there is a disabled bar to look at")
	if off then
		check(off.cfg == byId[tostring(off.id)],
			"a bar that is switched OFF is re-bound as well - those were the only"
			.. " ones that were wrong, and they are the ones nobody looks at")
	end


	-- IN COMBAT, which is what makes the re-binding its own step rather than a
	-- line inside SyncBars.
	--
	-- AB:OnConfigChanged returns immediately in combat - laying bars out means
	-- moving frames with secure children, and the client refuses - so SyncBars,
	-- and the re-bind with it, does not run at all. The restyle does. Without a
	-- step of its own, every bar would read a hollow table for as long as the
	-- fight lasted, and nothing would look wrong until something asked one of
	-- them where it lived.
	A.db:SetProfile(was)
	_G.__inCombat = true
	A.lastFailure = nil
	A.db:SetProfile("__profiletest")

	local liveNow = {}
	for _, c in ipairs(A.db.profile.modules.actionbars.bars) do
		liveNow[tostring(c.id)] = c
	end
	local stale = {}
	for _, bar in ipairs(AB2.bars) do
		if liveNow[tostring(bar.id)] and bar.cfg ~= liveNow[tostring(bar.id)] then
			stale[#stale + 1] = bar.id
		end
	end
	check(#stale == 0,
		"a profile change IN COMBAT still re-binds every bar, even though the"
		.. " layout pass it used to ride on is skipped entirely (" ..
		table.concat(stale, ", ") .. ")")
	check(A._profilePending == true,
		"while the REDRESSING is deferred whole - rescaling a unit capsule means"
		.. " touching a frame with a secure button in it, which the client"
		.. " refuses, and the player gets an interface-blocked dialog mid-fight"
		.. " for something they did before it started")
	check(A.lastFailure == nil,
		"and nothing was blocked on the way (" .. tostring(A.lastFailure) .. ")")

	-- And it catches up when the fight ends, from a registration made at load
	-- rather than one made inside the deferral.
	_G.__inCombat = false
	fire("PLAYER_REGEN_ENABLED")
	check(A._profilePending == nil,
		"and the deferred half runs when the fight ends, once")

	A.db:SetProfile(was)
	for _, bar in ipairs(AB2.bars) do
		if bar.kind == "action" then
			check(bar.cfg.point ~= nil,
				"and switching back is the same story in the other direction (bar "
				.. bar.id .. ")")
			break
		end
	end
end)

section("skins: the choice belongs to the profile, and travels with it", function()
	local P = A.Palette
	local was = A.db:GetCurrentProfile()

	-- WHERE THE CHOICE LIVES. The brief says persist it per character; this
	-- addon has Ace profiles, so the honest answer is profile scope and the
	-- player picks what that scope IS - default, character, class, realm. Storing
	-- it per character behind the profile system would give somebody two places
	-- to set one thing and no way to tell which had won.
	A.db.profile.skin = "midnight" A:Restyle()
	check(P.current == "midnight", "midnight on this profile")

	A.db:SetProfile("__skintest")
	A.db.profile.skin = OTHER A:Restyle()
	check(P.current == OTHER, "and " .. OTHER .. " on another")

	-- The switch back is the whole point, and it must NOT need a reload: AceDB
	-- fires OnProfileChanged, Core answers it with a restyle, and the interface
	-- is in the other skin before the profile dropdown has closed.
	A.db:SetProfile(was)
	check(P.current == "midnight",
		"and changing profile carries the skin with it, live - no reload, no"
		.. " second call (" .. tostring(P.current) .. ")")
	check(P.c.glass == P.skins.midnight.glass,
		"with the palette actually swapped, not merely the name")

	-- A profile naming a skin that no longer exists degrades to midnight rather
	-- than to a nil palette - which is every colour in the addon at once.
	A.db.profile.skin = "daylight" A:Restyle()
	check(P.current == "midnight",
		"a profile still asking for a skin that was removed falls back to midnight"
		.. " rather than to a nil table (" .. tostring(P.current) .. ")")
	A.db.profile.skin = "midnight" A:Restyle()
end)
section("skins: what a live switch actually looks like on the HUD", function()
	local P = A.Palette
	local function rgb(...) local r, g, b = ... return r, g, b end

	-- The two registries cover everything dressed BY TOKEN. These are the ones
	-- they deliberately do not reach - colours a module sets from state - and so
	-- the ones that need naming one at a time. Both were wrong: an empty action
	-- slot kept its old rim because every state painter returned early on a slot
	-- with nothing in it, and a buff tile was dressed with a colour rather than
	-- a token so the sweep passed it by.
	A.db.profile.skin = "midnight" A:Restyle()
	A.db.profile.skin = OTHER A:Restyle()

	local want = P.c.glassEdge
	local AB2 = A:GetModule("actionbars")
	local empty
	for _, bar in ipairs(AB2.bars) do
		for i, b in ipairs(bar.buttons) do
			if bar.kind == "action" and not b.__aetherAdopted
				and not HasAction(b:GetAttribute("action")) then
				empty = empty or b
			end
		end
	end
	check(empty ~= nil, "the fixture has an empty action slot to look at")
	if empty then
		local r, g, b = rgb(empty.edge:GetVertexColor())
		check(math.abs(r - want[1]) < 0.001 and math.abs(g - want[2]) < 0.001
			and math.abs(b - want[3]) < 0.001,
			"an EMPTY slot wears the new skin's rim - it is still on screen at a"
			.. " quarter alpha, and it was the last thing on the bar still wearing"
			.. " the old one (" .. string.format("%.2f %.2f %.2f", r, g, b) .. ")")
	end

	-- A stance button on a client with no stance API at all: built, on screen,
	-- and returning before any rim was ever set.
	for _, bar in ipairs(AB2.bars) do
		if bar.kind == "stance" and bar.buttons[1] then
			local r, g, b = rgb(bar.buttons[1].edge:GetVertexColor())
			check(math.abs(r - want[1]) < 0.001 and math.abs(g - want[2]) < 0.001
				and math.abs(b - want[3]) < 0.001,
				"and so does a stance slot (" ..
				string.format("%.2f %.2f %.2f", r, g, b) .. ")")
		end
	end

	-- And on a client with NO stance API at all. The rim is dressed before that
	-- guard rather than after it, and with the API present both orders look the
	-- same - so the only way to see the difference is to take it away.
	do
		local real = _G.GetShapeshiftFormInfo
		_G.GetShapeshiftFormInfo = nil
		for _, bar in ipairs(AB2.bars) do
			if bar.kind == "stance" and bar.buttons[1] then
				bar.buttons[1].edge:SetVertexColor(1, 0, 1, 1)   -- something wrong
				AB2.Repaint(bar.buttons[1])
				local r, g, b = rgb(bar.buttons[1].edge:GetVertexColor())
				check(math.abs(r - want[1]) < 0.001 and math.abs(g - want[2]) < 0.001
					and math.abs(b - want[3]) < 0.001,
					"a stance button on a client that has no stance API is still"
					.. " built, still on screen, and still gets a rim (" ..
					string.format("%.2f %.2f %.2f", r, g, b) .. ")")
			end
		end
		_G.GetShapeshiftFormInfo = real
		AB2:RefreshAll()
	end

	-- A buff tile, which is plain glass and had to say so BY TOKEN to be swept.
	local AU2 = A:GetModule("auras")
	local tile = AU2.playerBuffs and AU2.playerBuffs.tiles[1]
	check(tile ~= nil, "and a buff tile to look at")
	if tile then
		check(tile._fillToken == "glass",
			"a buff tile is dressed from the glass token rather than handed the"
			.. " colour, which is what puts it on the sweep at all")
		check(tile._fillColor == P.c.glass,
			"so it is wearing the live skin's glass after the switch")
	end

	-- A debuff tile is the other way round on purpose: its colour is its school,
	-- which is semantic, so it must NOT move when the skin does.
	local dtile = AU2.playerDebuffs and AU2.playerDebuffs.tiles[2]
	if dtile then
		local r, g, b = rgb(dtile.art.ring:GetVertexColor())
		local curse = P.c.debuffSchool.Curse
		check(math.abs(r - curse[1]) < 0.001 and math.abs(g - curse[2]) < 0.001
			and math.abs(b - curse[3]) < 0.001,
			"while a debuff tile keeps its school colour, which is semantic and the"
			.. " same in all four (" ..
			string.format("%.2f %.2f %.2f", r, g, b) .. ")")
	end

	A.db.profile.skin = "midnight" A:Restyle()
end)
section("skins: a colour set by hand is NOT swept away", function()
	local P = A.Palette
	A.db.profile.skin = "midnight" A:Restyle()

	-- The other half of the same rule, and the one that would break the HUD if
	-- it were wrong: a target capsule takes its reaction tint, a slot its
	-- quality rim, an aura tile its debuff school. Whoever set that owns it, and
	-- the sweep walking in afterwards and painting the skin default back over
	-- the top would turn every stateful colour on screen into plain glass.
	local s = A.Glass.CreatePanel(UIParent, { corner = 8 })
	s:ApplySkin("glass", "glassEdge")
	check(s._fillToken == "glass", "a surface dressed from a token remembers it")

	local mine = { 0.9, 0.1, 0.2, 1 }
	s:SetFillColor(mine)
	check(s._fillToken == nil,
		"and setting a colour by hand hands ownership back - the token is gone,"
		.. " not merely overwritten")

	A.db.profile.skin = OTHER A:Restyle()
	check(s._fillColor == mine,
		"so a restyle leaves it exactly where its owner put it")

	-- Same for a string. W.Color is handed a palette table or a computed one,
	-- and only the first kind is the palette's to keep changing.
	local fs = A.Widgets.Text(UIParent, "label", "LEFT")
	A.Widgets.Color(fs, P.c.accent)
	check(fs._aetherInk == "accent", "a string coloured from a token remembers it")
	A.Widgets.Color(fs, { 0.1, 0.9, 0.3, 1 })
	check(fs._aetherInk == nil, "and a computed colour clears it")
	A:Restyle()
	local r, g = fs:GetTextColor()
	check(math.abs(r - 0.1) < 0.001 and math.abs(g - 0.9) < 0.001,
		"so the sweep leaves that one alone too")

	A.db.profile.skin = "midnight" A:Restyle()
end)

section("skins: things that are not modules get told too", function()
	-- Eighteen modules get OnSkinChanged and always have. The context menu is
	-- not a module - any of them can open it - and Core used to name it by hand
	-- in Restyle, which is a list that only holds what somebody remembered to
	-- put in it.
	local fired = 0
	A:OnSkinChanged(function() fired = fired + 1 end)
	A:Restyle()
	check(fired == 1, "a listener is called once per restyle (" .. fired .. ")")
	A:Restyle()
	check(fired == 2, "and again on the next one")

	-- A bad listener must not take the restyle down with it. Half a skin change
	-- is worse than none: the interface is left in two skins at once.
	A:OnSkinChanged(function() error("deliberate") end)
	local after = 0
	A:OnSkinChanged(function() after = after + 1 end)
	A.lastFailure = nil
	A:Restyle()
	check(after == 1,
		"a listener that errors does not stop the ones behind it")
	check(A.lastFailure ~= nil, "and the failure is recorded rather than swallowed")
	A.lastFailure = nil
end)

print("== skins: chat ink follows the skin, because it is not baked in ==")
do
	local P = A.Palette

	-- A chat line cannot be re-coloured once it is in the log, so the colour
	-- has to be right at the moment the string is built. The 203 escapes this
	-- replaced were right on exactly one skin.
	P:Apply("midnight")
	local mid = A.Hi("x")
	P:Apply(OTHER)
	local other = A.Hi("x")
	check(mid ~= other,
		"the same call gives a different colour on a different skin")
	check(other:find(P:Hex(P.skins[OTHER].accent), 1, true) ~= nil,
		"and it is the LIVE skin's accent, not a remembered one (" .. other
		.. ")")

	-- Each helper on its own token. Two of them pointing at the same one is
	-- the kind of thing every other check here would sail past.
	local roles = {
		{ A.Hi, "accent" }, { A.Val, "text" }, { A.Good, "friendly" },
		{ A.Bad, "danger" }, { A.Dim, "dim" },
	}
	local seen = {}
	for _, r in ipairs(roles) do
		local fn, token = r[1], r[2]
		local hex = P:Hex(P.c[token])
		check(fn("x") == P:InkHex(hex, "x"),
			token .. " is what its helper writes (" .. fn("x") .. ")")
		check(not seen[hex], token .. " has a colour of its own")
		seen[hex] = true
	end

	-- A token that does not exist falls back to type rather than to nil, which
	-- in a chat line is the string |cffnil<text>.
	check(P:Ink("noSuchToken", "x") == P:InkHex(P:Hex(P.c.text), "x"),
		"an unknown token draws as ordinary type rather than as the word nil")

	P:Apply("midnight")
end

print("== skins: the family is offered in the order it is named for ==")
do
	local P = A.Palette
	local list = P:List()
	check(#list == #SKINS, "four skins are offered (" .. #list .. ")")

	-- The order is the day, not the alphabet - which sorts to dawn, dusk,
	-- midnight, noon and reads as four unrelated words.
	local keys, labels = {}, {}
	for i, e in ipairs(list) do
		keys[i] = e.key
		labels[i] = e.label
		check(e.label and e.label ~= "" and e.label ~= e.key,
			e.key .. " is offered under a written name rather than its key ("
			.. tostring(e.label) .. ")")
	end
	check(table.concat(keys, ",") == table.concat(SKINS, ","),
		"and in the day's order, not the alphabet's (" ..
		table.concat(keys, ", ") .. ")")

	-- And the order is what BUILDS them, so a skin left out of it does not exist
	-- rather than existing unreachably.
	local n = 0
	for _ in pairs(P.skins) do n = n + 1 end
	check(n == #SKINS,
		"there are no skins outside the order - one built and not offered is a"
		.. " skin nobody can pick and everybody has to maintain (" .. n .. ")")
end

print("== skins: a skin is a HUE remap, never a value one ==")
do
	-- THE BRIEF'S BINDING RULE, and the reason Daylight was dropped: components
	-- never change geometry, size, opacity, blur or shadow between skins.
	-- Brightness lives in the hue. So every alpha in the family has to be
	-- identical across all four, and only the RGB may move.
	--
	-- Written as a sweep rather than a list because the failure it catches is a
	-- token somebody tuned on one skin and nowhere else, which is exactly the
	-- token nobody would think to enumerate here.
	local function alphas(t, prefix, out)
		for k, v in pairs(t) do
			if type(v) == "table" then
				if type(v[1]) == "number" and #v >= 3 then
					out[prefix .. tostring(k)] = v[4] or 1
				else
					alphas(v, prefix .. tostring(k) .. ".", out)
				end
			end
		end
		return out
	end
	local base = alphas(A.Palette.skins.midnight, "", {})
	local moved, hues = {}, 0
	for _, name in ipairs(SKINS) do
		if name ~= "midnight" then
			local other = alphas(A.Palette.skins[name], "", {})
			for token, a in pairs(base) do
				if math.abs((other[token] or -1) - a) > 0.0001 then
					moved[#moved + 1] = name .. "." .. token
				end
			end
		end
	end
	check(#moved == 0,
		"not one alpha moves between skins (" .. table.concat(moved, ", ") .. ")")

	-- And the other half of the same claim: the hue DID move. Without this the
	-- check above passes on four identical skins.
	for _, name in ipairs(SKINS) do
		if name ~= "midnight" then
			local a, b = A.Palette.skins.midnight.accent, A.Palette.skins[name].accent
			if a[1] ~= b[1] or a[2] ~= b[2] or a[3] ~= b[3] then hues = hues + 1 end
		end
	end
	check(hues == #SKINS - 1,
		"while every other skin's accent is a different colour from midnight's ("
		.. hues .. " of " .. (#SKINS - 1) .. ")")
end

print("== skins: every skin draws LIGHT type on DARK glass ==")
do
	-- Not a stylistic note, a constraint. Daylight was tried as a light theme
	-- with dark ink and it failed on something that cannot be configured: WoW's
	-- OUTLINE flag is always BLACK, so every role carrying it - the level orb,
	-- stack counts, keybinds - drew dark text inside a black rim on white.
	--
	-- So the whole family keeps light text on dark glass, and every colour the
	-- game hands us (RAID_CLASS_COLORS, GetQuestDifficultyColor, ChatTypeInfo)
	-- works unchanged on all of them. A future skin wanting dark ink has to drop
	-- those outlines first.
	local function lum(c) return 0.299*c[1] + 0.587*c[2] + 0.114*c[3] end
	for _, name in ipairs(SKINS) do
		local skin = A.Palette.skins[name]
		check(lum(skin.text) > 0.7,
			name .. "'s primary text is light (" ..
			string.format("%.2f", lum(skin.text)) .. ")")
		check(lum(skin.glass) < 0.2,
			name .. "'s panel fill is dark (" ..
			string.format("%.2f", lum(skin.glass)) .. ") - the glass stays dark"
			.. " in all four, which is what the family is FOR")
	end

	local outlined = 0
	for _, style in pairs(A.Media.style) do
		if style[3] == "OUTLINE" then outlined = outlined + 1 end
	end
	check(outlined > 0,
		"there are still " .. outlined .. " roles with a hardcoded black OUTLINE,"
		.. " which is what pins the whole family to light type")
end

print("== skins: the rim is what makes a panel a panel ==")
do
	-- A dark panel over dark terrain is a smudge without a boundary, and this is
	-- the pairing that gives it one. Daylight needed a rim twice midnight's to
	-- survive on pale ground; the family that replaced it is dark throughout, so
	-- the rim can be the same weight on all four - but it still has to be THERE,
	-- and it still has to out-read the fill it surrounds.
	local function lum(c) return 0.299*c[1] + 0.587*c[2] + 0.114*c[3] end
	for _, name in ipairs(SKINS) do
		local skin = A.Palette.skins[name]
		check(lum(skin.glassEdge) * (skin.glassEdge[4] or 1)
			> lum(skin.glass) * (skin.glass[4] or 1),
			name .. ": the rim reads stronger than the fill it encloses")
		check((skin.glass[4] or 1) < 0.8,
			name .. ": and the fill is still glass rather than a slab (" ..
			string.format("%.2f", skin.glass[4]) .. ")")
		check((skin.shadow[4] or 1) > 0,
			name .. ": with a drop shadow lifting it off the ground")
	end
end

print("== skins: reading surfaces sit deeper than control surfaces ==")
do
	local P = A.Palette
	local C2, QLg = A:GetModule("chat"), A:GetModule("questlog")

	-- Two kinds of panel, two opacities. Action bars and unit capsules are
	-- glanced at; chat and the quest log carry paragraphs of small text over
	-- moving scenery, and at the control-surface opacity the clutter behind
	-- competes with every glyph. Chat has always sat deeper - the quest log was
	-- shipped at the control opacity and was hard to read for exactly that reason.
	for _, name in ipairs(SKINS) do
		P:Apply(name)
		local control = P.c.glassStrong[4] or 1
		local reading = P:ReadingFill()[4] or 1
		check(reading > control,
			name .. ": a reading surface is deeper than a control surface (" ..
			string.format("%.2f vs %.2f", reading, control) .. ")")
		check(reading < 1,
			"and never fully opaque - it is still glass")
	end

	P:Apply("midnight")
	C2:OnSkinChanged()
	QLg:OnSkinChanged()
	local want = P:ReadingFill()[4]
	check(math.abs((C2.panel._fillColor[4] or 1) - want) < 0.001,
		"chat uses it")
	check(math.abs((QLg.win._fillColor[4] or 1) - want) < 0.001,
		"and so does the quest log - one helper, so the two cannot drift apart")

	-- The boost closes a fraction of the remaining transparency rather than
	-- adding a constant: a flat addition is a different proportion on every skin,
	-- and a multiplier overshoots into opaque once the base is high.
	local function closed(skin)
		P:Apply(skin)
		local base = P.c.glassStrong[4] or 1
		return ((P:ReadingFill()[4] or 1) - base) / (1 - base)
	end
	local a, spread = closed("midnight"), 0
	for _, name in ipairs(SKINS) do
		spread = math.max(spread, math.abs(closed(name) - a))
	end
	check(spread < 0.001,
		"and closes the same fraction of the gap to opaque on every skin (worst"
		.. " gap " .. string.format("%.3f", spread) .. ")")
	P:Apply("midnight")
	C2:OnSkinChanged()
	QLg:OnSkinChanged()
end

print("== skins: reading opacity is a setting, not a constant ==")
do
	local P = A.Palette
	local C2, QLg = A:GetModule("chat"), A:GetModule("questlog")
	local cfg = A.db.profile.glass
	local saved = cfg.readOpacity

	check(saved == 0.35,
		"the default matches the constant it replaced, so nobody's HUD moved")

	-- How much background clutter a person can read through is eyesight and
	-- taste, so it is a slider rather than a number in the source.
	local function alphas(v)
		cfg.readOpacity = v
		A:Restyle()
		return (C2.panel._fillColor[4] or 1), (QLg.win._fillColor[4] or 1)
	end

	local base = P.c.glassStrong[4]
	local c0, q0 = alphas(0)
	check(math.abs(c0 - base) < 0.001 and math.abs(q0 - base) < 0.001,
		"at 0 they match the control surfaces exactly (" ..
		string.format("%.2f", c0) .. ")")

	local c1, q1 = alphas(1)
	check(c1 > 0.99 and q1 > 0.99, "at 1 they are solid")

	local ch, qh = alphas(0.7)
	check(ch > c0 and ch < c1 and math.abs(ch - qh) < 0.001,
		"and in between they move together - one setting, both panels (" ..
		string.format("%.2f", ch) .. ")")

	-- A saved variable is whatever was last written to it, including by hand.
	cfg.readOpacity = -3
	A:Restyle()
	check((C2.panel._fillColor[4] or 1) >= base,
		"a negative value clamps rather than making the panel more transparent"
		.. " than the HUD it belongs to")
	cfg.readOpacity = 42
	A:Restyle()
	check((C2.panel._fillColor[4] or 1) <= 1, "and an absurd one clamps to solid")

	cfg.readOpacity = saved
	A:Restyle()

	-- Reachable without editing the source, which is the whole point.
	local found
	local function walk(node)
		for _, opt in pairs(node.args or {}) do
			if opt.type == "group" then walk(opt)
			elseif opt.arg and opt.arg.path and opt.arg.path[1] == "glass"
				and opt.arg.path[2] == "readOpacity" then found = opt end
		end
	end
	walk(A.Options:Build())
	check(found and found.type == "range",
		"and it is a slider in the options panel, not a line in Palette.lua")
	check(found and found.arg.after == "restyle",
		"which restyles on change, so it takes effect without a /reload")
end

print("== chat: the selected tab ==")
do
	local C3 = A:GetModule("chat")
	local tab1, tab2 = _G.ChatFrame1Tab, _G.ChatFrame2Tab

	-- `dock.selected` is a FRAME. Comparing it to tab:GetID() is comparing a
	-- table to a number, which is never equal - so the selected tab never lit up
	-- in game while the harness, which stored a number, was perfectly happy.
	check(type(_G.GeneralDockManager.selected) == "table",
		"the dock records its selection as a frame, as the client does")
	check(C3.SelectedChatID() == 1,
		"and the module resolves it to an id (got " ..
		tostring(C3.SelectedChatID()) .. ")")

	-- THE UNREAD DOT. Blizzard's tab flash runs with flashDuration -1, so once
	-- it starts it stays SHOWN until something stops it - and selecting the tab
	-- is not reliably that something. So the dot appeared on the very window
	-- whose contents were in front of you, which is what got reported.
	do
		local flash1 = _G.ChatFrame1TabFlash
		local flash2 = _G.ChatFrame2TabFlash
		check(flash1 and flash2, "the tabs have Blizzard's flash textures")

		-- Tab 2 is unselected and flashing: that is a real unread.
		flash2:Show()
		flash1:Show()
		C3:UpdateFlashes()
		check(tab2._dot:GetAlpha() == 1,
			"an unselected tab with a live flash gets the unread dot")
		check(tab1._dot:GetAlpha() == 0,
			"and the SELECTED tab does not, however long its flash has been"
			.. " shown - an unread marker on the window you are reading is"
			.. " noise, and it is the one that was reported")

		-- Select the other one and the dots swap.
		_G.GeneralDockManager.selected = _G.ChatFrame2
		C3:UpdateFlashes()
		check(tab2._dot:GetAlpha() == 0 and tab1._dot:GetAlpha() == 1,
			"selecting a tab clears its dot and the other one keeps its own")
		_G.GeneralDockManager.selected = _G.ChatFrame1

		flash1:Hide(); flash2:Hide()
		C3:UpdateFlashes()
		check(tab1._dot:GetAlpha() == 0 and tab2._dot:GetAlpha() == 0,
			"and with nothing flashing there are no dots at all")
	end

	C3:StyleTab(tab1)
	C3:StyleTab(tab2)
	check(tab1._pill and tab1._pill:GetAlpha() == 1,
		"the selected tab draws its pill")
	check(tab1._pill._fillColor == A.Palette.c.accent,
		"filled with the accent, which is the concept's coloured pill")
	check(tab2._pill and tab2._pill:GetAlpha() == 0,
		"and an unselected tab draws none")

	-- Selecting the other one moves it.
	FCFDock_SelectWindow(_G.GeneralDockManager, _G.ChatFrame2)
	C3:StyleTab(tab1)
	C3:StyleTab(tab2)
	check(tab2._pill:GetAlpha() == 1 and tab1._pill:GetAlpha() == 0,
		"and it follows the selection")

	-- A client that hands back a number instead must still work.
	_G.GeneralDockManager.selected = 1
	check(C3.SelectedChatID() == 1, "a numeric selection is accepted too")

	FCFDock_SelectWindow(_G.GeneralDockManager, _G.ChatFrame1)
	C3:StyleTab(tab1)
	C3:StyleTab(tab2)

	-- Called with a colon, `dock` is the module table: non-nil, no `.selected`,
	-- and every tab goes unselected with nothing raised to say why.
	check(C3:SelectedChatID() == 1,
		"and calling it as a method answers the same as calling it plainly")

	-- The client hands the answer to the hook and the old one declared
	-- `function(tab)` and dropped it on the floor.
	FCFTab_UpdateColors(tab2, true)
	check(tab2._pill:GetAlpha() == 1,
		"a tab the client itself calls selected lights up, whatever the dock says")

	-- ...and that must not outlive the selection that produced it. This is the
	-- stale-flag case: two pills lit at once.
	FCFDock_SelectWindow(_G.GeneralDockManager, _G.ChatFrame1)
	C3:SkinAllTabs()
	check(tab1._pill:GetAlpha() == 1 and tab2._pill:GetAlpha() == 0,
		"and moving the selection back leaves exactly one pill lit")

	-- An undocked window is not in the dock, so it can never be the dock's
	-- selection - but it is the window you are reading.
	--
	-- `nil`, NOT `false`. FCFDock_RemoveChatFrame writes `chatFrame.isDocked =
	-- nil` and FCFDock_AddChatFrame writes `1`; those are the only two
	-- assignments the client makes. The first version of this test set `false`,
	-- which made a module written as `isDocked == false` pass here while doing
	-- nothing whatsoever in game.
	_G.ChatFrame2.isDocked = nil
	C3:SkinAllTabs()
	check(tab2._pill:GetAlpha() == 1,
		"an undocked window's tab is not dimmed forever for not being in the dock")

	-- ...and the whole undock sequence, in the client's order: colour the tab
	-- selected, then update the dock - which is our own SkinAllTabs wiping the
	-- flag that first step set. If the tier below it is wrong, the pill lights
	-- and then goes straight back out.
	FCFTab_UpdateColors(tab2, true)
	FCFDock_UpdateTabs(_G.GeneralDockManager)
	C3:SkinAllTabs()
	check(tab2._pill:GetAlpha() == 1,
		"and it survives the dock update that follows the undock")

	-- A CLOSED window is undocked too, and stays in CHAT_FRAMES forever.
	_G.ChatFrame2:Hide()
	C3:SkinAllTabs()
	check(tab2._pill:GetAlpha() == 0,
		"but a closed window's tab is not lit just for being undocked")
	_G.ChatFrame2:Show()

	_G.ChatFrame2.isDocked = true
	FCFDock_SelectWindow(_G.GeneralDockManager, _G.ChatFrame1)
	C3:SkinAllTabs()

	-- A tab with no id must not match a dock with no selection: `nil == nil`.
	local saved = _G.GeneralDockManager.selected
	_G.GeneralDockManager.selected = nil
	-- pcall because the guard is load-bearing twice over: without it the answer
	-- is `nil == nil`, true, an unknown tab lights - and one line further down
	-- `"ChatFrame" .. nil` raises, which in game is an error thrown out of a
	-- Blizzard hook every time a tab is coloured.
	local ok, lit = pcall(C3.TabIsSelected, {})
	check(ok and lit == false,
		"a tab that cannot say which window it is does not light, and does not"
		.. " error either (" .. tostring(ok) .. ", " .. tostring(lit) .. ")")
	_G.GeneralDockManager.selected = saved

	check(C3:TabIsSelected(tab1) == C3.TabIsSelected(tab1),
		"and TabIsSelected answers the same called as a method")
end

print("== chat: the pill is a pill, and it clears the divider ==")
do
	local C3 = A:GetModule("chat")
	local tab1 = _G.ChatFrame1Tab
	C3:StyleTab(tab1)

	-- The first version anchored the pill to the tab's corners inset by 2. A
	-- docked ChatFrameTab is 32 tall, so that drew a 28-tall slab - and the
	-- divider is only 24 below the dock's top edge, so 3px of it sat on the line.
	local pillH = tab1._pill:GetHeight()
	check(pillH < tab1:GetHeight() - 4,
		"the pill does not inherit the tab's height (" .. pillH .. " of "
		.. tab1:GetHeight() .. ")")

	-- ...and it must not START inheriting it again. A taller tab is the thing
	-- that would reveal a corner anchor, so give it one.
	local was = tab1:GetHeight()
	tab1:SetHeight(64)
	C3:StyleTab(tab1)
	check(tab1._pill:GetHeight() == pillH,
		"and doubling the tab's height does not change it")
	tab1:SetHeight(was)
	C3:StyleTab(tab1)

	-- The clearance, computed from what the module actually anchored rather
	-- than from numbers retyped here. Tabs are anchored by LEFT - by their
	-- vertical CENTRE - to the dock, so the pill's centre is the dock's centre.
	local p = C3.panel
	local _, _, _, _, panelY = p:GetPoint(1)             -- panel top from dock top
	local dy
	for i = 1, 4 do
		local pt, _, _, _, y = p.divider:GetPoint(i)
		if pt == "TOPLEFT" then dy = y end
	end
	if panelY and dy then
		local dockH = _G.GeneralDockManager:GetHeight()
		local dividerFromDockTop = panelY + dy           -- 10 + -34 = -24
		local pillBottomFromDockTop = -(dockH / 2) - pillH / 2   -- -13 - 9 = -22
		check(pillBottomFromDockTop > dividerFromDockTop,
			"the pill's bottom clears the divider by "
			.. (pillBottomFromDockTop - dividerFromDockTop) .. "px")
	end
end

print("== chat: clicking a tab does not deform the pill ==")
do
	local C3 = A:GetModule("chat")
	local tab1, tab2 = _G.ChatFrame1Tab, _G.ChatFrame2Tab
	local fs2 = _G.ChatFrame2TabText

	-- Everything above this point measured a tab the module had just styled.
	-- The bug only appears once BLIZZARD has had its turn: FCF_SelectDockFrame
	-- rebuilds the tabs and FCF_DockUpdate rebuilds them again, so
	-- PanelTemplates_TabResize runs twice per click, rewriting the tab's width
	-- and - for every tab but ChatFrame1's - pinning the label to a hard
	-- `dynTabSize - 32`.
	FCFDock_SelectWindow(_G.GeneralDockManager, _G.ChatFrame2)   -- the click
	FCFDock_UpdateTabs(_G.GeneralDockManager)                    -- ...and again
	C3:SkinAllTabs()

	check(fs2:GetWidth() == 0,
		"the label is handed back its auto width after the client pins it ("
		.. fs2:GetWidth() .. ")")
	check(fs2:GetHeight() == 0,
		"and its auto height, so its rect is the size of the word in it")

	local want = fs2:GetStringWidth() + 20
	check(math.abs(tab2:GetWidth() - want) < 0.01,
		"the tab is our width, not the client's 60 (" .. tab2:GetWidth() .. ")")

	-- The invariant that makes "off-centre label" impossible rather than merely
	-- unlikely: the pill is anchored to the LABEL. Its centre is then the
	-- label's centre by construction, whatever the tab is doing.
	local p1, rel1 = tab2._pill:GetPoint(1)
	local p2, rel2 = tab2._pill:GetPoint(2)
	check(rel1 == fs2 and rel2 == fs2,
		"and the pill hangs off the label, not off the tab (" .. tostring(p1)
		.. "/" .. tostring(p2) .. ")")
	check(tab2._pill:GetHeight() == 18,
		"with its height still its own (" .. tab2._pill:GetHeight() .. ")")

	-- Two points, not four and not two stacked on two: re-anchoring every pass
	-- without clearing first would pile them up until the frame is over-defined.
	local n = 0
	while tab2._pill:GetPoint(n + 1) do n = n + 1 end
	check(n == 2, "and exactly two anchor points survive repeated styling ("
		.. n .. ")")

	FCFDock_SelectWindow(_G.GeneralDockManager, _G.ChatFrame1)
	C3:SkinAllTabs()
	check(_G.ChatFrame1TabText:GetWidth() == 0 and tab1._pill:GetHeight() == 18,
		"and clicking back leaves the first tab as it started")
end

print("== chat: the tab label is not smudged ==")
do
	local C3 = A:GetModule("chat")
	local tab1, tab2 = _G.ChatFrame1Tab, _G.ChatFrame2Tab
	FCFDock_SelectWindow(_G.GeneralDockManager, _G.ChatFrame1)
	C3:SkinAllTabs()

	local sel, unsel = _G.ChatFrame1TabText, _G.ChatFrame2TabText

	-- GameFontNormalSmall inherits SystemFont_Shadow_Small, which carries
	-- `<Shadow x="1" y="-1"><Color r="0" g="0" b="0"/></Shadow>`. SetFont does
	-- not clear it, so dark type on the pale accent pill came with an opaque
	-- black halo baked in.
	local _, _, _, sa = sel:GetShadowColor()
	check(sa == 0, "the selected label casts no shadow onto its own pill ("
		.. tostring(sa) .. ")")

	-- ...but pale type on the dark panel still wants one.
	local _, _, _, ua = unsel:GetShadowColor()
	check(ua and ua > 0,
		"while an unselected one keeps it, as the message text does ("
		.. tostring(ua) .. ")")

	-- And the ink is opaque. `c.glass` is the panel FILL and carries alpha 0.55;
	-- passing it through as a text colour drew the label fainter than the black
	-- shadow behind it, which is what made it look blurred rather than dark.
	local _, _, _, ta = sel:GetTextColor()
	check(ta == 1, "and the selected label is fully opaque, not the panel fill's"
		.. " alpha (" .. tostring(ta) .. ")")

	-- Reselecting has to put both back, or the treatment is one-way.
	FCFDock_SelectWindow(_G.GeneralDockManager, _G.ChatFrame2)
	C3:SkinAllTabs()
	local _, _, _, a1 = _G.ChatFrame1TabText:GetShadowColor()
	local _, _, _, a2 = _G.ChatFrame2TabText:GetShadowColor()
	check(a1 and a1 > 0 and a2 == 0,
		"and the shadow follows the selection rather than being cleared once")

	FCFDock_SelectWindow(_G.GeneralDockManager, _G.ChatFrame1)
	C3:SkinAllTabs()
end

print("== chat: the idle composer does NOT follow the selection ==")
do
	local C3 = A:GetModule("chat")
	local eb1, eb2 = _G.ChatFrame1EditBox, _G.ChatFrame2EditBox

	-- This block asserted the opposite for one draft, which is how it earns its
	-- comment. The reasoning that produced it was: `selected == id or f ==
	-- ChatFrame1` inside a loop over CHAT_FRAMES can never let the selection
	-- decide, because ChatFrame1 is first in that list - therefore promote the
	-- selection. Correct diagnosis, wrong cure: the selection term was dead AND
	-- wrong, and making it live made the composer lie.
	--
	-- Era's OPENCHAT binding is `ChatFrameUtil.OpenChat("")` with no frame, and
	-- ChooseBoxForSend's first branch returns DEFAULT_CHAT_FRAME.editBox
	-- whenever `chatStyle == "classic"`, without looking at the dock at all. So
	-- pressing Enter with the guild window selected still types into SAY, and a
	-- capsule previewing the selection would name a channel you cannot reach.
	FCFDock_SelectWindow(_G.GeneralDockManager, _G.ChatFrame2)
	C3:UpdateComposers()
	if eb1 and eb1._pill and eb2 and eb2._pill then
		check(eb1._pill:IsShown() and not eb2._pill:IsShown(),
			"with nothing focused the composer previews the box Enter opens,"
			.. " whatever the dock has selected")
	end

	-- ...but a box that is genuinely open wins, and that is the whole of the
	-- `chatStyle = "im"` case: there the client hides the old box and shows the
	-- new one, so "which box is shown" already answers "which one moves".
	if eb1 and eb1._pill and eb2 and eb2._pill then
		eb2:Show()
		C3:UpdateComposers()
		check(eb2._pill:IsShown() and not eb1._pill:IsShown(),
			"and an open box outranks it, which is how the im chat style moves")
		eb2:Hide()
	end

	FCFDock_SelectWindow(_G.GeneralDockManager, _G.ChatFrame1)
	C3:UpdateComposers()
	if eb1 and eb1._pill then
		check(eb1._pill:IsShown(), "back to ChatFrame1's once it closes again")
	end
end

print("== chat: the tab type is smaller than the messages ==")
do
	local C3 = A:GetModule("chat")
	local tab = A.Media.style.chatTab[2]

	-- Two worthless versions of this check were written before this one, and
	-- both are worth naming so a third is not.
	--
	--   `tab < body` - passed at the old 11 against chatText's 12, so it could
	--   not see the very change it was added for.
	--
	--   `body - tab >= 2` - discriminates, but against a number that never
	--   reaches the screen. `Media.style.chatText[2]` supplies the message
	--   FACE only: Chat:SetFrameFont takes the SIZE from Chat:FontSize, which
	--   is Blizzard's own window size plus the `fontDelta` setting. On a stock
	--   profile that is 14 - 5 = 9, not 12.
	--
	-- So the messages are measured where they are actually drawn.
	local body = C3:FontSize(_G.ChatFrame1)
	check(body ~= A.Media.style.chatText[2],
		"the message size does not come from the chatText role - it is"
		.. " Blizzard's size plus fontDelta (" .. body .. ", not "
		.. A.Media.style.chatText[2] .. "), so never compare against that")

	-- The agreed value, pinned. There is nothing internal that distinguishes 10
	-- from 11 - it is a judgement about how loud the navigation should read -
	-- so the only honest guard is the number itself, checked where it lands.
	local fs = _G.ChatFrame1TabText
	-- `fs and fs:GetFont()` would truncate to one value and hand `drawn` a nil.
	local drawn
	if fs then drawn = select(2, fs:GetFont()) end
	check(drawn == 10,
		"and the tab label is drawn at the agreed 10 (" .. tostring(drawn) .. ")")
	check(drawn == tab,
		"which is the role's own number, so Media.lua still governs it")

	-- ...but the composer's channel capsule does not inherit it: the code you
	-- type beside reads at the size you type at.
	local eb = _G.ChatFrame1EditBox
	if eb and eb._tagText then
		local _, size = eb._tagText:GetFont()
		check(size and size ~= tab,
			"while the composer capsule is sized from the typing font, not from"
			.. " the tab role (" .. tostring(size) .. ")")
	end
end

-- ---------------------------------------------------------------------------
-- tooltips
--
-- This module reskins frames it does not own, alongside other addons doing the
-- same thing to the same frames. So most of what is worth asserting is not
-- "does it look right" - it is "does it still leave room for everybody else".
-- ---------------------------------------------------------------------------

print("== tooltips: the card, and what it is drawn instead of ==")
do
	local T = A:GetModule("tooltips")
	check(T and T.enabled, "tooltips module enabled")
	check(T.skinned[GameTooltip], "GameTooltip adopted")
	check(GameTooltip.aetherCard ~= nil, "and given a glass card")
	check(#GameTooltip.aetherCard._fill == 9, "which is a 9-slice panel, not a pill")

	-- The stone border has to be OFF, and it has to stay off. Classic's
	-- SharedTooltip_SetBackdropStyle re-applies the default NineSlice layout on
	-- every OnHide and on every item tooltip, so suppressing it once at login
	-- lasts until the first thing you hover.
	check(not GameTooltip.NineSlice:IsShown(), "Blizzard's NineSlice is suppressed")
	SharedTooltip_SetBackdropStyle(GameTooltip)
	check(not GameTooltip.NineSlice:IsShown(),
		"and is suppressed AGAIN after SharedTooltip_SetBackdropStyle puts it back")

	-- Every other tooltip in the family, so a linked item or a shift-compare does
	-- not open a stone box next to a glass one.
	for _, n in ipairs({ "ItemRefTooltip", "ShoppingTooltip1", "ShoppingTooltip2",
		"EmbeddedItemTooltip", "WorldMapTooltip" }) do
		check(_G[n] and T.skinned[_G[n]], n .. " adopted too")
	end
end

print("== media: every role reaches the real face ==")
do
	-- THE WHOLE INTERFACE went to Friz Quadrata once, and it got there through
	-- this one function. Media:SetFont is the chokepoint every string in the
	-- addon passes through, so a gate in front of it that answers wrong once
	-- answers wrong for everything - which is exactly what happened when the
	-- fallback probed each face through a scratch FontString and CACHED the
	-- verdict. The client said no, the cache remembered it, and the only text
	-- left in Outfit was chat's, because Modules/Chat.lua sets the message font
	-- directly and never comes through here.
	--
	-- So: every role, not a sample. A gate cannot fail for one and not the rest.
	local bad = {}
	for name, style in pairs(A.Media.style) do
		local fs = UIParent:CreateFontString(nil, "ARTWORK")
		A.Media:SetFont(fs, name)
		local got, size = fs:GetFont()
		local want = A.Media.font[style[1]]
		if got ~= want then
			bad[#bad + 1] = name .. " -> " .. tostring(got)
		elseif size ~= math.floor(style[2] + 0.5) then
			bad[#bad + 1] = name .. " @ " .. tostring(size)
		end
	end
	check(#bad == 0,
		"every role in Media.style lands on its own Outfit weight at its own"
		.. " size (" .. (#bad > 0 and table.concat(bad, ", ") or "all of them")
		.. ")")

	-- ...and it does that without reading a return value from anything. Both
	-- SetFont mocks answer nothing on purpose; if this passes, nothing in the
	-- path depends on a client being generous enough to reply.
	do
		local fs = UIParent:CreateFontString(nil, "ARTWORK")
		check(fs:SetFont(A.Media.font.regular, 12, "") == nil,
			"the mock's SetFont answers nothing, as the worst plausible client"
			.. " does")
		A.Media:SetFont(fs, "chatText")
		check(select(1, fs:GetFont()) == A.Media.font[A.Media.style.chatText[1]],
			"and the face still lands - verified by READ-BACK rather than by"
			.. " whatever the call felt like returning")
	end

	-- The fallback still exists for the thing it is for: one of OUR OWN new
	-- FontStrings whose face will not load has no font at all, and no font
	-- draws as nothing.
	do
		_G.__badFonts = { [A.Media.font.light] = true }
		local fs = UIParent:CreateFontString(nil, "ARTWORK")
		A.Media:SetFont(fs, "ttBody")
		check(select(1, fs:GetFont()) == [[Fonts\FRIZQT__.TTF]],
			"a face that will not load degrades to the game font rather than to"
			.. " invisible text (got " .. tostring(select(1, fs:GetFont())) .. ")")

		-- A font OBJECT that refuses keeps the client's own face, which IS the
		-- fallback. Nothing to correct, and nothing to have an opinion about.
		local obj = _G.GameTooltipText
		local before = select(1, obj:GetFont())
		A.Media:SetFont(obj, "ttBody")
		check(select(1, obj:GetFont()) == before,
			"and a font object that refuses one keeps the face it had - the"
			.. " client's, which is what the fallback would have set anyway")
		_G.__badFonts = nil
	end
end

print("== tooltips: the typeface actually reaches the client's font objects ==")
do
	local T = A:GetModule("tooltips")

	-- The three font objects are the highest-leverage thing the module touches:
	-- every line in every tooltip inherits one of them, including lines other
	-- addons add later. They are also the ONLY things the addon styles that are
	-- not FontStrings, and that difference is what broke them.
	--
	-- FontString:SetFont answers isValid. Font:SetFont answers NOTHING. Media
	-- used to read the return of the call it had just made and fall back to the
	-- game font when it was falsy, so every font object landed on
	-- FRIZQT__.TTF - at our sizes, which is why it read as "huge Friz" rather
	-- than as a font that had failed to load. Every FontString was fine
	-- throughout, so nothing else on screen looked wrong.
	for _, n in ipairs({ "GameTooltipHeaderText", "GameTooltipText",
		"GameTooltipTextSmall" }) do
		local obj = _G[n]
		check(obj:SetFont([[Interface\X.ttf]], 12, "") == nil,
			n .. " answers nothing from SetFont, as the client's does - a mock"
			.. " kinder than the client tests the wrong code")
	end

	T:ApplyFonts()

	local wanted = {
		GameTooltipHeaderText = A.Media.style.ttName,
		GameTooltipText       = A.Media.style.ttBody,
		GameTooltipTextSmall  = A.Media.style.ttSmall,
	}
	for n, style in pairs(wanted) do
		local path, size = _G[n]:GetFont()
		check(path == A.Media.font[style[1]],
			n .. " is left on Outfit " .. style[1] .. " rather than on the"
			.. " client's own face (got " .. tostring(path) .. ")")
		check(size == style[2],
			"at the role's size, " .. style[2] .. " (got " .. tostring(size) .. ")")
	end

	-- ...and the fallback still exists for the thing it was written for: an
	-- install with its Media folder missing.
	do
		local saved = A.Media.font.light
		A.Media.font.light = [[Interface\AddOns\AetherUI\Media\Fonts\Nope.ttf]]
		_G.__badFonts = { [A.Media.font.light] = true }
		T:ApplyFonts()
		local path = GameTooltipText:GetFont()
		check(path ~= A.Media.font.light,
			"a face the client cannot load falls back rather than leaving the"
			.. " tooltip blank (got " .. tostring(path) .. ")")
		_G.__badFonts = nil
		A.Media.font.light = saved
		T:ApplyFonts()
	end

	-- Turning the option off puts the CLIENT's face back, not our idea of it.
	local before = select(1, GameTooltipHeaderText:GetFont())
	A.Config:Module("tooltips").restyleFonts = false
	T:ApplyFonts()
	check(GameTooltipHeaderText:GetFont() == [[Fonts\FRIZQT__.TTF]],
		"unticking the option restores the face captured BEFORE we overwrote it"
		.. " (got " .. tostring(GameTooltipHeaderText:GetFont()) .. ")")
	A.Config:Module("tooltips").restyleFonts = true
	T:ApplyFonts()
	check(GameTooltipHeaderText:GetFont() == before, "and ticking it goes back")
end

print("== tooltips: drawn at the deck's scale, and kept there ==")
do
	local T = A:GetModule("tooltips")
	local was = A.db.profile.scale

	A.db.profile.scale = 0.71
	T:OnConfigChanged()
	check(math.abs(GameTooltip:GetScale() - 0.71) < 0.001,
		"the tooltip is drawn at profile.scale like every other module - the"
		.. " deck's 15pt title only lands where the deck put it if the surface"
		.. " under it is the same size as the rest of the HUD (got "
		.. tostring(GameTooltip:GetScale()) .. ")")

	-- ...and SOMEBODY ELSE writes to this.
	--
	-- Leatrix Plus's "Enhance tooltip" sets GameTooltip:SetScale from its own
	-- slider at startup, across the whole family - Leatrix_Plus.lua:10309. Its
	-- default is 100%, so on a UI at 0.71 it lands after us and the tooltip
	-- comes out forty per cent bigger than everything around it. That is not a
	-- preference, it is two addons disagreeing in public, and the one drawing
	-- the card should be the one that answers.
	GameTooltip:Hide()
	GameTooltip:SetScale(1.0)
	check(math.abs(GameTooltip:GetScale() - 1.0) < 0.001,
		"another addon really can take it away")

	GameTooltip:Show()
	check(math.abs(GameTooltip:GetScale() - 0.71) < 0.001,
		"and showing the tooltip takes it back - same rule as StripArt, and the"
		.. " same reason: setting either one once at login lasts until the first"
		.. " thing you hover (got " .. tostring(GameTooltip:GetScale()) .. ")")

	-- The per-module multiplier still rides on top, because a tooltip is the
	-- one surface people most often want a size apart from the HUD.
	-- Hide first: OnShow only fires on a hidden->shown transition, here and in
	-- the client. A test that calls Show on something already up is asserting
	-- against a hook that never ran.
	A.Config:Module("tooltips").scale = 1.2
	GameTooltip:Hide()
	GameTooltip:SetScale(1.0)
	GameTooltip:Show()
	check(math.abs(GameTooltip:GetScale() - 0.71 * 1.2) < 0.001,
		"profile scale times the tooltip's own (got "
		.. tostring(GameTooltip:GetScale()) .. ", want "
		.. tostring(0.71 * 1.2) .. ")")
	A.Config:Module("tooltips").scale = 1.0

	-- No write when it is already right. SetScale re-lays out everything
	-- anchored to the frame and this runs on every show.
	do
		GameTooltip:Hide(); GameTooltip:Show()
		local n = GameTooltip.__scaleWrites or 0
		GameTooltip:Hide(); GameTooltip:Show()
		GameTooltip:Hide(); GameTooltip:Show()
		check((GameTooltip.__scaleWrites or 0) == n,
			"and a tooltip already at the right scale is not written to again -"
			.. " this runs on every show, and SetScale re-lays out everything"
			.. " anchored to the frame")
	end

	A.db.profile.scale = was
	T:OnConfigChanged()
end

print("== tooltips: the card follows lines added AFTER the tooltip is up ==")
do
	-- Pawn hooksecurefuncs about thirty GameTooltip:Set*Item methods and adds its
	-- lines once the tooltip is already on screen; VendorPricePlus and every
	-- LibExtraTip consumer do the same. A card measured at OnShow is the wrong
	-- height for all of them, which is why the module sizes from OnSizeChanged.
	GameTooltip:SetItemByID(1234, "Staff of the Blessed Seer", 3)
	GameTooltip:Show()

	local card = GameTooltip.aetherCard
	card:ClearAllPoints()
	check(#card.__points == 0, "card points cleared, as a sentinel")

	GameTooltip:AddLine("|cff20ff20Pawn: 41.2 DPS|r")   -- what Pawn does
	check(#card.__points == 2,
		"adding a line after Show re-lays the card (the Pawn case)")
	local p1, rel1 = card:GetPoint(1)
	check(p1 == "TOPLEFT" and rel1 == GameTooltip,
		"and it is re-anchored to the tooltip, not to whatever it last held")
end

print("== tooltips: the level strip keeps what other addons appended ==")
do
	local T = A:GetModule("tooltips")

	-- MobInfo2 appends to the same line the badge takes the level out of:
	--     GameTooltipTextLeft2:SetText( txt.." "..mobData.class )   MI2_Tooltip.lua:381
	-- Our hook is already installed, so registering this one AFTER means our
	-- handler runs first and MobInfo2's runs second - one of the two load orders.
	-- Gated on a flag rather than installed and forgotten, for the same reason
	-- the addon gates its own hook bodies: a HookScript hook can never be taken
	-- off again. Left running, this one goes on appending to line 2 for the rest
	-- of the suite and quietly becomes part of every later assertion's fixture.
	local appended = false
	_G.__mi2Active = true
	GameTooltip:HookScript("OnTooltipSetUnit", function(self)
		if not _G.__mi2Active then return end
		local fs = _G.GameTooltipTextLeft2
		if fs and fs:GetText() then
			fs:SetText(fs:GetText() .. " MI2:8-11 dmg")
			appended = true
		end
	end)

	GameTooltip:SetUnit("mouseover")
	check(appended, "the simulated MobInfo2 hook ran at all")

	local line2 = _G.GameTooltipTextLeft2:GetText()
	check(not line2:find("Level"),
		"the level token is out of the line (" .. tostring(line2) .. ")")
	check(line2:find("Humanoid", 1, true),
		"the creature type survived")
	check(line2:find("MI2:8%-11 dmg"),
		"and so did everything MobInfo2 appended - THE point of the whole design")

	-- The other load order, done honestly rather than argued: a fresh tooltip
	-- that the simulated MobInfo2 hooked BEFORE we did.
	local other = _G.__makeTooltip("HarnessOrderTooltip")
	other:HookScript("OnTooltipSetUnit", function(self)
		local fs = _G.HarnessOrderTooltipTextLeft2
		if fs and fs:GetText() then fs:SetText(fs:GetText() .. " MI2-first") end
	end)
	T:Register(other)
	other:SetUnit("mouseover")
	local o2 = _G.HarnessOrderTooltipTextLeft2:GetText()
	check(o2 and not o2:find("Level") and o2:find("MI2%-first"),
		"and it works with the hooks installed the other way round too")

	_G.__mi2Active = nil
end

print("== tooltips: the strip is idempotent, and declines what it cannot parse ==")
do
	local T = A:GetModule("tooltips")

	-- The client re-runs SetUnit about five times a second for a mouseover, so a
	-- strip that ate one more word per pass would look fine for a frame.
	GameTooltip:SetUnit("mouseover")
	local first = _G.GameTooltipTextLeft2:GetText()
	GameTooltip:SetUnit("mouseover")
	GameTooltip:SetUnit("mouseover")
	check(_G.GameTooltipTextLeft2:GetText() == first,
		"three SetUnit passes produce the same line (" .. tostring(first) .. ")")

	-- A line that is not a level line is not a line we touch. This is the
	-- graceful-degradation path: wrong locale, or another addon rewrote it first.
	check(T.ParseLevelLine("Binds when equipped", false) == nil,
		"a non-level line does not parse")
	check(T.ParseLevelLine(nil, false) == nil, "and neither does nil")

	local lvl, rest = T.ParseLevelLine("Level 20 Elite Humanoid trailing junk", true)
	check(lvl == "20", "a level parses out of a full line")
	check(rest == "Humanoid trailing junk",
		"with the classification word dropped and the trailing text kept ("
		.. tostring(rest) .. ")")

	local lvl2, rest2 = T.ParseLevelLine("Level 20 Elite Humanoid", false)
	check(lvl2 == "20" and rest2 == "Elite Humanoid",
		"and the classification word is KEPT when no chip is going to say it")

	local skull = T.ParseLevelLine("Level ?? Boss", false)
	check(skull == "??", "the skull parses as a level, not as a failure")

	-- The pattern comes from the client's own string, not from an English
	-- literal, or every non-enUS player loses the badge.
	check(T.LevelPattern():find("Level"),
		"and the pattern is built from UNIT_LEVEL_TEMPLATE")
end

print("== tooltips: the elite chip, the badge, and the gutter that makes room ==")
do
	GameTooltip:SetUnit("mouseover")     -- Gazrog, elite

	local badge, chip = GameTooltip.aetherBadge, GameTooltip.aetherChip
	check(badge and badge:IsShown(), "the level badge is drawn")
	check(badge.label:GetText() == "20", "carrying the unit's level")
	check(chip and chip:IsShown(), "and an elite chip beside the name")

	-- The badge gets its room from the CARD growing left, not from re-anchoring
	-- the tooltip's own FontStrings - which would fight the C layout code and
	-- break LibExtraTip's right-column arithmetic (LibExtraTip.lua:1222).
	check(GameTooltip.aetherGutter and GameTooltip.aetherGutter > 0,
		"the card carries a left gutter for it (" .. tostring(GameTooltip.aetherGutter) .. ")")
	local _, _, _, x = GameTooltip.aetherCard:GetPoint(1)
	check(x and x < 0,
		"so the card's TOPLEFT sits left of the tooltip's (" .. tostring(x) .. ")")

	local anchorTo = select(2, badge:GetPoint(1))
	check(anchorTo == _G.GameTooltipTextLeft1,
		"and the badge hangs off line 1, so it tracks the name's own baseline")

	-- A plain mob gets neither, and the gutter goes back to nothing.
	_G.__units.mouseover.classification = "normal"
	GameTooltip:SetUnit("mouseover")
	check(not GameTooltip.aetherChip:IsShown(), "a normal mob gets no chip")
	_G.__units.mouseover.classification = "elite"
end

print("== tooltips: the health hairline ==")
do
	local T = A:GetModule("tooltips")
	local bar = _G.GameTooltipStatusBar
	check(bar and bar.aetherStyled, "the status bar is restyled in place")
	check(bar and bar.lockColor,
		"with lockColor set, or HealthBar_OnValueChanged forces it back to flat green")
	check(bar and bar:GetHeight() == 7, "at the deck's 7px")

	-- Guarded rather than indexed straight through. A regression that loses the
	-- readout entirely should show up here as a failed check naming what is
	-- missing, not as a nil-index that takes the rest of the suite with it.
	check(bar and bar.aetherValue ~= nil, "and a readout under it")
	if bar and bar.aetherValue then
		local function readout() return bar.aetherValue:GetText() or "<nil>" end

		GameTooltip:SetUnit("mouseover")
		check(readout() == "4,820  /  4,820",
			"which is grouped (" .. readout() .. ")")

		-- Driven from OnValueChanged, which is the only hook there is: nothing in
		-- Lua shows or fills this bar, the C tooltip code does it.
		_G.__units.mouseover.hp = 2410
		bar:SetValue(2410)
		check(readout() == "2,410  /  4,820", "a value change alone updates it")
		_G.__units.mouseover.hp = 4820

		local conf = A.Config:Module("tooltips")
		conf.healthValues = false
		T:UpdateStatusBar(bar)
		check(readout() == "", "and the readout is separable from the bar")
		conf.healthValues = true
	end
end

print("== tooltips: a player is their class colour ==")
do
	local T = A:GetModule("tooltips")

	-- The report: everybody appeared in "mage blue". They were - one blue for
	-- every friendly player is the deck's own treatment, and it was the default
	-- here while the unit frames class-coloured by default. Same player, two
	-- answers, a tooltip's width apart. That reads as class colours having been
	-- LOST rather than as a preference being expressed.
	check(A.Config:Module("tooltips").classColorNames ~= false,
		"tooltips class-colour by default, like the unit frames")

	-- The tooltip's own unit, not the target - see the note on __units.mouseover.
	local mo = _G.__units.mouseover
	local was = { mo.isPlayer, mo.class, mo.classToken, mo.reaction, mo.creature }
	mo.isPlayer, mo.class, mo.classToken = true, "Rogue", "ROGUE"
	mo.reaction, mo.creature = 5, nil
	GameTooltip:SetUnit("mouseover")

	local r, g, b = _G.GameTooltipTextLeft1:GetTextColor()
	-- Rogue yellow, chosen because it is nowhere near the deck's blue: a class
	-- colour that happens to look like the thing it replaced proves nothing.
	local want = RAID_CLASS_COLORS.ROGUE
	check(math.abs(r - want.r) < 0.01 and math.abs(g - want.g) < 0.01
		and math.abs(b - want.b) < 0.01,
		"a friendly player's name is their class colour (got "
		.. string.format("%.2f %.2f %.2f", r, g, b) .. ", want "
		.. string.format("%.2f %.2f %.2f", want.r, want.g, want.b) .. ")")

	-- ...and CUSTOM_CLASS_COLORS wins, which is what a colour-blind or
	-- ClassColors addon publishes. Chat already honoured it and the other two
	-- places did not, so one addon got recoloured names in chat and Blizzard's
	-- palette everywhere else.
	_G.CUSTOM_CLASS_COLORS = { ROGUE = { r = 0.1, g = 0.9, b = 0.2 } }
	GameTooltip:SetUnit("mouseover")
	local r2, g2, b2 = _G.GameTooltipTextLeft1:GetTextColor()
	check(math.abs(r2 - 0.1) < 0.01 and math.abs(g2 - 0.9) < 0.01,
		"an addon's own class colours are used ahead of Blizzard's (got "
		.. string.format("%.2f %.2f %.2f", r2, g2, b2) .. ")")
	_G.CUSTOM_CLASS_COLORS = nil

	-- The deck's treatment is still one switch away.
	A.Config:Module("tooltips").classColorNames = false
	GameTooltip:SetUnit("mouseover")
	local r3 = select(1, _G.GameTooltipTextLeft1:GetTextColor())
	check(math.abs(r3 - A.Palette.c.ttFriendly[1]) < 0.01,
		"and off gives the deck's one blue for every friendly player")
	A.Config:Module("tooltips").classColorNames = true

	-- An NPC that DOES have a class token, which is the realistic case: the
	-- client happily answers UnitClass for a great many of them. Class colouring
	-- has to be gated on being a PLAYER, not on there being a class to use -
	-- and an NPC left with a class token is the only way to tell those apart.
	mo.isPlayer = false
	mo.class, mo.classToken = "Rogue", "ROGUE"
	mo.creature = "Humanoid"
	GameTooltip:SetUnit("mouseover")
	local r4 = select(1, _G.GameTooltipTextLeft1:GetTextColor())
	check(math.abs(r4 - A.Palette.c.ttFriendlyNPC[1]) < 0.01,
		"an NPC keeps the friendly-NPC green - 'that is a person' is different"
		.. " information from 'that is a quest giver'")

	mo.isPlayer, mo.class, mo.classToken = was[1], was[2], was[3]
	mo.reaction, mo.creature = was[4], was[5]
end

print("== tooltips: quality drives the rim, not just the title ==")
do
	GameTooltip:SetItemByID(1234, "Staff of the Blessed Seer", 3)   -- rare
	local card = GameTooltip.aetherCard
	local rare = A.Palette.c.itemQuality[3].edge
	local e = card._edgeColor
	check(e and math.abs(e[1] - rare[1]) < 0.001 and math.abs(e[3] - rare[3]) < 0.001,
		"a rare item tints the card's rim")
	check(card._rim ~= nil and card._rim[1]:IsShown(),
		"and rare and above get an outer bloom")

	local ink = { _G.GameTooltipTextLeft1:GetTextColor() }
	check(math.abs(ink[1] - rare[1]) < 0.001, "the title takes the quality colour")

	GameTooltip:SetItemByID(99, "Linen Cloth", 1)                    -- common
	check(GameTooltip.aetherCard._rim == nil
		or not GameTooltip.aetherCard._rim[1]:IsShown(),
		"a common item gets no bloom - that is what makes a purple readable")

	-- The title's INK is a DIFFERENT token from the rim, and the two share an RGB
	-- to the digit - so nothing about the colour can tell them apart and a check
	-- on r,g,b passes whichever one was used. They part on ALPHA: a rim on common
	-- is a hint at 0.30, the title is type at 0.90. Reusing the rim as ink put a
	-- barely-there item name at the top of the card, and it was the alpha that
	-- did it, not the hue.
	--
	-- This was Daylight's check, where the rims were dark and the title read
	-- near-black on a pale wash. The family that replaced it has no pale skin, so
	-- the rims are semantic and identical throughout, and alpha is now the only
	-- thing left that can catch the same mistake.
	local ink1 = { _G.GameTooltipTextLeft1:GetTextColor() }
	local rim = A.Palette.c.itemQuality[1].edge
	local titleInk = A.Palette.c.ttQuality[1]
	check(math.abs(rim[1] - titleInk[1]) < 0.001,
		"the common rim and the common title ink share an RGB, so hue can prove"
		.. " nothing here")
	check(math.abs((rim[4] or 1) - (titleInk[4] or 1)) > 0.2,
		"and part on alpha - a rim is a hint, a title is type ("
		.. string.format("%.2f vs %.2f", rim[4] or 1, titleInk[4] or 1) .. ")")
	check(math.abs((ink1[4] or 1) - (titleInk[4] or 1)) < 0.001,
		"so the title is drawn at the TITLE's alpha, not the rim's (" ..
		string.format("%.2f", ink1[4] or 1) .. ")")
	local lum = 0.299 * ink1[1] + 0.587 * ink1[2] + 0.114 * ink1[3]
	check(lum > 0.7, "and it stays light type, like every other string on the"
		.. " card (" .. string.format("%.2f", lum) .. ")")
end

print("== tooltips: lore gold does not paint over another addon's line ==")
do
	GameTooltip:SetSpell(5504, "Conjure Water", "Conjures 14 bottles of fresh water.")
	local gold = A.Palette.c.ttLore
	local body = { _G.GameTooltipTextLeft2:GetTextColor() }
	check(math.abs(body[1] - gold[1]) < 0.001,
		"the client's own body copy goes lore gold")

	-- Pawn's score line is green on purpose. Recolouring it would be exactly the
	-- kind of thing this module exists not to do.
	GameTooltip:AddLine("Pawn: 41.2", 0.12, 1.0, 0.0)
	A:GetModule("tooltips"):OnSpell(GameTooltip)
	local pawn = { _G.GameTooltipTextLeft3:GetTextColor() }
	check(math.abs(pawn[2] - 1.0) < 0.001 and pawn[1] < 0.5,
		"but a line another addon deliberately coloured keeps its colour")
end

print("== tooltips: anchoring is scoped ==")
do
	local T = A:GetModule("tooltips")
	check(T.anchor ~= nil, "there is a mover anchor for unit tooltips")
	local entry = A.Movers.registry and A.Movers.registry.tooltip
	check(entry and entry.frame == T.anchor,
		"and Movers is actually holding it - `x ~= nil or true` is a check that"
		.. " cannot fail, which is not a check")

	GameTooltip_SetDefaultAnchor(GameTooltip, UIParent)
	local _, rel = GameTooltip:GetPoint(1)
	check(rel == T.anchor,
		"a default-anchored tooltip lands on the mover frame, not Blizzard's corner")

	-- The scoping rule. A bag slot that called SetOwner on itself keeps the
	-- position it asked for; only default/world tooltips get dragged to the
	-- cursor. Widening this is the fastest way to make every other addon's
	-- tooltips feel broken.
	GameTooltip.default = nil
	GameTooltip:SetOwner(_G.ContainerFrame1 or CreateFrame("Frame", nil, UIParent), "ANCHOR_RIGHT")
	check(not T.WantsCursor(GameTooltip),
		"a tooltip with its own owner is NOT dragged to the cursor")

	GameTooltip.default = 1
	check(T.WantsCursor(GameTooltip), "a default-anchored one is")

	local conf = A.Config:Module("tooltips")
	conf.cursorItems = false
	check(not T.WantsCursor(GameTooltip), "and the whole behaviour is one switch")
	conf.cursorItems = true
end

print("== tooltips: the typeface reaches lines we never see ==")
do
	-- Restyling the three FONT OBJECTS is the highest-leverage thing in the
	-- module: every line inherits from one of them, including the ones Pawn and
	-- MobInfo2 add later, so their lines come out in Outfit without either addon
	-- knowing we exist.
	local size = {}
	for _, n in ipairs({ "GameTooltipHeaderText", "GameTooltipText", "GameTooltipTextSmall" }) do
		local path, pt = _G[n]:GetFont()
		size[n] = pt
		check(path and path:find("Outfit"), n .. " is drawn in Outfit")
		check(type(pt) == "number" and pt > 0, "  at a real size (" .. tostring(pt) .. ")")
	end

	-- `size.a > size.b` on two nils is an error, not a failure, and an error here
	-- eats every check after it. Ask the question only once both answers exist.
	check(size.GameTooltipHeaderText and size.GameTooltipText
		and size.GameTooltipHeaderText > size.GameTooltipText,
		"and the name outranks the body copy")
end

print("== tooltips: the badge stands down for an addon that READS that line ==")
do
	local T = A:GetModule("tooltips")
	local conf = A.Config:Module("tooltips")

	-- MobInfo2 does not only append to line 2. It locates a mob's extra info by
	-- scanning for the level NUMBER as a substring (MobInfo2.lua:2118-2131):
	--     if string.find(ttLeft, levelInfo) then levelLine = idx
	-- Move the digits into the badge and that scan finds nothing, on its shipped
	-- default path (MobInfoConfig.UseGameTT == 0). There is no having it both
	-- ways, so the badge yields.
	_G.MobInfoConfig = { UseGameTT = 0 }
	_G.MI2_BuildTooltipMob = function() end

	GameTooltip:SetUnit("mouseover")
	local line = _G.GameTooltipTextLeft2:GetText()
	check(line and line:find("20", 1, true),
		"with MobInfo2 loaded the level NUMBER stays in the line (" .. tostring(line) .. ")")
	check(not GameTooltip.aetherBadge:IsShown(),
		"and the badge stands down rather than blinding it")

	-- ...but it is the player's tooltip. One switch takes it back.
	conf.deferToLevelReaders = false
	GameTooltip:SetUnit("mouseover")
	check(GameTooltip.aetherBadge:IsShown(), "overriding the deference restores the badge")
	conf.deferToLevelReaders = true

	-- MobInfo2 in its own-window mode does not do that scan, so it is not a
	-- reason to give up the badge. Detected by the SETTING, not by the addon.
	_G.MobInfoConfig.UseGameTT = 1
	GameTooltip:SetUnit("mouseover")
	check(GameTooltip.aetherBadge:IsShown(),
		"and MobInfo2 in its own-window mode is not a reason to stand down")

	_G.MobInfoConfig, _G.MI2_BuildTooltipMob = nil, nil
end

print("== tooltips: re-entry, and the two-word classification ==")
do
	local T = A:GetModule("tooltips")

	GameTooltip:SetUnit("mouseover")
	check(GameTooltip.aetherBadge:IsShown(), "badge up after a fill")
	local before = _G.GameTooltipTextLeft2:GetText()

	-- Running the handler again over text it has ALREADY stripped finds no level
	-- - correctly, we took it out. Reading that as "no badge here" would hide the
	-- badge drawn a moment ago, so the fill remembers it was stripped.
	T:OnUnit(GameTooltip)
	check(GameTooltip.aetherBadge:IsShown(),
		"and still up after the handler is re-entered on the same text")
	check(_G.GameTooltipTextLeft2:GetText() == before, "with the line unchanged")
	check(GameTooltip.aetherGutter > 0, "and the gutter still held open")

	-- The badge number comes from UnitLevel, not from the parsed token, so a
	-- locale or an addon that reformatted the line cannot put a wrong number in
	-- the disc.
	check(GameTooltip.aetherBadge.label:GetText() == tostring(UnitLevel("mouseover")),
		"and the number is the unit's own level, not the parsed string")

	-- A rare elite writes TWO classification words in front of the type. Breaking
	-- after the first left "Elite Humanoid" under a chip already saying "Rare+".
	local _, rest = T.ParseLevelLine("Level 20 Rare Elite Humanoid", true)
	check(rest == "Humanoid", "both classification words come off a rare elite ("
		.. tostring(rest) .. ")")
end

section("tooltips: the level badge is a circle, not a rumour of one", function()
	local T = A:GetModule("tooltips")

	-- Pinned, not inherited. By the time this runs the suite has flipped every
	-- toggle in the options tree both ways and the tooltip happens to be sitting
	-- at scale 1 - where "snap in the badge's own units" and "snap in UIParent's"
	-- give the same answer, and the assertion below cannot tell them apart. The
	-- whole point of the fix is what happens at the scale it actually ships at.
	local wasScale = GameTooltip:GetScale()
	GameTooltip:SetScale(0.71)

	_G.__units.mouseover.isPlayer = false
	GameTooltip:SetUnit("mouseover")
	local badge = GameTooltip.aetherBadge
	check(badge and badge:IsShown(), "badge drawn")
	check(math.abs(badge:GetEffectiveScale() - 0.71) < 1e-6,
		"and it inherits the tooltip's scale (" .. string.format("%.3f", badge:GetEffectiveScale()) .. ")")

	-- 1. No MaskTexture. A mask edge is the client's to anti-alias and it does
	--    that poorly - the same fact Tools/generate_textures.py records against
	--    minimap_border. At 46px with a portrait in it that is a fair trade; at
	--    26px the stair-stepping IS the shape.
	local masked = false
	for _, r in ipairs({ badge.disc, badge.ring }) do
		if r.__masks and #r.__masks > 0 then masked = true end
	end
	check(not masked, "the disc is drawn from Circle-Mask as artwork, not cut out"
		.. " with a mask")

	-- 2. The rim laps OVER the disc rather than sitting flush inside it, so the
	--    disc's own outer texel row cannot peek out from under it.
	local p1, rel1, _, x1, y1 = badge.ring:GetPoint(1)
	check(p1 == "TOPLEFT" and rel1 == badge and x1 < 0 and y1 > 0,
		"and the rim is drawn proud of it on every side (" .. tostring(x1) .. ")")
	check(math.abs(x1) == A:PxIn(badge),
		"by exactly one physical pixel, in the badge's own units - not UIParent's,"
		.. " which at the tooltip's 0.71 would be seven tenths of one")

	-- 3. The diameter lands on the pixel grid. Unsnapped, a 26-unit disc inside a
	--    frame scaled to 0.71 is 18.46 physical pixels and its rim crosses a
	--    boundary the whole way round, which the client resolves as half-lit grey.
	local step = A:PxIn(badge)
	local q = badge:GetWidth() / step
	check(math.abs(q - math.floor(q + 0.5)) < 1e-6,
		"and the diameter is a whole number of physical pixels ("
		.. string.format("%.3f", q) .. ")")
	check(math.abs(step - A.pixel) > 1e-6,
		"measured in the badge's OWN units, which at 0.71 are not UIParent's"
		.. " (" .. string.format("%.4f vs %.4f", step, A.pixel) .. ")")

	-- 4. The badge is the NAME'S colour, whoever the name belongs to.
	--
	--    Screen 6a tints the three NPC variants by reaction and leaves the
	--    anchored player card's badge in the skin's purple, and the reason is
	--    sound about REACTION: a player is friendly nearly every time you see
	--    one, so tinting by that says nothing the name did not and comes out a
	--    washed grey-blue. It is not sound about a CLASS colour, which is the
	--    one thing on the card you cannot read off the name's wording.
	local hostile = A.Palette.c.ttHostile
	local dr, dg, db, da = badge.disc:GetVertexColor()
	check(math.abs(dr - hostile[1]) < 0.001 and math.abs(da - 0.15) < 0.001,
		"a hostile NPC's badge is its reaction colour at .15")

	-- A class TOKEN, not just a display name. UnitClass returns the token
	-- second, and Palette:ClassColor keys on it - a mock player carrying only
	-- "Shaman" has no class colour at all, so the branch under test is never
	-- reached and the badge falls back to the purple the check was expecting.
	-- Which is how this passed before the behaviour changed.
	_G.__units.mouseover.isPlayer = true
	_G.__units.mouseover.class, _G.__units.mouseover.classToken = "Mage", "MAGE"
	GameTooltip:SetUnit("mouseover")
	local mage = RAID_CLASS_COLORS.MAGE
	local pr, pg, pb, pa = badge.disc:GetVertexColor()
	check(math.abs(pr - mage.r) < 0.001 and math.abs(pg - mage.g) < 0.001
		and math.abs(pa - 0.15) < 0.001,
		"and a player's badge is their CLASS colour at the same .15, so the rule"
		.. " is one rule (got " .. string.format("%.2f %.2f %.2f @%.2f",
			pr, pg, pb, pa) .. ")")
	local ir = { badge.label:GetTextColor() }
	check(math.abs(ir[1] - mage.r) < 0.001 and math.abs(ir[2] - mage.g) < 0.001,
		"with the same colour on it, not the skin's #cdbcff")

	-- Switch class colours off and the ink is a reaction again - and so is the
	-- reason, so the badge goes back to the skin's purple.
	local wasCC = A.db.profile.modules.tooltips.classColorNames
	A.db.profile.modules.tooltips.classColorNames = false
	GameTooltip:SetUnit("mouseover")
	local want = A.Palette.c.ttBadgeBg
	pr, pg, pb, pa = badge.disc:GetVertexColor()
	check(math.abs(pr - want[1]) < 0.001 and math.abs(pa - want[4]) < 0.001,
		"with class colours off it is the skin's own purple again, as screen 6a"
		.. " draws it - a friendly player's REACTION still says nothing worth"
		.. " spending the card's accent on")
	A.db.profile.modules.tooltips.classColorNames = wasCC

	_G.__units.mouseover.isPlayer = false
	GameTooltip:SetScale(wasScale)
end)

section("tooltips: the cursor follow, and the flip at a screen edge", function()
	local T = A:GetModule("tooltips")

	-- A flat coordinate space to reason in. The maths is done entirely in the
	-- TOOLTIP's own units - GetCursorPosition returns physical pixels, and
	-- SetPoint offsets are read in the space of the frame being positioned - so
	-- scale 1 everywhere is the case where the two agree and any arithmetic slip
	-- shows up as a plain wrong number rather than as a scale factor.
	local oldW, oldH = UIParent:GetWidth(), UIParent:GetHeight()
	UIParent:SetSize(1000, 600)
	UIParent.__scale = 1
	GameTooltip.__scale = 1
	GameTooltip:SetSize(300, 120)

	GameTooltip.default = 1
	GameTooltip:SetItemByID(1234, "Staff of the Blessed Seer", 3)
	check(GameTooltip.aetherFollow, "a default-anchored item tooltip is marked to follow")

	cursorX, cursorY = 200, 400
	GameTooltip.__scripts.OnUpdate(GameTooltip)
	local p, rel, relP, x, y = GameTooltip:GetPoint(1)
	check(p == "TOPLEFT" and rel == UIParent and relP == "BOTTOMLEFT",
		"it hangs its TOPLEFT off the screen origin")
	check(x == 224 and y == 378,
		"at the deck's +24 / -22 from the cursor (" .. tostring(x) .. ", " .. tostring(y) .. ")")

	-- Near the right edge it FLIPS rather than clamping. Clamping slides the card
	-- under the cursor, which is worse than putting it on the other side.
	cursorX, cursorY = 900, 400
	GameTooltip.__scripts.OnUpdate(GameTooltip)
	local _, _, _, fx = GameTooltip:GetPoint(1)
	check(fx == 900 - 24 - 300,
		"crowded on the right it flips to the other side of the cursor ("
		.. tostring(fx) .. ")")
	check(fx + 300 <= 900, "so the card never lands under the pointer")

	-- And at the bottom.
	cursorX, cursorY = 200, 60
	GameTooltip.__scripts.OnUpdate(GameTooltip)
	local _, _, _, _, fy = GameTooltip:GetPoint(1)
	check(fy == 60 + 22 + 120, "and flips upward at the bottom edge (" .. tostring(fy) .. ")")

	-- A tooltip nobody marked is left exactly where its owner put it.
	GameTooltip.aetherFollow = nil
	GameTooltip:ClearAllPoints()
	GameTooltip.__scripts.OnUpdate(GameTooltip)
	check(#GameTooltip.__points == 0,
		"and an unmarked tooltip is not moved at all - the follow flag is decided"
		.. " once per tooltip, not per frame")

	cursorX, cursorY = 500, 400
	UIParent:SetSize(oldW, oldH)
end)

section("tooltips: the anchor corner comes from where the frame SITS", function()
	local T = A:GetModule("tooltips")

	-- Not from the point string saved beside it. Movers re-anchors every drag to
	-- BOTTOMLEFT of UIParent and saves what it set, so that string reads
	-- BOTTOMRIGHT until the first drag and BOTTOMLEFT forever after - never a TOP
	-- variant, whatever the player actually did with the frame. A tooltip grows
	-- away from the corner it is pinned by, so believing it means one parked near
	-- the top of the screen grows off it.
	UIParent:SetSize(1000, 600)
	UIParent.__scale = 1

	T.anchor:SetGeom({ cx = 100, cy = 500 })      -- top-left quadrant
	GameTooltip_SetDefaultAnchor(GameTooltip, UIParent)
	check(GameTooltip:GetPoint(1) == "TOPLEFT",
		"parked top-left, the tooltip presents its TOPLEFT and grows down-right")

	T.anchor:SetGeom({ cx = 900, cy = 80 })       -- bottom-right, the default
	GameTooltip_SetDefaultAnchor(GameTooltip, UIParent)
	check(GameTooltip:GetPoint(1) == "BOTTOMRIGHT", "and bottom-right, the other way")

	-- Saved anchor data says BOTTOMLEFT; the frame is bottom-RIGHT. The screen
	-- wins, which is the whole point.
	A.db.profile.anchors.tooltip = { point = "BOTTOMLEFT", relPoint = "BOTTOMLEFT", x = 0, y = 0 }
	GameTooltip_SetDefaultAnchor(GameTooltip, UIParent)
	check(GameTooltip:GetPoint(1) == "BOTTOMRIGHT",
		"even when the saved point string disagrees")
	A.db.profile.anchors.tooltip = nil

	T.anchor:SetGeom(nil)
end)

section("tooltips: adopting frames whose names cannot be known in advance", function()
	local T = A:GetModule("tooltips")

	-- LibExtraTip - how Informant, Enchantrix and BeanCounter reach a tooltip -
	-- names its frames from its own version string:
	--     LIBSTRING = LIBNAME.."_"..MAJOR.."_"..MINOR      LibExtraTip.lua:63
	--     CreateFrame("GameTooltip", LIBSTRING.."Tooltip"..n, ...)          :1112
	-- so they carry a version number and cannot be in a static list.
	local lx = _G.__makeTooltip("LibExtraTip_1_400Tooltip1")
	check(not T.skinned[lx], "a LibExtraTip frame starts unskinned")
	local n = T:Sweep()
	check(n >= 1 and T.skinned[lx],
		"and the sweep adopts it (" .. tostring(n) .. " new)")
	check(lx.aetherCard ~= nil, "with a card of its own, so Auctioneer's extra tip"
		.. " is not a stone box glued under a glass one")
	check(T:Sweep() == 0, "and sweeping again adopts nothing twice")

	check(T:Register(GameTooltip) == false, "registering an adopted frame is a no-op")

	-- An anonymous frame has no global line strings to find. It must decline to
	-- decorate rather than nil-index its way through the unit handler.
	local anon = CreateFrame("Frame", nil, UIParent)
	anon.__hasScript = {}
	T:Register(anon)
	check(pcall(T.OnUnit, T, anon), "a nameless tooltip does not throw the unit handler")

	check(pcall(T.Diagnose, T), "and /aether tooltips reports without erroring")
end)

section("tooltips: a template this cannot parse costs a badge, not a line", function()
	local T = A:GetModule("tooltips")
	local real = _G.UNIT_LEVEL_TEMPLATE

	-- A positional placeholder - which some locales use - is a shape the pattern
	-- builder does not know. The dangerous outcome is not "no badge": it is a
	-- pattern left with one trailing capture, which matches the WHOLE line, hands
	-- back nil as the remainder, and writes an empty string over the text.
	_G.UNIT_LEVEL_TEMPLATE = "Level %1$d"
	check(T.LevelPattern() == nil, "an unparseable template yields no pattern at all")
	check(T.ParseLevelLine("Level 20 Humanoid", false) == nil,
		"so nothing parses, and nothing is rewritten")

	_G.UNIT_LEVEL_TEMPLATE = "Stufe %d"
	check(select(2, T.ParseLevelLine("Stufe 20 Humanoid", false)) == "Humanoid",
		"and the pattern re-derives when the client's template is not English")

	_G.UNIT_LEVEL_TEMPLATE = real
	check(T.LevelPattern() ~= nil, "back to the real one")
end)

section("tooltips: the guild line", function()
	local u = _G.__units.mouseover
	local was, wasGuild, wasClass = u.isPlayer, u.guild, u.classification
	u.isPlayer, u.guild, u.classification = true, "Samophlange", nil
	u.class = "Shaman"

	GameTooltip:SetUnit("mouseover")
	local fs = _G.GameTooltipTextLeft2
	check(fs:GetText() == "<Samophlange>", "the client writes the guild on its own line")
	local r, g, b = fs:GetTextColor()
	local want = A.Palette.c.ttGuild
	check(math.abs(r - want[1]) < 0.001 and math.abs(b - want[3]) < 0.001,
		"and it takes the accent, matched on the <brackets> rather than on a line"
		.. " index - an unguilded player has no such line at all")

	u.isPlayer, u.guild, u.classification = was, wasGuild, wasClass
end)

print("== tooltips: turning it off gives Blizzard's back ==")
do
	local T = A:GetModule("tooltips")
	A:SetModuleEnabled("tooltips", false)
	check(GameTooltip.NineSlice:IsShown(),
		"disabling restores the client's own border - a hook that cannot be"
		.. " removed still has to be able to become a no-op")
	check(not GameTooltip.aetherCard:IsShown(), "and hides the card")

	-- The parts that are easy to forget, because leaving them is not visible the
	-- way a leftover card would be. "Off" has to mean the client's tooltip, not a
	-- slightly haunted one.
	local bar = _G.GameTooltipStatusBar
	check(bar:GetHeight() == 8, "the health bar goes back to Blizzard's 8px")
	check(not bar.lockColor, "and stops refusing the client's own colour")
	check(not bar.aetherValue:IsShown(), "and our readout goes with it")
	local path = _G.GameTooltipText:GetFont()
	check(path and not path:find("Outfit"),
		"and the client's own tooltip face comes back (" .. tostring(path) .. ")")

	A:SetModuleEnabled("tooltips", true)
	check(T.enabled, "and it comes back")
	check(not GameTooltip.NineSlice:IsShown(),
		"with the stone border off again - re-enabling has to redo what disabling"
		.. " undid, or off-then-on is a third state neither of them describes")
	local back = _G.GameTooltipText:GetFont()
	check(back and back:find("Outfit"), "and Outfit back")
	check(_G.GameTooltipStatusBar:GetHeight() == 7, "and the hairline back")
end

print("== greeting: which build is this, without being asked ==")
do
	local said = A.Errors:Capture(function()
		A.__greeted = nil
		A:Greet()
	end)
	check(said:find(A.version, 1, true) ~= nil,
		"login says which build this is (" .. A.version .. ") - the point is a"
		.. " player can report it without being asked first")
	check(said:find("/aether help", 1, true) ~= nil,
		"and points at /aether HELP for the command list - bare /aether opens"
		.. " the settings panel, so sending people there 'for commands' sends"
		.. " them somewhere that lists none")
	-- And it is a real command. A greeting that names one which does nothing is
	-- worse than no greeting: it is the first thing a new player types.
	local helped = A.Errors:Capture(function()
		SlashCmdList["AETHERUI"]("help")
	end)
	check(helped:find("/aether", 1, true) ~= nil,
		"and /aether help actually lists the commands")

	local lines = 0
	for _ in said:gmatch("[^\n]+") do lines = lines + 1 end
	check(lines <= 2,
		"in two lines, not a banner (" .. lines .. ") - a greeting long enough"
		.. " to scroll the chat frame is one people turn off")

	-- AND IT SAYS WHERE TO ASK. Somebody who has just installed this has no
	-- idea where to go when something looks wrong, and the greeting is the
	-- one moment they are certainly reading. On the commands line rather
	-- than a third of its own, because two lines is the whole budget - and
	-- the check above is what says so.
	check(said:find("discord.gg/drveoj", 1, true) ~= nil,
		"the greeting says where to get support")
	-- RAW, not through Errors:Capture. That one strips colour codes on the way
	-- out - they are for a chat frame, not for a paste into a bug report - so
	-- asking IT whether something is highlighted always answers no.
	local raw = {}
	local realPrint = A.Print
	A.Print = function(_, msg) raw[#raw + 1] = tostring(msg) end
	A.__greeted = nil
	A:Greet()
	A.Print = realPrint
	local rawText = table.concat(raw, " ")
	check(rawText:find("|cff%x%x%x%x%x%xdiscord%.gg/drveoj|r") ~= nil,
		"with the address highlighted - it is the part somebody has to copy,"
		.. " and a plain-text address in a wall of chat is one nobody sees")

	-- Said once. Boot runs on ADDON_LOADED and again on PLAYER_LOGIN.
	local again = A.Errors:Capture(function() A:Greet() end)
	check(again == "", "and only once, however many times boot runs")

	local was = A.db.profile.greet
	A.db.profile.greet = false
	local quiet = A.Errors:Capture(function()
		A.__greeted = nil
		A:Greet()
	end)
	check(quiet == "", "off means silent")
	A.db.profile.greet = was
end

print("== errors: an error you cannot copy is an error you cannot send anybody ==")
do
	local Errors = A.Errors
	check(Errors ~= nil, "the catcher is loaded")

	-- Stand a handler of our own in first, the way BugSack or the client's own
	-- would be, and check we end up BEHIND it rather than on top of it.
	local seen = {}
	seterrorhandler(function(e) seen[#seen + 1] = tostring(e) end)

	Errors.installed = false
	for i = #Errors.log, 1, -1 do Errors.log[i] = nil end
	check(Errors:Install() == true, "it installs")

	local handler = geterrorhandler()
	handler("Interface/AddOns/Thing/Thing.lua:12: attempt to index a nil value")
	check(#Errors.log == 1, "an error is caught")
	check(#seen == 1,
		"AND PASSED ON to the handler that was already there - swallowing it"
		.. " would blind every other tool on the machine, which is worse than"
		.. " the problem this solves")

	-- A tick loop throws the same line every frame. Twelve copies of it is a
	-- box with one error in it and no room for the one before.
	handler("Interface/AddOns/Thing/Thing.lua:12: attempt to index a nil value")
	check(#Errors.log == 1 and Errors.log[1].count == 2,
		"the same error twice running is counted, not repeated (x"
		.. Errors.log[1].count .. ")")

	for i = 1, 40 do handler("distinct error " .. i) end
	check(#Errors.log <= 12, "and the list is capped (" .. #Errors.log .. ")")
	check(Errors.log[1].text == "distinct error 40",
		"newest first - the last thing that broke is the thing you came to read")

	-- The handler runs INSIDE the client's error path. Anything it raises comes
	-- straight back to it, and the client does not break that loop for you.
	local realInsert = table.insert
	table.insert = function() error("deliberate") end
	local ok = pcall(handler, "an error while we are already handling one")
	table.insert = realInsert
	check(ok,
		"and the catcher never raises out of the error path itself - it runs"
		.. " INSIDE the client's error handling, so anything it throws arrives"
		.. " back at the thing that threw it and the client does not break that"
		.. " loop for you")

	local text = Errors:Text()
	check(text:find("distinct error 40", 1, true) ~= nil,
		"the box carries the actual message, ready to select")

	-- A bug report without a version is a report about some build or other.
	check(text:find(A.version, 1, true) ~= nil,
		"and the version is at the top of it (" .. A.version .. ") - the first"
		.. " question about any report is which build it came from")

	-- /aether diag answers into the chat frame, the one place its answer cannot
	-- be selected.
	local grabbed = Errors:Capture(function()
		A:Print("|cff9d7bffcoloured|r line one")
		if DEFAULT_CHAT_FRAME then DEFAULT_CHAT_FRAME:AddMessage("line two") end
	end)
	check(grabbed:find("line one", 1, true) and grabbed:find("line two", 1, true),
		"chat output can be captured into the box - BOTH ways this addon writes"
		.. " a line, because diag uses one and everything else uses the other")
	check(grabbed:find("|cff", 1, true) == nil,
		"with the colour codes stripped: they are for a chat frame, not for a"
		.. " paste into a bug report")

	-- Whatever happens in there, chat has to work afterwards.
	local before = A.Print
	pcall(function() Errors:Capture(function() error("deliberate") end) end)
	check(A.Print == before,
		"and a capture that blows up still puts Print back - losing it would"
		.. " silence every message the addon makes for the rest of the session")

	Errors:ShowText("copy me")
	check(Errors.frame:IsShown() and Errors.frame.box:GetText() == "copy me",
		"and any text at all can be put in it")

	-- IT SCROLLS, and it says so.
	--
	-- The box was anchored straight to the dialog, so a diag of eighty lines
	-- drew forty of them and the rest went outside it - selected by Ctrl+A and
	-- copied correctly, and invisible. Which is the worst way for this to fail:
	-- the report you paste is complete and the one you can read is not.
	do
		local f = Errors.frame
		check(f.box:GetParent() == f.scroll and f.scroll:GetScrollChild() == f.box,
			"the box is the scroll frame's child rather than anchored to the"
			.. " dialog, which is what puts the overflow inside something")
		check((f.box:GetWidth() or 0) > 0,
			"and has a width of its own - a scroll child is anchored to nothing,"
			.. " so a multiline box without one puts the report on a single line")

		check(not f.thumb:IsShown(),
			"a report that fits draws no rail - a control that cannot do"
			.. " anything is worse than no control")

		local long = {}
		for i = 1, 80 do long[i] = "line " .. i end
		Errors:ShowText(table.concat(long, "\n"))

		check(f.thumb:IsShown() and f.track:IsShown(),
			"one that does not gets one (" .. tostring(f.box:GetHeight())
			.. " of text in " .. tostring(f.scroll:GetHeight()) .. ")")
		check((f.thumb:GetHeight() or 0) < (f.scroll:GetHeight() or 0),
			"with a thumb shorter than the rail, which is what says how much"
			.. " more there is")
		check(f.scroll:GetVerticalScroll() == 0,
			"and it opens at the top rather than where the last report was left"
			.. " scrolled to")

		local topY = select(5, f.thumb:GetPoint(1))
		f.scroll:GetScript("OnMouseWheel")(f.scroll, -1)
		check((f.scroll:GetVerticalScroll() or 0) > 0, "the wheel moves it")
		check(select(5, f.thumb:GetPoint(1)) < topY,
			"and the thumb follows (" .. string.format("%.1f", topY) .. " -> "
			.. string.format("%.1f", select(5, f.thumb:GetPoint(1))) .. ")")
	end

	Errors.frame:Hide()

	-- Put the strict one back for whatever runs after this.
	seterrorhandler(function(e) fail("errorhandler: " .. tostring(e)) end)
	Errors.installed = false
end

section("ifec: the route table, against flights that were actually flown", function()
	local Route = A.IFEC and A.IFEC.Route
	check(Route ~= nil, "the route lookup loaded")
	check(A.IFEC_ROUTE_BUILD == "1.15.9.69109",
		"the table was generated from the client's own build (" ..
		tostring(A.IFEC_ROUTE_BUILD) .. ")")

	local legs = 0
	for _, row in pairs(A.IFEC_LEGS or {}) do
		for _ in pairs(row) do legs = legs + 1 end
	end
	check(legs > 250, "and carries the game's legs (" .. legs .. ")")

	-- NINE REAL FLIGHTS. Measured on this account and recorded to the second.
	-- These are the whole justification for the generated table: they are what
	-- the taxi speed was fitted against, and a change to the generator that
	-- moves any of them is a change that needs looking at.
	local FLOWN = {
		{ "Camp Taurajo, The Barrens",    "Crossroads, The Barrens",           79 },
		{ "Crossroads, The Barrens",      "Orgrimmar, Durotar",               141 },
		{ "Crossroads, The Barrens",      "Ratchet, The Barrens",              51 },
		{ "Crossroads, The Barrens",      "Splintertree Post, Ashenvale",     162 },
		{ "Orgrimmar, Durotar",           "Crossroads, The Barrens",          109 },
		{ "Ratchet, The Barrens",         "Crossroads, The Barrens",           68 },
		{ "Splintertree Post, Ashenvale", "Orgrimmar, Durotar",                95 },
		{ "Thunder Bluff, Mulgore",       "Crossroads, The Barrens",          158 },
		{ "Undercity, Tirisfal",          "The Sepulcher, Silverpine Forest", 106 },
	}

	local worst, worstLeg = 0, nil
	for _, f in ipairs(FLOWN) do
		local secs = Route:Leg(f[1], f[2])
		if not secs then
			fail("no leg for " .. f[1] .. " -> " .. f[2])
		else
			local err = math.abs(secs - f[3])
			if err > worst then worst, worstLeg = err, f[1] .. " -> " .. f[2] end
		end
	end
	check(worst < 1.5, "every flown leg is within a second and a half of what it took"
		.. " (worst " .. string.format("%.1f", worst) .. "s on " .. tostring(worstLeg) .. ")")

	-- DIRECTIONAL. The same two nodes take different times each way, so a table
	-- that stored one figure per pair would be half a minute out on one of them.
	local there = Route:Leg("Orgrimmar, Durotar", "Crossroads, The Barrens")
	local back  = Route:Leg("Crossroads, The Barrens", "Orgrimmar, Durotar")
	check(there and back and math.abs(there - back) > 25,
		"a leg is not the same in both directions (" .. string.format("%.0f", there)
		.. "s out, " .. string.format("%.0f", back) .. "s back)")

	-- A JOURNEY IS THE SUM OF ITS LEGS. The client loses and regains control
	-- once for a whole multi-hop trip, so this is the only way to know a
	-- two-legged flight - and the measured 209s says it is the right way.
	local total, breakdown, complete = Route:Journey({
		"Ratchet, The Barrens", "Crossroads, The Barrens", "Orgrimmar, Durotar" })
	check(complete and total and math.abs(total - 209) < 2,
		"Ratchet to Orgrimmar via Crossroads comes to what it took ("
		.. string.format("%.0f", total or 0) .. "s vs 209s measured)")
	check(#breakdown == 2, "reported as two legs")
	check(breakdown[1].at and math.abs(breakdown[1].at - 68) < 2,
		"with the boundary tick where the first leg ends ("
		.. string.format("%.0f", breakdown[1].at or 0) .. "s vs 68s measured)")

	-- An unknown leg does not sink the journey: the console still opens and
	-- still counts, it just cannot say when you land.
	local t2, b2, ok2 = Route:Journey({ "Orgrimmar, Durotar", "Nowhere At All" })
	check(t2 == nil and ok2 == false, "an unknown leg leaves the total unknown")
	check(b2 and #b2 == 1 and b2[1].seconds == nil, "and is reported rather than dropped")

	-- THE EIGHT TWO-PATH LEGS. Both factions reach these hubs by different
	-- routes and nothing in the data says which is ours, so the shipped figure
	-- is a mean and is marked as one.
	check(Route:IsFuzzy("Gadgetzan, Tanaris", "Cenarion Hold, Silithus"),
		"a leg with one path per faction is flagged")
	check(not Route:IsFuzzy("Ratchet, The Barrens", "Crossroads, The Barrens"),
		"and an ordinary one is not")

	-- Learning beats the table, which is what makes a fuzzy leg fixable.
	local before = Route:Leg("Gadgetzan, Tanaris", "Cenarion Hold, Silithus")
	check(Route:Learn({ "Gadgetzan, Tanaris", "Cenarion Hold, Silithus" }, 196),
		"a flight we timed is recorded")
	local after, source = Route:Leg("Gadgetzan, Tanaris", "Cenarion Hold, Silithus")
	check(after == 196 and source == "learned", "and beats the shipped figure ("
		.. string.format("%.0f", before) .. "s -> 196s)")

	-- A MULTI-HOP FLIGHT TEACHES NOTHING ABOUT ITS LEGS, because the boundaries
	-- are not observable - control is lost and regained once for the whole trip.
	check(not Route:Learn({ "A", "B", "C" }, 300),
		"a multi-hop flight is not learned from, having no visible boundaries")
	check(not Route:Learn({ "A", "B" }, 3),
		"and neither is a blip too short to have been a flight")

	local div = Route:Divergence()
	check(#div >= 1 and div[1].from == "Gadgetzan, Tanaris",
		"divergence reports what we measured against what shipped")
end)

section("ifec: boarding, flying and landing", function()
	local Taxi  = A.IFEC and A.IFEC.Taxi
	local Route = A.IFEC and A.IFEC.Route
	check(Taxi ~= nil, "flight detection loaded")

	local seen = {}
	Taxi:AddListener(function(event, flight) seen[#seen + 1] = { event, flight } end)
	Taxi:Start()

	local function flightMap(nodes, routes)
		_G.__taxi.nodes, _G.__taxi.routes = nodes, routes or {}
	end
	local function board(index)
		TakeTaxiNode(index)
		_G.__onTaxi = true
		fire("PLAYER_CONTROL_LOST")
		tick(0.4)                      -- the settle delay before UnitOnTaxi is trusted
	end
	local function land(after)
		tick(after or 1)               -- time in the air, so there is a duration to learn
		_G.__onTaxi = false
		fire("PLAYER_CONTROL_GAINED")
	end

	-- Ratchet to Crossroads: a real single-hop leg, 68s in the table and 68s on
	-- the stopwatch when it was flown.
	flightMap({
		{ name = "Ratchet, The Barrens",    kind = "CURRENT" },
		{ name = "Crossroads, The Barrens", kind = "REACHABLE" },
	})

	-- A STUN IS NOT A FLIGHT. PLAYER_CONTROL_LOST fires for stuns, fear and
	-- mind control too, which is why Blizzard's own UIParent.lua asks
	-- UnitOnTaxi before believing it.
	fire("PLAYER_CONTROL_LOST")
	tick(0.4)
	check(not Taxi:IsFlying(), "being stunned does not open the console")
	check(#seen == 0, "and nobody is told a flight began")

	-- THE JOURNEY IS READ AT BOOKING. GetNumRoutes and TaxiGetNodeSlot only
	-- answer while the flight map is open, and it is shut by takeoff.
	board(2)
	check(Taxi:IsFlying(), "boarding opens it")
	check(seen[1] and seen[1][1] == "board", "and the console is told")
	local f = seen[1][2]
	check(f.from == "Ratchet, The Barrens" and f.to == "Crossroads, The Barrens",
		"with the route read off the map before it closed")
	check(f.expected and math.abs(f.expected - 68) < 2,
		"and the duration from the table (" .. string.format("%.0f", f.expected or 0) .. "s)")

	-- UnitOnTaxi is not settled in the frame the event fires, so the check is
	-- retried. A mock that flipped the flag instantly would never show this.
	local elapsed, remaining, fraction = Taxi:Progress()
	check(elapsed and elapsed >= 0 and fraction and fraction >= 0,
		"progress is readable in the air")

	land(67)
	check(not Taxi:IsFlying(), "landing closes it")
	check(seen[2] and seen[2][1] == "land", "and the console is told that too")
	check(seen[2][2].learned == true, "a clean single-hop flight is learned from")
	check(math.abs(Route:Leg("Ratchet, The Barrens", "Crossroads, The Barrens") - 67.4) < 1,
		"and the measured time replaces the table's")

	-- AN EARLY LANDING DID NOT GO WHERE IT WAS BOOKED. Recording it against the
	-- booked destination would teach the table a duration for a trip nobody
	-- took. Prior art misses this.
	local before = Route:Leg("Ratchet, The Barrens", "Crossroads, The Barrens")
	board(2)
	TaxiRequestEarlyLanding()
	land(40)
	check(Route:Leg("Ratchet, The Barrens", "Crossroads, The Barrens") == before,
		"a flight cut short teaches the table nothing")

	-- A MULTI-HOP JOURNEY reads every node off the map, and is not learned from
	-- because control is lost and regained once for the whole trip.
	flightMap({
		{ name = "Ratchet, The Barrens",   kind = "CURRENT" },
		{ name = "Crossroads, The Barrens", kind = "REACHABLE" },
		{ name = "Orgrimmar, Durotar",     kind = "REACHABLE" },
	}, { [3] = { 2, 3 } })

	board(3)
	local m = seen[#seen][2]
	check(m.nodes and #m.nodes == 3, "a two-leg journey names all three nodes")
	check(m.expected and math.abs(m.expected - 209) < 2,
		"and totals what the flight really takes ("
		.. string.format("%.0f", m.expected or 0) .. "s vs 209s measured)")
	check(m.legs and #m.legs == 2 and m.legs[1].at and math.abs(m.legs[1].at - 68) < 2,
		"with a boundary tick at the stopover")
	land()

	-- A FLIGHT NOBODY SAW BOOKED is still a flight - a disconnect mid-air puts
	-- you back on the griffin with no booking to recover.
	_G.__onTaxi = true
	fire("PLAYER_ENTERING_WORLD")
	check(Taxi:IsFlying(), "logging in airborne opens the console")
	local d = seen[#seen][2]
	check(d.expected == nil and d.from == nil,
		"with no route and no estimate, rather than a wrong one")
	local e2 = Taxi:Progress()
	check(e2 ~= nil, "and the elapsed time still counts")
	land()

	Taxi:Stop()
	_G.__onTaxi = false
end)

section("ifec: the console, which is a flight timer when it is nothing else", function()
	local IF   = A:GetModule("ifec")
	local Taxi = A.IFEC and A.IFEC.Taxi
	check(IF ~= nil and IF.enabled, "the console module is on")

	Taxi:Start()
	_G.__taxi.nodes = {
		{ name = "Ratchet, The Barrens",    kind = "CURRENT" },
		{ name = "Crossroads, The Barrens", kind = "REACHABLE" },
	}
	_G.__taxi.routes = {}

	-- The leg has been flown earlier in this file, so its duration is the
	-- learned one rather than the shipped one. Read it rather than assume.
	local LEG = A.IFEC.Route:Leg("Ratchet, The Barrens", "Crossroads, The Barrens")
	local function mmss(s)
		if s < 0 then s = 0 end
		return string.format("%d:%02d", math.floor(s / 60), math.floor(s % 60))
	end

	TakeTaxiNode(2)
	_G.__onTaxi = true
	fire("PLAYER_CONTROL_LOST")
	tick(0.4)

	local f = IF.frame
	check(f ~= nil and f:IsShown(), "boarding opens it")
	-- NOT AN ARROW. Outfit has no U+2192 and renders the missing-glyph box for
	-- it, which is what shipped and what it looked like on screen.
	check(f.route:GetText() == "Ratchet, The Barrens  \194\187  Crossroads, The Barrens",
		"showing where you are going")
	check(f.route:GetText():find("\226\134\146", 1, true) == nil,
		"with a separator the font actually has")

	-- THE NUMERAL IS TIME REMAINING, not elapsed - it is what the design puts
	-- inside the ring, and it is the number a passenger actually wants.
	check(f.dial.value:GetText() == mmss(LEG),
		"with the time left in the dial (" .. tostring(f.dial.value:GetText()) .. ")")
	check(f.sub:GetText():find("elapsed 0:00", 1, true) ~= nil
		and f.sub:GetText():find("lands " .. mmss(LEG), 1, true) ~= nil,
		"and the line under it reading " .. tostring(f.sub:GetText()))

	-- The arc is a sheet of baked steps, so "how full is the ring" is which
	-- cell is showing. There is no empty frame - a flight that has not started
	-- hides the texture instead, and any progress at all shows the first step
	-- rather than leaving the ring dead for the first second.
	check(A.Media:DialArc(0) == nil and A.Media:DialArc(nil) == nil,
		"nothing at all before the flight starts")
	check(select(2, A.Media:DialArc(0.0001)) == 0,
		"and the first step the moment it does")

	tick(LEG / 2)
	IF:Refresh()
	check(f.dial.arc:IsShown(), "the ring fills as the flight goes on")
	local half = table.concat({ f.dial.arc:GetTexCoord() }, ",")
	check(f.dial.value:GetText() == mmss(LEG / 2),
		"and the numeral counts down (" .. tostring(f.dial.value:GetText()) .. ")")

	tick(LEG / 4)
	IF:Refresh()
	check(table.concat({ f.dial.arc:GetTexCoord() }, ",") ~= half,
		"moving to a later frame of the sheet as it goes")

	-- A FLIGHT THAT RUNS LONG counts to zero and stays there. Minus figures in
	-- the dial would read as a fault rather than as an estimate being out.
	tick(60)
	IF:Refresh()
	check(f.dial.value:GetText() == "0:00", "an overrunning flight sits at zero")

	_G.__onTaxi = false
	fire("PLAYER_CONTROL_GAINED")
	check(not f:IsShown(), "landing closes it")

	-- WITH NO ROUTE THERE IS STILL A CONSOLE. The timer half must work with
	-- everything else absent, which includes not knowing where you are going.
	_G.__onTaxi = true
	fire("PLAYER_ENTERING_WORLD")
	IF:Refresh()
	check(f:IsShown(), "a flight nobody saw booked still opens it")
	check(f.sub:GetText():find("lands", 1, true) == nil,
		"with the landing clause dropped rather than shown as unknown")
	check(f.sub:GetText():find("elapsed", 1, true) ~= nil, "and the elapsed time still counting")
	check(not f.dial.arc:IsShown(), "and no ring, there being nothing to be a fraction of")

	_G.__onTaxi = false
	fire("PLAYER_CONTROL_GAINED")
	Taxi:Stop()
end)

section("ifec: landing, at the scale of everything else, out of the way", function()
	local IF   = A:GetModule("ifec")
	local Taxi = A.IFEC.Taxi

	-- ZEN DRIVES THE SAME UIParent ALPHA and re-asserts it on its own ticker, so
	-- it is stood down for this block. Two writers is a real interaction - the
	-- console re-asserts in flight so it wins - but a test that raced it would
	-- be measuring which ticker ran last.
	local zenWas = A:GetModule("zen").enabled
	A:SetModuleEnabled("zen", false)
	UIParent:SetAlpha(1)

	Taxi:Start()
	_G.__taxi.nodes = {
		{ name = "Ratchet, The Barrens",    kind = "CURRENT" },
		{ name = "Crossroads, The Barrens", kind = "REACHABLE" },
	}
	local function board()
		TakeTaxiNode(2)
		_G.__onTaxi = true
		fire("PLAYER_CONTROL_LOST")
		tick(0.4)
	end

	board()
	local f = IF.frame

	-- IT IS DRAWN AT THE PROFILE'S SCALE. Without this the console is the one
	-- thing on screen at 1.0 and reads enormous beside a HUD at 0.71.
	-- The profile's scale TIMES its own, the way the dock and the nameplates
	-- have theirs. The console is read once a minute from across the screen
	-- rather than glanced at constantly, so it sits smaller than the HUD.
	local cfg = A.Config:Module("ifec")
	check(math.abs(f:GetScale() - A.db.profile.scale * cfg.scale) < 0.0001,
		"the console is at the profile's scale times its own ("
		.. tostring(f:GetScale()) .. ")")
	check(cfg.scale < 1, "which is smaller (" .. tostring(cfg.scale) .. ")")

	-- THE INTERFACE GOES AWAY. One UIParent alpha, which is how Zen does it and
	-- covers addons we have never heard of.
	check(UIParent:GetAlpha() == 0, "the interface is hidden in flight")
	check(f:GetParent() == IF:Top() and IF:Top():GetParent() == nil,
		"and the console survives it, living under a holder outside UIParent")

	-- AND NOTHING UNDER IT MAY SPEAK. Alpha does not stop a frame taking the
	-- mouse: every buff, bag and action button is still sitting there at zero
	-- catching hovers, and the tooltip is deliberately moved OUT of UIParent so
	-- the console can be read - so the two together drew "Arcane Intellect, 24
	-- minutes remaining" over an empty sky, from a frame that was not on screen.
	local stranger = CreateFrame("Frame", nil, UIParent)
	-- From hidden, because a tooltip APPEARING is the event: Show() on one that
	-- is already up is not a transition and dispatches nothing, on the client or
	-- here. A check that skipped this would pass without the guard existing.
	GameTooltip:Hide()
	GameTooltip:SetOwner(stranger, "ANCHOR_RIGHT")
	GameTooltip:SetText("Arcane Intellect")
	GameTooltip:Show()
	check(not GameTooltip:IsShown(),
		"a frame hidden with the interface cannot raise a tooltip over it")

	-- OURS STILL CAN, which is the whole reason the tooltip was moved.
	GameTooltip:SetOwner(f, "ANCHOR_RIGHT")
	GameTooltip:SetText("Jump Off")
	GameTooltip:Show()
	check(GameTooltip:IsShown(),
		"while the console's own frames are still read normally")
	GameTooltip:Hide()

	-- LANDING. UnitOnTaxi is still true in the frame control comes back - the
	-- same lag as on the way out - so requiring it false and giving up left the
	-- console up for the rest of the session. This is that bug.
	fire("PLAYER_CONTROL_GAINED")
	check(Taxi:IsFlying(), "control returning while still aboard is not a landing yet")
	_G.__onTaxi = false
	tick(0.4)
	check(not Taxi:IsFlying(), "but it lands the moment the client agrees")
	check(not f:IsShown(), "and the console closes")
	check(UIParent:GetAlpha() == 1, "and the interface comes back")

	-- IF THE FLAG NEVER CLEARS, land anyway. Control coming back is the
	-- authority; UnitOnTaxi only says how soon to believe it. A console that
	-- waits forever for a flag is worse than one that closes a moment early.
	board()
	fire("PLAYER_CONTROL_GAINED")
	tick(0.4) tick(0.4) tick(0.4) tick(0.4) tick(0.4)
	check(not Taxi:IsFlying(), "a flag that never clears still lands")
	check(UIParent:GetAlpha() == 1, "with the interface restored")
	_G.__onTaxi = false

	-- THE BACKSTOP. If control coming back is missed altogether - a disconnect,
	-- a loading screen eating the event - anything saying we are off the taxi
	-- ends the flight rather than stranding the console for the session.
	board()
	check(Taxi:IsFlying(), "boarding again")
	_G.__onTaxi = false
	tick(0.2)
	check(not Taxi:IsFlying(), "losing the landing event entirely still lands")
	check(UIParent:GetAlpha() == 1, "and still gives the interface back")

	-- A HIDDEN INTERFACE THAT STAYS HIDDEN is the worst thing this could do, so
	-- the recovery is driven directly rather than through the event: what
	-- matters is that holding the interface down while not flying is always
	-- recoverable. It is wired to PLAYER_ENTERING_WORLD as well as to landing.
	IF._hidUI = true
	IF._uiAlpha = 1
	UIParent:SetAlpha(0)
	check(IF:Recover(), "a restore that never happened is recoverable")
	check(UIParent:GetAlpha() == 1, "and the interface comes back")

	-- But not mid-flight: that would undo the hiding on every loading screen.
	board()
	check(not IF:Recover(), "while actually flying it leaves the interface alone")
	check(UIParent:GetAlpha() == 0, "which stays hidden")
	_G.__onTaxi = false
	tick(0.4)

	Taxi:Stop()
	IF:HideInterface(false)
	A:SetModuleEnabled("zen", zenWas)
end)

section("ifec: cut to its contents, and the map you still want", function()
	local IF   = A:GetModule("ifec")
	local Taxi = A.IFEC.Taxi
	local MM   = A:GetModule("minimap")

	local zenWas = A:GetModule("zen").enabled
	A:SetModuleEnabled("zen", false)
	UIParent:SetAlpha(1)
	Taxi:Start()

	local function fly(nodes, routes)
		_G.__taxi.nodes, _G.__taxi.routes = nodes, routes or {}
		TakeTaxiNode(#nodes)
		_G.__onTaxi = true
		fire("PLAYER_CONTROL_LOST")
		tick(0.4)
	end
	local function land()
		_G.__onTaxi = false
		fire("PLAYER_CONTROL_GAINED")
		tick(0.4)
	end

	-- THE DESIGN'S 560 IS A CEILING, not a width. It is a 1920-wide screen's
	-- 560, and on a smaller one at minimum scale it is most of a third of the
	-- screen - for a route whose names are short and mostly empty capsule.
	fly({
		{ name = "Ratchet, The Barrens",    kind = "CURRENT" },
		{ name = "Crossroads, The Barrens", kind = "REACHABLE" },
	})
	local f = IF.frame
	local short = f:GetWidth()
	check(short <= 560, "the capsule never exceeds the design's width (" .. short .. ")")
	check(short >= 240, "nor shrinks below something readable")
	land()

	fly({
		{ name = "Marshal's Refuge, Un'Goro Crater", kind = "CURRENT" },
		{ name = "Thunder Bluff, Mulgore",           kind = "REACHABLE" },
	})
	check(f:GetWidth() > short,
		"a longer route gets a longer capsule (" .. f:GetWidth() .. " vs " .. short .. ")")
	land()

	-- JUMP OFF IS FOR MULTI-LEG JOURNEYS ONLY. Early landing puts you down at
	-- the NEXT flight master, which on a single-hop flight is where you were
	-- going anyway.
	fly({
		{ name = "Ratchet, The Barrens",    kind = "CURRENT" },
		{ name = "Crossroads, The Barrens", kind = "REACHABLE" },
	})
	check(IF.jump == nil or not IF.jump:IsShown(),
		"a single-hop flight offers no way to jump off")
	land()

	fly({
		{ name = "Ratchet, The Barrens",    kind = "CURRENT" },
		{ name = "Crossroads, The Barrens", kind = "REACHABLE" },
		{ name = "Orgrimmar, Durotar",      kind = "REACHABLE" },
	}, { [3] = { 2, 3 } })
	check(IF.jump ~= nil and IF.jump:IsShown(), "a two-leg journey offers one")
	check(IF.jump:GetParent() == MM.frame, "hung off the minimap, where the concept puts it")

	-- UNDER THE ZONE PILL, NOT ON IT. The pill is already anchored to the map's
	-- bottom edge, so anchoring to the map put the two in the same place and
	-- the button landed on top of "In flight".
	local point, rel = IF.jump:GetPoint()
	check(point == "TOP" and rel == MM.pill,
		"below the zone pill rather than on top of it")

	-- ALPHA DOES NOT STOP A FRAME TAKING THE MOUSE. The whole interface is
	-- sitting there at zero alpha still catching clicks, and this button was
	-- underneath it - clicking it did nothing at all in game.
	check(IF.jump:GetFrameStrata() == "FULLSCREEN_DIALOG",
		"and above the interface we just hid, or the click never reaches it")
	check(IF.frame:GetParent() == IF:Top(), "as is the console, for the same reason")

	check(IF.jump.label:GetText() == "Jump Off", "reading Jump Off")

	-- NOT WHITE. It sits just under the pill's clock, and two white readouts
	-- stacked read as one block of text - the colour is what says they are
	-- different things.
	check(IF.jump.label:GetTextColor() == A.Palette.c.accent[1],
		"in accent rather than white, so it does not compete with the clock")

	-- ITS OWN GLYPH. The chevron means "this opens" everywhere else in the
	-- interface, so borrowing it here would promise a window.
	check(IF.jump.glyph:GetTexture() == A.Media.icons.file,
		"with a mark of its own rather than the chevron")

	-- The tooltip says what the thing DOES, not what it is called again.
	IF.jump:GetScript("OnEnter")(IF.jump)
	check(GameTooltip:GetText() == "Jump Off", "with a tooltip before it is used")
	IF.jump:GetScript("OnLeave")(IF.jump)

	local before = _G.__taxi.earlyLandings
	IF.jump:GetScript("OnClick")(IF.jump)
	check(_G.__taxi.earlyLandings == before + 1, "and clicking it asks to land early")

	-- ASKING CANNOT BE TAKEN BACK - the client has no "actually, carry on" - so
	-- the control becomes a readout rather than staying a button that lies.
	check(IF.jump.label:GetText() == "Exit requested", "after which it says so")
	check(IF.jump.label:GetTextColor() == A.Palette.c.textDim[1],
		"and dims, being a readout rather than a control")
	IF.jump:GetScript("OnClick")(IF.jump)
	check(_G.__taxi.earlyLandings == before + 1, "and asking twice asks once")

	-- THE MAP STAYS. Alpha multiplies down the parent chain, so a child of a
	-- frame at zero cannot be given an alpha - it has to leave the chain.
	check(UIParent:GetAlpha() == 0, "the interface is hidden")
	-- INTO A HOLDER, NOT INTO NIL. SetParent(nil) on a live frame left the
	-- subtree half-alive: the map drew, its clock stopped, and nothing under it
	-- took the mouse - no clicks and no tooltips on the button below it.
	check(MM.frame:GetParent() == IF:Top(),
		"but the map has moved into our own holder, out of UIParent's alpha")

	-- AND THE PILL WITH IT. The pill is the map's sibling, not its child - both
	-- set profile.scale themselves, so a child would take it twice - so moving
	-- the map left the pill behind in UIParent, where it faded to nothing a
	-- moment after appearing.
	check(MM.pill:GetParent() == IF:Top(),
		"and the pill with it, being its sibling rather than its child")

	-- AND THE TOOLTIP. It is a child of UIParent like everything else, so with
	-- the interface at zero it was being shown perfectly and drawn at nothing:
	-- the button took the hover and produced no tooltip at all.
	check(GameTooltip:GetParent() == IF:Top(),
		"and the tooltip, or hovering anything of ours produces nothing visible")

	-- The button has already been clicked by this point in the block, so the
	-- tooltip should be saying what it says AFTER asking.
	IF.jump:GetScript("OnEnter")(IF.jump)
	check(GameTooltip:IsShown(), "so the jump-off button raises one")
	check((GameTooltip:GetText() or "") == "Exit requested",
		"which follows the button's state rather than naming it once ("
		.. tostring(GameTooltip:GetText()) .. ")")
	IF.jump:GetScript("OnLeave")(IF.jump)
	check(IF:Top():GetParent() == nil, "which is itself parentless, being created that way")

	-- And the pill says so, the way it says "In combat".
	MM:UpdateZone()
	check(MM.pill.zone:GetText() == "In flight", "with the pill reading In flight")

	-- THE CLOCK STAYS, exactly as it does in combat. It is set outside the
	-- branches for that reason, and a state that cleared it would be the odd
	-- one out.
	check(MM.pill.clock:GetText() ~= nil and MM.pill.clock:GetText() ~= "",
		"and the clock still in it (" .. tostring(MM.pill.clock:GetText()) .. ")")

	-- The dot is a state light, not a fixed red one: red says you are being
	-- attacked, which a griffin is not.
	local dr = MM.pill.dot:GetVertexColor()
	check(dr == A.Palette.c.accent[1], "its light in accent rather than combat red")

	-- THE FADER MUST NOT TAKE IT AWAY. A flight is the most idle you ever are -
	-- no combat, no target, no cursor, nothing to cast - so every test the
	-- fader makes said "gone" and it faded the map out from under the one thing
	-- worth watching. The pill showed for a second and vanished.
	local hadDelay = A.db.profile.fader.delay
	A.db.profile.fader.delay = 1
	for i = 1, 40 do tick(0.1) end
	check(A.Fader.state == "awake",
		"a flight keeps the HUD awake, being idle by every other measure ("
		.. tostring(A.Fader.state) .. ")")
	A.db.profile.fader.delay = hadDelay


	land()
	check(MM.frame:GetParent() == UIParent, "and the map goes back afterwards")
	check(MM.pill:GetParent() == UIParent, "and so does the pill")
	check(IF.jump == nil or not IF.jump:IsShown(), "with the jump-off control put away")
	MM:UpdateZone()
	check(MM.pill.zone:GetText() ~= "In flight", "and the pill back to the zone")

	Taxi:Stop()
	IF:HideInterface(false)
	A:SetModuleEnabled("zen", zenWas)
end)

section("ifec: registering content packs, several at once", function()
	local R = A.IFEC and A.IFEC.Registry
	check(R ~= nil, "the registry loaded")

	local function pack(id, season, api, items)
		return { packId = id, seasonIndex = season, apiVersion = api or 1,
		         displayName = id, items = items }
	end
	local function ep(id, title, file)
		return { id = id, type = "podcast", title = title, totalDuration = 60,
		         segments = { { file = file or ("audio\\" .. id .. ".ogg"), duration = 60 } } }
	end

	R:Reset()

	-- THE HANDSHAKE WORKS BOTH WAYS ROUND. Load order is not guaranteed, so a
	-- pack that loaded first leaves its manifest in a global for us to collect
	-- and one that loads later calls straight in. A pack that only worked one
	-- way round would vanish depending on how the client felt that session.
	check(type(_G.AetherUI_IFEC) == "table" and type(_G.AetherUI_IFEC.Register) == "function",
		"the register function is published for packs that load after us")

	_G.AetherUI_IFEC_Pending = { pack("EarlyBird", 1, 1, { ep("e1", "Early One") }) }
	check(R:Drain() == 1, "and a pack that loaded before us is collected from the pending table")
	check(_G.AetherUI_IFEC_Pending == nil, "which is cleared once drained")
	check(R:Drain() == 0, "so draining again finds nothing rather than doubling up")

	check(_G.AetherUI_IFEC.Register(pack("LateBird", 2, 1, { ep("l1", "Late One") })),
		"a pack registering through the published function is taken")

	-- A CLASH IS REPORTED, NEVER SILENTLY OVERWRITTEN. packId is the addon
	-- folder name, so two of them means two copies installed or somebody has
	-- borrowed a name; either way the player wants telling.
	local ok = R:Register(pack("EarlyBird", 9, 1, { ep("x", "Impostor") }))
	check(ok == false, "a second pack under a registered name is refused")
	check(R.packs["EarlyBird"].items[1].title == "Early One", "the first one is untouched")

	-- MIXED API VERSIONS ARE NORMAL and refusal is per-pack, never
	-- all-or-nothing: one season built against a version we cannot serve must
	-- not take the others down with it.
	check(R:Register(pack("FromTheFuture", 3, 99, { ep("f", "Too New") })) == false,
		"a pack built for a newer console is refused")
	check(R:Register(pack("Ancient", 4, 0, { ep("a", "Too Old") })) == false,
		"and one built for an older one")
	check(R:Register(pack("StillFine", 5, 1, { ep("s", "Fine") })), "while the rest still register")

	-- A BROKEN PACK IS SOMEBODY ELSE'S DATA. It must be refused rather than
	-- half-carried: a browse list with a nameless row in it reads as our bug.
	check(R:Register({ packId = "Malformed", apiVersion = 1, items = "not a table" }) == false,
		"a manifest whose items are not a list is refused")
	check(R:Register(pack("Empty", 6, 1, {})) == false, "and one with no items")
	check(R:Register(pack("Nameless", 7, 1, { { id = "x", type = "podcast" } })) == false,
		"and one whose only item has no title or segments")
	check(R:Register(nil) == false and R:Register("nonsense") == false,
		"and something that is not a manifest at all")

	-- A BULLETIN IS PAGES. It carries no audio and no segments, so the only
	-- thing that makes one openable is having something to open - and a row in
	-- the library that does nothing when clicked is our bug, not the pack's.
	check(R:Register(pack("Pageless", 8, 1, {
		{ id = "g", type = "gossip", masthead = "ogler", title = "Spotted" },
	})) == false, "a bulletin with no pages is refused")
	check(R:Register(pack("Numbered", 9, 1, {
		{ id = "g", type = "gossip", masthead = "ogler", title = "Spotted",
		  pages = { 3 } },
	})) == false, "and one whose pages are not paths")

	-- An overlap that is not a number is compared against zero on every boundary
	-- of every piece, which for three-second chunks is an error a second and a
	-- half for as long as the track runs.
	check(R:Register(pack("Overlapped", 10, 1, {
		{ id = "x", type = "music", title = "Wrong", totalDuration = 6,
		  overlap = "lots",
		  segments = { { file = "a.ogg", duration = 3 } } },
	})) == false, "and an item whose overlap is not a number")

	local failures = R:Failures()
	check(#failures == 11, "every refusal is recorded for the settings readout (" .. #failures .. ")")
	check(failures[1].packId == "EarlyBird"
		and failures[1].reason:find("already registered", 1, true) ~= nil,
		"in words a settings page can print: " .. failures[1].reason)

	-- ORDERING MUST NOT DEPEND ON REGISTRATION ORDER, or the browse list
	-- reshuffles between sessions for no visible reason. seasonIndex decides.
	local order = R:Sorted()
	check(table.concat(order, ",") == "EarlyBird,LateBird,StillFine",
		"packs sort by season, not by arrival (" .. table.concat(order, ",") .. ")")

	R:Reset()
	R:Register(pack("Zed", 2, 1, { ep("z", "Zed One") }))
	R:Register(pack("Alpha", 1, 1, { ep("a", "Alpha One") }))
	check(table.concat(R:Sorted(), ",") == "Alpha,Zed",
		"and registering them backwards gives the same order")

	-- COMPOSITE KEYS. Two packs built independently will eventually ship the
	-- same item id, and only packId:itemId is unique.
	R:Reset()
	R:Register(pack("S01", 1, 1, { ep("e01", "Season One, One", "s1e1.ogg") }))
	R:Register(pack("S02", 2, 1, { ep("e01", "Season Two, One", "s2e1.ogg") }))
	local cat = R:Catalogue()
	check(#cat == 2, "two packs using the same item id both survive")
	check(cat[1].key == "S01:e01" and cat[2].key == "S02:e01",
		"keyed by pack and item together")

	-- DEDUPLICATION on the resolved file: the same track legitimately appears
	-- in two packs, and showing it twice under two headings reads as a bug.
	R:Reset()
	R:Register(pack("Ambient", 1, 1, { ep("t1", "Rainfall", "shared\\rain.ogg") }))
	R:Register(pack("BestOf", 2, 1, {
		ep("t9", "Rainfall (again)", "shared\\rain.ogg"),
		ep("t8", "Something Else", "other.ogg"),
	}))
	cat = R:Catalogue()
	check(#cat == 2, "a track in two packs is carried once (" .. #cat .. " entries)")
	check(cat[1].title == "Rainfall", "and the earlier season keeps it")

	-- BUT NEVER WITHIN ONE PACK. An author who opens two of their own items on
	-- the same file has done so deliberately - an episode whose first chapter
	-- is the same ambient bed the pack also offers on its own is a real shape,
	-- and it is what the dev pack is. Dropping the second was a pack quietly
	-- serving fewer items than it declared, with nothing anywhere saying so.
	R:Reset()
	R:Register(pack("Own", 1, 1, {
		ep("show", "The Show", "bed.ogg"),
		ep("bed",  "The Bed",  "bed.ogg"),
	}))
	cat = R:Catalogue()
	check(#cat == 2, "a pack reusing its own audio keeps both items ("
		.. #cat .. " of 2)")

	-- AN ARTIST IS OPTIONAL BUT NOT UNTYPED. A song is named by two things and
	-- the title alone is half of it, so it is carried - but a number here would
	-- reach the console as "3" beside a song name and read as our bug rather
	-- than the pack's, so it is refused at the door with everything else.
	R:Reset()
	R:Register(pack("Tunes", 1, 1, {
		{ id = "t1", type = "music", title = "Big Drum Deep Water",
		  artist = "The Mudfoot Kings", totalDuration = 60,
		  segments = { { file = "big.ogg", duration = 60 } } },
		{ id = "t2", type = "music", title = "Untyped", artist = 3,
		  totalDuration = 60, segments = { { file = "num.ogg", duration = 60 } } },
	}))
	cat = R:Catalogue()
	check(#cat == 1, "an item whose artist is not a string is refused ("
		.. #cat .. " of 1 kept)")
	check(cat[1].artist == "The Mudfoot Kings",
		"and a real one is carried onto the item (" .. tostring(cat[1].artist) .. ")")

	R:Reset()
end)

section("ifec: what is in season, and what fills a flight", function()
	local R, C = A.IFEC.Registry, A.IFEC.Content
	check(C ~= nil, "content selection loaded")

	local function item(id, kind, mins, from, until_)
		return { id = id, type = kind, title = id, totalDuration = mins * 60,
		         activeFrom = from, activeUntil = until_,
		         segments = { { file = id .. ".ogg", duration = mins * 60 } } }
	end
	local function pack(id, season, items)
		return { packId = id, seasonIndex = season, apiVersion = 1, items = items }
	end

	local cfg = A.Config:Module("ifec")
	cfg.progress = {}
	R:Reset()

	-- NO PACKS IS DORMANT, and so is every other way of getting there. The
	-- console asks one question and gets one answer.
	check(C:IsDormant(), "with nothing installed the console is dormant")

	R:Register(pack("Expired", 1, { item("old", "podcast", 10, "2026-01-01", "2026-02-01") }))
	check(C:IsDormant(), "and with only an expired season, still dormant")
	check(#R:Failures() == 0, "though nothing failed to register - it is in date, not in error")

	-- THE WINDOW IS READ ON EVERY ASKING, never cached. A player logged in
	-- across a season boundary gets the new content on their next flight
	-- rather than having to relog for it.
	R:Register(pack("S02", 2, { item("e1", "podcast", 10, "2026-09-01", "2026-10-01") }))
	check(C:IsDormant(), "a season that has not opened yet is not in season")
	_G.__today = "20260915"
	check(not C:IsDormant(), "and the same question the next day says it is")
	check(#C:Available() == 1, "with exactly the item whose window is open")
	_G.__today = "20261015"
	check(C:IsDormant(), "and dormant again once it closes")

	-- No bounds at all is evergreen, which is a real state the settings page
	-- has a word for.
	R:Register(pack("Evergreen", 3, { item("amb", "music", 1) }))
	check(not C:IsDormant(), "an item with no dates is evergreen")

	-- THE PROGRAMME. Resume first, then unplayed newest-season-first, then
	-- music as filler - and it crosses packs, because music is a different
	-- pack from a podcast and a queue that could not cross would fall silent
	-- with flight remaining.
	_G.__today = "20260915"
	R:Reset()
	cfg.progress = {}
	R:Register(pack("Music", 1, { item("rain", "music", 1), item("wind", "music", 1) }))
	R:Register(pack("S01", 2, { item("old1", "podcast", 2) }))
	R:Register(pack("S03", 3, { item("new1", "podcast", 2), item("new2", "podcast", 2) }))

	local queue = C:Programme(600)
	check(#queue > 0, "a programme is built for a ten-minute flight")
	check(queue[1].packId == "S03", "the newest season goes first ("
		.. tostring(queue[1].packId) .. ":" .. tostring(queue[1].id) .. ")")

	local kinds = {}
	for _, q in ipairs(queue) do kinds[#kinds + 1] = q.type end
	check(kinds[#kinds] == "music", "and music fills the end of it ("
		.. table.concat(kinds, ",") .. ")")

	-- A PART-PLAYED EPISODE GREETS YOU. Half-finished beats brand new.
	C:Remember("S01:old1", 3, false)
	queue = C:Programme(600)
	check(queue[1].key == "S01:old1", "something part-played comes first next time ("
		.. tostring(queue[1].key) .. ")")

	-- A finished one is not offered again as though it were new.
	C:Remember("S03:new1", 9, true)
	queue = C:Programme(600)
	local sawFinished = false
	for _, q in ipairs(queue) do if q.key == "S03:new1" then sawFinished = true end end
	check(not sawFinished, "and a finished one is not queued as unplayed")

	-- THE PLAYER'S OWN PICKS ARE NEVER OVERRIDDEN and never dropped, even if
	-- they overrun - a queue that quietly removes what somebody asked for is
	-- worse than one that runs long.
	queue = C:Programme(60, { "S03:new2" })
	check(queue[1].key == "S03:new2", "a picked item leads the programme")
	local _, filled = C:Programme(30, { "S03:new2" })
	check(filled > 30, "and is kept even when it overruns the flight ("
		.. string.format("%.0f", filled) .. "s of 30s)")

	-- PROGRESS IS PACK-SCOPED, so uninstalling one season leaves another's
	-- alone, and state for a pack we no longer know is ignored rather than
	-- deleted - a season that expires and returns picks up where it was.
	C:Remember("Gone:whatever", 4, false)
	R:Reset()
	R:Register(pack("Music", 1, { item("rain", "music", 1) }))
	check(C:Programme(120) ~= nil, "a programme still builds with a stale id in the store")
	check(C:Progress("Gone:whatever") ~= nil, "and the stale progress is kept, not purged")
	check(C:Progress("S01:old1") ~= nil, "as is progress for a season not currently installed")

	-- MUSIC ROTATES, LONGEST AGO FIRST. Taken in catalogue order it was the same
	-- opening track on every single flight, which is a season of eleven
	-- behaving like a season of three.
	R:Reset()
	cfg.progress, cfg.playCount = {}, nil
	R:Register(pack("Tunes", 1, {
		item("one", "music", 3), item("two", "music", 3), item("three", "music", 3),
	}))

	queue = C:Programme(360)
	check(queue[1].id == "one" and queue[2].id == "two",
		"with nothing heard yet the pack's own order stands")

	C:Remember("Tunes:one", 1, true)
	C:Remember("Tunes:two", 1, true)
	queue = C:Programme(360)
	check(queue[1].id == "three", "the one never heard leads the next flight ("
		.. tostring(queue[1].id) .. ")")
	check(queue[2].id == "one", "then the one heard longest ago ("
		.. tostring(queue[2].id) .. ")")

	-- A COUNTER, NOT JUST A DATE. Everything heard on one afternoon carries the
	-- same date, and that is exactly the tie the rotation has to break.
	check((C:Progress("Tunes:two").seq or 0) > (C:Progress("Tunes:one").seq or 0),
		"and the order within a single day is still known")

	-- THE DEV PACK SITS AT SEASON ZERO, and between two never-heard tracks it is
	-- the newest season first - so once there is real content the filler is real
	-- content, and the test season is what you get after it has run out.
	R:Reset()
	cfg.progress, cfg.playCount = {}, nil
	R:Register(pack("Dev", 0, { item("test_bed", "music", 3) }))
	R:Register(pack("Season", 1, { item("real_song", "music", 3) }))
	queue = C:Programme(360)
	check(queue[1].id == "real_song", "a real season is reached for before the dev pack ("
		.. tostring(queue[1].id) .. ")")
	check(queue[2].id == "test_bed", "which still fills when the real one has run out")

	-- AMBIENT SHUFFLE IS MUSIC, not everything over again. It is the complete
	-- state's one-press default, and its job is to fill the rest of the flight
	-- rather than to start an episode nobody asked for.
	R:Reset()
	cfg.progress, cfg.playCount = {}, nil
	R:Register(pack("Mixed", 1, {
		item("talk", "podcast", 3), item("tune", "music", 3),
	}))
	local shuffle = C:MusicQueue()
	check(#shuffle == 1 and shuffle[1].id == "tune",
		"the ambient shuffle is music only (" .. #shuffle .. " item(s))")
	check(#C:Everything() == 2,
		"though the whole catalogue is still reachable (" .. #C:Everything() .. ")")

	-- ONE MORE, OR NOTHING. What the transport asks for when the queue runs out.
	check((C:NextAfter({}) or {}).id ~= nil, "with nothing queued there is a next thing")
	check(C:NextAfter(C:Everything()) == nil, "and with all of it queued there is not")

	R:Reset()
	cfg.progress, cfg.playCount = {}, nil
	_G.__today = "20260815"
end)

section("ifec: playing a programme across a flight", function()
	local R, C, P = A.IFEC.Registry, A.IFEC.Content, A.IFEC.Playback
	check(P ~= nil, "playback loaded")

	local cfg = A.Config:Module("ifec")
	cfg.progress = {}
	R:Reset()
	_G.__musicMuted = false

	-- Sixty-second segments, which is what makes the chaining testable: the
	-- boundaries are what drift, so an item has to have several.
	local function ep(id, title, n)
		local segs = {}
		for i = 1, n do
			segs[#segs + 1] = { file = id .. "_" .. i .. ".ogg", duration = 60 }
		end
		return { id = id, type = "podcast", title = title,
		         totalDuration = 60 * n, segments = segs }
	end
	R:Register({ packId = "S00", apiVersion = 1, seasonIndex = 0, items = {
		ep("e01", "Episode One", 3),
		ep("e02", "Episode Two", 2),
		{ id = "amb", type = "music", title = "Ambient", totalDuration = 60,
		  segments = { { file = "amb.ogg", duration = 60 } } },
	} })

	local cat = R:Catalogue()
	local queue = { cat[1], cat[2], cat[3] }

	local heard = {}
	P:AddListener(function(event, item) heard[#heard + 1] = event end)

	-- THE GAME'S OWN MUSIC IS SILENCED for the flight. Playing on the Music
	-- channel puts the programme OVER the zone music rather than in place of
	-- it, and switching that channel off would take our audio with it - so the
	-- game's music goes off and the programme plays somewhere else.
	_G.__cvars.Sound_EnableMusic = "1"
	check(P:Start(queue), "a programme starts")
	check(P.state == "playing", "and is playing")
	check(_G.__cvars.Sound_EnableMusic == "0",
		"with the game's own music switched off rather than played over")
	check(_G.__lastSound == "e01_1.ogg", "the first segment of the first item")
	check(_G.__soundsPlaying() == 1, "one thing at a time")

	-- CHAINED WITHOUT A CALLBACK. This client gives no playback-finished event
	-- for a file path, so the end of a segment is predicted from the duration
	-- the manifest baked in - which is why tooling probes them.
	tick(60)
	check(_G.__lastSound == "e01_2.ogg", "the next segment follows on its own ("
		.. tostring(_G.__lastSound) .. ")")
	check(_G.__soundsPlaying() == 1, "with the last one stopped, not left running")

	-- POSITION SAVED AT EVERY BOUNDARY, not at landing. A disconnect mid-flight
	-- is exactly when somebody wants their place kept and is the one moment no
	-- landing handler ever runs.
	local p = C:Progress("S00:e01")
	check(p and p.segment == 1, "the boundary is written down as it passes")
	check(not p.complete, "and not marked finished part way through")

	-- AUTOPLAY-NEXT. The brief calls this a functional requirement rather than
	-- polish: a flight outlasts an episode, and silence over the Barrens is the
	-- failure this exists to prevent.
	tick(60) tick(60)
	check(_G.__lastSound == "e02_1.ogg",
		"the programme moves to the next item by itself (" .. tostring(_G.__lastSound) .. ")")
	check(C:Progress("S00:e01").complete, "with the one it finished marked finished")

	-- RESUME WHERE IT WAS LEFT. The stored index is the last segment COMPLETED,
	-- so the next one is where to start.
	P:Stop()
	check(_G.__soundsPlaying() == 0, "stopping stops the sound")
	C:Remember("S00:e02", 1, false)
	P:Start({ cat[2] })
	check(_G.__lastSound == "e02_2.ogg",
		"a part-heard item resumes at the segment after the last one finished ("
		.. tostring(_G.__lastSound) .. ")")

	-- PAUSE keeps the place. There is no seek on this client, so resuming
	-- restarts the segment rather than dropping into the middle of it.
	check(P:Pause(), "it pauses")
	check(_G.__soundsPlaying() == 0, "with nothing left playing")
	check(P.state == "paused", "and says so")
	check(P:Resume() and P.state == "playing", "and picks up again")

	-- A TIMER THAT WAS CANCELLED MUST NOT FIRE. Skipping forward while a
	-- segment is playing leaves its "next one starts now" scheduled, and
	-- without cancelling it the skipped-to item is talked over a moment later.
	P:Stop()
	P:Start(queue)
	P:Next()
	local afterSkip = _G.__lastSound
	tick(60)
	check(_G.__soundsPlaying() == 1,
		"skipping does not leave the old segment's timer to start a second track")

	-- ONE TIMER IS THE WHOLE CHAIN, so there is a backstop behind it. Without a
	-- playback-finished event a lost timer means the programme stops dead and
	-- goes on saying "playing" - which is indistinguishable, from the outside,
	-- from a segment that simply did not start.
	P:Stop()
	P:Start(queue)
	check(_G.__lastSound == "e01_1.ogg", "a programme starts again")
	P.timer:Cancel()                           -- the timer, lost
	P.timer = nil
	tick(60)
	check(_G.__lastSound == "e01_1.ogg", "with its timer gone nothing follows on")
	tick(3)
	-- RECOVERED BY WHOEVER OWNS THE POLL, which is the fact worth checking now
	-- that there are two surfaces: on the ground it is the mini-player's own
	-- tick, in flight it is the console's region, and Poll refuses to fire twice
	-- for one segment precisely so the two cannot both take it. Asserting Poll
	-- answers true HERE meant asserting nobody else had already done the job.
	check(_G.__lastSound == "e01_2.ogg",
		"but the lost boundary is picked up anyway ("
		.. tostring(_G.__lastSound) .. ")")
	check(not P:Poll(), "and it does not fire twice for the same boundary")

	-- A CHUNKED TRACK, which is the only way to get a pause out of this client.
	-- A handle supports exactly one verb - stop - and stopping is destructive,
	-- so pause is synthesised from the chaining the console already does for
	-- chaptered episodes: cut the audio into three-second pieces and stop-and-
	-- remember costs at most one piece.
	R:Reset()
	cfg.progress = {}
	local chunks = {}
	for i = 1, 8 do
		chunks[i] = { file = "chunk_" .. i .. ".ogg", duration = 3 }
	end
	R:Register({ packId = "S02", apiVersion = 1, seasonIndex = 2, items = {
		{ id = "cut", type = "music", title = "Chunked", totalDuration = 24,
		  overlap = 0.25, segments = chunks },
	} })
	local cut = R:Catalogue()[1]

	P:Stop()
	P:Start({ cut })
	tick(3) tick(3)
	check(_G.__lastSound == "chunk_3.ogg",
		"the pieces chain like any other segments (" .. tostring(_G.__lastSound) .. ")")
	check(math.abs(P:Elapsed() - 6) < 0.2,
		"and the clock reads the whole track, not the piece ("
		.. string.format("%.1f", P:Elapsed()) .. ")")

	-- THE OUTGOING PIECE IS LEFT TO RUN OUT. Stopping it to start the next one
	-- is a hard cut mid-sample, which is the loudest kind of step there is and
	-- was half the click. Its tail carries a fade of its own and the incoming
	-- piece fades up through it, so for a quarter of a second there are two.
	check(_G.__soundsPlaying() == 2,
		"a crossfaded boundary leaves the outgoing piece playing under the"
		.. " incoming one (" .. _G.__soundsPlaying() .. ")")

	-- BOUNDED AT TWO. An hour of three-second pieces must not accumulate twelve
	-- hundred handles nobody ever silenced.
	tick(3) tick(3) tick(3)
	check(_G.__soundsPlaying() == 2,
		"and never more than two, however many boundaries go by ("
		.. _G.__soundsPlaying() .. ")")

	-- AND EVERYTHING THAT MEANS SILENCE REACHES BOTH. A single handle field
	-- would have leaked the one it had just overwritten.
	check(P:Pause(), "pausing")
	check(_G.__soundsPlaying() == 0,
		"silences both of them (" .. _G.__soundsPlaying() .. ")")
	check(P:Resume(), "and it resumes")
	check(_G.__soundsPlaying() == 1, "on one piece again")

	-- PAUSE COSTS AT MOST ONE PIECE. Resume restarts the piece it stopped in,
	-- because there is no seek - which is exactly why the pieces are short.
	local was = _G.__lastSound
	tick(1)
	check(P:Pause(), "it pauses")
	check(_G.__soundsPlaying() == 0, "with the channel silent")
	check(P:Resume(), "and resumes")
	check(_G.__lastSound == was,
		"from the piece it stopped in, losing a second of it at worst ("
		.. tostring(_G.__lastSound) .. ")")

	-- AND A SONG STILL STARTS FROM THE TOP. Sixty pieces instead of one means a
	-- stop halfway writes a real position, and without this a track would pick
	-- up two minutes in because that is where you landed last week - and would
	-- be dragged to the front of every programme until somebody finished it.
	P:Stop()
	check((C:Progress("S02:cut") or {}).segment > 0, "stopping writes where it got to")
	P:Start({ cut })
	check(_G.__lastSound == "chunk_1.ogg",
		"but a song starts again from the beginning ("
		.. tostring(_G.__lastSound) .. ")")

	-- AND IT IS NOT DRAGGED TO THE FRONT of the next programme either. The
	-- resume list exists so a half-finished EPISODE greets you; a song stopped
	-- at the two-minute mark qualifying for it means that song leads every
	-- flight until somebody sits through the end of it.
	R:Register({ packId = "S03", apiVersion = 1, seasonIndex = 3, items = {
		ep("fresh", "Something Unplayed", 2),
	} })
	-- Stopped part way IN, so there is a real position written down. Stopping on
	-- the first piece records nothing to be dragged forward by.
	tick(3) tick(3)
	P:Stop()
	local queue2 = C:Programme(600)
	check(queue2[1] and queue2[1].key == "S03:fresh",
		"an unplayed episode still leads (" .. tostring(queue2[1] and queue2[1].key) .. ")")
	check(C:Progress("S02:cut") ~= nil and (C:Progress("S02:cut").segment or 0) > 0,
		"with the part-played song still recorded as part-played")
	for i, q in ipairs(queue2) do
		if q.key == "S02:cut" then
			check(i > 1, "and sitting where the filler goes, not at the front (" .. i .. ")")
		end
	end

	P:Stop()
	R:Reset()
	cfg.progress = {}
	R:Register({ packId = "S00", apiVersion = 1, seasonIndex = 0, items = {
		ep("e01", "Episode One", 3),
		ep("e02", "Episode Two", 2),
		{ id = "amb", type = "music", title = "Ambient", totalDuration = 60,
		  segments = { { file = "amb.ogg", duration = 60 } } },
	} })
	cat = R:Catalogue()
	queue = { cat[1], cat[2], cat[3] }

	-- MUTED IS NOT SILENCE. willPlay comes back nil when the channel is off,
	-- and the difference between saying so and playing nothing is the
	-- difference between a console that explains itself and one that looks
	-- broken.
	P:Stop()
	_G.__musicMuted = true
	check(not P:Start(queue), "with the music channel muted, nothing starts")
	check(P.state == "muted", "and the state says why rather than 'playing'")
	_G.__musicMuted = false

	-- GOSSIP IS READ, NOT PLAYED. It occupies no time on the channel, so the
	-- programme steps past it rather than sitting in silence for its duration.
	R:Reset()
	R:Register({ packId = "S01", apiVersion = 1, seasonIndex = 1, items = {
		{ id = "news", type = "gossip", masthead = "ogler", title = "Spotted",
		  pages = { "mag\\page-01", "mag\\page-02" } },
		ep("e09", "After The News", 1),
	} })
	local c2 = R:Catalogue()
	P:Stop()
	P:Start({ c2[1], c2[2] })
	check(_G.__lastSound == "e09_1.ogg",
		"a gossip item does not hold the channel (" .. tostring(_G.__lastSound) .. ")")

	-- THE END OF THE PROGRAMME with flight remaining is the state the whole of
	-- v2 is designed around, so it is announced rather than simply stopping.
	P:Stop()
	heard = {}
	P:Start({ c2[2] })
	tick(60)
	local sawExhausted = false
	for _, e in ipairs(heard) do if e == "exhausted" then sawExhausted = true end end
	check(sawExhausted, "running out of programme is announced, not just silence")

	-- AND THE CHANNEL GOES QUIET WITH IT. Running off the end left the last
	-- track sounding while the state said exhausted, the clock read zero and the
	-- button showed play - a console insisting nothing was playing over the
	-- sound of something playing. Skipping past the last item was the fast way
	-- to see it and is how it was found.
	P:Stop()
	P:Start({ c2[2] })
	check(_G.__soundsPlaying() == 1, "an item is playing")
	P:Next()
	check(P.state == "exhausted", "skipping past the last item ends the programme")
	check(_G.__soundsPlaying() == 0,
		"and silences the channel rather than leaving it running ("
		.. _G.__soundsPlaying() .. " still going)")
	check(P.item == nil, "with nothing left to call the current item")

	-- A PROGRAMME COVERS THE FLIGHT, it is not everything there is: a short hop
	-- is filled by ONE track, so "next" had nowhere to go on most flights and
	-- ended the programme instead. Whoever built the queue is asked for more.
	P:Stop()
	local asked = 0
	P.refill = function()
		asked = asked + 1
		return asked == 1 and c2[2] or nil
	end
	P:Start({ c2[2] })
	P:Next()
	check(asked == 1, "the end of the queue asks for one more")
	check(P.state == "playing", "and plays it rather than ending (" .. P.state .. ")")
	P:Next()
	check(P.state == "exhausted", "and ends once there is genuinely nothing left")
	P.refill = nil

	-- EVERY OTHER STATE STILL HAS A PLAY BUTTON. Toggle handled two of the five
	-- and did nothing at all in the rest, so the transport went dead the moment
	-- anything went wrong - a file that would not play, a skip off the end, the
	-- client killing the sound while the window was in the background.
	check(P:Toggle(), "play restarts a programme that has run out")
	check(P.state == "playing", "which is playing again (" .. P.state .. ")")
	check(P:Toggle() and P.state == "paused", "and pauses from there as usual")
	check(P:Toggle() and P.state == "playing", "and back")

	-- AND THE GAME GETS ITS SOUND SETTINGS BACK. A silenced game is the worst
	-- thing this could leave behind: nothing on screen would say why. Put back
	-- on landing, and again on any world load that finds us holding them.
	P:Stop()
	check(_G.__cvars.Sound_EnableMusic == "1", "and the game's music comes back")

	-- THE BACKGROUND SETTING IS HELD TOO. Without it the client kills every
	-- sounding handle when the window loses focus and starts none of them again,
	-- and there is no focus event to recover from - so an alt-tab mid-flight
	-- came back to a programme that was silent with the clock still counting.
	_G.__cvars.Sound_EnableSoundWhenGameIsInBG = "0"
	P:Start({ c2[2] })
	check(_G.__cvars.Sound_EnableSoundWhenGameIsInBG == "1",
		"sound in the background is held on for the flight")
	P:Stop()
	check(_G.__cvars.Sound_EnableSoundWhenGameIsInBG == "0",
		"and handed back exactly as it was, not left on")
	check(_G.__badCVarWrites == 0,
		"and every name written is one the client has (" .. _G.__badCVarWrites .. " bad)")

	P:Start({ c2[2] })
	P.state = "stopped"                        -- a flight that ended unseen
	check(P:Recover(), "a setting still held with nothing playing is recoverable")
	check(_G.__cvars.Sound_EnableMusic == "1", "and recovering hands it back")

	-- A RELOAD IS NOT A STOP. Reloading throws away every Lua table in the addon
	-- - the sound handle with them - and does NOT touch the client's sound
	-- engine, so the track carried straight on with nothing left alive that knew
	-- how to stop it, and the next thing played played OVER it.
	P:Stop()
	_G.__cvars.Sound_EnableMusic = "1"
	P:Start({ c2[2] })
	check(_G.__soundsPlaying() == 1, "something is playing when the reload comes")
	fire("PLAYER_LOGOUT")
	check(_G.__soundsPlaying() == 0,
		"logging out or reloading silences it (" .. _G.__soundsPlaying() .. " left)")
	check(_G.__cvars.Sound_EnableMusic == "1",
		"and hands the sound settings back on the way past")
	check(cfg.held == nil or cfg.held.Sound_EnableMusic == nil,
		"with nothing left written down, so the next login has nothing to undo")

	-- A CLIENT THAT DIED ON THE GRIFFIN. What is held is written to the save
	-- file, so the next login can undo it - `_took` was a field on a live table,
	-- which made the one case this most needed to cover the one case it did
	-- nothing for: the game stayed silent, permanently, with nothing saying why.
	P:Stop()
	P:Start({ c2[2] })
	check(cfg.held and cfg.held.Sound_EnableMusic == "1",
		"what was taken is written down, not only remembered")
	P.state, P._took = "stopped", nil          -- the session that never came back
	_G.__cvars.Sound_EnableMusic = "0"
	check(_G.__soundsPlaying() == 1, "with its audio still going and nothing"
		.. " left alive that knows the handle")
	check(P:Recover(), "a fresh session still finds the settings it is holding")
	check(_G.__cvars.Sound_EnableMusic == "1", "and puts them back")

	-- AND CLEARS THE GHOST. The handle died with the session, so the channel
	-- enable is the only lever left: off stops what is on it, and it goes
	-- straight back on. Best effort, and only on the path that already knows
	-- something was left behind.
	check(_G.__soundsPlaying() == 0, "and silences what the last session left"
		.. " playing (" .. _G.__soundsPlaying() .. " left)")
	check(_G.__cvars.Sound_EnableAmbience == "1",
		"with the channel handed straight back on")

	P:Stop()
	cfg.progress = {}
	cfg.held = nil
	R:Reset()
end)

section("ifec: the player region, on the flight's own axis", function()
	local R, C, P = A.IFEC.Registry, A.IFEC.Content, A.IFEC.Playback
	local PL, Taxi, IF = A.IFEC.Player, A.IFEC.Taxi, A:GetModule("ifec")
	check(PL ~= nil, "the player region loaded")

	local zenWas = A:GetModule("zen").enabled
	A:SetModuleEnabled("zen", false)
	UIParent:SetAlpha(1)

	local cfg = A.Config:Module("ifec")
	cfg.progress = {}
	R:Reset()
	_G.__musicMuted = false
	Taxi:Start()

	local function fly()
		_G.__taxi.nodes = {
			{ name = "Ratchet, The Barrens",    kind = "CURRENT" },
			{ name = "Crossroads, The Barrens", kind = "REACHABLE" },
		}
		_G.__taxi.routes = {}
		TakeTaxiNode(2)
		_G.__onTaxi = true
		fire("PLAYER_CONTROL_LOST")
		tick(0.4)
	end
	local function land()
		_G.__onTaxi = false
		fire("PLAYER_CONTROL_GAINED")
		tick(0.4)
	end

	-- DORMANT IS ABSENT, not empty. With nothing installed the console lays out
	-- as though the player region had never existed.
	fly()
	check(not IF:HasRegion(), "with no content the console carries no player region")
	land()

	R:Register({ packId = "S00", apiVersion = 1, seasonIndex = 0, items = {
		{ id = "e1", type = "podcast", title = "Episode One", totalDuration = 30,
		  segments = { { file = "e1a.ogg", duration = 15 }, { file = "e1b.ogg", duration = 15 } } },
		{ id = "e2", type = "podcast", title = "Episode Two", totalDuration = 20,
		  segments = { { file = "e2.ogg", duration = 20 } } },
		-- LONGER THAN WHAT IS LEFT OF THE FLIGHT, deliberately. A programme is
		-- filled until it COVERS the flight, so the last item almost always
		-- overshoots - and that overshoot is what used to draw out of the side
		-- of the window. The ordinary case is the awkward one.
		{ id = "amb", type = "music", title = "Ambient", totalDuration = 120,
		  segments = { { file = "amb.ogg", duration = 120 } } },
	} })

	fly()
	check(IF:HasRegion(), "with content it appears, between flights and with no reload")
	local f = PL.frame
	check(f ~= nil and f:IsShown(), "and is shown")

	-- THE TWO BARS SHARE AN AXIS. That is the whole reason they are stacked: a
	-- landing line across both means the same instant on each.
	check(f.flight:GetWidth() == f.programme:GetWidth(),
		"the flight bar and the programme bar are the same width")
	check(math.abs(f.flight:XFor(34) - f.programme:XFor(34)) < 0.01,
		"so the same second is the same pixel on both")

	check(f.now.title:GetText() == "Episode One",
		"the now-playing row names what is playing (" .. tostring(f.now.title:GetText()) .. ")")
	-- AND NOT WHAT FOLLOWS IT. That is UP NEXT's job, four rows down, with a
	-- duration and a channel mark this line has no room for - and saying it here
	-- as well ran the row under the landing label on any real route.
	check(f.now.meta:GetText():find("then", 1, true) == nil,
		"and does not also name what follows (" .. tostring(f.now.meta:GetText()) .. ")")

	-- UP NEXT is what is COMING, so it starts after the thing playing rather
	-- than including it.
	check(f.rows[1]:IsShown() and f.rows[1].title:GetText() == "Episode Two",
		"up next starts after the current item (" .. tostring(f.rows[1].title:GetText()) .. ")")

	-- IT COUNTS DOWN ON ITS OWN. Everything painted here is a countdown, and
	-- the only thing repainting it was a playback event - which happens once a
	-- minute at best. So the region sat frozen on whatever the last boundary
	-- said, and a segment that had in fact moved on looked like one that had
	-- stopped.
	local wasLanding, wasLeft = f.landingLabel:GetText(), f.now.meta:GetText()
	tick(3)
	check(f.landingLabel:GetText() ~= wasLanding,
		"the landing countdown moves between playback events ("
		.. tostring(wasLanding) .. " -> " .. tostring(f.landingLabel:GetText()) .. ")")
	check(f.now.meta:GetText() ~= wasLeft,
		"and so does the time left on what is playing ("
		.. tostring(f.now.meta:GetText()) .. ")")

	-- The transport says what pressing it will DO, not what is happening.
	check(f.transport.toggle.glyph:GetTexture() == A.Media.icons.file,
		"the transport is drawn from the shared sheet")
	P:Pause()
	PL:Paint()
	check(P.state == "paused", "pausing pauses")

	-- LANDING IS AN INSTANT ON BOTH BARS, drawn once.
	local _, _, _, lx = f.landing:GetPoint()
	check(lx ~= nil, "the landing line is placed along the axis")

	-- AND ABOVE THEM. A bar is a child frame and each piece is a child of that,
	-- so a mark drawn on the region itself sorts underneath all of it however
	-- high its draw layer. The landing line only ever showed because it fell
	-- exactly where the flight bar's one piece ended.
	check(f.marks:GetFrameLevel() > f.programme:GetFrameLevel(),
		"the landing line is drawn over the bars, not under them")

	-- ONE AXIS, LONG ENOUGH FOR BOTH. A programme is filled until it COVERS the
	-- flight, so it overshoots by up to one item. Against an axis of the
	-- flight's own length that overshoot ran out of the side of the window -
	-- and landing was always the far right edge, which is a border, not a mark.
	local queued = 0
	for _, item in ipairs(PL.queue or {}) do queued = queued + (item.duration or 0) end
	check(queued > (Taxi.flight.expected or 0),
		"this programme runs longer than its flight (" .. queued .. "s of "
		.. tostring(Taxi.flight.expected) .. "s), which is the case that overflowed")
	-- MEASURED ON THE PIECES, not with XFor. XFor clamps to the bar, so it can
	-- never report an overrun; the pieces are what actually drew past the edge.
	local far = 0
	for _, part in ipairs(f.programme.parts) do
		if part:IsShown() then
			local _, _, _, x = part:GetPoint()
			far = math.max(far, (x or 0) + (part:GetWidth() or 0))
		end
	end
	check(far > 0 and far <= f.programme:GetWidth() + 0.01,
		"and the whole of it still lands inside the bar (" .. far .. " of "
		.. f.programme:GetWidth() .. ")")
	check(f.flight:XFor(Taxi.flight.expected) < f.flight:GetWidth() - 1,
		"with landing marked short of the end, where it can be seen")

	check(f.fills:GetText():find("programme fills", 1, true) ~= nil,
		"and the headline says how much of the flight is filled ("
		.. tostring(f.fills:GetText()) .. ")")

	check(#(f.legs or {}) == 0 or not f.legs[1]:IsShown(),
		"a single-hop flight has no stopover to mark")
	land()

	-- THE BRASS TICKS. A leg boundary is an INSTANT, so it is drawn over the
	-- flight bar rather than being a piece of it - and over, not under: the bar
	-- is a child frame and each piece is a child of that.
	_G.__taxi.nodes = {
		{ name = "Ratchet, The Barrens",    kind = "CURRENT" },
		{ name = "Crossroads, The Barrens", kind = "REACHABLE" },
		{ name = "Orgrimmar, Durotar",      kind = "REACHABLE" },
	}
	_G.__taxi.routes = { [3] = { 2, 3 } }
	TakeTaxiNode(3)
	_G.__onTaxi = true
	fire("PLAYER_CONTROL_LOST")
	tick(0.4)

	check(f.legs and f.legs[1] and f.legs[1]:IsShown(),
		"a two-leg journey marks the stopover on the flight bar")
	check(not (f.legs[2] and f.legs[2]:IsShown()),
		"and only the stopover - the last boundary is landing, which is drawn"
		.. " already and would be saying it twice")

	-- THE TICK IS WHERE THE LEG ENDS, which is only worth drawing because the
	-- route table stores single hops and a journey is the sum of them.
	local _, _, _, tx = f.legs[1]:GetPoint()
	local want = f.flight:XFor(Taxi.flight.legs[1].at)
	check(math.abs((tx or 0) - want) < 0.01,
		"at the second the first leg ends (" .. tostring(tx) .. " vs " .. want .. ")")

	-- AND IT FOLLOWS THE BAR. The tick is placed in PIXELS off the bar's
	-- width, and the bar does change width - it settles about forty units
	-- narrower as the console opens, which was measured rather than guessed.
	-- Nothing repainted the ticks when it did, so the boundary between two
	-- legs sat wherever the bar used to end: a mark claiming the stopover is
	-- somewhere it is not.
	local wide = f.flight:GetWidth()
	f.flight:SetWidth(wide * 0.75)
	local _, _, _, moved = f.legs[1]:GetPoint()
	local wantNarrow = f.flight:XFor(Taxi.flight.legs[1].at)
	check(math.abs((moved or 0) - wantNarrow) < 0.01,
		"and moves with the bar when it is resized under it (" ..
		tostring(moved) .. " vs " .. wantNarrow .. ")")
	f.flight:SetWidth(wide)

	-- THE REGION GOES WITH THE FLIGHT. Landing takes it away and stops the
	-- audio; nothing is left playing over somebody who has control back.
	land()
	check(not IF:HasRegion(), "landing takes the region away")
	check(_G.__soundsPlaying() == 0, "and stops the audio")

	-- SKIPPING HAS SOMEWHERE TO GO. A programme is filled until it COVERS the
	-- flight, which on a short hop is a single item - so "next" ran off the end
	-- of a one-item queue and ended the programme, which is a skip button that
	-- stops the music. It asks for more instead.
	R:Reset()
	cfg.progress = {}
	R:Register({ packId = "S00", apiVersion = 1, seasonIndex = 0, items = {
		{ id = "long", type = "music", title = "The Long One", totalDuration = 600,
		  segments = { { file = "long.ogg", duration = 600 } } },
		{ id = "other", type = "music", title = "The Other One", totalDuration = 600,
		  segments = { { file = "other.ogg", duration = 600 } } },
	} })

	fly()
	check(#(PL.queue or {}) == 1, "one long track covers this flight on its own ("
		.. #(PL.queue or {}) .. " queued)")

	-- WHAT AN ITEM ACTUALLY GOT. Skip twenty seconds in and the track occupied
	-- twenty seconds, not the ten minutes it was going to - and this bar is a
	-- timeline, so drawn at full length everything after it sat in the wrong
	-- place and the headline announced a queue filling 6:30 of a 4:09 flight.
	tick(20)
	local before = f.fills:GetText()
	f.transport.next:GetScript("OnClick")(f.transport.next)
	check(P:Spent(1, PL.queue[1]) < 60, "a skipped item is measured by what it played ("
		.. string.format("%.0f", P:Spent(1, PL.queue[1])) .. "s of 600s)")
	check(f.fills:GetText() ~= before, "so the headline moves when you skip ("
		.. tostring(before) .. " -> " .. tostring(f.fills:GetText()) .. ")")

	check(#(PL.queue or {}) == 2, "skipping past it pulls another out of the season")

	-- MEASURED ON THE PIECES, which is what actually drew wrong. Both items are
	-- ten minutes long, so at full length they are the same width; the one that
	-- got twenty seconds has to be a sliver beside the one that is playing.
	local w1 = f.programme.parts[1]:GetWidth() or 0
	local w2 = f.programme.parts[2]:GetWidth() or 0
	check(w1 < w2 / 4, "and the skipped item is drawn at what it played, not what"
		.. " it was going to (" .. string.format("%.0f", w1) .. " vs "
		.. string.format("%.0f", w2) .. ")")
	check(P.state == "playing" and _G.__lastSound == "other.ogg",
		"and plays it (" .. P.state .. ", " .. tostring(_G.__lastSound) .. ")")
	check(not PL.complete, "so the programme has not ended")

	-- AND WHEN THERE GENUINELY IS NOTHING LEFT, the complete state - which was
	-- built, and then never shown by anything. A programme that ran out left the
	-- last item's row on screen still counting down a track that had stopped.
	local tall = f:GetHeight()
	f.transport.next:GetScript("OnClick")(f.transport.next)
	check(PL.complete, "running out for real ends the programme")
	check(f.done:IsShown(), "the complete line is shown")
	check(f.chips[1]:IsShown() and f.chips[1].label:GetText() == "Ambient shuffle",
		"with the default action first ("
		.. tostring(f.chips[1].label:GetText()) .. ")")
	check(f.chips[1].__aetherSelected and not f.chips[3].__aetherSelected,
		"drawn filled, the way a selected tab is, and only that one")
	check(f.chips[2].label:GetText():find("Replay", 1, true) ~= nil,
		"replay names what it would replay (" .. tostring(f.chips[2].label:GetText()) .. ")")
	check(not f.now:IsShown() and not f.transport:IsShown(),
		"and everything belonging to a running programme is put away")
	check(not f.rows[1]:IsShown(), "up next included")

	-- A DIFFERENT HEIGHT, so the console has to be told rather than only
	-- repainted: one line and three chips floating in a panel four times too
	-- tall is what painting alone gave.
	check(f:GetHeight() < tall, "the region shrinks to fit it ("
		.. f:GetHeight() .. " from " .. tall .. ")")

	-- THE DEFAULT ACTION, ONE PRESS. Never dump the player into dead silence
	-- over the Barrens is the design's phrase for the whole state.
	f.chips[1]:GetScript("OnClick")(f.chips[1])
	check(not PL.complete, "the ambient shuffle starts the music again")
	check(P.state == "playing", "and it is playing (" .. P.state .. ")")
	check(f.now:IsShown() and f.done:IsShown() == false,
		"with the running programme back and the complete line gone")
	check(f:GetHeight() > tall - 1, "and the region grown back to fit it")

	land()

	-- A SKIP SHORTENS THE PROGRAMME as well as advancing it: the track that was
	-- going to fill the journey filled twenty seconds, and what covered the
	-- flight now stops short of it. Left alone, one skip emptied UP NEXT and the
	-- console showed a heading with nothing under it while a track was playing.
	R:Reset()
	cfg.progress = {}
	local many = {}
	for i = 1, 5 do
		many[i] = { id = "t" .. i, type = "music", title = "Track " .. i,
			totalDuration = 60, segments = { { file = "t" .. i .. ".ogg", duration = 60 } } }
	end
	R:Register({ packId = "S00", apiVersion = 1, seasonIndex = 0, items = many })

	fly()
	-- A LONG FLIGHT, STATED rather than inferred. The estimate comes from route
	-- data and from what earlier flights actually took, so a check that depends
	-- on it silently changes meaning when either of those does.
	Taxi.flight.expected = 200
	PL:TopUp()
	PL:Paint()

	local covered = #(PL.queue or {})
	check(covered >= 3, "a programme of short tracks is filled to cover the flight ("
		.. covered .. " queued)")
	check(f.upNextLabel:IsShown() and f.rows[1]:IsShown(), "so there is an up next")

	tick(5)
	f.transport.next:GetScript("OnClick")(f.transport.next)
	check(#(PL.queue or {}) > covered,
		"skipping tops the queue back up to covering the flight ("
		.. #(PL.queue or {}) .. " from " .. covered .. ")")
	check(f.rows[1]:IsShown(), "so up next still has something in it")
	check(f.rows[1].title:GetText() ~= (Playback and Playback.item or {}).title,
		"and it is not the thing that is playing")

	-- A HEADING WITH NOTHING UNDER IT reads as a list that failed to load.
	local was = PL.queue
	PL.queue = { was[PL.at] }
	PL.at = 1
	PL:Paint()
	check(not f.upNextLabel:IsShown(),
		"with genuinely nothing next, the heading goes too")
	PL.queue = was

	land()

	-- THE LIBRARY. A slide-out on the side of the console, because there are
	-- three kinds of content and the transport can only say "not this one".
	R:Reset()
	cfg.progress = {}
	R:Register({ packId = "S01", apiVersion = 1, seasonIndex = 1, displayName = "Season One",
		items = {
			{ id = "m1", type = "music", title = "Big Drum Deep Water",
			  artist = "The Mudfoot Kings", totalDuration = 60,
			  segments = { { file = "m1.ogg", duration = 60 } } },
			{ id = "m2", type = "music", title = "Blood and Thunder",
			  totalDuration = 60, segments = { { file = "m2.ogg", duration = 60 } } },
			{ id = "p1", type = "podcast", title = "The Gadgeteer",
			  totalDuration = 60, segments = { { file = "p1.ogg", duration = 60 } } },
		} })

	fly()
	local LB = A.IFEC.Library
	check(LB ~= nil, "the library loaded")
	check(IF.frame.library:IsShown(), "and the console carries the control that opens it")
	check(not LB:IsOpen(), "shut to begin with")

	IF.frame.library:GetScript("OnClick")(IF.frame.library)
	check(LB:IsOpen(), "the control opens it")
	local lib = LB.frame

	-- A CHILD OF THE CONSOLE, not a window of its own. The interface is at zero
	-- alpha for the whole flight, so anything under UIParent is drawn at
	-- nothing - and anything merely anchored to the console would have to be
	-- moved, scaled and hidden alongside it forever.
	check(lib:GetParent() == IF.frame, "as a child of the console, not a window")

	-- EVERYTHING IN SEASON, under its season.
	local listed, heads = 0, 0
	for _, row in ipairs(lib.rows) do if row:IsShown() then listed = listed + 1 end end
	for _, h in ipairs(lib.headings) do if h:IsShown() then heads = heads + 1 end end
	check(listed == 3, "every item in season is listed (" .. listed .. " of 3)")
	check(heads == 1, "under one heading for the pack it came from (" .. heads .. ")")
	check(lib.headings[1].text:GetText() == "SEASON ONE",
		"named after the pack (" .. tostring(lib.headings[1].text:GetText()) .. ")")

	-- The artist belongs to the title here: there is no second line, and the
	-- title alone is half a name.
	local sawArtist = false
	for _, row in ipairs(lib.rows) do
		if row:IsShown() and row.title:GetText():find("Mudfoot", 1, true) then
			sawArtist = true
		end
	end
	check(sawArtist, "with the artist beside the title")

	-- CLICKING QUEUES IT, and says so.
	local target
	for _, row in ipairs(lib.rows) do
		if row:IsShown() and not row.__aetherSelected then target = row break end
	end
	check(target ~= nil, "something in the list is not already queued")
	local wasLen = #PL.queue
	target:GetScript("OnClick")(target)
	check(#PL.queue == wasLen + 1, "clicking it adds it to the programme ("
		.. #PL.queue .. " from " .. wasLen .. ")")
	check(target.__aetherSelected, "and the row is drawn as the selected thing it now is")
	check(target.meta:GetText() == "queued", "saying so in words ("
		.. tostring(target.meta:GetText()) .. ")")
	check(P.picked[target.item.key], "recorded as the player's own pick")
	-- KEYED ON OUR OWN SET, never written onto the item: the registry hands the
	-- same table to everybody, so a flag set here outlives the flight.
	check(target.item.picked == nil, "and nothing is written onto the registry's item")

	-- AND CLICKING AGAIN TAKES IT BACK OUT.
	target:GetScript("OnClick")(target)
	check(#PL.queue == wasLen, "clicking again removes it (" .. #PL.queue .. ")")
	check(not P.picked[target.item.key], "and it is no longer a pick")

	-- NO ROW IS EVER DEAD. A click means "take it out" on something still to
	-- come and "again" on everything else - what is playing, and what has been
	-- played or skipped past. The queue keeps its history so the programme bar
	-- can draw a timeline, which is what left a skipped track drawn filled and
	-- refusing to be clicked: a toggle stuck on with no way to clear it.
	local playing
	for _, row in ipairs(lib.rows) do
		if row:IsShown() and row.meta:GetText() == "playing" then playing = row end
	end
	check(playing ~= nil, "the row that is playing says so")
	local held = #P.queue
	playing:GetScript("OnClick")(playing)
	check(#P.queue == held + 1, "and clicking it queues it again rather than"
		.. " doing nothing (" .. #P.queue .. " from " .. held .. ")")
	check(P.queue[#P.queue].key == playing.item.key, "at the end, not over the top"
		.. " of what is sounding")
	playing:GetScript("OnClick")(playing)
	check(#P.queue == held, "and clicking once more takes that repeat back out")

	-- A SKIPPED TRACK IS CLICKABLE AGAIN, which is the bug this rule exists for.
	local first = P.queue[1]
	P:Next()
	LB:Paint()
	local skipped
	for _, row in ipairs(lib.rows) do
		if row:IsShown() and row.item.key == first.key then skipped = row end
	end
	check(skipped ~= nil, "the skipped track is still in the list")
	check(not skipped.__aetherSelected,
		"no longer drawn as something coming up, because it is not")
	local before = #P.queue
	skipped:GetScript("OnClick")(skipped)
	check(#P.queue == before + 1, "and clicking it queues it again ("
		.. #P.queue .. " from " .. before .. ")")
	skipped:GetScript("OnClick")(skipped)
	check(#P.queue == before, "and again to take it back out")

	-- THE FILTERS say only what is true: three channels are declared and two are
	-- installed, so gossip has no tab.
	check(lib.tabs[1]:IsShown() and lib.tabs[2]:IsShown() and lib.tabs[3]:IsShown(),
		"a season of two channels gets All and one tab each")
	check(not lib.tabs[4]:IsShown(), "and no tab for the channel nobody shipped")

	lib.tabs[3]:GetScript("OnClick")(lib.tabs[3])       -- music
	local musicOnly = 0
	for _, row in ipairs(lib.rows) do
		if row:IsShown() then musicOnly = musicOnly + 1 end
	end
	check(musicOnly == 2, "filtering to one channel shows only that one ("
		.. musicOnly .. " of 2)")
	check(lib.tabs[3].__aetherSelected, "with its tab filled, the way a selected tab is")
	lib.tabs[1]:GetScript("OnClick")(lib.tabs[1])       -- back to all

	-- IT GOES WITH THE FLIGHT. A drawer left open over the world after landing
	-- is a window nothing on screen explains.
	land()
	check(not LB:IsOpen(), "landing shuts the drawer")

	Taxi:Stop()
	IF:HideInterface(false)
	R:Reset()
	cfg.progress = {}
	A:SetModuleEnabled("zen", zenWas)
end)

section("nifec: the mini-player, on the ground", function()
	local R, C, P = A.IFEC.Registry, A.IFEC.Content, A.IFEC.Playback
	local M, LB   = A.IFEC.Mini, A.IFEC.Library
	local TBm     = A:GetModule("toolbox")
	local IF      = A:GetModule("ifec")
	check(M ~= nil, "the mini-player loaded")

	local cfg = A.Config:Module("ifec")
	cfg.progress = {}
	R:Reset()
	P:Stop()
	_G.__musicMuted = false

	UIParent:SetSize(1365, 768)
	A.db.profile.scale = 0.71
	TBm:SetDock("LEFT")
	TBm:SetOpen(true, true)

	-- DORMANT IS ABSENT, not empty - the same answer the console gives, because
	-- it is the same question. A NOW PLAYING heading over a player with nothing
	-- to play is a section you go looking for and find broken.
	TBm:LayoutContent()
	check(not TBm:HasPlayer(), "with no content installed there is no player")
	check(not TBm.rail.play:IsShown(), "and no transport on the rail")
	check(not (TBm.content.now and TBm.content.now:IsShown()),
		"and no section at the foot of the drawer")

	local season = { packId = "S01", apiVersion = 1, seasonIndex = 1,
		displayName = "Season One", items = {
			{ id = "m1", type = "music", title = "Big Drum Deep Water",
			  artist = "The Mudfoot Kings", totalDuration = 60,
			  segments = { { file = "m1.ogg", duration = 60 } } },
			{ id = "m2", type = "music", title = "Blood and Thunder",
			  totalDuration = 60, segments = { { file = "m2.ogg", duration = 60 } } },
			{ id = "p1", type = "podcast", title = "The Gadgeteer",
			  totalDuration = 60, segments = { { file = "p1.ogg", duration = 60 } } },
			{ id = "g1", type = "gossip", masthead = "ogler",
			  title = "The Orgrimmar Ogler - Issue 37",
			  pages = { "ogler_037\\page-01", "ogler_037\\page-02",
			            "ogler_037\\page-03" } },
		} }
	R:Register(season)

	TBm:Layout()
	TBm:LayoutContent()
	check(TBm:HasPlayer(), "installing a season gives the Toolbox a player")
	check(TBm.rail.play:IsShown(), "with a transport on the rail, reachable"
		.. " with the drawer shut")
	local mini = TBm.content.now
	check(mini ~= nil and mini:IsShown(), "and a section at the foot of the drawer")

	-- IT FITS. The drawer cuts its lists to fit rather than growing, and a new
	-- fixed-cost section at the bottom is exactly the thing that pushes them
	-- through the floor - which is the one failure this file keeps having.
	check(TBm._contentHeight <= TBm.panel:GetHeight() + 0.5,
		"and the whole drawer still fits inside the panel ("
		.. string.format("%.0f", TBm._contentHeight) .. " of "
		.. string.format("%.0f", TBm.panel:GetHeight()) .. ")")

	-- AND IT FITS AT EVERY SCALE AND EVERY DOCK. The vertical panel clamps to a
	-- proportion of the screen, so at scale 1.0 it is a third shorter than at
	-- the design's 0.71 - and a fixed-cost section added at the bottom is
	-- exactly what pushes the lists that give way through the floor. The flat
	-- panel is the other shape: a sixth column, on a drawer whose short axis is
	-- the one the section has to fit in.
	for _, sc in ipairs({ 0.71, 1 }) do
		for _, edge in ipairs({ "LEFT", "RIGHT", "TOP", "BOTTOM" }) do
			A.db.profile.scale = sc
			TBm:SetDock(edge)
			TBm:SetOpen(true, true)
			TBm:RefreshWidgets(); TBm:RefreshTiles()
			TBm:RefreshAddons(); TBm:RefreshMicro()
			check(TBm._contentHeight <= TBm.panel:GetHeight() + 0.5,
				("at scale %s docked %s the drawer with a player still fits (%.0f of %.0f)")
				:format(sc, edge, TBm._contentHeight, TBm.panel:GetHeight()))
		end
	end
	A.db.profile.scale = 0.71
	TBm:SetDock("LEFT")
	TBm:SetOpen(true, true)
	TBm:LayoutContent()
	mini = TBm.content.now

	-- SILENCE HAS SOMETHING TO SAY. A blank line where a title goes reads as a
	-- player that failed rather than one that is waiting to be told.
	M:Paint()
	check(mini.title:GetText() == "Nothing playing",
		"with nothing playing it says so (" .. tostring(mini.title:GetText()) .. ")")
	check(mini.meta:GetText():find("play", 1, true) ~= nil,
		"and what pressing play will do (" .. tostring(mini.meta:GetText()) .. ")")

	-- PLAY MEANS PLAY FROM A STANDING START. On the ground there is no
	-- programme yet, and a play button that does nothing on the first press is
	-- a broken one.
	mini.toggle:GetScript("OnClick")(mini.toggle)
	check(P:IsPlaying(), "pressing play with nothing queued starts the music")
	check(#(P.queue or {}) > 0 and P.item ~= nil, "off a queue it built itself")

	-- THE AMBIENT SHUFFLE IS MUSIC. Pressing play should not start an episode
	-- nobody asked for.
	local anyTalk = false
	for _, q in ipairs(P.queue) do if q.type ~= "music" then anyTalk = true end end
	check(not anyTalk, "and it is music, not whatever came first in the season")

	M:Paint()
	check(mini.title:GetText() == P.item.title,
		"the region names what is playing (" .. tostring(mini.title:GetText()) .. ")")
	if P.item.artist then
		check(mini.meta:GetText():find(P.item.artist, 1, true) ~= nil,
			"with the artist on it (" .. tostring(mini.meta:GetText()) .. ")")
	end

	-- THE RAIL CHIP IS THE SAME TRANSPORT, and the only thing on screen saying
	-- anything is playing at all with the drawer shut.
	TBm.rail.play:GetScript("OnClick")(TBm.rail.play)
	check(P.state == "paused", "the rail chip pauses it (" .. P.state .. ")")
	TBm.rail.play:GetScript("OnClick")(TBm.rail.play)
	check(P.state == "playing", "and starts it again")

	-- THE RAIL, IN ORDER. The two settled controls sit at the far end together:
	-- the way to the options, and the way to stop the music.
	do
		-- CHECKED ON THE ANCHORS, which is what the layout actually decides. The
		-- chain has to be built from what is SHOWING: anchored to a hidden frame
		-- the envelope keeps the geometry that frame would have had, so a season
		-- nobody installed leaves an icon's worth of hole in the rail.
		local _, playRel = TBm.rail.play:GetPoint()
		local _, mailRel = TBm.rail.mail:GetPoint()
		check(playRel == TBm.rail.gear,
			"the transport sits immediately above the gear")
		check(mailRel == TBm.rail.play, "with the envelope above it")

		R:Reset()
		TBm:Layout()
		local _, bare = TBm.rail.mail:GetPoint()
		check(not TBm.rail.play:IsShown() and bare == TBm.rail.gear,
			"and with no content the envelope closes the gap rather than"
			.. " anchoring to a chip that is not there")
		R:Register(season)
		TBm:Layout()
		TBm:LayoutContent()
	end

	-- GOSSIP IS READ, NOT PLAYED. It has no audio and no duration, so it has no
	-- place in a running order - it used to be queued and stepped straight past,
	-- which put a bulletin in UP NEXT as something about to happen.
	do
		local full = C:Everything()
		local sawGossip = false
		for _, q in ipairs(full) do if q.type == "gossip" then sawGossip = true end end
		check(not sawGossip, "no programme ever contains a bulletin")
		check(P:Pick({ key = "S01:g1", type = "gossip" }) == nil,
			"and it cannot be picked into one")
	end

	-- ONE LIBRARY, TWO HOSTS. It hangs off whatever opened it, or it is drawn at
	-- zero alpha in flight and off the bottom of the screen on the ground.
	mini.library:GetScript("OnClick")(mini.library)
	check(LB:IsOpen(), "the mini-player opens the library")
	check(LB.frame:GetParent() == mini,
		"hung off the mini-player, not off the console")

	-- Clicking a row queues into the SAME programme the console would use.
	local row
	for _, r in ipairs(LB.frame.rows) do
		if r:IsShown() and not r.__aetherSelected then row = r break end
	end
	check(row ~= nil, "the list has something not already queued")
	local was = #P.queue
	row:GetScript("OnClick")(row)
	check(#P.queue == was + 1, "and clicking it queues into the running programme")

	-- AND THE TOOLTIP COMES UP IN FRONT. It is a shared object anything can
	-- reparent and this addon does exactly that - the console moves it out of
	-- UIParent for a flight so it can be read over a hidden interface. Left
	-- somewhere else it draws under the chat log, which is where it was found.
	do
		local chip = TBm.rail.play
		GameTooltip:Hide()
		GameTooltip:SetFrameStrata("BACKGROUND")     -- as something else left it
		chip:GetScript("OnEnter")(chip)
		check(GameTooltip:IsShown(), "hovering the chip raises a tooltip")
		check(GameTooltip:GetFrameStrata() == "TOOLTIP",
			"in front of everything, whatever it was left at ("
			.. tostring(GameTooltip:GetFrameStrata()) .. ")")
		chip:GetScript("OnLeave")(chip)
		check(not GameTooltip:IsShown(), "and goes again")
	end

	-- THE REST OF THE TRANSPORT, ON A RIGHT-CLICK. The chip is one icon wide and
	-- the whole point of it is not opening the drawer, so the three controls
	-- that do not fit go on a menu rather than nowhere.
	do
		local chip = TBm.rail.play
		A.Widgets.CloseMenu()
		chip:GetScript("OnClick")(chip, "RightButton")
		local menu = A.Widgets.MenuFrame()
		check(menu and menu:IsShown(), "right-clicking the chip opens a menu")
		local words = {}
		for i = 1, 3 do words[i] = menu.items[i].text:GetText() end
		check(table.concat(words, ",") == "Stop,Previous,Next",
			"with stop, previous and next on it (" .. table.concat(words, ",") .. ")")

		-- AND LEFT-CLICK STILL PLAYS. A button that grew a menu and lost its
		-- press is a worse button.
		A.Widgets.CloseMenu()
		local was = P.state
		chip:GetScript("OnClick")(chip, "LeftButton")
		check(P.state ~= was, "and left-clicking still works the transport ("
			.. was .. " -> " .. P.state .. ")")
		if not P:IsPlaying() then chip:GetScript("OnClick")(chip, "LeftButton") end

		-- STOP STOPS.
		chip:GetScript("OnClick")(chip, "RightButton")
		menu = A.Widgets.MenuFrame()
		menu.items[1]:GetScript("OnClick")(menu.items[1])
		check(P.state == "stopped", "stop stops it (" .. P.state .. ")")
		check(_G.__soundsPlaying() == 0, "and silences the channel")

		-- DISABLED RATHER THAN ABSENT with nothing to do: a menu that changes
		-- shape between openings is one you cannot learn.
		chip:GetScript("OnClick")(chip, "RightButton")
		menu = A.Widgets.MenuFrame()
		check(menu.items[1].action == nil, "with nothing playing, stop is dead")
		check(menu.items[1]:IsShown(), "and still on the menu, not missing from it")
		A.Widgets.CloseMenu()

		mini.toggle:GetScript("OnClick")(mini.toggle)
	end

	-- AND IT OPENS AWAY FROM THE DRAWER'S OWN BODY. "Beside the host" is only
	-- right while the host sits at a screen edge with open screen next to it.
	-- Docked ACROSS THE TOP the mini-player is one column of a wide strip, and
	-- beside it is the middle of that strip - the list opened over the settings
	-- tiles it had just come out from under.
	do
		local want = { LEFT = "BOTTOMLEFT", RIGHT = "BOTTOMRIGHT",
		               TOP = "TOPRIGHT", BOTTOM = "BOTTOMRIGHT" }
		local rel  = { LEFT = "BOTTOMRIGHT", RIGHT = "BOTTOMLEFT",
		               TOP = "BOTTOMRIGHT", BOTTOM = "TOPRIGHT" }
		for _, edge in ipairs({ "LEFT", "RIGHT", "TOP", "BOTTOM" }) do
			TBm:SetDock(edge)
			TBm:SetOpen(true, true)
			TBm:LayoutContent()
			LB:SetOpen(true, TBm.content.now)

			local p1, relTo, p2 = LB.frame:GetPoint(1)
			check(p1 == want[edge] and p2 == rel[edge] and relTo == TBm.content.now,
				("docked %s the list opens %s of the player (%s to %s)")
				:format(edge, edge == "TOP" and "below" or
					(edge == "BOTTOM" and "above" or "beside"), p1, p2))
			check(LB.frame:GetNumPoints() == 1,
				"anchored once, not left spanned between the last corner and this one")
		end

		TBm:SetDock("LEFT")
		TBm:SetOpen(true, true)
		TBm:LayoutContent()
		mini = TBm.content.now
		LB:SetOpen(true, mini)
	end

	-- THE LIBRARY GOES WITH THE DRAWER. It hangs off the mini-player at the foot
	-- of the panel and slides away with it - but off the RIGHT of that, so a
	-- panel a full width off screen left the list sitting just inside the edge
	-- with nothing behind it.
	do
		check(LB:IsOpen(), "the library is open")
		TBm:SetOpen(false, true)
		check(not LB:IsOpen(), "closing the drawer shuts the list with it")
		TBm:SetOpen(true, true)
		LB:SetOpen(true, mini)
	end

	-- A READING FILL, not the control-surface one: a column of titles read over
	-- whatever the world is doing behind it, which is the argument the quest log
	-- and the chat log already make.
	do
		local want = A.Palette:ReadingFill()[4] or 1
		local plain = (A.Palette.c.glassStrong or A.Palette.c.glass)[4] or 1
		local got = (LB.frame._fillColor or {})[4] or 0
		check(math.abs(got - want) < 0.001,
			("the list is at the readable opacity (%.2f of %.2f)"):format(got, want))
		-- The two have to DIFFER, or this passes on a profile where the boost is
		-- zero and proves only that a number equals itself.
		check(math.abs(want - plain) > 0.001,
			("and that is deeper than a control surface (%.2f against %.2f)")
			:format(want, plain))

		-- AND SO IS THE PAPER. The page is opaque, but the margin around it and
		-- the strip under it are not, and a border you can see the world through
		-- is a page that looks like it is floating.
		local RDb = A.IFEC.Reader
		RDb:Build()
		local paper = (RDb.frame._fillColor or {})[4] or 0
		check(math.abs(paper - want) < 0.001,
			("the paper is too (%.2f of %.2f)"):format(paper, want))
	end

	-- THE MAGAZINE OPENS, it does not queue. You read the paper while the music
	-- carries on, which is the whole point of it having no duration.
	do
		local RD = A.IFEC.Reader
		check(RD ~= nil, "the reader loaded")

		local gossip
		for _, r in ipairs(LB.frame.rows) do
			if r:IsShown() and r.item.type == "gossip" then gossip = r end
		end
		check(gossip ~= nil, "the bulletin is in the list with everything else")
		check(gossip.meta:GetText() == "3 pages", "unread, saying how long it is ("
			.. tostring(gossip.meta:GetText()) .. ")")
		check(not gossip.__aetherSelected,
			"and never drawn as something cued, because it cannot be")

		local held = #P.queue
		local wasPlaying = P.item and P.item.key
		gossip:GetScript("OnClick")(gossip)
		check(RD:IsOpen(), "clicking it opens the paper")
		check(#P.queue == held, "and queues nothing (" .. #P.queue .. ")")
		check(P.item and P.item.key == wasPlaying,
			"with the music carrying on underneath it")
		-- NOT HUNG OFF THE LIST, unlike the drawer itself. A page is authored at
		-- 1024 and wants the screen; beside the Toolbox it would be mostly off
		-- the edge of it. Outside UIParent too, so it survives the interface
		-- being hidden at altitude.
		check(RD.frame:GetParent() == IF:Top(),
			"the paper is its own window, outside the interface it has to survive")
		-- MEASURED IN PHYSICAL PIXELS, at both ends. The window is under a
		-- parentless holder so that it survives the interface being hidden,
		-- which means it does NOT share UIParent's scale - so asking UIParent
		-- how big the screen is and then drawing that many units HERE is asking
		-- one ruler and cutting with another. It hung off the top of the screen.
		--
		-- Swept rather than checked once, because the two directions fail at
		-- different scales and a single scale is a coin toss between them.
		local function px(frame)
			local sc = frame:GetEffectiveScale() or 1
			return (frame:GetWidth() or 0) * sc, (frame:GetHeight() or 0) * sc
		end
		local uiWas = UIParent:GetScale() or 1
		local profWas = A.db.profile.scale
		for _, uiScale in ipairs({ 0.53, 0.64, 1, 1.875 }) do
			for _, prof in ipairs({ 0.71, 1 }) do
				UIParent:SetScale(uiScale)
				A.db.profile.scale = prof
				RD:Size()
				local w, h = px(RD.frame)
				local sw, sh = px(UIParent)
				check(w <= sw and h <= sh,
					("at UI scale %s and profile %s the page fits (%.0fx%.0f of %.0fx%.0f)")
					:format(uiScale, prof, w, h, sw, sh))
			end
		end

		-- IT FOLLOWS THE GLOBAL SCALE, like every window of ours.
		UIParent:SetScale(1)
		A.db.profile.scale = 0.71
		RD:Size()
		check(math.abs((RD.frame:GetScale() or 1) - 0.71) < 0.001,
			"the paper is at the profile's scale like everything else ("
			.. tostring(RD.frame:GetScale()) .. ")")

		-- AND ACTUAL SIZE STILL MEANS ACTUAL SIZE. The window shrinks with the
		-- profile, so a page of 1024 units is 727 pixels at 0.71 - a "1:1" that
		-- is nothing of the kind. Zoomed, the art lands one texel to one pixel.
		RD:SetZoomed(true)
		local pw = px(RD.frame.sheet)
		check(math.abs(pw - 1024) < 1.5,
			"and zoomed, one texel is one pixel whatever the scale ("
			.. string.format("%.0f", pw) .. " of 1024)")
		RD:SetZoomed(false)
		A.db.profile.scale = profWas

		-- BUILT AROUND THE PAGE, not around the screen. The first version asked
		-- how much room there was and took all of it, which on a tall monitor is
		-- a magazine filling the monitor. The page is authored at a known size,
		-- so that is the number to start from and the screen only says no.
		--
		-- The rule of thumb: the whole window - page, margin and the strip under
		-- it - fits vertically on a 1080 screen with the interface still around
		-- it. Checked at the top of the scale range as well as the default,
		-- because a setting that can be turned up past the screen is one that
		-- puts the pager off the bottom of it.
		UIParent:SetSize(1920, 1080)
		UIParent:SetScale(1)
		A.db.profile.scale = 1
		for _, rs in ipairs({ 0.7, 1 }) do
			cfg.readerScale = rs
			RD:Size()
			local _, hh = px(RD.frame)
			check(hh <= 1080,
				("at magazine size %s the window fits a 1080 screen (%.0f tall)")
				:format(rs, hh))
		end

		-- CHECKED AWAY FROM THE DEFAULT. At 0.7 the setting and the built-in
		-- fraction are the same number, so a reader that ignored the setting
		-- entirely would draw exactly the right size and prove nothing.
		for _, rs in ipairs({ 0.5, 0.7, 0.85 }) do
			cfg.readerScale = rs
			RD:Size()
			check(math.abs((RD.frame.sheet:GetWidth() or 0) - 1024 * rs) < 1,
				("the page is drawn at the fraction asked for, not at whatever"
				.. " fits (%s -> %.0f, wanted %.0f)"):format(
					rs, RD.frame.sheet:GetWidth() or 0, 1024 * rs))
		end
		cfg.readerScale = 0.7
		RD:Size()
		UIParent:SetSize(1365, 768)
		UIParent:SetScale(uiWas)
		A.db.profile.scale = profWas
		RD:Size()

		-- EVERY CONTROL IN THE STRIP IS LINE ART. The close was a typed
		-- multiplication sign, and whether a font has U+00D7 is the font's
		-- business - the weight it landed in drew the notdef box and then the
		-- digits of the escape, on screen, next to the magnifier.
		for _, b in ipairs({ RD.frame.prev, RD.frame.next,
		                     RD.frame.zoom, RD.frame.close }) do
			check(b.glyph ~= nil and b.glyph:GetTexture() == A.Media.icons.file,
				"the reader's controls all come off the shared sheet")
		end
		-- WHAT THE WINDOW IS, not what is in it. It used to caption itself with
		-- the issue's own title, which every page already carries in letters an
		-- inch high - our chrome talking over the thing it is showing.
		--
		-- AND IT FOLLOWS THE MODE, because the rest of the console does. This is
		-- the ground, so it is the Not-In-Flight one.
		check(RD.frame.title:GetText() == "N.I.F.E.C. MEDIA READER",
			"on the ground the window is the N.I.F.E.C. reader ("
			.. tostring(RD.frame.title:GetText()) .. ")")
		check(RD.frame.title:GetText() ~= gossip.item.title,
			"and not what is in it - the page has its own masthead")

		-- A PAGE IS AN IMAGE. The reader has no opinion about what is on one.
		check(RD.frame.sheet.page:GetTexture() == gossip.item.pages[1],
			"open at the first page (" .. tostring(RD.frame.sheet.page:GetTexture()) .. ")")
		check(RD.frame.pager:GetText() == "1 / 3", "and says which one ("
			.. tostring(RD.frame.pager:GetText()) .. ")")

		RD:Turn(1)
		check(RD.frame.sheet.page:GetTexture() == gossip.item.pages[2],
			"turning goes to the next page")
		-- A MAGAZINE IS NOT A LOOP. Turning past the back cover onto the front
		-- again is a thing no paper does, and it is how you lose your place.
		RD:Turn(-1) RD:Turn(-1) RD:Turn(-1)
		check(RD.frame.pager:GetText() == "1 / 3", "and stops at the front cover")
		RD:Turn(9)
		check(RD.frame.pager:GetText() == "3 / 3", "and at the back one")

		-- WHERE YOU GOT TO, in the same field an episode keeps its segment in.
		LB:Paint()
		for _, r in ipairs(LB.frame.rows) do
			if r:IsShown() and r.item.type == "gossip" then gossip = r end
		end
		check(gossip.meta:GetText() == "read",
			"reaching the back page marks it read ("
			.. tostring(gossip.meta:GetText()) .. ")")

		-- A FINISHED MAGAZINE STARTS AGAIN, or it is one you cannot re-read.
		RD:Close()
		RD:Open(gossip.item)
		check(RD.frame.pager:GetText() == "1 / 3",
			"and reopening a finished one starts at the front")

		-- Part way through, it picks up where it was left - the same rule the
		-- programme follows for a half-heard episode.
		RD:Turn(1)
		RD:Close()
		RD:Open(gossip.item)
		check(RD.frame.pager:GetText() == "2 / 3",
			"while a half-read one opens where it was left ("
			.. tostring(RD.frame.pager:GetText()) .. ")")

		LB:Paint()
		for _, r in ipairs(LB.frame.rows) do
			if r:IsShown() and r.item.type == "gossip" then gossip = r end
		end
		check(gossip.meta:GetText() == "page 2 of 3",
			"and the list says how far in you are ("
			.. tostring(gossip.meta:GetText()) .. ")")

		-- THE PAPER STAYS when the list goes. It came out of that list but it is
		-- a window of its own, and reading a magazine with the Toolbox shut and
		-- the music carrying on is the whole reason it takes no time.
		LB:Close()
		check(RD:IsOpen(), "shutting the list leaves the paper open")
		RD:Close()
		LB:SetOpen(true, mini)
	end

	-- BOARDING TAKES OVER. There is only ever one thing playing: the console
	-- builds a programme shaped like the journey and the mini-player becomes a
	-- view onto it rather than a second player.
	--
	-- AND IT DOES NOT START AGAIN. Boarding used to build a programme and Start
	-- it, which cut off whatever was already sounding to play something else - a
	-- track stopped mid-bar to be replaced by a track. The flight is a length to
	-- fill, not a reason to begin again.
	LB:Close()
	local boardingWith = P.item and P.item.key
	-- COUNTED FROM EVER-STARTED, not from the last file name. Restarting a track
	-- plays the SAME file, so a check on the name passes whether the console
	-- adopted what was sounding or stopped it and began it again from the top.
	local startsBefore = 0
	for _ in pairs(_G.__sounds) do startsBefore = startsBefore + 1 end
	check(boardingWith ~= nil, "something is playing as the griffin arrives")
	A.IFEC.Taxi:Start()
	_G.__taxi.nodes = {
		{ name = "Ratchet, The Barrens",    kind = "CURRENT" },
		{ name = "Crossroads, The Barrens", kind = "REACHABLE" },
	}
	_G.__taxi.routes = {}
	TakeTaxiNode(2)
	_G.__onTaxi = true
	fire("PLAYER_CONTROL_LOST")
	tick(0.4)

	check(IF:HasRegion(), "boarding hangs the console's own region")

	-- AND THE READER FOLLOWS THE MODE. Aboard a griffin the same window is the
	-- IN-flight console's, which is the one place the joke would not have run.
	do
		local RD = A.IFEC.Reader
		local bulletin
		for _, item in ipairs(C:Available()) do
			if item.type == "gossip" then bulletin = item end
		end
		check(bulletin ~= nil, "there is a bulletin to open in the air")
		RD:Open(bulletin)
		check(RD.frame.title:GetText() == "I.F.E.C. MEDIA READER",
			"in the air the same window is the I.F.E.C. reader ("
			.. tostring(RD.frame.title:GetText()) .. ")")
		RD:Close()
	end
	check(_G.__soundsPlaying() <= 1,
		"and there is still only one thing playing ("
		.. _G.__soundsPlaying() .. ")")
	check(A.IFEC.Player.queue ~= nil and P.queue == A.IFEC.Player.queue,
		"off one queue, which the console now owns")
	check(P.item and P.item.key == boardingWith,
		"and the track that was already playing is still the one playing ("
		.. tostring(P.item and P.item.title) .. ")")
	check(P.queue[1] and P.queue[1].key == boardingWith,
		"leading the programme rather than queued behind it")
	local startsAfter = 0
	for _ in pairs(_G.__sounds) do startsAfter = startsAfter + 1 end
	check(startsAfter == startsBefore,
		"with nothing restarted - the track carries on rather than being cut off"
		.. " mid-bar and begun again (" .. startsAfter .. " vs " .. startsBefore .. ")")

	-- AND THE PROGRAMME IS BUILT AROUND IT. What is left of the running track
	-- counts towards the journey, so only the remainder has to be covered -
	-- ignoring it queues a flight's worth of music on top of a track that is
	-- already playing most of the first minute of it.
	do
		local want = A.IFEC.Taxi.flight.expected or 0
		local total = 0
		for _, item in ipairs(P.queue) do total = total + (item.duration or 0) end
		local withoutLast = total - (P.queue[#P.queue].duration or 0)
		check(total >= want, ("the programme still covers the flight (%ds of %ds)")
			:format(total, want))
		check(withoutLast < want,
			("and is no longer than it has to be - one item less falls short"
			.. " (%ds of %ds)"):format(withoutLast, want))
	end

	-- LANDING IS NOT ALWAYS A STOP. Off, the programme goes with the flight;
	-- on, the same queue simply carries on into the mini-player, which is
	-- already a view onto it.
	cfg.playOn = true
	check(P:IsPlaying(), "a programme is running as the flight ends")
	_G.__onTaxi = false
	fire("PLAYER_CONTROL_GAINED")
	tick(0.4)
	check(P:IsPlaying(), "with 'keep playing' on, landing does not stop it")
	check(not IF:HasRegion(), "though the console's own region goes with the flight")
	check(_G.__soundsPlaying() == 1, "and the audio carries on (" ..
		_G.__soundsPlaying() .. ")")
	M:Paint()
	check(mini.title:GetText() == (P.item and P.item.title),
		"with the mini-player describing it now (" .. tostring(mini.title:GetText()) .. ")")

	-- AND OFF IS THE DEFAULT, because audio still going after the player has
	-- control back is the worst failure this feature has.
	cfg.playOn = false
	TakeTaxiNode(2)
	_G.__onTaxi = true
	fire("PLAYER_CONTROL_LOST")
	tick(0.4)
	check(P:IsPlaying(), "boarding again")
	_G.__onTaxi = false
	fire("PLAYER_CONTROL_GAINED")
	tick(0.4)
	check(not P:IsPlaying(), "with it off, landing stops the programme")
	check(_G.__soundsPlaying() == 0, "and silences the channel")

	-- THE TILE SWITCHES THE PLAYER, NOT THE TIMER. A player who never wants a
	-- programme on a griffin still wants to know when the griffin lands.
	_G.__onTaxi = false
	fire("PLAYER_CONTROL_GAINED")
	tick(0.4)

	cfg.player = false
	-- COUNTED FROM EVER-STARTED, not from still-playing. A programme that begins
	-- and is stopped a second later by the tick that notices is silence by the
	-- time anybody asks, and an audible blip on every takeoff.
	local startedBefore = 0
	for _ in pairs(_G.__sounds) do startedBefore = startedBefore + 1 end

	TakeTaxiNode(2)
	_G.__onTaxi = true
	fire("PLAYER_CONTROL_LOST")
	tick(0.4)
	check(A.IFEC.Taxi:IsFlying(), "with the player switched off the flight is still tracked")
	check(IF.frame:IsShown(), "and the console still opens")
	check(not IF:HasRegion(), "but hangs no programme under it")

	local startedAfter = 0
	for _ in pairs(_G.__sounds) do startedAfter = startedAfter + 1 end
	check(startedAfter == startedBefore,
		"and nothing was ever started, not started and hushed ("
		.. startedAfter .. " vs " .. startedBefore .. ")")

	_G.__onTaxi = false
	fire("PLAYER_CONTROL_GAINED")
	tick(0.4)
	cfg.player = true

	-- AND THE TILE CAN BE PRESSED MID-FLIGHT. It is a tile on a drawer that
	-- opens over a griffin, so "takes effect next flight" is not good enough for
	-- switching it OFF - the programme it would leave running is the thing you
	-- just said you did not want.
	TakeTaxiNode(2)
	_G.__onTaxi = true
	fire("PLAYER_CONTROL_LOST")
	tick(0.4)
	check(IF:HasRegion() and _G.__soundsPlaying() == 1, "a programme is running")

	cfg.player = false
	tick(1)
	check(not IF:HasRegion(), "switching it off mid-flight takes the region away")
	check(_G.__soundsPlaying() == 0, "and stops the audio with it")
	check(A.IFEC.Taxi:IsFlying(), "while the flight carries on being tracked")

	_G.__onTaxi = false
	fire("PLAYER_CONTROL_GAINED")
	tick(0.4)
	cfg.player = true

	-- AND THE MINI-PLAYER IS NOT IN FLIGHT, so the setting is none of its
	-- business: it is the one surface that has nothing to do with a griffin.
	cfg.player = false
	TBm:LayoutContent()
	check(TBm:HasPlayer(), "the mini-player is unaffected - it is not in flight")
	cfg.player = true

	A.IFEC.Taxi:Stop()
	P:Stop()
	TBm:SetOpen(false, true)
	R:Reset()
	cfg.progress = {}
end)

section("ifec: the console takes a region, and gives it back", function()
	local IF   = A:GetModule("ifec")
	local Taxi = A.IFEC.Taxi

	Taxi:Start()
	_G.__taxi.nodes = {
		{ name = "Ratchet, The Barrens",    kind = "CURRENT" },
		{ name = "Crossroads, The Barrens", kind = "REACHABLE" },
	}
	TakeTaxiNode(2)
	_G.__onTaxi = true
	fire("PLAYER_CONTROL_LOST")
	tick(0.4)

	local f = IF.frame
	local bare = f:GetHeight()
	check(f.capsule:IsShown() and not f.panel:IsShown(),
		"with nothing to play it is a capsule")
	check(not f.hairline:IsShown(), "and there is no rule under the header")
	check(not IF:HasRegion(), "and it knows it carries nothing")

	-- THE ONLY GEOMETRY THAT CHANGES IS THE CORNER. Same width, same header,
	-- same dial - the design is explicit that these are two forms of one thing
	-- rather than two things.
	-- NO CHEVRON WITH NOTHING TO FOLD. A control that does nothing is bad
	-- enough; this one would also say the console had a hidden half, which is
	-- the opposite of "nothing reads as missing".
	check(not f.chevron:IsShown(), "and no fold control, there being nothing to fold")

	local region = CreateFrame("Frame", nil, UIParent)
	region:SetSize(560, 120)
	check(IF:AttachRegion(region, 120), "something can be hung under the header")
	check(f.chevron:IsShown(), "which brings the fold control with it")
	check(f.panel:IsShown() and not f.capsule:IsShown(), "which makes it a panel")
	check(f.hairline:IsShown(), "with the rule showing")
	check(f:GetHeight() == bare + 120, "and the frame grown by exactly the region ("
		.. f:GetHeight() .. " from " .. bare .. ")")
	check(f.route:GetText():find("Ratchet", 1, true) ~= nil,
		"the header is untouched by the change")

	-- THE HEADER STAYS AT THE TOP. Everything in it hangs off the vertical
	-- centre of what it is parented to, which is right while that is the
	-- capsule and catastrophic the moment a region makes the frame four times
	-- taller: the dial, the route and the fold control all slid down to the
	-- middle of the panel and drew across the player region.
	check(f.head ~= nil and f.head:GetHeight() == bare,
		"the header is a strip of its own, the capsule's height")
	check(f.dial:GetParent() == f.head and f.route:GetParent() == f.head
		and f.chevron:GetParent() == f.head,
		"and the dial, the route and the fold control hang off it, not the frame")
	local hp = f.head.__points[1]
	check(hp[1] == "TOPLEFT" and hp[2] == f and hp[3] == "TOPLEFT" and hp[5] == 0,
		"pinned to the top, so both forms lay the header out identically")

	-- A PANEL HAS A WIDER FLOOR THAN A CAPSULE. Fit used to bail out the moment
	-- a region was attached, so a panel kept whatever the capsule happened to be
	-- when the region arrived - and the region attaches BEFORE the route is
	-- painted, so the first flight of a session got the bare minimum and the
	-- now-playing row drew over its own transport.
	check(f:GetWidth() >= 400,
		"and a panel is at least as wide as the player region needs ("
		.. f:GetWidth() .. ")")

	-- FOLDING IS NOT THE SAME AS HAVING NOTHING. Both look like the capsule, but
	-- one is "there is nothing to play" and the other is "you put it away" - and
	-- the difference is whether there is a control to bring it back.
	check(IF:SetCollapsed(true), "the fold control folds it")
	check(f.capsule:IsShown() and not f.panel:IsShown(), "back to a capsule")
	check(f:GetHeight() == bare, "at the capsule's height")
	check(f.chevron:IsShown(), "with the control still there to unfold it")
	check(IF:HasRegion(), "and the region still attached, just put away")
	check(IF:SetCollapsed(false), "and it unfolds again")
	check(f.panel:IsShown() and f:GetHeight() == bare + 120, "to the panel it was")

	check(IF:DetachRegion(), "and it goes back")
	check(f.capsule:IsShown() and not f.panel:IsShown(), "to a capsule")
	check(f:GetHeight() == bare, "at its old height")
	check(not region:IsShown(), "with the region put away rather than left behind")
	check(not f.chevron:IsShown(), "and the fold control gone with the thing it folded")
	check(not IF:SetCollapsed(true), "which cannot be folded when there is nothing to fold")

	-- No /reload between the two: the player region can appear between one
	-- flight and the next, and a form change that needed a reload would mean
	-- installing a season did nothing until you relogged.
	IF:AttachRegion(region, 80)
	IF:DetachRegion()
	IF:AttachRegion(region, 80)
	check(f:GetHeight() == bare + 80 and f.panel:IsShown(),
		"and back and forth as often as you like")
	IF:DetachRegion()

	_G.__onTaxi = false
	fire("PLAYER_CONTROL_GAINED")
	Taxi:Stop()
end)

-- LAST IN THE FILE, and it has to be. Spawning a plate takes a frame out
-- of the mock's pool, and the recycling checks above are about a plate
-- being handed out FRESH the first time - so a section that spawns one
-- earlier quietly spends the case they exist to make.
section("party controls: the marks go on your target", function()
	local PF = A:GetModule("partyframes")
	A:SetModuleEnabled("partyframes", true)
	-- An earlier section takes the target away entirely, and a party control
	-- that acts on your target has nothing to act on without one.
	_G.__units.target = _G.__units.target or {
		exists = true, name = "Savannah Prowler", level = 16,
		creature = "Beast", hp = 640, hpMax = 1000, reaction = 2,
		power = 0, powerMax = 0, powerType = 0, powerToken = "MANA",
	}
	local p = PF:BuildPanel()
	check(p ~= nil, "the controls panel builds")
	check(#p.wells == 8, "eight marks (" .. #p.wells .. ")")
	check(p.clear ~= nil, "and a Clear that is not a ninth mark")

	-- EVERY WELL WEARS ITS MARK. The wells came up empty on screen while every
	-- other check about them passed, because nothing here had ever asked what
	-- was actually in one - the grid was checked for what it DID, never for
	-- what it showed.
	local blank = 0
	for i, b in ipairs(p.wells) do
		if not b.icon or not tostring(b.icon.__tex):find("RaidTargetingIcons", 1, true) then
			blank = blank + 1
		end
	end
	check(blank == 0, "each well shows its mark (" .. blank .. " blank)")

	-- AND ITS OWN CELL out of the sheet. A texture given the file and no
	-- texcoord draws all eight marks at once.
	local seen, clash = {}, nil
	for i, b in ipairs(p.wells) do
		local l, r, t2, b2 = b.icon:GetTexCoord()
		local key = string.format("%.3f,%.3f,%.3f,%.3f", l, r, t2, b2)
		if seen[key] then clash = i .. " and " .. seen[key] end
		seen[key] = i
	end
	check(not clash, "and its own cell out of the sheet (" .. tostring(clash) .. ")")

	-- AT THE PROFILE'S SCALE, and AT A SCREEN EDGE. A panel floating in the
	-- middle is not a dock: half the shape the brief describes is the thing
	-- being drawn out of the side of the screen rather than dropped on it.
	local wasScale = A.db.profile.scale
	A.db.profile.scale = 0.6
	PF:RefreshPanel()
	check(math.abs(p:GetScale() - 0.6) < 0.001,
		"the panel is drawn at the profile's scale (" .. p:GetScale() .. ")")
	A.db.profile.scale = wasScale
	PF:RefreshPanel()

	check(PF:PanelEdge() == "LEFT", "docked left by default")

	-- THE HANDLE IS THE THING AT THE EDGE, and the panel comes out of the
	-- handle. That chain is the shape the brief describes - a tab flush to the
	-- screen with a drawer behind it - and it is also what makes the panel
	-- move when the handle is re-docked without either of them knowing about
	-- the other.
	check(PF.handle ~= nil, "there is a dock handle")
	local _, hrel, hat = PF.handle:GetPoint()
	check(hrel == UIParent and hat == "LEFT",
		"the handle is flush to the screen edge (" .. tostring(hat) .. ")")
	local _, prel = p:GetPoint()
	check(prel == PF.handle,
		"and the panel comes out of the handle, not off the bare edge")

	check(PF:SetPanelEdge("RIGHT"), "it can be moved to another edge")
	local _, _, hat2 = PF.handle:GetPoint()
	check(hat2 == "RIGHT", "and the handle goes there (" .. tostring(hat2) .. ")")
	check(not PF:SetPanelEdge("MIDDLE"),
		"and a corner that is not an edge is refused rather than obeyed")
	PF:SetPanelEdge("LEFT")

	-- A QUARTER ALONG, NOT THE MIDDLE. The Toolbox rail lives at the middle of
	-- its edge and both default to LEFT, so a handle centred there lands on top
	-- of it - which is exactly what it did. The client puts its own party dock
	-- about a quarter down, which is where a player already looks and is clear
	-- of the rail by construction rather than by collision-detection.
	check(PF:PanelSlot() == 1, "the handle takes the first slot by default")
	local _, _, _, _, dy = PF.handle:GetPoint()
	check(dy and dy > 0,
		"which is up from the middle of a side edge, not on it (" ..
		tostring(dy) .. ")")
	local TB = A:GetModule("toolbox")
	if TB and TB.rail and TB.rail:IsShown() then
		local _, _, _, _, ry = TB.rail:GetPoint()
		check(math.abs(dy - (ry or 0)) > 40,
			"and clear of the Toolbox rail on the same edge (" ..
			tostring(dy) .. " vs " .. tostring(ry) .. ")")
	end

	check(PF:SetPanelSlot(2), "there is a second slot per edge")
	local _, _, _, _, dy2 = PF.handle:GetPoint()
	check(dy2 and dy2 < 0,
		"three quarters along, on the other side of the middle (" ..
		tostring(dy2) .. ")")
	check(not PF:SetPanelSlot(3),
		"and a third slot is refused rather than invented")
	PF:SetPanelSlot(1)

	-- MEASURED IN THE HANDLE'S OWN UNITS. SetPoint offsets are in the
	-- anchored frame's coordinate space, and this frame runs at the profile
	-- scale - so a quarter of the screen expressed in UIParent pixels lands
	-- at a third of the way down at 0.71, and off a small screen entirely.
	--
	-- The scale has to MOVE for this to say anything: at 1 the conversion is
	-- the identity and a check that never leaves the default passes with the
	-- bug in it. That is how this one got through the first time.
	local wasScale = A.db.profile.scale
	local _, _, _, _, atOne = PF.handle:GetPoint()
	A.db.profile.scale = 0.5
	PF:LayoutHandle()
	local _, _, _, _, atHalf = PF.handle:GetPoint()
	-- The offset scales by exactly the ratio of the two scales: the same
	-- quarter of the screen, counted in smaller units.
	local want = atOne * ((wasScale or 1) / 0.5)
	check(atHalf and atOne and math.abs(atHalf - want) < 1,
		"the offset is in the handle's own units, so it grows as the frame"
		.. " shrinks (" .. string.format("%.0f -> %.0f, wanted %.0f",
		atOne, atHalf, want) .. ")")
	A.db.profile.scale = wasScale
	PF:LayoutHandle()
	-- IT LOOKS MOVABLE WHEN IT IS. Every other frame wears an accent wash in
	-- placement mode; this one is not a Movers frame - it docks to an edge
	-- rather than sitting at a point - so it gets no handle of its own, and
	-- without this it was the one thing on an unlocked screen giving no sign
	-- it could be moved at all.
	local hh = PF.handle
	A.Movers:Lock()
	check(not hh.tag:IsShown(), "locked, the dock wears no placement label")
	check(hh._fillToken ~= nil,
		"and is coloured by token, so a restyle reaches it (" ..
		tostring(hh._fillToken) .. ")")

	A.Movers:Unlock()
	check(hh.tag:IsShown(),
		"unlocked, it says what it is - beside the tab, because a word laid"
		.. " over a 34-unit strip is a word laid across something narrower"
		.. " than itself")
	local fill = hh._fillColor
	local acc = A.Palette.c.accent
	check(fill and math.abs(fill[1] - acc[1]) < 0.01
		and math.abs(fill[2] - acc[2]) < 0.01
		and math.abs(fill[3] - acc[3]) < 0.01,
		"and wears the same accent wash as everything else you can move")

	-- AND A RESTYLE MID-PLACEMENT does not wash it back to ordinary glass.
	-- ApplySkin is the obvious thing to call on a skin change and it is the
	-- wrong one here: it would put the ordinary rim back while the frames are
	-- still unlocked, leaving the dock the only fixed-looking thing on screen
	-- again the moment somebody changed skin mid-placement.
	PF:OnSkinChanged()
	local after = hh._fillColor
	check(after and math.abs(after[1] - A.Palette.c.accent[1]) < 0.01,
		"and keeps it through a restyle, rather than reverting to plain glass")
	A.Movers:Lock()
	check(hh._fillToken ~= nil, "and takes the skin back when you lock again")
	-- DRAG IT TO ANOTHER EDGE, the way the Toolbox rail re-docks. Same gate -
	-- the frames have to be unlocked - so there is no second gesture to learn.
	--
	-- Eight targets: four edges with two slots each. The preview is the handle
	-- itself moving, which for a tab this size is a clearer answer than a ghost
	-- rectangle saying where it would go.
	local h = PF.handle
	local function dragTo(x, y)
		-- __setCursor, not a global of my own: the mock keeps the cursor in a
		-- file-local, so setting __cursorX moved nothing and the drag read 500,400
		-- every time - which is the middle of the screen and therefore LEFT.
		__setCursor(x * (UIParent:GetEffectiveScale() or 1),
			y * (UIParent:GetEffectiveScale() or 1))
		h:GetScript("OnDragStart")(h)
		local up = h:GetScript("OnUpdate")
		if up then up(h, 0) end
		h:GetScript("OnDragStop")(h)
	end

	local W0, H0 = UIParent:GetWidth(), UIParent:GetHeight()
	A.Movers.unlocked = true

	-- Hard right, low down: the RIGHT edge, second slot.
	dragTo(W0 - 10, H0 * 0.2)
	check(PF:PanelEdge() == "RIGHT" and PF:PanelSlot() == 2,
		"dragged to the bottom of the right-hand side it docks there (" ..
		PF:PanelEdge() .. " " .. PF:PanelSlot() .. ")")

	-- BY FRACTION OF THE SCREEN, not by pixels. The middle of the left side of
	-- a wide monitor is nearer the top and bottom edges in raw pixels than it
	-- is to the left one, and answering TOP there is nonsense a player would
	-- report as the drag being broken.
	dragTo(10, H0 * 0.5)
	check(PF:PanelEdge() == "LEFT",
		"and hard against the left side it is LEFT, whatever the pixel counts"
		.. " say (" .. PF:PanelEdge() .. ")")

	dragTo(W0 * 0.5, H0 - 10)
	check(PF:PanelEdge() == "TOP" and PF:PanelSlot() == 2,
		"the top edge has two slots of its own (" .. PF:PanelEdge() .. " " ..
		PF:PanelSlot() .. ")")
	dragTo(W0 * 0.2, H0 - 10)
	check(PF:PanelSlot() == 1,
		"and the left half of it is the first")

	-- LOCKED FRAMES ARE LOCKED. The same gate the rail uses, and the one that
	-- stops a stray click on a crowded screen re-docking it.
	PF:SetPanelEdge("LEFT")
	PF:SetPanelSlot(1)
	A.Movers.unlocked = false
	dragTo(W0 - 10, H0 * 0.2)
	check(PF:PanelEdge() == "LEFT",
		"locked, dragging it does nothing at all (" .. PF:PanelEdge() .. ")")

	-- AND NOT IN A FIGHT. Re-docking moves the party stack, which carries
	-- secure children - the drag is dropped rather than finished.
	A.Movers.unlocked = true
	_G.__inCombat = true
	local blocked = _G.__blocked
	dragTo(W0 - 10, H0 * 0.2)
	check(PF:PanelEdge() == "LEFT" and _G.__blocked == blocked,
		"and mid-fight it is refused rather than half-finished (" ..
		PF:PanelEdge() .. ", " .. (_G.__blocked - blocked) .. " refused)")
	_G.__inCombat = false

	-- AND A FIGHT STARTING MID-DRAG, which is the case the guard in the update
	-- loop exists for - the one above never reaches it, because the drag is
	-- refused at the start. The button can still be down when the pull
	-- happens, and finishing then would move the stack, which carries secure
	-- children.
	PF:SetPanelEdge("LEFT")
	PF:SetPanelSlot(1)
	h:GetScript("OnDragStart")(h)
	_G.__inCombat = true
	local mid = _G.__blocked
	__setCursor((W0 - 10) * (UIParent:GetEffectiveScale() or 1),
		(H0 * 0.2) * (UIParent:GetEffectiveScale() or 1))
	local up = h:GetScript("OnUpdate")
	if up then up(h, 0) end
	h:GetScript("OnDragStop")(h)
	check(PF:PanelEdge() == "LEFT" and _G.__blocked == mid,
		"a fight starting mid-drag drops it rather than finishing it (" ..
		PF:PanelEdge() .. ", " .. (_G.__blocked - mid) .. " refused)")
	_G.__inCombat = false

	A.Movers.unlocked = false
	PF:SetPanelEdge("LEFT")
	PF:SetPanelSlot(1)
	-- THE ARROW TURNS ROUND. Open, the click retreats the drawer to its own
	-- edge; shut, it emerges away from it - the same rule the Toolbox rail
	-- follows, from the same function.
	p:Hide()
	PF:LayoutHandle()
	local shut = PF.handle.chev.__rotation
	PF:TogglePanel()
	local open = PF.handle.chev.__rotation
	check(shut ~= nil and open ~= nil and shut ~= open,
		"the handle's arrow faces the other way with the drawer open (" ..
		tostring(shut) .. " -> " .. tostring(open) .. ")")
	PF:TogglePanel()

	-- NOT IN A GROUP, NOT ON SCREEN. A dock to party controls with nobody in
	-- the party is a tab that does nothing, permanently, on the edge of every
	-- screen - and this addon already has one thing living there.
	local keep = {}
	for _, u in ipairs({ "party1", "party2", "party3", "party4" }) do
		keep[u] = _G.__units[u].exists
		_G.__units[u].exists = false
	end
	PF:LayoutHandle()
	check(not PF.handle:IsShown(), "alone, there is no handle at all")
	for u, was in pairs(keep) do _G.__units[u].exists = was end
	PF:LayoutHandle()
	check(PF.handle:IsShown(), "and it is back the moment you group up")

	-- THE MARK GOES ON YOUR TARGET, which the brief never says and which
	-- decides how the whole grid behaves: SetRaidTarget takes a unit and the
	-- unit is always "target". So with nothing targeted every well is inert,
	-- and a well that looks pressable and does nothing is the worse of the two.
	_G.__units.target.exists = false
	PF:RefreshPanel()
	local before = _G.__partyCalls.marks
	p.wells[1]:GetScript("OnClick")(p.wells[1])
	check(_G.__partyCalls.marks == before,
		"with no target, pressing a mark asks the client for nothing")
	check(p.wells[1]:GetAlpha() < 1,
		"and the grid says so rather than looking ready (" ..
		tostring(p.wells[1]:GetAlpha()) .. ")")

	_G.__units.target.exists = true
	PF:RefreshPanel()

	-- HIGHEST INDEX FIRST - skull, cross, square, moon, triangle, diamond,
	-- circle, star. Blizzard's own grid has read that way since the marks
	-- existed and everybody reaches for the skull in the top-left without
	-- looking; laying them out 1 to 8 puts the star there and every mark you
	-- set is the wrong one until you slow down and read the grid.
	check(p.wells[1].index == 8,
		"the skull is the first well, as it is in the client's own grid (" ..
		tostring(p.wells[1].index) .. ")")
	check(p.wells[8].index == 1, "and the star is the last")

	p.wells[1]:GetScript("OnClick")(p.wells[1])
	check(GetRaidTargetIndex("target") == 8,
		"pressing a well sets the mark it SHOWS (" ..
		tostring(GetRaidTargetIndex("target")) .. ")")
	check(p.wells[1].__on == true,
		"and the ring lands on that same well - the grid is laid out"
		.. " backwards to the indices, so comparing the slot rings the"
		.. " wrong one")
	check(p.wells[8].__on == false, "and only that one")

	-- CLEAR IS INDEX 0, not a missing argument. SetRaidTarget with nothing
	-- passed leaves the mark exactly where it was.
	p.clear:GetScript("OnClick")(p.clear)
	check(GetRaidTargetIndex("target") == nil,
		"Clear takes it off (" .. tostring(GetRaidTargetIndex("target")) .. ")")
end)

section("party: the stack rides the dock until you move it", function()
	local PF = A:GetModule("partyframes")
	PF:BuildPanel()

	-- WHERE A PLAYER EXPECTS TO FIND IT. The client's own party frames come off
	-- the left edge with the controls, and somebody installing this should find
	-- their party where they left it rather than somewhere new they now have to
	-- tidy up.
	A.db.profile.anchors.party = nil
	PF.panel:Hide()
	PF:AnchorStack()
	local _, rel = PF.stack:GetPoint()
	check(rel == PF.handle,
		"unplaced and shut, the stack hangs off the dock handle")
	check(not PF:StackIsPlaced(), "and counts as unplaced")

	-- AND A RESTORE LEAVES IT THERE. Movers positions every frame it knows
	-- about from the saved anchor or the default, and unlocking the frames
	-- runs the lot - so without the onPlaced hook handing the stack back, one
	-- /aether unlock would snap it off the dock and it would never return.
	A.Movers:Restore("party")
	local _, relAfter = PF.stack:GetPoint()
	check(relAfter == PF.handle,
		"and a Movers restore hands it straight back to the dock")

	-- AND IT SHIFTS WHEN THE DRAWER OPENS, the way the client's own party
	-- frames do: off the handle while the controls are shut, off the panel
	-- while they are open, so opening them pushes the party out of the way
	-- rather than drawing over it.
	PF:TogglePanel()
	check(PF.panel:IsShown(), "the controls open")
	local _, relOpen = PF.stack:GetPoint()
	check(relOpen == PF.panel,
		"and the stack shifts out to hang off the panel instead")
	PF:TogglePanel()
	local _, relShut = PF.stack:GetPoint()
	check(relShut == PF.handle,
		"and comes back to the handle when they shut")

	-- IT RIDES THE DOCK TO ANOTHER EDGE, which is what makes it attached rather
	-- than merely placed near it.
	PF:SetPanelEdge("RIGHT")
	local at = PF.stack:GetPoint()
	check(at == "TOPRIGHT",
		"docking the panel right takes the stack with it (" .. tostring(at) .. ")")
	PF:SetPanelEdge("LEFT")

	-- DRAG IT ONCE AND IT IS YOURS. Movers writes an anchor and that is the
	-- answer from then on - including when the panel moves.
	A.db.profile.anchors.party = { point = "CENTER", relPoint = "CENTER", x = 0, y = 0 }
	check(PF:StackIsPlaced(), "a dragged stack counts as placed")
	check(PF:AnchorStack() == false,
		"and the dock stops moving it")
	-- AND MOVERS PUTS IT WHERE YOU LEFT IT, not where the dock is. onPlaced
	-- runs after every restore and hands the stack back to the dock only when
	-- nobody has placed it - without that, unlocking the frames would snap a
	-- stack you had positioned straight back onto the panel.
	A.Movers:Restore("party")
	local _, relPlaced = PF.stack:GetPoint()
	check(relPlaced ~= PF.panel,
		"and a restore leaves it where you put it, not back on the dock")

	-- AND YOU CAN HAND IT BACK.
	PF:ResetStack()
	check(not PF:StackIsPlaced(), "/aether party reset drops the anchor")
	local _, relReset = PF.stack:GetPoint()
	check(relReset == PF.handle or relReset == PF.panel,
		"and puts it back on the dock")
end)
section("party controls: what a member may press", function()
	local PF = A:GetModule("partyframes")
	local p = PF.panel
	local calls = _G.__partyCalls
	_G.__units.target = _G.__units.target
		or { exists = true, hp = 1, hpMax = 1 }

	-- HIDDEN, NOT DIMMED. The client gates ready-check itself, but simply
	-- IGNORES a role poll or a convert from a member - no error, nothing said -
	-- and a button that does nothing without saying so is a button you keep
	-- pressing. So they are gone for a member and the panel is shorter.
	_G.__units.player.leader = false
	PF:RefreshPanel()
	local shortH = p:GetHeight()
	local hidden, visible = 0, 0
	for _, b in ipairs(p.rows) do
		if b:IsShown() then visible = visible + 1 else hidden = hidden + 1 end
	end
	check(hidden == 3 and visible == 1,
		"a member sees one row of four (" .. visible .. " shown, " .. hidden ..
		" hidden)")
	check(p.rows[2]:IsShown(),
		"and the one left is Countdown - the client does not gate that one")

	_G.__units.player.leader = true
	PF:RefreshPanel()
	check(p:GetHeight() > shortH,
		"the panel is taller for a leader (" .. p:GetHeight() .. " from " ..
		shortH .. ")")

	-- Each row calls the client, and the RIGHT call.
	calls.ready, calls.countdown, calls.roles, calls.raid = 0, 0, 0, 0
	p.rows[1]:GetScript("OnClick")(p.rows[1])
	check(calls.ready == 1, "Ready Check reaches C_PartyInfo.DoReadyCheck")
	p.rows[3]:GetScript("OnClick")(p.rows[3])
	check(calls.roles == 1, "Role Check reaches InitiateRolePoll")

	-- THE CONFIRMING CONVERT. A raid cannot be turned back into a party, and
	-- the client has a call that asks first - using the other one is a group
	-- somebody has changed for everybody by mis-clicking a row.
	p.rows[4]:GetScript("OnClick")(p.rows[4])
	check(calls.raid == 1, "Convert to Raid reaches the client")
	check((calls.confirmedCold or 0) == 0,
		"through the call this client actually has - ConfirmConvertToRaid"
		.. " reads like an ask-first version and is not one; called cold it"
		.. " does nothing at all, which is what the button did")

	-- The countdown carries its own number, and the client's cap rather than
	-- one of ours: DoCountdown refuses anything longer and says nothing.
	p.rows[2].seconds = 10
	p.rows[2]:GetScript("OnClick")(p.rows[2])
	check(calls.countdown == 1 and calls.seconds == 10,
		"Countdown runs for the number on its picker (" ..
		tostring(calls.seconds) .. ")")
	p.rows[2].seconds = 9999
	p.rows[2]:GetScript("OnClick")(p.rows[2])
	check(calls.seconds <= 60,
		"and never longer than the client will take (" ..
		tostring(calls.seconds) .. ")")
	p.rows[2].seconds = 10

	PF.panel:Hide()
end)
section("party: a diagnostic that answers the question", function()
	local PF = A:GetModule("partyframes")
	A:SetModuleEnabled("partyframes", true)
	_G.__raidTargets.party1 = 3
	fire("RAID_TARGET_UPDATE")

	-- THREE ROUNDS WENT BY GUESSING why a raid mark was not on screen. Every
	-- answer is a one-liner from the client and none of them can be read from
	-- outside the game, so the report puts what the client SAYS next to what we
	-- actually drew - and the two disagreeing is the whole diagnosis.
	local lines = {}
	local ok, err = pcall(A.PartyDiag, function(fmt, ...)
		lines[#lines + 1] = string.format(fmt, ...)
	end)
	check(ok, "/aether party reports without erroring (" .. tostring(err) .. ")")

	local all = table.concat(lines, "\n")
	check(all:find("party1", 1, true) ~= nil, "with a row per member")
	check(all:find("PartyFrame", 1, true) ~= nil,
		"and what became of the client's own frames")
	check(all:find("mark", 1, true) ~= nil,
		"and says which decorators are actually drawn")

	-- The player is a different frame in a different module, and leaving it out
	-- is how you spend a round asking about the wrong one.
	check(all:find("player", 1, true) ~= nil, "your own capsule included")

	_G.__raidTargets.party1 = nil
	fire("RAID_TARGET_UPDATE")
end)

section("nameplates: a pet's title is not every boar's title", function()
	local NP = A:GetModule("nameplates")

	-- THE BUG, EXACTLY. Dismiss a hunter's Dire Mottled Boar, target a wild
	-- Dire Mottled Boar, and the plate reads "<Ifindu's Pet>" - because the
	-- scanned title was filed under the creature's NAME, and those two share a
	-- name to the letter.
	--
	-- The GUID is what tells them apart: a pet is type Pet, a mob is type
	-- Creature, and both carry an id that is per creature KIND - so the cache
	-- still answers once for every Beverage Merchant in the world.
	__spawnPlate("nameplate7", {
		exists = true, name = "Dire Mottled Boar", level = 10, reaction = 4,
		hp = 300, hpMax = 420, creature = "Beast",
		guidType = "Pet", title = "Ifindu's Pet",
	})
	local pet = NP.byUnit.nameplate7
	check(pet ~= nil, "the pet's plate is up")
	check(pet and pet.guild and pet.guild:GetText() and
		pet.guild:GetText():find("Ifindu", 1, true) ~= nil,
		"and it says whose pet it is (" ..
		tostring(pet and pet.guild and pet.guild:GetText()) .. ")")
	__despawnPlate("nameplate7")

	-- Now the wild one. Same name, same species, no owner.
	-- NEUTRAL, like the one in the report. A hostile mob is drawn as a plate
	-- and has no subtitle line at all, so it could not show the bug however
	-- badly the cache behaved - which is exactly what the first version of
	-- this check did, and it passed against every mutation.
	--
	-- Reaction 4 and a title is what puts a unit in the NAME form, which is
	-- the form that has somewhere to print one.
	__spawnPlate("nameplate8", {
		exists = true, name = "Dire Mottled Boar", level = 10, reaction = 4,
		hp = 300, hpMax = 420, creature = "Beast",
	})
	local wild = NP.byUnit.nameplate8
	check(wild ~= nil, "the wild one's plate is up")
	local sub = wild and wild.guild and wild.guild:IsShown()
		and wild.guild:GetText() or nil
	check(sub == nil or sub:find("Ifindu", 1, true) == nil,
		"and it does NOT inherit the pet's owner (" .. tostring(sub) .. ")")
	__despawnPlate("nameplate8")

	-- AND TWO HUNTERS WITH THE SAME SPECIES. A pet's title is its OWNER'S
	-- name, so the creature id is the wrong key for one even against another
	-- pet - both boars are the same creature and the answers differ. Per
	-- spawn is the only key that is true for a pet.
	__spawnPlate("nameplate7", {
		exists = true, name = "Dire Mottled Boar", level = 10, reaction = 4,
		hp = 300, hpMax = 420, creature = "Beast",
		guidType = "Pet", title = "Grimtusk's Pet",
	})
	local other = NP.byUnit.nameplate7
	local osub = other and other.guild and other.guild:GetText() or nil
	check(osub and osub:find("Grimtusk", 1, true) ~= nil,
		"another hunter's boar says ITS owner, not the first one's (" ..
		tostring(osub) .. ")")
	__despawnPlate("nameplate7")

	-- AND THE CACHE STILL DOES ITS JOB. Two of the same creature, different
	-- spawns: scanned once between them. Keying by spawn would be correct
	-- and useless - every mob in the zone rescanned on every plate, which
	-- looks identical on screen and is the reason this cache exists.
	_G.__titleScans = 0
	__spawnPlate("nameplate6", {
		exists = true, name = "Beverage Merchant", level = 30, reaction = 4,
		hp = 800, hpMax = 800, creature = "Humanoid", title = "Drink Vendor",
	})
	__despawnPlate("nameplate6")
	__spawnPlate("nameplate6", {
		exists = true, name = "Beverage Merchant", level = 30, reaction = 4,
		hp = 800, hpMax = 800, creature = "Humanoid", title = "Drink Vendor",
	})
	check(_G.__titleScans == 1,
		"two of the same merchant are scanned once between them (" ..
		tostring(_G.__titleScans) .. " scans)")
	__despawnPlate("nameplate6")
end)
section("decorators: a mark on a mob is a mark on its nameplate", function()
	local NP = A:GetModule("nameplates")

	-- THERE WAS NO MARK AT ALL. Put a skull on something and the plate over its
	-- head said nothing about it, which is the one moment a marked mob is worth
	-- marking.
	-- Its own token. Spawning nameplate1 here would hand the plate-recycling
	-- checks below a frame that already exists, and spend the one case they
	-- are about.
	__spawnPlate("nameplate9", {
		exists = true, name = "Kolkar Marauder", level = 18, reaction = 2,
		hp = 900, hpMax = 1000,
	})
	local f = NP.byUnit.nameplate9
	check(f ~= nil, "a plate is up")
	check(f and f.mark ~= nil, "and it has a raid mark")
	check(f and not f.mark:IsShown(),
		"hidden on something nobody has marked")

	-- RAID_TARGET_UPDATE CARRIES NO UNIT. One event for every mark in the group
	-- at once, so a handler waiting to be told which plate would never run - and
	-- a plate would keep wearing a skull that had moved to somebody else.
	_G.__raidTargets.nameplate9 = 8
	fire("RAID_TARGET_UPDATE")
	check(f and f.mark:IsShown(), "and there the moment somebody does")
	check(f and tostring(f.mark.__tex):find("RaidTargetingIcons", 1, true) ~= nil,
		"in the client's own art (" .. tostring(f and f.mark.__tex) .. ")")
	local l, r = f.mark:GetTexCoord()
	check(not (l == 0 and r == 1),
		"with one cell picked out of it, not all eight marks at once")

	_G.__raidTargets.nameplate9 = nil
	fire("RAID_TARGET_UPDATE")
	check(f and not f.mark:IsShown(), "and gone when the mark is cleared")
	__despawnPlate("nameplate9")
end)


print("")
if #FAIL == 0 then
	print("ALL CHECKS PASSED")
else
	print(#FAIL .. " FAILURE(S):")
	for _, m in ipairs(FAIL) do print("  - " .. m) end
	os.exit(1)
end
